module draw_block_assertions(
    input logic clock,
    input logic [10:0] vcounter,
    input logic [11:0] hcounter,
    input logic [2:0] block,
    input logic [4:0] sel_row,
    input logic [4:0] sel_col,
    input logic [3:0] out
);

localparam [11:0] LEFT   = 12'd160;
localparam [11:0] RIGHT  = 12'd480;
localparam [11:0] TILE_W = 12'd32;
localparam [10:0] BOTTOM = 11'd480;
localparam [10:0] TILE_H = 11'd16;

// sel_col matches the 32-pixel horizontal tile index in the draw region.
check_sel_col_decode: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT))
    |-> (sel_col == ((hcounter - LEFT) / TILE_W))
);

// sel_row matches the 16-pixel vertical tile index in the draw region.
check_sel_row_decode: assert property (
    @(posedge clock)
    (vcounter < BOTTOM)
    |-> (sel_row == (vcounter / TILE_H))
);

// out is blank outside the active drawing window.
check_out_zero_outside_window: assert property (
    @(posedge clock)
    (!((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM)))
    |-> (out == 4'b0000)
);

// block 000 always produces blank output in range.
check_block_zero_blank: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b000))
    |-> (out == 4'b0000)
);

// Nonzero narrow blocks draw 8 on the top and bottom of the center strip.
check_narrow_center_border: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block != 3'b000) && (block[2] == 1'b0) &&
     (((hcounter - LEFT) % TILE_W) > 12'd8) &&
     (((hcounter - LEFT) % TILE_W) < 12'd23) &&
     (((vcounter % TILE_H) == 11'd0) || ((vcounter % TILE_H) == 11'd15)))
    |-> (out == 4'b1000)
);

// block 001 fills the center strip interior with 1100.
check_narrow_center_fill_block_001: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b001) &&
     (((hcounter - LEFT) % TILE_W) > 12'd8) &&
     (((hcounter - LEFT) % TILE_W) < 12'd23) &&
     ((vcounter % TILE_H) != 11'd0) && ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1100)
);

// block 010 fills the center strip interior with 1011.
check_narrow_center_fill_block_010: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b010) &&
     (((hcounter - LEFT) % TILE_W) > 12'd8) &&
     (((hcounter - LEFT) % TILE_W) < 12'd23) &&
     ((vcounter % TILE_H) != 11'd0) && ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1011)
);

// block 011 fills the center strip interior with 1101.
check_narrow_center_fill_block_011: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b011) &&
     (((hcounter - LEFT) % TILE_W) > 12'd8) &&
     (((hcounter - LEFT) % TILE_W) < 12'd23) &&
     ((vcounter % TILE_H) != 11'd0) && ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1101)
);

// Nonzero narrow blocks draw 8 on the two center-strip side columns.
check_narrow_side_columns_border: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block != 3'b000) && (block[2] == 1'b0) &&
     ((((hcounter - LEFT) % TILE_W) == 12'd8) ||
      (((hcounter - LEFT) % TILE_W) == 12'd23)))
    |-> (out == 4'b1000)
);

// Narrow blocks other than 011 are blank in the outer columns.
check_narrow_outer_blank_non_011: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block[2] == 1'b0) && (block[1:0] != 2'b11) &&
     ((((hcounter - LEFT) % TILE_W) < 12'd8) ||
      (((hcounter - LEFT) % TILE_W) > 12'd23)))
    |-> (out == 4'b0000)
);

// block 011 draws 8 on the tile border in the outer columns.
check_narrow_outer_block_011_border: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b011) &&
     ((((hcounter - LEFT) % TILE_W) < 12'd8) ||
      (((hcounter - LEFT) % TILE_W) > 12'd23)) &&
     ((((hcounter - LEFT) % TILE_W) == 12'd0) ||
      (((hcounter - LEFT) % TILE_W) == 12'd31) ||
      ((vcounter % TILE_H) == 11'd0) ||
      ((vcounter % TILE_H) == 11'd15)))
    |-> (out == 4'b1000)
);

// block 011 fills the outer-column tile interior with 1110.
check_narrow_outer_block_011_fill: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b011) &&
     ((((hcounter - LEFT) % TILE_W) < 12'd8) ||
      (((hcounter - LEFT) % TILE_W) > 12'd23)) &&
     (((hcounter - LEFT) % TILE_W) != 12'd0) &&
     (((hcounter - LEFT) % TILE_W) != 12'd31) &&
     ((vcounter % TILE_H) != 11'd0) &&
     ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1110)
);

// Wide blocks draw 8 on the tile border.
check_wide_border: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block[2] == 1'b1) &&
     ((((hcounter - LEFT) % TILE_W) == 12'd0) ||
      (((hcounter - LEFT) % TILE_W) == 12'd31) ||
      ((vcounter % TILE_H) == 11'd0) ||
      ((vcounter % TILE_H) == 11'd15)))
    |-> (out == 4'b1000)
);

// block 100 fills the wide tile interior with 1001.
check_wide_fill_block_100: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b100) &&
     (((hcounter - LEFT) % TILE_W) != 12'd0) &&
     (((hcounter - LEFT) % TILE_W) != 12'd31) &&
     ((vcounter % TILE_H) != 11'd0) &&
     ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1001)
);

// block 101 fills the wide tile interior with 1010.
check_wide_fill_block_101: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b101) &&
     (((hcounter - LEFT) % TILE_W) != 12'd0) &&
     (((hcounter - LEFT) % TILE_W) != 12'd31) &&
     ((vcounter % TILE_H) != 11'd0) &&
     ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1010)
);

// block 110 fills the wide tile interior with 1110.
check_wide_fill_block_110: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b110) &&
     (((hcounter - LEFT) % TILE_W) != 12'd0) &&
     (((hcounter - LEFT) % TILE_W) != 12'd31) &&
     ((vcounter % TILE_H) != 11'd0) &&
     ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1110)
);

// block 111 fills the wide tile interior with 1111.
check_wide_fill_block_111: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b111) &&
     (((hcounter - LEFT) % TILE_W) != 12'd0) &&
     (((hcounter - LEFT) % TILE_W) != 12'd31) &&
     ((vcounter % TILE_H) != 11'd0) &&
     ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1111)
);

endmodule

rtl:
module priority_encoder (
    input [3:0] I,
    output reg [1:0] O
);

always @(*) begin
    casez(I)
        4'b0001: O = 2'b00;
        4'b0010: O = 2'b01;
        4'b0100: O = 2'b10;
        4'b1000: O = 2'b11;
        default: O = 2'b00;
    endcase
end

endmodule

sva:
module priority_encoder_sva (
    input logic [3:0] I,
    input logic [1:0] O
);

    // 0001 encodes to 00.
    check_encode_0001: assert property (
        @($global_clock) (I == 4'b0001) |-> (O == 2'b00)
    );

    // 0010 encodes to 01.
    check_encode_0010: assert property (
        @($global_clock) (I == 4'b0010) |-> (O == 2'b01)
    );

    // 0100 encodes to 10.
    check_encode_0100: assert property (
        @($global_clock) (I == 4'b0100) |-> (O == 2'b10)
    );

    // 1000 encodes to 11.
    check_encode_1000: assert property (
        @($global_clock) (I == 4'b1000) |-> (O == 2'b11)
    );

    // All other known inputs return the default 00.
    check_default_for_other_known_inputs: assert property (
        @($global_clock)
        (!$isunknown(I) &&
         (I != 4'b0001) &&
         (I != 4'b0010) &&
         (I != 4'b0100) &&
         (I != 4'b1000)) |-> (O == 2'b00)
    );

endmodule

rtl:
module synchronizer_ff_15
   (out,
    rd_rst_asreg_reg ,
    in0,
    s_axi_aclk);
  output out;
  output rd_rst_asreg_reg ;
  input [0:0]in0;
  input s_axi_aclk;

  reg Q_reg;
  wire [0:0]in0;
  wire rd_rst_asreg_reg ;
  wire s_axi_aclk;

  assign out = Q_reg;
  always @(posedge s_axi_aclk) begin
    if (rd_rst_asreg_reg)
      Q_reg <= 1'b0;
    else
      Q_reg <= in0;
  end
  assign rd_rst_asreg_reg = (in0 != Q_reg);
endmodule

sva:
module synchronizer_ff_15_sva (
    input logic out,
    input logic rd_rst_asreg_reg,
    input logic [0:0] in0,
    input logic s_axi_aclk
);

    // The flag is the combinational mismatch between in0 and out.
    check_flag_definition: assert property (
        @(posedge s_axi_aclk) rd_rst_asreg_reg === (in0[0] != out)
    );

    // A high mismatch flag clears the registered output on the next clock.
    check_mismatch_clears_out: assert property (
        @(posedge s_axi_aclk) rd_rst_asreg_reg |=> (out == 1'b0)
    );

    // With no mismatch, the registered output captures the current input.
    check_match_captures_input: assert property (
        @(posedge s_axi_aclk) !rd_rst_asreg_reg |=> (out === $past(in0[0]))
    );

    // Once out is low, this logic keeps it low on the next cycle.
    check_zero_state_sticky: assert property (
        @(posedge s_axi_aclk) (out == 1'b0) |=> (out == 1'b0)
    );

    // A high output stays high when the input is also high.
    check_high_holds_with_high_input: assert property (
        @(posedge s_axi_aclk) (out == 1'b1 && in0[0] == 1'b1) |=> (out == 1'b1)
    );

    // A high output clears when the input goes low.
    check_high_clears_with_low_input: assert property (
        @(posedge s_axi_aclk) (out == 1'b1 && in0[0] == 1'b0) |=> (out == 1'b0)
    );

endmodule

rtl:
module myNAND3 (IN1,IN2,IN3,QN);

input IN1,IN2,IN3;
output QN;

wire nand1, nand2;

nand (nand1, IN1, IN2, IN3);
nand (nand2, nand1, nand1);
not (QN, nand2);

endmodule

sva:
module myNAND3_sva (
    input logic clk,
    input logic IN1,
    input logic IN2,
    input logic IN3,
    input logic QN
);

    // QN must equal the 3-input NAND of IN1, IN2, and IN3.
    check_nand3_function: assert property (
        @(posedge clk) QN == ~(IN1 & IN2 & IN3)
    );

    // When all inputs are high, QN must be low.
    check_all_high_drives_low: assert property (
        @(posedge clk) (IN1 && IN2 && IN3) |-> !QN
    );

    // If IN1 is low, QN must be high.
    check_in1_low_drives_high: assert property (
        @(posedge clk) !IN1 |-> QN
    );

    // If IN2 is low, QN must be high.
    check_in2_low_drives_high: assert property (
        @(posedge clk) !IN2 |-> QN
    );

    // If IN3 is low, QN must be high.
    check_in3_low_drives_high: assert property (
        @(posedge clk) !IN3 |-> QN
    );

    // A low QN is only possible when all three inputs are high.
    check_low_output_requires_all_high: assert property (
        @(posedge clk) !QN |-> (IN1 && IN2 && IN3)
    );

endmodule

rtl:
module four_to_one (
    input A1,
    input A2,
    input B1,
    input B2,
    output X
);

    wire A_low, A_high, B_low, B_high;

    assign A_low = ~(A1 | A2);
    assign A_high = A1 & A2;
    assign B_low = ~(B1 | B2);
    assign B_high = B1 & B2;

    assign X = (A_low & B_low) | (A_high & B_high);

endmodule

sva:
module four_to_one_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic X
);

    // X matches the implemented sum-of-products function.
    check_functional_equivalence: assert property (
        @(posedge clk)
        X == (((~(A1 | A2)) & (~(B1 | B2))) | ((A1 & A2) & (B1 & B2)))
    );

    // All four inputs low drives X high.
    check_all_low_sets_x: assert property (
        @(posedge clk)
        ((!A1 && !A2) && (!B1 && !B2)) |-> X
    );

    // All four inputs high drives X high.
    check_all_high_sets_x: assert property (
        @(posedge clk)
        ((A1 && A2) && (B1 && B2)) |-> X
    );

    // A mixed pair cannot produce X high.
    check_mixed_a_clears_x: assert property (
        @(posedge clk)
        (A1 ^ A2) |-> !X
    );

    // B mixed pair cannot produce X high.
    check_mixed_b_clears_x: assert property (
        @(posedge clk)
        (B1 ^ B2) |-> !X
    );

    // A low pair with B high pair drives X low.
    check_a_low_b_high_clears_x: assert property (
        @(posedge clk)
        ((!A1 && !A2) && (B1 && B2)) |-> !X
    );

    // A high pair with B low pair drives X low.
    check_a_high_b_low_clears_x: assert property (
        @(posedge clk)
        ((A1 && A2) && (!B1 && !B2)) |-> !X
    );

    // X can only be high for matching all-low or all-high pairs.
    check_x_high_only_on_matching_extremes: assert property (
        @(posedge clk)
        X |-> (((!A1 && !A2) && (!B1 && !B2)) || ((A1 && A2) && (B1 && B2)))
    );

endmodule

rtl:
module full_adder (
    input A, B, CARRY_IN,
    output SUM, CARRY_OUT
);

    assign {CARRY_OUT, SUM} = A + B + CARRY_IN;

endmodule

module four_bit_adder(
    input [3:0] A, B,
    output [3:0] OUT,
    output CARRY_OUT,
    input CARRY_IN
);

    wire [3:0] SUM;
    wire CO1, CO2, CO3;

    // First full adder
    full_adder FA1 (.A(A[0]), .B(B[0]), .CARRY_IN(CARRY_IN), .SUM(SUM[0]), .CARRY_OUT(CO1));

    // Second full adder
    full_adder FA2 (.A(A[1]), .B(B[1]), .CARRY_IN(CO1), .SUM(SUM[1]), .CARRY_OUT(CO2));

    // Third full adder
    full_adder FA3 (.A(A[2]), .B(B[2]), .CARRY_IN(CO2), .SUM(SUM[2]), .CARRY_OUT(CO3));

    // Fourth full adder
    full_adder FA4 (.A(A[3]), .B(B[3]), .CARRY_IN(CO3), .SUM(SUM[3]), .CARRY_OUT(CARRY_OUT));

    // Assign the output
    assign OUT = SUM;

endmodule

sva:
module four_bit_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] OUT,
    input logic CARRY_OUT,
    input logic CARRY_IN
);

    // Combined outputs equal the 5-bit addition result.
    check_total_sum: assert property (
        @($global_clock) {CARRY_OUT, OUT} == ({1'b0, A} + {1'b0, B} + CARRY_IN)
    );

    // Bit 0 matches full-adder XOR behavior.
    check_lsb_sum: assert property (
        @($global_clock) OUT[0] == (A[0] ^ B[0] ^ CARRY_IN)
    );

    // With no carry-in, the module reduces to A plus B.
    check_no_carry_in_add: assert property (
        @($global_clock) (CARRY_IN == 1'b0) |-> ({CARRY_OUT, OUT} == ({1'b0, A} + {1'b0, B}))
    );

    // A equal to zero passes B through with carry-in addition.
    check_zero_a_passthrough: assert property (
        @($global_clock) (A == 4'b0000) |-> ({CARRY_OUT, OUT} == ({1'b0, B} + CARRY_IN))
    );

    // B equal to zero passes A through with carry-in addition.
    check_zero_b_passthrough: assert property (
        @($global_clock) (B == 4'b0000) |-> ({CARRY_OUT, OUT} == ({1'b0, A} + CARRY_IN))
    );

    // Zero operands produce only the carry-in in the LSB.
    check_zero_operands: assert property (
        @($global_clock) ((A == 4'b0000) && (B == 4'b0000)) |-> ({CARRY_OUT, OUT} == {4'b0000, CARRY_IN})
    );

    // Carry-out is high exactly when the 4-bit addition overflows.
    check_carry_out_overflow: assert property (
        @($global_clock) CARRY_OUT == (({1'b0, A} + {1'b0, B} + CARRY_IN) > 5'd15)
    );

    // Adding one to 4'hF wraps OUT to zero and raises carry-out.
    check_increment_overflow: assert property (
        @($global_clock) ((A == 4'hF) && (B == 4'h0) && (CARRY_IN == 1'b1)) |-> ({CARRY_OUT, OUT} == 5'h10)
    );

    // Maximum inputs produce all ones on the 5-bit result.
    check_max_input_sum: assert property (
        @($global_clock) ((A == 4'hF) && (B == 4'hF) && (CARRY_IN == 1'b1)) |-> ({CARRY_OUT, OUT} == 5'h1F)
    );

endmodule

module power_of_2_detection_sva (
    input logic        clk,
    input logic [15:0] num,
    input logic        is_power_of_2
);

    // Zero must not be flagged as a power of two.
    check_zero_is_not_power_of_two: assert property (
        @(posedge clk) (num == 16'd0) |-> (is_power_of_2 == 1'b0)
    );

    // A one-hot input must be flagged as a power of two.
    check_onehot_input_sets_output: assert property (
        @(posedge clk) $onehot(num) |-> (is_power_of_2 == 1'b1)
    );

    // A nonzero input with multiple bits set must clear the output.
    check_multibit_input_clears_output: assert property (
        @(posedge clk) ((num != 16'd0) && !$onehot(num)) |-> (is_power_of_2 == 1'b0)
    );

    // A high output must only occur for a one-hot input.
    check_high_output_requires_onehot_input: assert property (
        @(posedge clk) (is_power_of_2 == 1'b1) |-> $onehot(num)
    );

    // The output must match the RTL power-of-two detection expression.
    check_output_matches_rtl_expression: assert property (
        @(posedge clk) (is_power_of_2 == (((num != 16'd0) && ((num & (num - 16'd1)) == 16'd0)) ? 1'b1 : 1'b0))
    );

endmodule

rtl:
module addition_module (
  input [7:0] A,
  input [7:0] B,
  output reg [8:0] Sum
);

  always @(*) begin
    Sum = A + B;
  end

endmodule

sva:
module addition_module_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [8:0] Sum
);

    // Sum always equals the zero-extended addition of A and B.
    check_sum_matches_addition: assert property (
        @($global_clock) Sum == ({1'b0, A} + {1'b0, B})
    );

    // If both inputs stay the same between samples, Sum also stays the same.
    check_stable_inputs_hold_sum: assert property (
        @($global_clock) ($stable(A) && $stable(B)) |-> $stable(Sum)
    );

endmodule

rtl:
module sky130_fd_sc_ls__inv (
    Y,
    A
);

    output Y;
    input  A;

    wire not0_out_Y;

    not not0 (not0_out_Y, A              );
    buf buf0 (Y         , not0_out_Y     );

endmodule

sva:
module sky130_fd_sc_ls__inv_sva (
    input logic clk,
    input logic Y,
    input logic A
);

    // Y must always be the bitwise inversion of A.
    check_output_is_inverse: assert property (
        @(posedge clk) (Y === ~A)
    );

    // A low input drives Y high.
    check_low_input_drives_high_output: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b1)
    );

    // A high input drives Y low.
    check_high_input_drives_low_output: assert property (
        @(posedge clk) (A === 1'b1) |-> (Y === 1'b0)
    );

    // Unknown or high-impedance input produces an unknown output.
    check_unknown_input_produces_unknown_output: assert property (
        @(posedge clk) ((A === 1'bx) || (A === 1'bz)) |-> (Y === 1'bx)
    );

endmodule

module counter_sva (
    input logic       CLK,
    input logic       RST,
    input logic       enable,
    input logic [3:0] count_out
);

    // Reset clears the counter.
    check_reset_clears_count: assert property (
        @(posedge CLK) RST |=> (count_out == 4'b0000)
    );

    // When enabled outside reset, the counter increments by one.
    check_enable_increments_count: assert property (
        @(posedge CLK) disable iff (RST)
        enable |=> (count_out == ($past(count_out) + 4'b0001))
    );

    // When disabled outside reset, the counter holds its value.
    check_disable_holds_count: assert property (
        @(posedge CLK) disable iff (RST)
        !enable |=> (count_out == $past(count_out))
    );

    // Counting from 4'hF wraps the counter to 4'h0.
    check_wraps_after_max: assert property (
        @(posedge CLK) disable iff (RST)
        (enable && (count_out == 4'hF)) |=> (count_out == 4'h0)
    );

    // Reset takes priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge CLK)
        (RST && enable) |=> (count_out == 4'b0000)
    );

endmodule

rtl:
module edge_detector (
    input clk,
    input [7:0] in,
    output reg [7:0] anyedge
);

reg [7:0] prev_in;
reg [2:0] count;

always @(posedge clk) begin
    prev_in <= in;
    count <= count + 1;
end

always @(posedge clk) begin
    if (prev_in != in) begin
        anyedge <= {anyedge[6:0], 1'b1};
    end else begin
        anyedge <= {anyedge[6:0], 1'b0};
    end
end

endmodule

module top_module (
    input clk,
    input [7:0] in,
    output [7:0] anyedge
);

edge_detector detector (
    .clk(clk),
    .in(in),
    .anyedge(anyedge)
);

endmodule

sva:
module edge_detector_sva (
    input logic clk,
    input logic [7:0] in,
    input logic [7:0] anyedge
);

    // Upper bits shift forward by one position each cycle.
    check_anyedge_shift_upper: assert property (
        @(posedge clk) disable iff ($initstate)
        anyedge[7:1] == $past(anyedge[6:0])
    );

    // An input change shifts a 1 into the register on the next cycle.
    check_change_shifts_in_one: assert property (
        @(posedge clk) disable iff ($initstate)
        (in != $past(in)) |=> (anyedge == {$past(anyedge[6:0]), 1'b1})
    );

    // A stable input shifts a 0 into the register on the next cycle.
    check_stable_shifts_in_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        (in == $past(in)) |=> (anyedge == {$past(anyedge[6:0]), 1'b0})
    );

    // An input change sets the next-cycle LSB.
    check_change_sets_lsb: assert property (
        @(posedge clk) disable iff ($initstate)
        (in != $past(in)) |=> (anyedge[0] == 1'b1)
    );

    // A stable input clears the next-cycle LSB.
    check_stable_clears_lsb: assert property (
        @(posedge clk) disable iff ($initstate)
        (in == $past(in)) |=> (anyedge[0] == 1'b0)
    );

endmodule

rtl:
module xor_adder (
  input clk,
  input [1:0] a,
  input [1:0] b,
  output reg [1:0] sum
);

  always @(posedge clk) begin
    sum <= a ^ b;
  end

endmodule

sva:
module xor_adder_sva (
    input logic       clk,
    input logic [1:0] a,
    input logic [1:0] b,
    input logic [1:0] sum
);

    // Sum captures the previous cycle XOR of a and b.
    check_sum_registers_prev_xor: assert property (
        @(posedge clk) 1'b1 |=> (sum == ($past(a) ^ $past(b)))
    );

    // Equal inputs produce a zero sum on the next clock.
    check_equal_inputs_produce_zero: assert property (
        @(posedge clk) (a == b) |=> (sum == 2'b00)
    );

    // A zero a input passes b through to sum on the next clock.
    check_zero_a_passthrough_b: assert property (
        @(posedge clk) (a == 2'b00) |=> (sum == $past(b))
    );

    // A zero b input passes a through to sum on the next clock.
    check_zero_b_passthrough_a: assert property (
        @(posedge clk) (b == 2'b00) |=> (sum == $past(a))
    );

endmodule

rtl:
module hc161_like ( input  wire [3:0] cpu_d
							, input  wire cpu_rw
							, input  wire Ncpu_romsel
							, output wire hc161_out0
							, output wire hc161_out1
							, output wire hc161_out2
							, output wire hc161_out3
							);
	reg [3:0] hc161_krn; assign hc161_out0 = hc161_krn [0:0];
	assign hc161_out1 = hc161_krn [1:1];
	assign hc161_out2 = hc161_krn [2:2];
	assign hc161_out3 = hc161_krn [3:3]; always @(posedge Ncpu_romsel) begin
		if (!cpu_rw) begin
			hc161_krn <= cpu_d; 
		end
	end

endmodule

