module up_counter(
  input clk,
  input reset,
  output reg [3:0] count
);

  always @(posedge clk) begin
    if (reset) begin
      count <= 4'b0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module up_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

    // A reset cycle forces count to zero on the next sampled clock.
    check_reset_forces_zero_next_cycle: assert property (
        @(posedge clk) reset |=> (count == 4'd0)
    );

    // The first non-reset cycle after reset still shows zero.
    check_count_zero_after_reset_release: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && $past(reset)) |-> (count == 4'd0)
    );

    // Across consecutive non-reset cycles, count increments by one.
    check_count_increments_between_non_reset_cycles: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset)) |-> (count == ($past(count) + 4'd1))
    );

    // Across consecutive non-reset cycles, 4'hF wraps to 4'h0.
    check_count_wraps_from_f_to_0: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

endmodule

rtl:
module two_bit_adder (
    input [1:0] A,
    input [1:0] B,
    input cin,
    output [1:0] sum,
    output cout
);

    // Local signals
    wire c1;
    wire [1:0] s1;

    //  Name  Output  Other arguments
    full_adder U0 (.COUT(c1), .SUM(s1[0]), .A(A[0]), .B(B[0]), .CI(cin));
    full_adder U1 (.COUT(cout), .SUM(s1[1]), .A(A[1]), .B(B[1]), .CI(c1));
    assign sum = {s1[1], s1[0]};

endmodule

module full_adder (
    output COUT,
    output SUM,
    input A,
    input B,
    input CI
);
    assign {COUT, SUM} = A + B + CI;

endmodule

sva:
module two_bit_adder_sva (
    input logic       clk,
    input logic [1:0] A,
    input logic [1:0] B,
    input logic       cin,
    input logic [1:0] sum,
    input logic       cout
);

    // Combined output must equal A + B + cin.
    check_total_addition: assert property (
        @(posedge clk) disable iff (1'b0)
        ({cout, sum} == ({1'b0, A} + {1'b0, B} + cin))
    );

    // The LSB sum bit matches the first full-adder sum equation.
    check_lsb_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        (sum[0] == (A[0] ^ B[0] ^ cin))
    );

    // The MSB sum bit uses the carry generated by the LSB stage.
    check_msb_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        (sum[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (A[0] & cin) | (B[0] & cin))))
    );

    // The final carry-out matches the upper full-adder carry equation.
    check_cout_function: assert property (
        @(posedge clk) disable iff (1'b0)
        (cout == ((A[1] & B[1]) |
                  (A[1] & ((A[0] & B[0]) | (A[0] & cin) | (B[0] & cin))) |
                  (B[1] & ((A[0] & B[0]) | (A[0] & cin) | (B[0] & cin)))))
    );

    // Adding zero with no carry-in passes A through unchanged.
    check_a_passthrough: assert property (
        @(posedge clk) disable iff (1'b0)
        ((B == 2'b00) && (cin == 1'b0)) |-> ((sum == A) && (cout == 1'b0))
    );

    // Adding zero with no carry-in passes B through unchanged.
    check_b_passthrough: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 2'b00) && (cin == 1'b0)) |-> ((sum == B) && (cout == 1'b0))
    );

    // A carry-in alone increments the zero input case by one.
    check_cin_only_increment: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 2'b00) && (B == 2'b00) && (cin == 1'b1)) |-> ((sum == 2'b01) && (cout == 1'b0))
    );

endmodule

rtl:
module top_module (
  input clk,
  input reset, // Synchronous active-high reset
  input [7:0] in1,
  input [7:0] in2,
  input select,
  output [7:0] out
);

  wire [7:0] adder1_out;
  wire [7:0] adder2_out;
  wire [7:0] and_out;

  // Instantiate the two adder modules
  adder adder1 (
    .clk(clk),
    .reset(reset),
    .in1(in1),
    .in2(in2),
    .out(adder1_out)
  );

  adder adder2 (
    .clk(clk),
    .reset(reset),
    .in1(in1),
    .in2(in2),
    .out(adder2_out)
  );

  // Instantiate the control logic module
  control_logic control (
    .select(select),
    .adder1_out(adder1_out),
    .adder2_out(adder2_out),
    .and_out(and_out)
  );

  // Output the result of the AND operation
  assign out = and_out;

endmodule

module adder (
  input clk,
  input reset, // Synchronous active-high reset
  input [7:0] in1,
  input [7:0] in2,
  output [7:0] out
);

  reg [7:0] sum;

  always @(posedge clk) begin
    if (reset) begin
      sum <= 8'd0;
    end else begin
      sum <= in1 + in2;
    end
  end

  assign out = sum;

endmodule

module control_logic (
  input select,
  input [7:0] adder1_out,
  input [7:0] adder2_out,
  output [7:0] and_out
);

  assign and_out = (select) ? (adder1_out & adder2_out) : (adder2_out & adder1_out);

endmodule

sva:
module top_module_sva (
  input logic clk,
  input logic reset,
  input logic [7:0] in1,
  input logic [7:0] in2,
  input logic select,
  input logic [7:0] out
);

  // Reset drives the registered output to zero on the next cycle.
  check_reset_forces_zero: assert property (
    @(posedge clk) reset |=> (out == 8'd0)
  );

  // With select high, output matches the previous cycle's 8-bit sum.
  check_select_high_result: assert property (
    @(posedge clk) disable iff (reset || $initstate)
    (select && !$past(reset)) |-> (out == ($past(in1) + $past(in2)))
  );

  // With select low, output matches the previous cycle's 8-bit sum.
  check_select_low_result: assert property (
    @(posedge clk) disable iff (reset || $initstate)
    (!select && !$past(reset)) |-> (out == ($past(in1) + $past(in2)))
  );

  // Adding zero on in2 passes through in1.
  check_in2_zero_passthrough: assert property (
    @(posedge clk) disable iff (reset || $initstate)
    (!$past(reset) && ($past(in2) == 8'd0)) |-> (out == $past(in1))
  );

  // Adding zero on in1 passes through in2.
  check_in1_zero_passthrough: assert property (
    @(posedge clk) disable iff (reset || $initstate)
    (!$past(reset) && ($past(in1) == 8'd0)) |-> (out == $past(in2))
  );

  // Equal operands produce an even sum.
  check_equal_operands_even_sum: assert property (
    @(posedge clk) disable iff (reset || $initstate)
    (!$past(reset) && ($past(in1) == $past(in2))) |-> (out[0] == 1'b0)
  );

  // 8-bit addition wraps on overflow.
  check_overflow_wrap_to_zero: assert property (
    @(posedge clk) disable iff (reset || $initstate)
    (!$past(reset) && ($past(in1) == 8'hFF) && ($past(in2) == 8'h01)) |-> (out == 8'h00)
  );

  // Max plus max produces 8'hFE.
  check_max_plus_max: assert property (
    @(posedge clk) disable iff (reset || $initstate)
    (!$past(reset) && ($past(in1) == 8'hFF) && ($past(in2) == 8'hFF)) |-> (out == 8'hFE)
  );

endmodule

rtl:
module counter (rstn, clk, up, down, count);
    // Default parameter. This can be overridden
    parameter WIDTH = 8;

    input rstn;
    input clk;
    input up;
    input down;
    output reg [WIDTH-1:0] count;

    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            count <= 0;
        end else begin
            if (up && !down) begin
                count <= count + 1;
            end else if (!up && down) begin
                count <= count - 1;
            end
        end
    end
endmodule

sva:
module counter_sva #(parameter WIDTH = 8) (
    input logic rstn,
    input logic clk,
    input logic up,
    input logic down,
    input logic [WIDTH-1:0] count
);

    // Active-low reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rstn |-> (count == {WIDTH{1'b0}})
    );

    // up without down increments count by one.
    check_increment_when_up_only: assert property (
        @(posedge clk) disable iff (!rstn)
        (up && !down) |=> (count == ($past(count) + 1'b1))
    );

    // down without up decrements count by one.
    check_decrement_when_down_only: assert property (
        @(posedge clk) disable iff (!rstn)
        (!up && down) |=> (count == ($past(count) - 1'b1))
    );

    // With neither input asserted, count holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (!rstn)
        (!up && !down) |=> (count == $past(count))
    );

    // With both inputs asserted, count holds its value.
    check_hold_when_up_and_down: assert property (
        @(posedge clk) disable iff (!rstn)
        (up && down) |=> (count == $past(count))
    );

endmodule

rtl:
module RippleCarryAdder(
    A,
    B,
    Cin,
    S,
    Cout
);

    input [3:0] A;
    input [3:0] B;
    input Cin;
    output [3:0] S;
    output Cout;

    wire [3:0] C;

    assign C = {1'b0, 1'b0, 1'b0, Cin};
    assign S = A ^ B ^ C;
    assign Cout = (A & B) | (C & (A ^ B));

endmodule

sva:
module RippleCarryAdder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] S,
    input logic       Cout
);

    // Combinational RTL is sampled on the formal global clock.

    // S must match the implemented XOR expression with Cin only on bit 0.
    check_sum_matches_rtl: assert property (
        @($global_clock) S == (A ^ B ^ {3'b000, Cin})
    );

    // Sum bit 0 includes the carry-in.
    check_sum_bit0_uses_cin: assert property (
        @($global_clock) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Sum bits 3:1 ignore carry-in because the internal C[3:1] are tied low.
    check_sum_upper_bits_ignore_cin: assert property (
        @($global_clock) S[3:1] == (A[3:1] ^ B[3:1])
    );

    // Cout is the implemented LSB carry term after scalar truncation.
    check_cout_matches_implemented_lsb_carry: assert property (
        @($global_clock) Cout == ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
    );

    // With Cin low, S reduces to A XOR B.
    check_sum_when_cin_zero: assert property (
        @($global_clock) (Cin == 1'b0) |-> (S == (A ^ B))
    );

    // With Cin low, Cout reduces to the LSB AND term.
    check_cout_when_cin_zero: assert property (
        @($global_clock) (Cin == 1'b0) |-> (Cout == (A[0] & B[0]))
    );

    // With Cin high, only S[0] is inverted relative to A XOR B.
    check_sum_when_cin_one: assert property (
        @($global_clock) (Cin == 1'b1) |-> (S == (A ^ B ^ 4'b0001))
    );

    // With Cin high, Cout reduces to the LSB OR term.
    check_cout_when_cin_one: assert property (
        @($global_clock) (Cin == 1'b1) |-> (Cout == (A[0] | B[0]))
    );

endmodule

rtl:
module logic_unit (
            opB, opA,
            op,
            result);

input [31:0] opA;
input [31:0] opB;
input [1:0] op;
output [31:0] result;

reg [31:0] logic_result;

always@(opA or opB or op )
    case(op)
        2'b00:
            logic_result=opA&opB;
        2'b01:
            logic_result=opA|opB;
        2'b10:
            logic_result=opA^opB;
        2'b11:
            logic_result=~(opA|opB);
    endcase

assign result=logic_result;

endmodule

sva:
module logic_unit_sva (
    input logic        clk,
    input logic [31:0] opB,
    input logic [31:0] opA,
    input logic [1:0]  op,
    input logic [31:0] result
);

    // AND mode drives result with opA & opB.
    check_and_operation: assert property (
        @(posedge clk) disable iff (1'b0)
        (op == 2'b00) |-> (result == (opA & opB))
    );

    // OR mode drives result with opA | opB.
    check_or_operation: assert property (
        @(posedge clk) disable iff (1'b0)
        (op == 2'b01) |-> (result == (opA | opB))
    );

    // XOR mode drives result with opA ^ opB.
    check_xor_operation: assert property (
        @(posedge clk) disable iff (1'b0)
        (op == 2'b10) |-> (result == (opA ^ opB))
    );

    // NOR mode drives result with ~(opA | opB).
    check_nor_operation: assert property (
        @(posedge clk) disable iff (1'b0)
        (op == 2'b11) |-> (result == ~(opA | opB))
    );

    // Unchanged inputs and opcode keep the output unchanged.
    check_stable_inputs_stable_result: assert property (
        @(posedge clk) disable iff (1'b0)
        ($stable(opA) && $stable(opB) && $stable(op)) |-> $stable(result)
    );

    // Any output change must be caused by an input or opcode change.
    check_result_change_has_cause: assert property (
        @(posedge clk) disable iff (1'b0)
        $changed(result) |-> ($changed(opA) || $changed(opB) || $changed(op))
    );

endmodule

module adder_sva(
    input logic signed [15:0] a,
    input logic signed [15:0] b,
    input logic clk,
    input logic rst,
    input logic signed [15:0] sum
);

    // Sum matches the operation taken on the previous clock edge.
    check_sum_matches_previous_cycle_operation: assert property (
        @(posedge clk)
        1'b1 |=> (sum == ($past(rst) ? 16'sd0 : ($past(a) + $past(b))))
    );

    // A reset cycle drives sum to zero.
    check_reset_clears_sum: assert property (
        @(posedge clk)
        rst |=> (sum == 16'sd0)
    );

    // A non-reset cycle loads the previous sum of a and b.
    check_sum_updates_after_nonreset_cycle: assert property (
        @(posedge clk) disable iff (rst)
        !rst |=> (sum == ($past(a) + $past(b)))
    );

    // With a equal to zero, sum passes through the previous value of b.
    check_zero_a_passes_b: assert property (
        @(posedge clk) disable iff (rst)
        (!rst && (a == 16'sd0)) |=> (sum == $past(b))
    );

    // With b equal to zero, sum passes through the previous value of a.
    check_zero_b_passes_a: assert property (
        @(posedge clk) disable iff (rst)
        (!rst && (b == 16'sd0)) |=> (sum == $past(a))
    );

endmodule

rtl:
module adder_mux (
    input [3:0] a,
    input [3:0] b,
    input control,
    output [3:0] sum
);

    wire [3:0] sum1, sum2;

    // First 4-bit adder
    four_bit_adder adder1(.a(a), .b(b), .sum(sum1));

    // Second 4-bit adder
    four_bit_adder adder2(.a(a), .b(b), .sum(sum2));

    // 2-to-1 multiplexer
    assign sum = control ? sum2 : sum1;

endmodule

module four_bit_adder (
    input [3:0] a,
    input [3:0] b,
    output [3:0] sum
);

    wire c1, c2, c3;

    full_adder adder0(.a(a[0]), .b(b[0]), .cin(0), .sum(sum[0]), .cout(c1));
    full_adder adder1(.a(a[1]), .b(b[1]), .cin(c1), .sum(sum[1]), .cout(c2));
    full_adder adder2(.a(a[2]), .b(b[2]), .cin(c2), .sum(sum[2]), .cout(c3));
    full_adder adder3(.a(a[3]), .b(b[3]), .cin(c3), .sum(sum[3]), .cout());

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

sva:
module adder_mux_sva (
    input logic       clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic       control,
    input logic [3:0] sum
);

    // Output must equal the 4-bit sum of a and b.
    check_sum_matches_four_bit_addition: assert property (
        @(posedge clk) (sum == (a + b))
    );

    // With control low, the selected path still produces a+b.
    check_control_low_matches_addition: assert property (
        @(posedge clk) (!control) |-> (sum == (a + b))
    );

    // With control high, the selected path still produces a+b.
    check_control_high_matches_addition: assert property (
        @(posedge clk) control |-> (sum == (a + b))
    );

    // Bit 0 follows the full-adder equation with cin tied low.
    check_lsb_matches_full_adder_equation: assert property (
        @(posedge clk) (sum[0] == (a[0] ^ b[0]))
    );

    // The low two bits match a 2-bit addition.
    check_low_two_bits_match_partial_addition: assert property (
        @(posedge clk) (sum[1:0] == (a[1:0] + b[1:0]))
    );

    // The low three bits match a 3-bit addition.
    check_low_three_bits_match_partial_addition: assert property (
        @(posedge clk) (sum[2:0] == (a[2:0] + b[2:0]))
    );

    // Adding zero on b preserves a.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (b == 4'h0) |-> (sum == a)
    );

    // Adding zero on a preserves b.
    check_zero_a_passthrough: assert property (
        @(posedge clk) (a == 4'h0) |-> (sum == b)
    );

    // Toggling only control does not change the observed sum.
    check_control_toggle_does_not_change_sum: assert property (
        @(posedge clk) disable iff ($initstate)
        ($changed(control) && $stable(a) && $stable(b)) |-> $stable(sum)
    );

    // If all inputs are stable, the combinational output stays stable.
    check_stable_inputs_hold_sum: assert property (
        @(posedge clk) disable iff ($initstate)
        ($stable(a) && $stable(b) && $stable(control)) |-> $stable(sum)
    );

endmodule

rtl:

module debounce(
    clk,
    PB,
    PB_state
);
	input clk;
	input PB;
	output PB_state;

reg init_state = 1'b0;
reg PB_state = 1'b0;

reg [11:0] PB_cnt = 12'd0;
wire PB_cnt_max = &PB_cnt;
wire PB_idle = (PB_cnt == 12'd0);
wire PB_changed = (PB != init_state);

always @(posedge clk)
if(PB_idle & PB_changed)
begin
	init_state = PB;
	PB_cnt = 12'd1;
end
else if(PB_cnt_max)
begin
	PB_state = init_state;
	PB_cnt = 12'd0;
end
else if(~PB_idle)
	PB_cnt = PB_cnt + 12'd1;

endmodule

