module up_counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count
);

    // Reset drives the counter to zero.
    check_reset_drives_zero: assert property (
        @(posedge clk) disable iff ($initstate && !rst)
        !rst |-> (count == 4'd0)
    );

    // The first sampled cycle after reset release still shows zero.
    check_release_keeps_zero: assert property (
        @(posedge clk) disable iff (!rst)
        (!$initstate && $rose(rst)) |-> (count == 4'd0)
    );

    // Across sampled active cycles, count either increments or is zeroed by async reset.
    check_active_transition_is_increment_or_zero: assert property (
        @(posedge clk) disable iff (!rst)
        (!$initstate && $past(rst)) |-> ((count == 4'd0) || (count == ($past(count) + 4'd1)))
    );

    // A sampled value of 15 wraps to zero on the next active clock.
    check_wraps_from_f_to_zero: assert property (
        @(posedge clk) disable iff (!rst)
        (!$initstate && $past(rst) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

endmodule

rtl:
module der_misc
	(
	input		de_clk,		
	input		hb_clk,		
	input		prst,		
	input		cr_pulse,
	input [1:0] 	ps_sel_2,	input		bc_co,
	input [31:0] 	mf_sorg_2,      
	input [31:0] 	mf_dorg_2,      
	input [1:0] 	apat_1,
	input		sd_selector,	output	reg		prst_1,
	output 			hb_ca_rdy,
	output 			de_ca_rdy,
	output 			ps16s_2,
	output 			ps565s_2,
	output		[31:0]	de_sorg_2,      
	output		[31:0]	de_dorg_2,      
	output		[27:0]	sorg_2,         
	output		[27:0]	dorg_2,         
	output			or_apat_1
	);

  assign 	or_apat_1 = |apat_1;

  always @(posedge de_clk) prst_1 <= prst;

  assign 	ps16s_2  = ~ps_sel_2[1] &  ps_sel_2[0];
  assign 	ps565s_2 = &ps_sel_2[1:0];



  assign hb_ca_rdy = 1'b1;
  assign  de_ca_rdy = 1'b1;
  assign de_sorg_2 = {32{sd_selector}} & mf_sorg_2;
  assign de_dorg_2 = {32{sd_selector}} & mf_dorg_2;
  assign sorg_2 = {28{~sd_selector}} & {6'h0, mf_sorg_2[25:4]};
  assign dorg_2 = {28{~sd_selector}} & {6'h0, mf_dorg_2[25:4]};

endmodule

sva:
module der_misc_sva (
    input  logic        de_clk,
    input  logic        hb_clk,
    input  logic        prst,
    input  logic        cr_pulse,
    input  logic [1:0]  ps_sel_2,
    input  logic        bc_co,
    input  logic [31:0] mf_sorg_2,
    input  logic [31:0] mf_dorg_2,
    input  logic [1:0]  apat_1,
    input  logic        sd_selector,
    input  logic        prst_1,
    input  logic        hb_ca_rdy,
    input  logic        de_ca_rdy,
    input  logic        ps16s_2,
    input  logic        ps565s_2,
    input  logic [31:0] de_sorg_2,
    input  logic [31:0] de_dorg_2,
    input  logic [27:0] sorg_2,
    input  logic [27:0] dorg_2,
    input  logic        or_apat_1
);
    // prst_1 is a de_clk-registered copy of prst (1-cycle delay).
    check_prst_1_registers_prst: assert property (
        @(posedge de_clk) disable iff (prst) prst_1 == $past(prst)
    );

    // or_apat_1 is the reduction-OR of apat_1.
    check_or_apat_1_reduce: assert property (
        @(posedge de_clk) disable iff (prst) or_apat_1 == (|apat_1)
    );

    // ps16s_2 decodes ps_sel_2 == 2'b01.
    check_ps16s_decode: assert property (
        @(posedge de_clk) disable iff (prst) ps16s_2 == (~ps_sel_2[1] & ps_sel_2[0])
    );

    // ps565s_2 decodes ps_sel_2 == 2'b11.
    check_ps565s_decode: assert property (
        @(posedge de_clk) disable iff (prst) ps565s_2 == (&ps_sel_2)
    );

    // The two decodes are mutually exclusive.
    check_ps_decode_mutex: assert property (
        @(posedge de_clk) disable iff (prst) !(ps16s_2 && ps565s_2)
    );

    // hb_ca_rdy is constantly HIGH.
    check_hb_ca_rdy_const_high: assert property (
        @(posedge de_clk) disable iff (prst) hb_ca_rdy == 1'b1
    );

    // de_ca_rdy is constantly HIGH.
    check_de_ca_rdy_const_high: assert property (
        @(posedge de_clk) disable iff (prst) de_ca_rdy == 1'b1
    );

    // de_sorg_2 passes mf_sorg_2 when sd_selector is 1.
    check_de_sorg_when_sel1: assert property (
        @(posedge de_clk) disable iff (prst) sd_selector |-> (de_sorg_2 == mf_sorg_2)
    );

    // de_sorg_2 is zero when sd_selector is 0.
    check_de_sorg_when_sel0: assert property (
        @(posedge de_clk) disable iff (prst) !sd_selector |-> (de_sorg_2 == 32'b0)
    );

    // de_dorg_2 passes mf_dorg_2 when sd_selector is 1.
    check_de_dorg_when_sel1: assert property (
        @(posedge de_clk) disable iff (prst) sd_selector |-> (de_dorg_2 == mf_dorg_2)
    );

    // de_dorg_2 is zero when sd_selector is 0.
    check_de_dorg_when_sel0: assert property (
        @(posedge de_clk) disable iff (prst) !sd_selector |-> (de_dorg_2 == 32'b0)
    );

    // sorg_2 equals {6'h0, mf_sorg_2[25:4]} when sd_selector is 0.
    check_sorg2_when_sel0: assert property (
        @(posedge de_clk) disable iff (prst) !sd_selector |-> (sorg_2 == {6'h0, mf_sorg_2[25:4]})
    );

    // sorg_2 is zero when sd_selector is 1.
    check_sorg2_when_sel1: assert property (
        @(posedge de_clk) disable iff (prst) sd_selector |-> (sorg_2 == 28'b0)
    );

    // dorg_2 equals {6'h0, mf_dorg_2[25:4]} when sd_selector is 0.
    check_dorg2_when_sel0: assert property (
        @(posedge de_clk) disable iff (prst) !sd_selector |-> (dorg_2 == {6'h0, mf_dorg_2[25:4]})
    );

    // dorg_2 is zero when sd_selector is 1.
    check_dorg2_when_sel1: assert property (
        @(posedge de_clk) disable iff (prst) sd_selector |-> (dorg_2 == 28'b0)
    );
endmodule

rtl:
module top_module (
    Y,
    A1,
    A2,
    A3,
    B1
);

    // Module ports
    output Y ;
    input  A1;
    input  A2;
    input  A3;
    input  B1;

    assign Y = ~((A1 & A2 & A3) | B1); 



endmodule

sva:
module top_module_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1
);
    ///// Functional correctness /////
    // Y equals ~((A1 & A2 & A3) | B1).
    check_function_equation: assert property (
        @(posedge A1 or negedge A1 or
          posedge A2 or negedge A2 or
          posedge A3 or negedge A3 or
          posedge B1 or negedge B1)
        Y == ~((A1 & A2 & A3) | B1)
    );

    // If Y is HIGH, B1 must be LOW and at least one Ai is LOW.
    check_y_high_requires_inputs: assert property (
        @(posedge A1 or negedge A1 or
          posedge A2 or negedge A2 or
          posedge A3 or negedge A3 or
          posedge B1 or negedge B1)
        (Y == 1'b1) |-> ((B1 == 1'b0) && ((A1 == 1'b0) || (A2 == 1'b0) || (A3 == 1'b0)))
    );

    // If B1 is LOW and at least one Ai is LOW, Y must be HIGH.
    check_inputs_imply_y_high: assert property (
        @(posedge A1 or negedge A1 or
          posedge A2 or negedge A2 or
          posedge A3 or negedge A3 or
          posedge B1 or negedge B1)
        ((B1 == 1'b0) && ((A1 == 1'b0) || (A2 == 1'b0) || (A3 == 1'b0))) |-> (Y == 1'b1)
    );

    // If B1 is HIGH, Y must be LOW.
    check_b1_high_forces_y_low: assert property (
        @(posedge A1 or negedge A1 or
          posedge A2 or negedge A2 or
          posedge A3 or negedge A3 or
          posedge B1 or negedge B1)
        (B1 == 1'b1) |-> (Y == 1'b0)
    );

    // If all A inputs are HIGH, Y must be LOW.
    check_all_a_high_forces_y_low: assert property (
        @(posedge A1 or negedge A1 or
          posedge A2 or negedge A2 or
          posedge A3 or negedge A3 or
          posedge B1 or negedge B1)
        ((A1 == 1'b1) && (A2 == 1'b1) && (A3 == 1'b1)) |-> (Y == 1'b0)
    );

    // Y and B1 cannot both be HIGH.
    check_y_and_b1_mutex: assert property (
        @(posedge A1 or negedge A1 or
          posedge A2 or negedge A2 or
          posedge A3 or negedge A3 or
          posedge B1 or negedge B1)
        !(Y && B1)
    );
endmodule

rtl:
module sky130_fd_sc_hdll__and3b (
    X  ,
    A_N,
    B  ,
    C
);

    output X  ;
    input  A_N;
    input  B  ;
    input  C  ;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire not0_out  ;
    wire and0_out_X;

    not not0 (not0_out  , A_N            );
    and and0 (and0_out_X, C, not0_out, B );
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_hdll__and3b_sva (
    input  logic clk,
    input  logic X,
    input  logic A_N,
    input  logic B,
    input  logic C
);
    // X equals (~A_N & B & C).
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((~A_N) & B & C)
    );

    // X high implies B&C are 1 and A_N is 0.
    check_x_high_implies_inputs: assert property (
        @(posedge clk) X |-> (B && C && !A_N)
    );

    // When !A_N & B & C, X must be high.
    check_inputs_imply_x_high: assert property (
        @(posedge clk) (!A_N && B && C) |-> X
    );

    // A_N high forces X low.
    check_an_high_forces_x_low: assert property (
        @(posedge clk) A_N |-> !X
    );

    // B low forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

    // C low forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

    // X can only rise when B&C=1 and A_N=0.
    check_rise_requires_inputs_true: assert property (
        @(posedge clk) $rose(X) |-> (B && C && !A_N)
    );

    // X can only fall when at least one disabling input is active.
    check_fall_requires_any_input_false: assert property (
        @(posedge clk) $fell(X) |-> (A_N || !B || !C)
    );

    // Any disabling input active implies X low.
    check_any_disable_implies_x_low: assert property (
        @(posedge clk) (A_N || !B || !C) |-> !X
    );
endmodule

rtl:
module three_to_one (
    input A1,
    input A2,
    input B1,
    output Y,
    input clk
);

    reg Y_reg;

    always @(posedge clk) begin
        if (A1 && A2) begin
            Y_reg <= 1;
        end else if (!A1 && !A2) begin
            Y_reg <= 0;
        end else if (A1 && !A2) begin
            Y_reg <= ~B1;
        end else begin
            Y_reg <= B1;
        end
    end

    assign Y = Y_reg;

endmodule

sva:
module three_to_one_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic Y,
    input logic clk
);
    // When A1 and A2 are both 1 at a clock edge, Y must be 1 on the next edge.
    check_y_next_both_one: assert property (
        @(posedge clk) (A1 && A2) |=> (Y == 1'b1)
    );

    // When A1 and A2 are both 0 at a clock edge, Y must be 0 on the next edge.
    check_y_next_both_zero: assert property (
        @(posedge clk) (!A1 && !A2) |=> (Y == 1'b0)
    );

    // When A1=1 and A2=0 at a clock edge, Y must be ~B1 from that edge on the next edge.
    check_y_next_a1_1_a2_0: assert property (
        @(posedge clk) (A1 && !A2) |=> (Y == ~($past(B1)))
    );

    // When A1=0 and A2=1 at a clock edge, Y must be B1 from that edge on the next edge.
    check_y_next_a1_0_a2_1: assert property (
        @(posedge clk) (!A1 && A2) |=> (Y == $past(B1))
    );

    // On every cycle, next Y equals the RTL's full priority case using prior-cycle inputs.
    check_y_next_functional: assert property (
        @(posedge clk) 1'b1 |=> (Y == (
            ($past(A1) && $past(A2)) ? 1'b1 :
            ((!$past(A1) && !$past(A2)) ? 1'b0 :
            (($past(A1) && !$past(A2)) ? ~($past(B1)) : $past(B1)))
        ))
    );

    // When A1 != A2 at a clock edge, next Y equals B1 XOR A1 from that edge.
    check_y_next_when_mismatch_xor: assert property (
        @(posedge clk) (A1 ^ A2) |=> (Y == ($past(B1) ^ $past(A1)))
    );

    // When A1 == A2 at a clock edge, next Y equals A1 from that edge (independent of B1).
    check_y_next_when_equal_matches_a1: assert property (
        @(posedge clk) (A1 == A2) |=> (Y == $past(A1))
    );
endmodule

rtl:
module td_mode_generator (
  input [8:0] ctrl,
  output reg [3:0] td_mode
);

  always @ (ctrl) begin
    case (ctrl[8:6])
      3'b000: td_mode = 4'b0000;
      3'b001: td_mode = 4'b1000;
      3'b010: td_mode = 4'b0100;
      3'b011: td_mode = 4'b1100;
      3'b100: td_mode = 4'b0010;
      3'b101: td_mode = 4'b1010;
      3'b110: td_mode = 4'b0101;
      3'b111: td_mode = 4'b1111;
      default: td_mode = 4'b0000;
    endcase
  end

endmodule

sva:
module td_mode_generator_sva (
    input logic clk,              // External clock for SVA sampling (RTL is combinational)
    input logic [8:0] ctrl,
    input logic [3:0] td_mode
);
    ///// Combinational decode mapping checks /////
    // When ctrl[8:6]==000, td_mode must be 0000.
    check_decode_000: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b000) |-> (td_mode == 4'b0000)
    );
    // When ctrl[8:6]==001, td_mode must be 1000.
    check_decode_001: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b001) |-> (td_mode == 4'b1000)
    );
    // When ctrl[8:6]==010, td_mode must be 0100.
    check_decode_010: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b010) |-> (td_mode == 4'b0100)
    );
    // When ctrl[8:6]==011, td_mode must be 1100.
    check_decode_011: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b011) |-> (td_mode == 4'b1100)
    );
    // When ctrl[8:6]==100, td_mode must be 0010.
    check_decode_100: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b100) |-> (td_mode == 4'b0010)
    );
    // When ctrl[8:6]==101, td_mode must be 1010.
    check_decode_101: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b101) |-> (td_mode == 4'b1010)
    );
    // When ctrl[8:6]==110, td_mode must be 0101.
    check_decode_110: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b110) |-> (td_mode == 4'b0101)
    );
    // When ctrl[8:6]==111, td_mode must be 1111.
    check_decode_111: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b111) |-> (td_mode == 4'b1111)
    );

    ///// Output value constraints /////
    // td_mode must always be one of the defined decode values.
    check_td_mode_value_set: assert property (
        @(posedge clk) disable iff (1'b0) td_mode inside {4'b0000,4'b1000,4'b0100,4'b1100,4'b0010,4'b1010,4'b0101,4'b1111}
    );

    ///// Dependency and stability checks /////
    // Changes in ctrl[8:6] must cause a change in td_mode (unique mapping).
    check_output_changes_with_key_input: assert property (
        @(posedge clk) disable iff (1'b0) $changed(ctrl[8:6]) |-> $changed(td_mode)
    );
    // td_mode may only change when ctrl[8:6] changes.
    check_no_spurious_output_change: assert property (
        @(posedge clk) disable iff (1'b0) $changed(td_mode) |-> $changed(ctrl[8:6])
    );
    // Changes in lower ctrl bits [5:0] alone must not change td_mode.
    check_lower_bits_irrelevant: assert property (
        @(posedge clk) disable iff (1'b0) ($changed(ctrl[5:0]) && !$changed(ctrl[8:6])) |-> !$changed(td_mode)
    );
endmodule

rtl:
module carry_select_adder_32bit (A, B, Cin, S);
  input [31:0] A;
  input [31:0] B;
  input Cin;
  output [31:0] S;

  // Generate the sum and carry for each bit
  wire [31:0] sum, carry;
  genvar i;
  generate
    for (i = 0; i < 32; i = i + 1) begin: full_adder_instances
      full_adder fa (
        .A(A[i]),
        .B(B[i]),
        .Cin(Cin),
        .S(sum[i]),
        .Cout(carry[i])
      );
    end
  endgenerate

  // Select the correct sum and carry based on the input carry
  assign S = Cin ? sum : carry;

endmodule

module full_adder (A, B, Cin, S, Cout);
  input A, B, Cin;
  output S, Cout;

  assign S = A ^ B ^ Cin;
  assign Cout = (A & B) | (A & Cin) | (B & Cin);
endmodule

sva:
module carry_select_adder_32bit_sva (
    input logic [31:0] A,
    input logic [31:0] B,
    input logic        Cin,
    input logic [31:0] S
);
    ///// Functional correctness /////
    // When Cin is 1, S equals bitwise XNOR of A and B.
    check_s_eq_xnor_when_cin_high: assert property (
        @(posedge Cin) disable iff (1'b0) (Cin) |-> (S == ~(A ^ B))
    );

    // When Cin is 0, S equals bitwise AND of A and B.
    check_s_eq_and_when_cin_low: assert property (
        @(negedge Cin) disable iff (1'b0) (!Cin) |-> (S == (A & B))
    );

    // When inputs are known (no X/Z), output S is known.
    check_s_known_when_inputs_known: assert property (
        @(posedge Cin) disable iff (1'b0) (!$isunknown({A,B,Cin})) |-> (!$isunknown(S))
    );

    ///// Useful special cases derived from the logic /////
    // With Cin=1 and A==B, S is all ones (XNOR true).
    check_allones_when_cin_high_and_a_eq_b: assert property (
        @(posedge Cin) disable iff (1'b0) (Cin && (A == B)) |-> (S == {32{1'b1}})
    );

    // With Cin=1 and A==~B, S is all zeros (XNOR false).
    check_allzeros_when_cin_high_and_a_eq_notb: assert property (
        @(posedge Cin) disable iff (1'b0) (Cin && (A == ~B)) |-> (S == 32'b0)
    );

    // With Cin=0 and B all ones, S equals A (A & all1 = A).
    check_s_eq_a_when_cin_low_and_b_allones: assert property (
        @(negedge Cin) disable iff (1'b0) (!Cin && (B == {32{1'b1}})) |-> (S == A)
    );

    // With Cin=0 and A all ones, S equals B (all1 & B = B).
    check_s_eq_b_when_cin_low_and_a_allones: assert property (
        @(negedge Cin) disable iff (1'b0) (!Cin && (A == {32{1'b1}})) |-> (S == B)
    );

    // With Cin=0 and either operand all zeros, S is all zeros.
    check_s_zero_when_cin_low_and_any_zero: assert property (
        @(negedge Cin) disable iff (1'b0) (!Cin && ((A == 32'b0) || (B == 32'b0))) |-> (S == 32'b0)
    );
endmodule

rtl:
module PADIN (output padout, input padin);
   assign padout = padin;
endmodule

module PADOUT (output padout, input padin, input oe);
   assign padout  = padin;
   assign oe = oe;
endmodule

module LUT4 (output dout,
             input  din0, din1, din2, din3);

parameter [15:0] lut_function = 16'hFFFF;
reg combout_rt;
wire dataa_w;
wire datab_w;
wire datac_w;
wire datad_w;

assign dataa_w = din0;
assign datab_w = din1;
assign datac_w = din2;
assign datad_w = din3;

function lut_data;
input [15:0] mask;
input        dataa, datab, datac, datad;
reg [7:0]   s3;
reg [3:0]   s2;
reg [1:0]   s1;
  begin
       s3 = datad ? mask[15:8] : mask[7:0];
       s2 = datac ?   s3[7:4]  :   s3[3:0];
       s1 = datab ?   s2[3:2]  :   s2[1:0];
       lut_data = dataa ? s1[1] : s1[0];
  end
endfunction

always @(dataa_w or datab_w or datac_w or datad_w) begin
   combout_rt = lut_data(lut_function, dataa_w, datab_w,
                         datac_w, datad_w);
end
assign dout = combout_rt & 1'b1;
endmodule

module DFF (output q,
            input  d, ck);
   reg             q;
   always @(posedge ck)
     q <= d;

endmodule

sva:
module DFF_sva (
    input logic q,
    input logic d,
    input logic ck
);
    // q must equal d from the previous rising edge (1-cycle latency).
    check_q_updates_from_prev_d: assert property (
        @(posedge ck) !$isunknown($past(d)) |-> (q == $past(d))
    );

    // If d did not change across the last two cycles, q did not change in the last cycle.
    check_q_stable_when_prev_d_stable: assert property (
        @(posedge ck) (!$isunknown($past(d)) && !$isunknown($past(d,2)) && !$isunknown(q) && !$isunknown($past(q)) && ($past(d) == $past(d,2))) |-> (q == $past(q))
    );

    // q change between this and last cycle matches d change between the previous two cycles.
    check_q_change_matches_prev_d_change: assert property (
        @(posedge ck) (!$isunknown($past(d)) && !$isunknown($past(d,2)) && !$isunknown(q) && !$isunknown($past(q))) |-> ($changed(q) == ($past(d) != $past(d,2)))
    );

    // If d toggled at this edge, q must differ from d (since q reflects previous d).
    check_q_differs_from_d_when_d_toggled: assert property (
        @(posedge ck) (!$isunknown(d) && !$isunknown($past(d)) && (d != $past(d))) |-> (q != d)
    );

    // If d is stable across this edge, q must equal d at this edge.
    check_q_equals_d_when_d_stable: assert property (
