module top_module (
    input clk,
    input reset,
    input data,
    output q
);

wire [2:0] shift_reg_out;
wire d_ff_out;

shift_register shift_reg(
    .clk(clk),
    .reset(reset),
    .data(data),
    .q(shift_reg_out)
);

d_ff d_ff(  // Fixed the spelling
    .clk(clk),
    .reset(reset),
    .d(shift_reg_out[2]),
    .q(d_ff_out)
);

assign q = shift_reg_out[2] ^ d_ff_out;

