module shift_register(
    input clk,
    input reset,
    input data,
    output reg [2:0] q
);

always @(posedge clk) begin // Changed negative edge to positive edge for posedge
    if (reset) begin
        q <= 3'b0;
    end else begin
        q <= {q[1:0], data};
    end
end

endmodule

module d_ff (
    input clk,
    input reset,
    input d,
    output reg q
);

always @(posedge clk) begin // Changed negative edge to positive edge for posedge
    if (reset) begin
        q <= 1'b0;
    end else begin
        q <= d;
    end
end

endmodule

