    input [3:0] data5,
    output reg [7:0] sum_out
);

reg out_2to1_mux;
wire [3:0] out_6to1_mux;

always @(posedge clk) begin
    if (sel_b1 && sel_b2)
        out_2to1_mux <= b;
    else
        out_2to1_mux <= a;
end

mux_6to1 mux_inst (
    .sel(sel),
    .data0(data0),
    .data1(data1),
    .data2(data2),
    .data3(data3),
    .data4(data4),
    .data5(data5),
    .out(out_6to1_mux)
);

always @(posedge clk) begin
    sum_out <= out_2to1_mux + out_6to1_mux;
end

