rtl:
module mux2to1 (
  in1, // input 1
  in2, // input 2
  sel, // select input
  out // output
);

	input in1, in2, sel;
	output out;

	assign out = sel ? in2 : in1;

endmodule

sva:
module mux2to1_sva (
    input logic clk,
    input logic in1,
    input logic in2,
    input logic sel,
    input logic out
);
    // Output equals selected input every cycle.
    check_mux_function: assert property (
        @(posedge clk) disable iff (1'b0) out == (sel ? in2 : in1)
    );

    // When sel is 0, out equals in1.
    check_sel0_path: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 1'b0) |-> (out == in1)
    );

    // When sel is 1, out equals in2.
    check_sel1_path: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 1'b1) |-> (out == in2)
    );

    // Out is always equal to one of the inputs.
    check_out_is_one_of_inputs: assert property (
        @(posedge clk) disable iff (1'b0) ((out == in1) || (out == in2))
    );

    // Out changes only if sel or the selected input changes.
    check_out_change_causes: assert property (
        @(posedge clk) disable iff (1'b0) $changed(out) |-> ($changed(sel) || (sel ? $changed(in2) : $changed(in1)))
    );

    // If all inputs are stable, out remains stable.
    check_out_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (1'b0) ($stable(sel) && $stable(in1) && $stable(in2)) |-> $stable(out)
    );

    // If out differs from in1, sel must be 1.
    check_out_ne_in1_implies_sel1: assert property (
        @(posedge clk) disable iff (1'b0) (out != in1) |-> (sel == 1'b1)
    );

    // If out differs from in2, sel must be 0.
    check_out_ne_in2_implies_sel0: assert property (
        @(posedge clk) disable iff (1'b0) (out != in2) |-> (sel == 1'b0)
    );

    // With sel=0 and stable, an out change implies in1 changed.
    check_sel0_out_change_implies_in1_change: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 1'b0 && $stable(sel) && $changed(out)) |-> $changed(in1)
    );

    // With sel=1 and stable, an out change implies in2 changed.
    check_sel1_out_change_implies_in2_change: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 1'b1 && $stable(sel) && $changed(out)) |-> $changed(in2)
    );

    // If sel toggles and inputs are equal, out does not change.
    check_sel_toggle_equal_inputs_no_out_change: assert property (
        @(posedge clk) disable iff (1'b0) ($changed(sel) && $stable(in1) && $stable(in2) && (in1 == in2)) |-> !$changed(out)
    );

    // If sel toggles and inputs differ, out changes.
    check_sel_toggle_diff_inputs_out_change: assert property (
        @(posedge clk) disable iff (1'b0) ($changed(sel) && $stable(in1) && $stable(in2) && (in1 != in2)) |-> $changed(out)
    );
endmodule

rtl:
module custom_module (
    X ,
    A1,
    A2,
    A3,
    A4,
    B1
);

    output X ;
    input  A1;
    input  A2;
    input  A3;
    input  A4;
    input  B1;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire xor1, xor2, xor3, xor4, xor5;

    xnor (xor1, A1, A2, A3, A4, B1);

    assign xor2 = xor1 ^ A2;
    assign xor3 = xor2 ^ A3;
    assign xor4 = xor3 ^ A4;
    assign xor5 = xor4 ^ B1;
    assign X = xor5;

endmodule

sva:
module custom_module_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic B1
);
    // On A1 rising, X must be 0 (X = ~A1).
    x_eq_not_a1_on_a1_rise: assert property (
        @(posedge A1) (X == 1'b0)
    );

    // On A1 falling, X must be 1 (X = ~A1).
    x_eq_not_a1_on_a1_fall: assert property (
        @(negedge A1) (X == 1'b1)
    );

    // X equals ~A1 on A2 rising.
    x_eq_not_a1_on_a2_rise: assert property (
        @(posedge A2) (X == ~A1)
    );

    // X equals ~A1 on A2 falling.
    x_eq_not_a1_on_a2_fall: assert property (
        @(negedge A2) (X == ~A1)
    );

    // X equals ~A1 on A3 rising.
    x_eq_not_a1_on_a3_rise: assert property (
        @(posedge A3) (X == ~A1)
    );

    // X equals ~A1 on A3 falling.
    x_eq_not_a1_on_a3_fall: assert property (
        @(negedge A3) (X == ~A1)
    );

    // X equals ~A1 on A4 rising.
    x_eq_not_a1_on_a4_rise: assert property (
        @(posedge A4) (X == ~A1)
    );

    // X equals ~A1 on A4 falling.
    x_eq_not_a1_on_a4_fall: assert property (
        @(negedge A4) (X == ~A1)
    );

    // X equals ~A1 on B1 rising.
    x_eq_not_a1_on_b1_rise: assert property (
        @(posedge B1) (X == ~A1)
    );

    // X equals ~A1 on B1 falling.
    x_eq_not_a1_on_b1_fall: assert property (
        @(negedge B1) (X == ~A1)
    );
endmodule

rtl:
module pipeline_register(
    input clock,
    input reset,
    input IF_Flush,
    input IF_Stall,
    input ID_Stall,
    input [31:0] IF_Instruction,
    input [31:0] IF_PCAdd4,
    input [31:0] IF_PC,
    input IF_IsBDS,
    input [31:0] ID_Instruction,
    input [31:0] ID_PCAdd4,
    input [31:0] ID_RestartPC,
    input ID_IsBDS,
    input ID_IsFlushed,
    output reg [31:0] vote_ID_Instruction,
    output reg [31:0] vote_ID_PCAdd4,
    output reg [31:0] vote_ID_RestartPC,
    output reg vote_ID_IsBDS,
    output reg vote_ID_IsFlushed
);

    always @(posedge clock) begin
        if (reset) begin
            vote_ID_Instruction <= 32'b0;
            vote_ID_PCAdd4 <= 32'b0;
            vote_ID_RestartPC <= 32'b0;
            vote_ID_IsBDS <= 1'b0;
            vote_ID_IsFlushed <= 1'b0;
        end else begin
            if (ID_Stall) begin
                vote_ID_Instruction <= ID_Instruction;
                vote_ID_PCAdd4 <= ID_PCAdd4;
                vote_ID_IsBDS <= ID_IsBDS;
                vote_ID_RestartPC <= ID_RestartPC;
                vote_ID_IsFlushed <= ID_IsFlushed;
            end else begin
                if (IF_Stall | IF_Flush) begin
                    vote_ID_Instruction <= 32'b0;
                    vote_ID_PCAdd4 <= 32'b0;
                end else begin
                    vote_ID_Instruction <= IF_Instruction;
                    vote_ID_PCAdd4 <= IF_PCAdd4;
                end
                if (ID_IsFlushed | IF_IsBDS) begin
                    vote_ID_RestartPC <= ID_RestartPC;
                end else begin
                    vote_ID_RestartPC <= IF_PC;
                end
                vote_ID_IsBDS <= ID_IsBDS;
                vote_ID_IsFlushed <= ID_IsFlushed;
            end
        end
    end

endmodule

sva:
module pipeline_register_sva (
    input logic clock,
    input logic reset,
    input logic IF_Flush,
    input logic IF_Stall,
    input logic ID_Stall,
    input logic [31:0] IF_Instruction,
    input logic [31:0] IF_PCAdd4,
    input logic [31:0] IF_PC,
    input logic IF_IsBDS,
    input logic [31:0] ID_Instruction,
    input logic [31:0] ID_PCAdd4,
    input logic [31:0] ID_RestartPC,
    input logic ID_IsBDS,
    input logic ID_IsFlushed,
    input logic [31:0] vote_ID_Instruction,
    input logic [31:0] vote_ID_PCAdd4,
    input logic [31:0] vote_ID_RestartPC,
    input logic vote_ID_IsBDS,
    input logic vote_ID_IsFlushed
);
    // On reset, all outputs clear to zero on the next cycle.
    reset_clears_outputs: assert property (
        @(posedge clock) reset |=> (vote_ID_Instruction == 32'b0)
                            && (vote_ID_PCAdd4 == 32'b0)
                            && (vote_ID_RestartPC == 32'b0)
                            && (vote_ID_IsBDS == 1'b0)
                            && (vote_ID_IsFlushed == 1'b0)
    );

    // When ID_Stall is asserted, data fields capture from ID_* on the next cycle.
    id_stall_captures_id_data: assert property (
        @(posedge clock) disable iff (reset)
            ID_Stall |=> (vote_ID_Instruction == $past(ID_Instruction))
                      && (vote_ID_PCAdd4    == $past(ID_PCAdd4))
                      && (vote_ID_RestartPC == $past(ID_RestartPC))
    );

    // When !ID_Stall and IF_Stall or IF_Flush, instruction and PCAdd4 zero on next cycle.
    zero_if_fields_on_if_stall_or_flush: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && (IF_Stall || IF_Flush)) |=> (vote_ID_Instruction == 32'b0)
                                                  && (vote_ID_PCAdd4 == 32'b0)
    );

    // When !ID_Stall and no IF_Stall/Flush, instruction and PCAdd4 pass through from IF_*.
    pass_if_fields_when_no_if_controls: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && !(IF_Stall || IF_Flush)) |=> (vote_ID_Instruction == $past(IF_Instruction))
                                                   && (vote_ID_PCAdd4    == $past(IF_PCAdd4))
    );

    // When !ID_Stall and (ID_IsFlushed or IF_IsBDS), RestartPC comes from ID_RestartPC.
    restartpc_selects_id_on_flush_or_bds: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && (ID_IsFlushed || IF_IsBDS)) |=> (vote_ID_RestartPC == $past(ID_RestartPC))
    );

    // When !ID_Stall and not (ID_IsFlushed or IF_IsBDS), RestartPC comes from IF_PC.
    restartpc_selects_if_on_normal_flow: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && !(ID_IsFlushed || IF_IsBDS)) |=> (vote_ID_RestartPC == $past(IF_PC))
    );

    // vote_ID_IsBDS always reflects prior-cycle ID_IsBDS (outside reset).
    flags_follow_id_isbds: assert property (
        @(posedge clock) disable iff (reset)
            1'b1 |=> (vote_ID_IsBDS == $past(ID_IsBDS))
    );

    // vote_ID_IsFlushed always reflects prior-cycle ID_IsFlushed (outside reset).
    flags_follow_id_isflushed: assert property (
        @(posedge clock) disable iff (reset)
            1'b1 |=> (vote_ID_IsFlushed == $past(ID_IsFlushed))
    );
endmodule

module counter_with_load_reset_sva (
    input  logic [3:0] DATA_IN,
    input  logic       LOAD,
    input  logic       CLK,
    input  logic       RESET,
    input  logic [3:0] COUNT
);
    ///// Reset behavior /////
    // When RESET is asserted low, COUNT must be 0.
    check_reset_drives_zero: assert property (
        @(posedge CLK) (!RESET) |-> (COUNT == 4'd0)
    );

    ///// Next-state behavior /////
    // General next-state: after a non-reset cycle, COUNT matches LOAD/Data/Inc from previous cycle.
    check_next_state_function: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) |-> COUNT == ($past(LOAD) ? $past(DATA_IN) : (($past(COUNT) + 4'd1) & 4'hF))
    );

    // LOAD=1 loads DATA_IN on the next cycle.
    check_load_updates_next: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && $past(LOAD) |-> (COUNT == $past(DATA_IN))
    );

    // LOAD=0 increments COUNT by 1 modulo 16 on the next cycle.
    check_increment_updates_next: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && !$past(LOAD) |-> (COUNT == (($past(COUNT) + 4'd1) & 4'hF))
    );

    // LOAD=0 causes COUNT to change (it cannot hold its value).
    check_increment_changes_value: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && !$past(LOAD) |-> (COUNT != $past(COUNT))
    );

    // With LOAD=0 and COUNT at 15, next COUNT wraps to 0.
    check_wrap_on_max_no_load: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && !$past(LOAD) && ($past(COUNT) == 4'hF) |-> (COUNT == 4'h0)
    );

    // If LOAD=1, the load path has priority over increment (distinct from +1 result).
    check_load_priority_over_increment: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && $past(LOAD) &&
            ($past(DATA_IN) != (($past(COUNT) + 4'd1) & 4'hF)) |-> (COUNT != (($past(COUNT) + 4'd1) & 4'hF))
    );

    // Two consecutive cycles with LOAD=0 increment COUNT by 2 modulo 16.
    check_two_cycle_increment_no_load: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET,2) && $past(RESET) && !$past(LOAD,2) && !$past(LOAD)
            |-> COUNT == (($past(COUNT,2) + 4'd2) & 4'hF)
    );

    // LOAD followed by no LOAD results in DATA_IN+1 on the second cycle (modulo 16).
    check_load_then_increment: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET,2) && $past(RESET) && $past(LOAD,2) && !$past(LOAD)
            |-> COUNT == (($past(DATA_IN,2) + 4'd1) & 4'hF)
    );
endmodule

rtl:
module max_module (
    input wire [3:0] priority_enc_out,
    input wire [3:0] comb_circuit_out,
    output reg [3:0] max_out
);

    // Comparator functional module
    always @(*) begin
        if (priority_enc_out > comb_circuit_out) begin
            max_out = priority_enc_out;
        end else begin
            max_out = comb_circuit_out;
        end
    end

endmodule

sva:
module max_module_sva (
    input logic clk,
    input logic [3:0] priority_enc_out,
    input logic [3:0] comb_circuit_out,
    input logic [3:0] max_out
);
    // Output equals the max of the two inputs (unsigned compare).
    check_max_function: assert property (
        @(posedge clk) max_out == (priority_enc_out > comb_circuit_out ? priority_enc_out : comb_circuit_out)
    );

    // Output is always equal to one of the two inputs.
    check_output_is_one_of_inputs: assert property (
        @(posedge clk) (max_out == priority_enc_out) || (max_out == comb_circuit_out)
    );

    // When priority_enc_out > comb_circuit_out, select priority_enc_out.
    check_select_priority_when_greater: assert property (
        @(posedge clk) (priority_enc_out > comb_circuit_out) |-> (max_out == priority_enc_out)
    );

    // When priority_enc_out <= comb_circuit_out, select comb_circuit_out.
    check_select_comb_when_not_greater: assert property (
        @(posedge clk) (priority_enc_out <= comb_circuit_out) |-> (max_out == comb_circuit_out)
    );

    // On tie, output equals comb_circuit_out.
    check_tie_selects_comb: assert property (
        @(posedge clk) (priority_enc_out == comb_circuit_out) |-> (max_out == comb_circuit_out)
    );

    // Output is not less than priority_enc_out.
    check_max_ge_priority: assert property (
        @(posedge clk) max_out >= priority_enc_out
    );

    // Output is not less than comb_circuit_out.
    check_max_ge_comb: assert property (
        @(posedge clk) max_out >= comb_circuit_out
    );

    // If both inputs are stable between cycles, output is stable.
    check_stability_when_inputs_stable: assert property (
        @(posedge clk) ($stable(priority_enc_out) && $stable(comb_circuit_out)) |-> $stable(max_out)
    );

    // If output equals priority_enc_out, then priority_enc_out > comb_circuit_out.
    check_out_eq_priority_implies_priority_greater: assert property (
        @(posedge clk) (max_out == priority_enc_out) |-> (priority_enc_out > comb_circuit_out)
    );

    // If output equals comb_circuit_out, then comb_circuit_out >= priority_enc_out.
    check_out_eq_comb_implies_comb_ge_priority: assert property (
        @(posedge clk) (max_out == comb_circuit_out) |-> (comb_circuit_out >= priority_enc_out)
    );
endmodule

rtl:
module DFF(clk, d, q, en, rst);
  input clk, d, en, rst;
  output q;

  reg q_reg;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      q_reg <= 1'b0;
    end else if (en) begin
      q_reg <= d;
    end
  end

  assign q = q_reg;
endmodule

module BUF(A, Y);
  input A;
  output Y;

  assign Y = A;
endmodule

module Clock_Gating_Circuit (CLK, EN, TE, ENCLK);
  input CLK, EN, TE;
  output ENCLK;
  wire n2, n3;

  DFF latch(.clk(CLK), .d(n3), .q(n2), .en(EN), .rst(1'b0));
  BUF U1(.A(n2), .Y(ENCLK));

  assign n3 = EN & TE;
endmodule

sva:
module Clock_Gating_Circuit_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

    ///// DFF with enable behavior reflected on ENCLK /////
    // When EN was 1 last cycle, ENCLK equals last TE.
    capture_when_prev_enable_high: assert property (
        @(posedge CLK) disable iff (1'b0) (!$initstate && ($past(EN) == 1'b1)) |-> (ENCLK == $past(TE))
    );

    // When EN was 0 last cycle, ENCLK holds its previous value.
    hold_when_prev_enable_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!$initstate && ($past(EN) == 1'b0)) |-> (ENCLK == $past(ENCLK))
    );

    // ENCLK can only change if EN was 1 last cycle.
    output_change_requires_prev_enable: assert property (
        @(posedge CLK) disable iff (1'b0) (!$initstate && $changed(ENCLK)) |-> $past(EN)
    );

    // If EN and TE were 1 last cycle, ENCLK must be 1 now.
    prev_enable_and_te_high_sets_output_high: assert property (
        @(posedge CLK) disable iff (1'b0) (!$initstate && $past(EN & TE)) |-> (ENCLK == 1'b1)
    );

    // If EN was 1 and TE was 0 last cycle, ENCLK must be 0 now.
    prev_enable_and_te_low_sets_output_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!$initstate && $past(EN) && !$past(TE)) |-> (ENCLK == 1'b0)
    );

    // Each cycle after init, ENCLK equals either its previous value or last TE.
    output_either_prev_te_or_hold: assert property (
        @(posedge CLK) disable iff (1'b0) (!$initstate) |-> ((ENCLK == $past(ENCLK)) || (ENCLK == $past(TE)))
    );

    // If EN is 1 this cycle, ENCLK will equal TE on the next cycle.
    next_cycle_matches_te_when_enable_now: assert property (
        @(posedge CLK) disable iff (1'b0) (!$initstate && EN) |=> (ENCLK == $past(TE))
    );

    // If EN is 0 this cycle, ENCLK will hold its value on the next cycle.
    next_cycle_holds_when_enable_now_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!$initstate && (EN == 1'b0)) |=> (ENCLK == $past(ENCLK))
    );

endmodule

rtl:
module and_gate(
    input a, 
    input b,
    output reg out
);

    always @(*) begin
        out = (a & b) ? 1'b1 : 1'b0;
    end

endmodule

sva:
module and_gate_sva (
    input logic clk,     // sampling clock (environment-provided)
    input logic a,
    input logic b,
    input logic out
);
    // Output equals logical AND of inputs (4-state aware).
    check_out_equals_and: assert property (
        @(posedge clk) out === (a & b)
    );

    // When both inputs are 1, out must be 1.
    check_out_one_when_both_one: assert property (
        @(posedge clk) (a === 1'b1 && b === 1'b1) |-> (out === 1'b1)
    );

    // When any input is 0, out must be 0.
    check_out_zero_when_any_zero: assert property (
        @(posedge clk) ((a === 1'b0) || (b === 1'b0)) |-> (out === 1'b0)
    );

    // Out can be 1 only if both inputs are 1.
    check_out_one_implies_inputs_one: assert property (
        @(posedge clk) (out === 1'b1) |-> (a === 1'b1 && b === 1'b1)
    );

    // If both inputs are stable, output is stable.
    check_out_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(a) && $stable(b)) |-> $stable(out)
    );

    // Output changes only when at least one input changes.
    check_out_change_implies_input_change: assert property (
        @(posedge clk) $changed(out) |-> ($changed(a) || $changed(b))
    );

    // Rising edge on out only when both inputs are high.
    check_out_rise_requires_both_high: assert property (
        @(posedge clk) $rose(out) |-> (a === 1'b1 && b === 1'b1)
    );

    // Falling edge on out only when any input is low.
    check_out_fall_requires_any_low: assert property (
        @(posedge clk) $fell(out) |-> ((a === 1'b0) || (b === 1'b0))
    );

    // With known inputs, out is known and equals a & b.
    check_out_known_when_inputs_known: assert property (
        @(posedge clk) ((a inside {1'b0,1'b1}) && (b inside {1'b0,1'b1})) |-> ((out inside {1'b0,1'b1}) && (out === (a & b)))
    );

    // Unknown out implies at least one input is unknown.
    check_x_out_implies_x_input: assert property (
        @(posedge clk) (!(out inside {1'b0,1'b1})) |-> ( !(a inside {1'b0,1'b1}) || !(b inside {1'b0,1'b1}) )
    );
endmodule

rtl:
module mux_2to1 (
    input A,
    input B,
    input SEL,
    output Y
);

    assign Y = (SEL == 0) ? A : B;

endmodule

sva:
module mux_2to1_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic SEL,
    input logic Y
);
    // Y must equal the selected input per mux function.
    check_mux_function: assert property (
        @(posedge CLK) disable iff (1'b0) Y == ((SEL == 1'b0) ? A : B)
    );

    // When SEL is 0, Y must equal A.
    check_sel_zero_path: assert property (
        @(posedge CLK) disable iff (1'b0) (SEL == 1'b0) |-> (Y == A)
    );

    // When SEL is 1, Y must equal B.
    check_sel_one_path: assert property (
        @(posedge CLK) disable iff (1'b0) (SEL == 1'b1) |-> (Y == B)
    );

    // Y must always equal one of the inputs.
    check_output_is_one_of_inputs: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == A) || (Y == B)
    );

    // If inputs are equal, Y must equal that common value.
    check_equal_inputs: assert property (
        @(posedge CLK) disable iff (1'b0) (A == B) |-> (Y == A)
    );

    // If inputs differ and Y equals A, SEL must be 0.
    check_select_infers_zero_when_outputs_A: assert property (
        @(posedge CLK) disable iff (1'b0) (A != B && Y == A) |-> (SEL == 1'b0)
    );

    // If inputs differ and Y equals B, SEL must be 1.
    check_select_infers_one_when_outputs_B: assert property (
        @(posedge CLK) disable iff (1'b0) (A != B && Y == B) |-> (SEL == 1'b1)
    );

    // With SEL=0, Y can equal B only if A equals B.
    check_no_bypass_when_sel_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (SEL == 1'b0 && (Y == B)) |-> (A == B)
    );

    // With SEL=1, Y can equal A only if A equals B.
    check_no_bypass_when_sel_one: assert property (
        @(posedge CLK) disable iff (1'b0) (SEL == 1'b1 && (Y == A)) |-> (A == B)
    );
endmodule

rtl:
module two_bit_output(clk, b, so);
input clk;
input [3:0] b;
output [1:0] so;
reg [1:0] so;

	always @(posedge clk)
		case (b)
			4'b0000, 4'b0001, 4'b0010: so = 2'b00;
			4'b0011, 4'b0100: so = 2'b01;
			4'b0101, 4'b0110: so = 2'b10;
			4'b0111: so = 2'b11;
			default: so = 2'b00;
		endcase

endmodule

sva:
module two_bit_output_sva (
    input logic clk,
    input logic [3:0] b,
    input logic [1:0] so
);
    // Next cycle so=00 when b is 0,1,2.
    map_b_0_1_2_to_so_00: assert property (
        @(posedge clk) (b inside {4'd0,4'd1,4'd2}) |=> (so == 2'b00)
    );

    // Next cycle so=01 when b is 3 or 4.
    map_b_3_4_to_so_01: assert property (
        @(posedge clk) (b inside {4'd3,4'd4}) |=> (so == 2'b01)
    );

    // Next cycle so=10 when b is 5 or 6.
    map_b_5_6_to_so_10: assert property (
        @(posedge clk) (b inside {4'd5,4'd6}) |=> (so == 2'b10)
    );

    // Next cycle so=11 when b is 7.
    map_b_7_to_so_11: assert property (
        @(posedge clk) (b == 4'd7) |=> (so == 2'b11)
    );

    // Next cycle so=00 for default cases b=8..15.
    map_b_8_to_15_default_to_so_00: assert property (
        @(posedge clk) (b inside {[4'd8:4'd15]}) |=> (so == 2'b00)
    );

    // For b=3..7, next cycle so is never 00.
    not_00_for_b_3_to_7: assert property (
        @(posedge clk) (b inside {[4'd3:4'd7]}) |=> (so != 2'b00)
    );

    // Only b=3 or 4 produce next cycle so=01.
    only_3_4_give_01: assert property (
        @(posedge clk) (!(b inside {4'd3,4'd4})) |=> (so != 2'b01)
    );

    // Only b=5 or 6 produce next cycle so=10.
    only_5_6_give_10: assert property (
        @(posedge clk) (!(b inside {4'd5,4'd6})) |=> (so != 2'b10)
    );

    // Only b=7 produces next cycle so=11.
    only_7_gives_11: assert property (
        @(posedge clk) (b != 4'd7) |=> (so != 2'b11)
    );
endmodule

rtl:
module nand4 (
    input A,
    input B,
    input C,
    input D,
    output Y
);

wire AB, CD, ABCD;
not (AB, A & B);
not (CD, C & D);
not (ABCD, AB & CD);
not (Y, ABCD);

endmodule

sva:
module nand4_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);
    // Y equals (~(A & B)) & (~(C & D)).
    check_y_eq_nands_and_form: assert property (
        @(posedge CLK) Y == ((~(A & B)) & (~(C & D)))
    );

    // Y equals ~((A & B) | (C & D)) by De Morgan.
    check_y_eq_demorgan_or_form: assert property (
        @(posedge CLK) Y == ~( (A & B) | (C & D) )
    );

    // If A and B are both 1, Y must be 0.
    check_ab_high_forces_y_low: assert property (
        @(posedge CLK) (A & B) |-> (Y == 1'b0)
    );

    // If C and D are both 1, Y must be 0.
    check_cd_high_forces_y_low: assert property (
        @(posedge CLK) (C & D) |-> (Y == 1'b0)
    );

    // If neither A&B nor C&D is 1, Y must be 1.
    check_no_pair_and_implies_y_high: assert property (
        @(posedge CLK) (!(A & B) && !(C & D)) |-> (Y == 1'b1)
    );

    // If Y is 1, then neither A&B nor C&D is 1.
    check_y_high_implies_no_pair_and: assert property (
        @(posedge CLK) Y |-> (!(A & B) && !(C & D))
    );

    // If Y is 0, then at least one of A&B or C&D is 1.
    check_y_low_implies_some_pair_and: assert property (
        @(posedge CLK) (!Y) |-> ((A & B) || (C & D))
    );
endmodule

rtl:
module priority_encoder (
    input [7:0] I,
    output reg EN,
    output reg V,
    output reg [2:0] Q
);

    parameter WIDTH = 8;
    integer i;

    always @(*) begin
        if (|I) begin
            EN = 1;
            V = (|I) & (~&I);
            for (i = 0; i < WIDTH; i = i + 1) begin
                if (I[i]) begin
                    Q = i + 1'b1;
                end
            end
        end
        else begin
            EN = 0;
            V = 0;
            Q = 0;
        end
    end

endmodule

sva:
module priority_encoder_sva (
    input logic clk,
    input logic [7:0] I,
    input logic EN,
    input logic V,
    input logic [2:0] Q
);
    // EN equals reduction-OR of I.
    check_en_matches_or: assert property (
        @(posedge clk) EN == (|I)
    );

    // V is 1 when some but not all bits of I are 1.
    check_v_matches_some_but_not_all: assert property (
        @(posedge clk) V == ((|I) & (~&I))
    );

    // When I is zero, outputs are all zero.
    check_outputs_when_I_zero: assert property (
        @(posedge clk) (I == 8'b0) |-> (EN == 1'b0 && V == 1'b0 && Q == 3'b000)
    );

    // If bit 7 is set, Q wraps to 0 due to i+1 truncation to 3 bits.
    check_q_zero_when_bit7_set: assert property (
        @(posedge clk) I[7] |-> (Q == 3'b000)
    );

    // If highest set bit is 6 (and 7 is 0), Q is 7.
    check_q_when_highest_6: assert property (
        @(posedge clk) (I[7] == 1'b0 && I[6] == 1'b1) |-> (Q == 3'b111)
    );

    // If highest set bit is 5 (and 7:6 are 0), Q is 6.
    check_q_when_highest_5: assert property (
        @(posedge clk) (I[7:6] == 2'b00 && I[5]) |-> (Q == 3'b110)
    );

    // If highest set bit is 4 (and 7:5 are 0), Q is 5.
    check_q_when_highest_4: assert property (
        @(posedge clk) (I[7:5] == 3'b000 && I[4]) |-> (Q == 3'b101)
    );

    // If highest set bit is 3 (and 7:4 are 0), Q is 4.
    check_q_when_highest_3: assert property (
        @(posedge clk) (I[7:4] == 4'b0000 && I[3]) |-> (Q == 3'b100)
    );

    // If highest set bit is 2 (and 7:3 are 0), Q is 3.
    check_q_when_highest_2: assert property (
        @(posedge clk) (I[7:3] == 5'b00000 && I[2]) |-> (Q == 3'b011)
    );

    // If highest set bit is 1 (and 7:2 are 0), Q is 2.
    check_q_when_highest_1: assert property (
        @(posedge clk) (I[7:2] == 6'b000000 && I[1]) |-> (Q == 3'b010)
    );

    // If highest set bit is 0 (and 7:1 are 0), Q is 1.
    check_q_when_highest_0: assert property (
        @(posedge clk) (I[7:1] == 7'b0000000 && I[0]) |-> (Q == 3'b001)
    );
endmodule

rtl:
module up_down_counter (
    input clk,
    input reset,
    input load,
    input up_down,
    input [3:0] data_in,
    output reg [3:0] count_out
);

    always @(posedge clk) begin
        if (reset) begin
            count_out <= 4'b0;
        end else if (load) begin
            count_out <= data_in;
        end else if (up_down) begin
            count_out <= count_out + 1;
        end else begin
            count_out <= count_out - 1;
        end
    end

endmodule

sva:
module up_down_counter_sva (
    input logic clk,
    input logic reset,       // active-high synchronous reset
    input logic load,
    input logic up_down,
    input logic [3:0] data_in,
    input logic [3:0] count_out
);
    ///// Reset behavior /////
    // Synchronous reset drives count_out to zero on the next clock.
    reset_clears_count: assert property (
        @(posedge clk) reset |=> (count_out == 4'b0000)
    );

    ///// Load behavior /////
    // When load is asserted (no reset), next count_out equals data_in.
    load_updates_count: assert property (
        @(posedge clk) disable iff (reset) load |=> (count_out == $past(data_in))
    );
    // Load has priority over up/down counting when both are asserted.
    load_overrides_updown: assert property (
        @(posedge clk) disable iff (reset) (load && up_down) |=> (count_out == $past(data_in))
    );

    ///// Counting behavior /////
    // When counting up (load=0, up_down=1), next count_out = previous + 1 (mod 16).
    count_up_when_up_down: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down) |=> (count_out == ($past(count_out) + 4'd1))
    );
    // When counting down (load=0, up_down=0), next count_out = previous - 1 (mod 16).
    count_down_when_not_up_down: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down) |=> (count_out == ($past(count_out) - 4'd1))
    );

    ///// Wrap-around behavior /////
    // Up-count wraps from 15 to 0.
    wrap_on_increment_from_max: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down && (count_out == 4'hF)) |=> (count_out == 4'h0)
    );
    // Down-count wraps from 0 to 15.
    wrap_on_decrement_from_min: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down && (count_out == 4'h0)) |=> (count_out == 4'hF)
    );
endmodule

rtl:
module my_nor (
    input a,
    input b,
    output y
);

    assign y = ~(a | b);

endmodule

sva:
module my_nor_assert (
    input logic clk,
    input logic a,
    input logic b,
    input logic y
);
    ///// NOR function checks /////
    // y must equal NOR of a and b.
    check_y_is_nor: assert property (
        @(posedge clk) y == ~(a | b)
    );

    // If a is 1, y must be 0.
    check_y_zero_if_a_one: assert property (
        @(posedge clk) (a == 1'b1) |-> (y == 1'b0)
    );

    // If b is 1, y must be 0.
    check_y_zero_if_b_one: assert property (
        @(posedge clk) (b == 1'b1) |-> (y == 1'b0)
    );

    // If both a and b are 0, y must be 1.
    check_y_one_if_both_zero: assert property (
        @(posedge clk) (a == 1'b0 && b == 1'b0) |-> (y == 1'b1)
    );

    // If y is 1, both inputs must be 0.
    check_inputs_zero_if_y_one: assert property (
        @(posedge clk) (y == 1'b1) |-> (a == 1'b0 && b == 1'b0)
    );

    // If y is 0, at least one input must be 1.
    check_some_input_one_if_y_zero: assert property (
        @(posedge clk) (y == 1'b0) |-> (a == 1'b1 || b == 1'b1)
    );
endmodule

rtl:
module two_input_logic (
    A,
    B,
    X
);

    // Module ports
    input  A;
    input  B;
    output X;

    // Local signals
    wire not_A;
    wire not_B;
    wire and1_out;
    wire and2_out;
    wire or_out;

    //  Name        Output      Other arguments
    not not_A_gate (not_A, A);
    not not_B_gate (not_B, B);
    and and1_gate   (and1_out, A, not_B);
    and and2_gate   (and2_out, not_A, B);
    or  or_gate     (or_out, and1_out, and2_out);
    not not_out     (X, or_out);

endmodule

sva:
module two_input_logic_sva (
    input logic A,
    input logic B,
    input logic X
);
    // X equals XNOR of A and B
    check_x_equals_xnor: assert property (
        @(posedge A or negedge A or posedge B or negedge B) X == ~(A ^ B)
    );

    // Truth table: A=0, B=0 => X=1
    check_tt_a0b0: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (!A && !B) |-> (X == 1'b1)
    );

    // Truth table: A=1, B=1 => X=1
    check_tt_a1b1: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (A && B) |-> (X == 1'b1)
    );

    // Truth table: A=1, B=0 => X=0
    check_tt_a1b0: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (A && !B) |-> (X == 1'b0)
    );

    // Truth table: A=0, B=1 => X=0
    check_tt_a0b1: assert property (
        @(posedge A or negedge A or posedge B or negedge B) (!A && B) |-> (X == 1'b0)
    );
endmodule

rtl:
module top_module (
    input [2:0] A, // Inputs for 3-to-8 decoder
    input [3:0] in, // Inputs for 4-to-16 decoder
    output [7:0] q // 8-bit output from functional module
);

    wire [7:0] dec_3to8;
    wire [15:0] dec_4to16;

    decoder_3to8 dec3to8(.A(A), .Y(dec_3to8));
    decoder_4to16 dec4to16(.in(in), .out(dec_4to16));
    functional_module func(.dec_3to8(~dec_3to8), .dec_4to16(dec_4to16), .q(q));

endmodule

module decoder_3to8 (
    input [2:0] A,
    output reg [7:0] Y
);
    always @*
    begin
        case(A)
            3'b000: Y = 8'b11111110;
            3'b001: Y = 8'b11111101;
            3'b010: Y = 8'b11111011;
            3'b011: Y = 8'b11110111;
            3'b100: Y = 8'b11101111;
            3'b101: Y = 8'b11011111;
            3'b110: Y = 8'b10111111;
            3'b111: Y = 8'b01111111;
            default: Y = 8'b00000000;
        endcase
    end

endmodule

module decoder_4to16 (
    input [3:0] in,
    output reg [15:0] out
);
    always @*
    begin
        case(in)
            4'b0000: out = 16'b0000000000000001;
            4'b0001: out = 16'b0000000000000010;
            4'b0010: out = 16'b0000000000000100;
            4'b0011: out = 16'b0000000000001000;
            4'b0100: out = 16'b0000000000010000;
            4'b0101: out = 16'b0000000000100000;
            4'b0110: out = 16'b0000000001000000;
            4'b0111: out = 16'b0000000010000000;
            4'b1000: out = 16'b0000000100000000;
            4'b1001: out = 16'b0000001000000000;
            4'b1010: out = 16'b0000010000000000;
            4'b1011: out = 16'b0000100000000000;
            4'b1100: out = 16'b0001000000000000;
            4'b1101: out = 16'b0010000000000000;
            4'b1110: out = 16'b0100000000000000;
            4'b1111: out = 16'b1000000000000000;
            default: out = 16'b0000000000000000;
        endcase
    end

endmodule

module functional_module (
    input [7:0] dec_3to8, // Active-low outputs of 3-to-8 decoder
    input [15:0] dec_4to16, // Active-high outputs of 4-to-16 decoder
    output reg [7:0] q // 8-bit output from bitwise OR operation
);
    always @*
    begin
        q = dec_3to8 | dec_4to16[15:8];
    end

endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic [2:0] A,
    input logic [3:0] in,
    input logic [7:0] q
);
    // q equals onehot(A) OR (in[3] ? onehot(in[2:0]) : 0)
    check_q_matches_formula: assert property (
        @(posedge CLK)
        q == ((8'b00000001 << A) | (in[3] ? (8'b00000001 << in[2:0]) : 8'b00000000))
    );

    // q must always have bit A set
    check_q_bit_A_always_set: assert property (
        @(posedge CLK)
        q[A] == 1'b1
    );

    // When in[3]==0, q is exactly onehot(A)
    check_when_in_msb0_exact: assert property (
        @(posedge CLK)
        (in[3] == 1'b0) |-> (q == (8'b00000001 << A))
    );

    // When in[3]==1, q must include bit indexed by in[2:0]
    check_when_in_msb1_bit_set: assert property (
        @(posedge CLK)
        (in[3] == 1'b1) |-> (q[in[2:0]] == 1'b1)
    );

    // When in[3]==1 and in[2:0]!=A, q has exactly two 1s
    check_two_bits_when_distinct: assert property (
        @(posedge CLK)
        (in[3] && (in[2:0] != A)) |-> ($countones(q) == 2)
    );

    // When in[3]==1 and in[2:0]==A, q is onehot
    check_onehot_when_same: assert property (
        @(posedge CLK)
        (in[3] && (in[2:0] == A)) |-> $onehot(q)
    );

    // q always has one or two 1s
    check_countones_bound: assert property (
        @(posedge CLK)
        ($countones(q) >= 1) && ($countones(q) <= 2)
    );

    // q is never all zeros
    check_q_never_zero: assert property (
        @(posedge CLK)
        q != 8'b00000000
    );

    // No spurious bits in q beyond the two allowed sources
    check_no_spurious_bits: assert property (
        @(posedge CLK)
        (q & ~((8'b00000001 << A) | (in[3] ? (8'b00000001 << in[2:0]) : 8'b00000000))) == 8'b00000000
    );

    // When in[3]==1, q equals onehot(A) OR onehot(in[2:0])
    check_when_in_msb1_exact: assert property (
        @(posedge CLK)
        (in[3] == 1'b1) |-> (q == ((8'b00000001 << A) | (8'b00000001 << in[2:0])))
    );
endmodule

rtl:
module my_dff (
  input clk,
  input d,
  output reg q
);

always @(posedge clk) begin
  q <= d;
end

endmodule

module shift_register (
  input clk,
  input [3:0] data_in,
  output [3:0] data_out
);

wire [3:0] dff_out;

my_dff dff0 (.clk(clk), .d(data_in[0]), .q(dff_out[0]));
my_dff dff1 (.clk(clk), .d(dff_out[0]), .q(dff_out[1]));
my_dff dff2 (.clk(clk), .d(dff_out[1]), .q(dff_out[2]));
my_dff dff3 (.clk(clk), .d(dff_out[2]), .q(dff_out[3]));

assign data_out = dff_out;

endmodule

sva:
module shift_register_sva (
    input logic clk,
    input logic [3:0] data_in,
    input logic [3:0] data_out
);
    ///// Shift behavior per stage /////
    // Stage0 captures data_in[0] one cycle later.
    check_stage0_captures_data_in0: assert property (
        @(posedge clk) 1'b1 |=> (data_out[0] == $past(data_in[0]))
    );
    // Stage1 captures previous stage0 value.
    check_stage1_follows_prev_stage: assert property (
        @(posedge clk) 1'b1 |=> (data_out[1] == $past(data_out[0]))
    );
    // Stage2 captures previous stage1 value.
    check_stage2_follows_prev_stage: assert property (
        @(posedge clk) 1'b1 |=> (data_out[2] == $past(data_out[1]))
    );
    // Stage3 captures previous stage2 value.
    check_stage3_follows_prev_stage: assert property (
        @(posedge clk) 1'b1 |=> (data_out[3] == $past(data_out[2]))
    );

    ///// Vector-level shift relation /////
    // Full vector equals previous vector left-shifted with prior data_in[0] inserted at bit0.
    check_vector_shift: assert property (
        @(posedge clk) 1'b1 |=> (data_out == { $past(data_out[2]), $past(data_out[1]), $past(data_out[0]), $past(data_in[0]) })
    );

    ///// Depth to input relation /////
    // Stage1 equals data_in[0] from two cycles earlier.
    check_stage1_matches_input_2cycle: assert property (
        @(posedge clk) 1'b1 |=> ##2 (data_out[1] == $past(data_in[0], 2))
    );
    // Stage2 equals data_in[0] from three cycles earlier.
    check_stage2_matches_input_3cycle: assert property (
        @(posedge clk) 1'b1 |=> ##3 (data_out[2] == $past(data_in[0], 3))
    );
    // Stage3 equals data_in[0] from four cycles earlier.
    check_stage3_matches_input_4cycle: assert property (
        @(posedge clk) 1'b1 |=> ##4 (data_out[3] == $past(data_in[0], 4))
    );

    ///// Cross-stage timing consistency /////
    // Stage2 equals stage0 from two cycles earlier.
    check_stage2_matches_stage0_2cycle: assert property (
        @(posedge clk) 1'b1 |=> ##2 (data_out[2] == $past(data_out[0], 2))
    );
    // Stage3 equals stage1 from two cycles earlier.
    check_stage3_matches_stage1_2cycle: assert property (
        @(posedge clk) 1'b1 |=> ##2 (data_out[3] == $past(data_out[1], 2))
    );
    // Stage3 equals stage0 from three cycles earlier.
    check_stage3_matches_stage0_3cycle: assert property (
        @(posedge clk) 1'b1 |=> ##3 (data_out[3] == $past(data_out[0], 3))
    );
endmodule

module updown_counter_sva (
    input logic clk,
    input logic U_D,
    input logic [3:0] Q
);
    ///// Counter update behavior /////
    // Q updates by +1 when U_D=1, else -1 (mod 16), on each clock after the first.
    check_update_rule: assert property (
        @(posedge clk) 1'b1 |=> (U_D ? (Q == $past(Q) + 4'd1) : (Q == $past(Q) - 4'd1))
    );

    // Q must change every cycle (never holds its value).
    check_q_always_changes: assert property (
        @(posedge clk) 1'b1 |=> $changed(Q)
    );

    // If counting up and previous Q was 15, wrap to 0.
    check_inc_wrap: assert property (
        @(posedge clk) 1'b1 |=> ( !(U_D && ($past(Q) == 4'hF)) || (Q == 4'h0) )
    );

    // If counting down and previous Q was 0, wrap to 15.
    check_dec_wrap: assert property (
        @(posedge clk) 1'b1 |=> ( !((!U_D) && ($past(Q) == 4'h0)) || (Q == 4'hF) )
    );

    // If counting up and previous Q != 15, increment by 1.
    check_inc_nonwrap: assert property (
        @(posedge clk) 1'b1 |=> ( !(U_D && ($past(Q) != 4'hF)) || (Q == $past(Q) + 4'd1) )
    );

    // If counting down and previous Q != 0, decrement by 1.
    check_dec_nonwrap: assert property (
        @(posedge clk) 1'b1 |=> ( !((!U_D) && ($past(Q) != 4'h0)) || (Q == $past(Q) - 4'd1) )
    );

    // The magnitude of the step each cycle is exactly 1 (mod 16).
    check_delta_one: assert property (
        @(posedge clk) 1'b1 |=> ( (Q == $past(Q) + 4'd1) || (Q == $past(Q) - 4'd1) )
    );

    // Exactly one of +1 or -1 delta holds each cycle.
    check_delta_exclusive: assert property (
        @(posedge clk) 1'b1 |=> ( (Q == $past(Q) + 4'd1) != (Q == $past(Q) - 4'd1) )
    );

    // U_D reflects the direction of change (increment iff U_D==1).
    check_direction_matches_delta: assert property (
        @(posedge clk) 1'b1 |=> ( U_D == (Q == $past(Q) + 4'd1) )
    );

    // LSB toggles every cycle due to +/-1 operation.
    check_lsb_toggle: assert property (
        @(posedge clk) 1'b1 |=> ( Q[0] != $past(Q[0]) )
    );
endmodule

rtl:
module mux_2to1 (
  input A0,
  input A1,
  input S,
  output X
);

  // select A0 if S is 0, A1 if S is 1
  assign X = (!S) ? A0 : A1;

endmodule

sva:
module mux_2to1_sva (
    input logic clk,
    input logic A0,
    input logic A1,
    input logic S,
    input logic X
);
    // X equals A0 when S=0, else A1 (functional equivalence).
    check_mux_truth_table: assert property (
        @(posedge clk) X == ((S == 1'b0) ? A0 : A1)
    );

    // When S=0 and only A1 changes, X must remain unchanged.
    check_unselected_change_no_effect_S0: assert property (
        @(posedge clk) (S == 1'b0) && $changed(A1) && $stable(A0) && $stable(S) |-> $stable(X)
    );

    // When S=1 and only A0 changes, X must remain unchanged.
    check_unselected_change_no_effect_S1: assert property (
        @(posedge clk) (S == 1'b1) && $changed(A0) && $stable(A1) && $stable(S) |-> $stable(X)
    );

    // When S=0 and A0 changes (others stable), X must equal A0.
    check_selected_change_reflected_S0: assert property (
        @(posedge clk) (S == 1'b0) && $changed(A0) && $stable(A1) && $stable(S) |-> (X == A0)
    );

    // When S=1 and A1 changes (others stable), X must equal A1.
    check_selected_change_reflected_S1: assert property (
        @(posedge clk) (S == 1'b1) && $changed(A1) && $stable(A0) && $stable(S) |-> (X == A1)
    );

    // On S rising edge, X must equal A1.
    check_select_rise_routes_A1: assert property (
        @(posedge clk) $rose(S) |-> (X == A1)
    );

    // On S falling edge, X must equal A0.
    check_select_fall_routes_A0: assert property (
        @(posedge clk) $fell(S) |-> (X == A0)
    );

    // If A0 equals A1, X must equal that value regardless of S.
    check_equal_inputs_drive_x: assert property (
        @(posedge clk) (A0 == A1) |-> (X == A0)
    );

    // If S, A0, and A1 are stable, X must be stable.
    check_stable_inputs_hold_output: assert property (
        @(posedge clk) $stable({S, A0, A1}) |-> $stable(X)
    );

    // If X changes, at least one of S, A0, or A1 must have changed.
    check_output_change_requires_input_change: assert property (
        @(posedge clk) $changed(X) |-> ($changed(S) || $changed(A0) || $changed(A1))
    );
endmodule

module pg_to_PG_sva (
    input logic clk,
    input logic [15:0] p,
    input logic [15:0] g,
    input logic [3:0] bp,
    input logic [3:0] bg
);

    ///// Block-generate definitions /////
    // bg[0] equals g[3] | p[3]&g[2] | p[3]&p[2]&g[1] | p[3]&p[2]&p[1]&g[0]
    check_bg0_definition: assert property (
        @(posedge clk) bg[0] == ( g[3]
                               | (p[3] & g[2])
                               | (p[3] & p[2] & g[1])
                               | (p[3] & p[2] & p[1] & g[0]) )
    );
    // bg[1] equals g[7] | p[7]&g[6] | p[7]&p[6]&g[5] | p[7]&p[6]&p[5]&g[4]
    check_bg1_definition: assert property (
        @(posedge clk) bg[1] == ( g[7]
                               | (p[7] & g[6])
                               | (p[7] & p[6] & g[5])
                               | (p[7] & p[6] & p[5] & g[4]) )
    );
    // bg[2] equals g[11] | p[11]&g[10] | p[11]&p[10]&g[9] | p[11]&p[10]&p[9]&g[8]
    check_bg2_definition: assert property (
        @(posedge clk) bg[2] == ( g[11]
                               | (p[11] & g[10])
                               | (p[11] & p[10] & g[9])
                               | (p[11] & p[10] & p[9] & g[8]) )
    );
    // bg[3] equals g[15] | p[15]&g[14] | p[15]&p[14]&g[13] | p[15]&p[14]&p[13]&g[12]
    check_bg3_definition: assert property (
        @(posedge clk) bg[3] == ( g[15]
                               | (p[15] & g[14])
                               | (p[15] & p[14] & g[13])
                               | (p[15] & p[14] & p[13] & g[12]) )
    );

    ///// Block-propagate definitions /////
    // bp[0] equals p[3]&p[2]&p[1]&p[0]
    check_bp0_definition: assert property (
        @(posedge clk) bp[0] == (p[3] & p[2] & p[1] & p[0])
    );
    // bp[1] equals p[7]&p[6]&p[5]&p[4]
    check_bp1_definition: assert property (
        @(posedge clk) bp[1] == (p[7] & p[6] & p[5] & p[4])
    );
    // bp[2] equals p[11]&p[10]&p[9]&p[8]
    check_bp2_definition: assert property (
        @(posedge clk) bp[2] == (p[11] & p[10] & p[9] & p[8])
    );
    // bp[3] equals p[15]&p[14]&p[13]&p[12]
    check_bp3_definition: assert property (
        @(posedge clk) bp[3] == (p[15] & p[14] & p[13] & p[12])
    );

    ///// Necessary conditions for block-generate /////
    // If bg[0] is 1, at least one g in [3:0] is 1.
    check_bg0_implies_some_g: assert property (
        @(posedge clk) bg[0] |-> (g[3] || g[2] || g[1] || g[0])
    );
    // If bg[1] is 1, at least one g in [7:4] is 1.
    check_bg1_implies_some_g: assert property (
        @(posedge clk) bg[1] |-> (g[7] || g[6] || g[5] || g[4])
    );
    // If bg[2] is 1, at least one g in [11:8] is 1.
    check_bg2_implies_some_g: assert property (
        @(posedge clk) bg[2] |-> (g[11] || g[10] || g[9] || g[8])
    );
    // If bg[3] is 1, at least one g in [15:12] is 1.
    check_bg3_implies_some_g: assert property (
        @(posedge clk) bg[3] |-> (g[15] || g[14] || g[13] || g[12])
    );

endmodule

rtl:
module binary_counter(
    input clk,
    input rst,
    output reg [3:0] count
);

always @(posedge clk or negedge rst) begin
    if (!rst) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic rst,          // active-low reset
    input logic [3:0] count
);
    // When reset is asserted (low), count must be 0 at each clock edge.
    check_reset_forces_zero: assert property (
        @(posedge clk) (!rst) |-> (count == 4'h0)
    );

    // While reset stays asserted across cycles, count remains 0 and stable.
    check_hold_zero_during_reset: assert property (
        @(posedge clk) (!rst && !$past(rst)) |-> (count == 4'h0 && $stable(count))
    );

    // With reset deasserted in consecutive cycles, count increments by 1 each cycle (mod 16).
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (count == $past(count) + 4'd1)
    );

    // When previous value was 15 and still enabled, next value wraps to 0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

    // Over two consecutive enabled cycles, count advances by 2 (mod 16).
    check_two_step_increment: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst,2) && $past(rst)) |-> (count == $past(count,2) + 4'd2)
    );

    // On reset release ($rose), the next enabled cycle increments from the reset value.
    check_increment_after_reset_release: assert property (
        @(posedge clk) disable iff (!rst) $rose(rst) |-> (count == $past(count) + 4'd1)
    );

    // On reset assertion ($fell), count is driven to 0 at that clock edge.
    check_zero_on_reset_assertion: assert property (
        @(posedge clk) $fell(rst) |-> (count == 4'h0)
    );

    // When enabled and not wrapping, next value cannot be 0.
    check_nonzero_when_not_wrapping: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && ($past(count) != 4'hF)) |-> (count != 4'h0)
    );
endmodule

module my_flip_flop_sva (
    input logic Q,
    input logic CLK,
    input logic D,
    input logic DE,
    input logic VPWR,
    input logic VGND
);
    // When DE was 1 on the previous edge, Q now equals previous D.
    check_capture_on_prev_enable: assert property (
        @(posedge CLK) $past(DE) |-> (Q == $past(D))
    );

    // When DE was 0 on the previous edge, Q holds its previous value.
    check_hold_on_prev_disable: assert property (
        @(posedge CLK) !$past(DE) |-> (Q == $past(Q))
    );

    // A change in Q since last edge implies DE was 1 on the previous edge.
    check_change_requires_prev_enable: assert property (
        @(posedge CLK) (Q != $past(Q)) |-> $past(DE)
    );

    // If DE was 1 and D differed from Q previously, Q must change.
    check_prev_enable_data_mismatch_causes_change: assert property (
        @(posedge CLK) ($past(DE) && ($past(D) != $past(Q))) |-> (Q != $past(Q))
    );

    // If DE was 1 and D matched Q previously, Q must not change.
    check_prev_enable_data_match_no_change: assert property (
        @(posedge CLK) ($past(DE) && ($past(D) == $past(Q))) |-> (Q == $past(Q))
    );

    // With DE=1 now, on the next edge Q equals the current D.
    check_capture_next_cycle_on_current_enable: assert property (
        @(posedge CLK) DE |-> ##1 (Q == $past(D))
    );

    // Q's update each cycle equals (DE ? D : hold) from the previous edge.
    check_functional_update_equation: assert property (
        @(posedge CLK) (Q == ($past(DE) ? $past(D) : $past(Q)))
    );
endmodule

rtl:
module abs_difference (
    CLOCK,
    RESET,
    x,
    y,
    DIFF
);

    input CLOCK, RESET;
    input [11:0] x, y;
    output reg [11:0] DIFF;

    always @ (posedge CLOCK or posedge RESET) begin
        if (RESET) begin
            DIFF <= 0;
        end else begin
            DIFF <= (x > y) ? x - y : y - x;
        end
    end

endmodule

sva:
module abs_difference_sva (
    input logic CLOCK,
    input logic RESET,
    input logic [11:0] x,
    input logic [11:0] y,
    input logic [11:0] DIFF
);
    // Clock: CLOCK (posedge). Reset: RESET (active-high, asynchronous).
    // Logic: Sequential register computing absolute difference; DIFF cleared to 0 on RESET.

    // DIFF must be 0 whenever RESET is asserted at the clock edge.
    reset_forces_zero: assert property (
        @(posedge CLOCK) RESET |-> (DIFF == 12'd0)
    );

    // Functional behavior: when not in reset, DIFF equals |x - y|.
    diff_matches_abs: assert property (
        @(posedge CLOCK) disable iff (RESET) DIFF == ((x > y) ? (x - y) : (y - x))
    );

    // If inputs are equal (not in reset), DIFF must be 0.
    diff_zero_when_equal: assert property (
        @(posedge CLOCK) disable iff (RESET) (x == y) |-> (DIFF == 12'd0)
    );

    // If inputs differ (not in reset), DIFF must be strictly positive.
    diff_positive_when_unequal: assert property (
        @(posedge CLOCK) disable iff (RESET) (x != y) |-> (DIFF > 12'd0)
    );

    // DIFF never exceeds the larger of x and y when not in reset.
    diff_bounded_by_max: assert property (
        @(posedge CLOCK) disable iff (RESET) (DIFF <= ((x > y) ? x : y))
    );

    // DIFF plus the smaller input equals the larger input when not in reset.
    add_inverse_relation: assert property (
        @(posedge CLOCK) disable iff (RESET) ((x > y) ? ((DIFF + y) == x) : ((DIFF + x) == y))
    );
endmodule

rtl:
module add_sub_comp (
    input [3:0] a,
    input [3:0] b,
    input sub,
    output reg out
);

    reg [3:0] result;
    wire [1:0] comp_out;

    two_bit_comparator comp (
        .a(a),       // Fix the a and b inputs order
        .b(b),   // Fix the a and b inputs order
        .out(comp_out)
    );

    adder_subtractor add_sub (
        .a(a),
        .b(b),
        .sub(sub),
        .result(result)
    );

    always @(*) begin
        case (comp_out)
            2'b00: out <= 1;
            default: out <= 0;
        endcase
    end

endmodule
module two_bit_comparator (
    input [3:0] a,
    input [3:0] b,
    output reg [1:0] out
);

    always @(*) begin
        if (a > b) begin
            out = 2'b10;
        end else if (a == b) begin
            out = 2'b01;
        end else begin
            out = 2'b00;
        end
    end

endmodule
module adder_subtractor (
    input [3:0] a,
    input [3:0] b,
    input sub,
    output reg [3:0] result
);

    always @(*) begin
        if (sub) begin
            result = a - b;
        end else begin
            result = a + b;
        end
    end

endmodule

sva:
module add_sub_comp_sva (
    input logic clk,           // Sampling clock for assertions (DUT has no clock/reset)
    input logic [3:0] a,       // DUT input
    input logic [3:0] b,       // DUT input
    input logic sub,           // DUT input (does not affect out)
    input logic out            // DUT output: 1 when a < b, else 0
);
    // Analysis: No clock/reset in RTL; pure combinational. out=1 iff a<b; sub does not affect out.

    ///// Functional equivalence /////
    // out must reflect comparator result: out == (a < b).
    check_out_equals_less: assert property (
        @(posedge clk) out == (a < b)
    );

    ///// Case-specific behavior /////
    // When a < b, out is 1.
    check_out_one_when_less: assert property (
        @(posedge clk) (a < b) |-> (out == 1'b1)
    );
    // When a >= b, out is 0.
    check_out_zero_when_ge: assert property (
        @(posedge clk) (a >= b) |-> (out == 1'b0)
    );

    ///// Independence from sub /////
    // Changes on sub do not affect out when a and b are stable.
    check_out_independent_of_sub_when_inputs_stable: assert property (
        @(posedge clk) ($stable(a) && $stable(b) && (sub != $past(sub))) |-> $stable(out)
    );

    ///// Combinational determinism /////
    // If a and b are stable, out must remain stable.
    check_out_stable_if_inputs_stable: assert property (
        @(posedge clk) ($stable(a) && $stable(b)) |-> $stable(out)
    );

endmodule

rtl:
module alt_ctl(op,func,aluc
    );
	input [5:0] op,func;
	output reg [4:0] aluc;
	always @* 
	begin
		case(op)
			6'b001000 : begin
				case(func)
					6'b100000 : aluc =  0;	6'b100010 : aluc =  1;	6'b100100 : aluc =  2;	6'b100101 : aluc =  3;	6'b100110 : aluc =  4;	6'b101010 : aluc =  5;	6'b000000 : aluc =  6;	6'b000100 : aluc =  7;	6'b000011 : aluc =  8;	6'b000111 : aluc =  9;	6'b000010 : aluc = 10;	6'b000110 : aluc = 11;	6'b000001 : aluc = 12;	6'b000010 : aluc = 13;	6'b011011 : aluc = 14; default   : aluc =  0;
				endcase
			end
			6'b000000 : aluc =  0;
			6'b000001 : aluc =  1;
			6'b000010 : aluc =  2;
			6'b000011 : aluc =  3;
			6'b000100 : aluc =  5;
			6'b000101 : aluc = 14;
			6'b001001 : aluc =  1;
			6'b001010 : aluc =  13;default : aluc = 0;
		endcase
	end

endmodule

sva:
module alt_ctl_sva (
    input logic CLK,        // External clock for SVA
    input logic RESETn,     // External active-low reset for SVA gating
    input logic [5:0] op,
    input logic [5:0] func,
    input logic [4:0] aluc
);
    // Analysis: RTL has no clock/reset and is purely combinational (always @*); this module uses external CLK/RESETn only to clock/gate assertions.

    ///// General range /////
    // aluc must be within 0..14 as all assignments are in this range.
    check_aluc_range: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc <= 5'd14)
    );

    ///// Outer op decode (direct mappings) /////
    // When op == 000000, aluc must be 0.
    check_op_000000_aluc0: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000000) |-> (aluc == 5'd0)
    );
    // When op == 000001, aluc must be 1.
    check_op_000001_aluc1: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000001) |-> (aluc == 5'd1)
    );
    // When op == 000010, aluc must be 2.
    check_op_000010_aluc2: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000010) |-> (aluc == 5'd2)
    );
    // When op == 000011, aluc must be 3.
    check_op_000011_aluc3: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000011) |-> (aluc == 5'd3)
    );
    // When op == 000100, aluc must be 5.
    check_op_000100_aluc5: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000100) |-> (aluc == 5'd5)
    );
    // When op == 000101, aluc must be 14.
    check_op_000101_aluc14: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000101) |-> (aluc == 5'd14)
    );
    // When op == 001001, aluc must be 1.
    check_op_001001_aluc1: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001001) |-> (aluc == 5'd1)
    );
    // When op == 001010, aluc must be 13.
    check_op_001010_aluc13: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001010) |-> (aluc == 5'd13)
    );
    // For any op not explicitly listed (and not 001000), aluc must be 0 (outer default).
    check_default_other_ops_aluc0: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (!(op inside {6'b001000,6'b000000,6'b000001,6'b000010,6'b000011,6'b000100,6'b000101,6'b001001,6'b001010})) |-> (aluc == 5'd0)
    );

    ///// Inner func decode when op == 001000 /////
    // func 100000 -> aluc 0
    check_op001000_func100000_aluc0: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b100000) |-> (aluc == 5'd0)
    );
    // func 100010 -> aluc 1
    check_op001000_func100010_aluc1: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b100010) |-> (aluc == 5'd1)
    );
    // func 100100 -> aluc 2
    check_op001000_func100100_aluc2: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b100100) |-> (aluc == 5'd2)
    );
    // func 100101 -> aluc 3
    check_op001000_func100101_aluc3: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b100101) |-> (aluc == 5'd3)
    );
    // func 100110 -> aluc 4
    check_op001000_func100110_aluc4: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b100110) |-> (aluc == 5'd4)
    );
    // func 101010 -> aluc 5
    check_op001000_func101010_aluc5: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b101010) |-> (aluc == 5'd5)
    );
    // func 000000 -> aluc 6
    check_op001000_func000000_aluc6: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b000000) |-> (aluc == 5'd6)
    );
    // func 000100 -> aluc 7
    check_op001000_func000100_aluc7: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b000100) |-> (aluc == 5'd7)
    );
    // func 000011 -> aluc 8
    check_op001000_func000011_aluc8: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b000011) |-> (aluc == 5'd8)
    );
    // func 000111 -> aluc 9
    check_op001000_func000111_aluc9: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b000111) |-> (aluc == 5'd9)
    );
    // func 000110 -> aluc 11
    check_op001000_func000110_aluc11: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b000110) |-> (aluc == 5'd11)
    );
    // func 000001 -> aluc 12
    check_op001000_func000001_aluc12: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b000001) |-> (aluc == 5'd12)
    );
    // func 011011 -> aluc 14
    check_op001000_func011011_aluc14: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b011011) |-> (aluc == 5'd14)
    );
    // For op==001000 and any func not listed in the case items, aluc must be 0 (inner default).
    check_op001000_default_other_funcs_aluc0: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (op == 6'b001000 && !(func inside {6'b100000,6'b100010,6'b100100,6'b100101,6'b100110,6'b101010,6'b000000,6'b000100,6'b000011,6'b000111,6'b000010,6'b000110,6'b000001,6'b011011})) |-> (aluc == 5'd0)
    );

endmodule

