module mux_2to1 (output reg out, input in0, in1, sel);
    always @ (sel) begin
        if (sel == 0) begin
            out <= in0;
        end
        else begin
            out <= in1;
        end
    end
endmodule

sva:
module mux_2to1_sva (
    input logic out,
    input logic in0,
    input logic in1,
    input logic sel
);
    // No explicit clock/reset; behavior updates only on sel edges (posedge/negedge).
    // Function: on sel==0 capture in0; on sel==1 capture in1; out changes only when sel toggles.

    // Before update at a rising sel edge, out equals the previously latched in0.
    check_prev_latch_visible_on_rise: assert property (
        @(posedge sel or negedge sel) $rose(sel) |-> (out == $past(in0))
    );

    // Before update at a falling sel edge, out equals the previously latched in1.
    check_prev_latch_visible_on_fall: assert property (
        @(posedge sel or negedge sel) $fell(sel) |-> (out == $past(in1))
    );

    // After a rising sel edge, by the next sel edge out equals in1 captured at the rise.
    check_latch_in1_persists_until_next_edge: assert property (
        @(posedge sel or negedge sel) $rose(sel) |-> ##1 (out == $past(in1))
    );

    // After a falling sel edge, by the next sel edge out equals in0 captured at the fall.
    check_latch_in0_persists_until_next_edge: assert property (
        @(posedge sel or negedge sel) $fell(sel) |-> ##1 (out == $past(in0))
    );
endmodule

rtl:
module exu_eclcomp8 (
  input [7:0] a,
  input [7:0] b,
  output result
);

  wire [7:0] xor_result;
  wire [3:0] first_nor_input;
  wire [3:0] second_nor_input;
  wire [2:0] third_nor_input;
  wire [2:0] nand_input;

  assign xor_result = a ^ b;
  assign first_nor_input = {~xor_result[7], ~xor_result[6], ~xor_result[5], ~xor_result[4]};
  assign second_nor_input = {~xor_result[3], ~xor_result[2], ~xor_result[1], ~xor_result[0]};
  assign third_nor_input = {~xor_result[4], ~xor_result[5], ~xor_result[6]};
  assign nand_input = {~second_nor_input[3], ~second_nor_input[2], ~second_nor_input[1], ~third_nor_input[2]};

  assign result = ~(|(first_nor_input) | |(second_nor_input) | ~(|(third_nor_input) | &(nand_input)));

endmodule

sva:
module exu_eclcomp8_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic result
);
    // Result equals AND-reduction of bitwise XOR of a and b.
    check_result_equals_andxor: assert property (
        @(posedge clk) result == (&(a ^ b))
    );

    // If b is bitwise complement of a, result must be 1.
    check_complement_implies_result_high: assert property (
        @(posedge clk) (b == ~a) |-> (result == 1'b1)
    );

    // If MSB bits are equal, result must be 0.
    check_zero_if_bit_equal_7: assert property (
        @(posedge clk) (a[7] == b[7]) |-> (result == 1'b0)
    );

    // If bit 6 is equal, result must be 0.
    check_zero_if_bit_equal_6: assert property (
        @(posedge clk) (a[6] == b[6]) |-> (result == 1'b0)
    );

    // If bit 5 is equal, result must be 0.
    check_zero_if_bit_equal_5: assert property (
        @(posedge clk) (a[5] == b[5]) |-> (result == 1'b0)
    );

    // If bit 4 is equal, result must be 0.
    check_zero_if_bit_equal_4: assert property (
        @(posedge clk) (a[4] == b[4]) |-> (result == 1'b0)
    );

    // If bit 3 is equal, result must be 0.
    check_zero_if_bit_equal_3: assert property (
        @(posedge clk) (a[3] == b[3]) |-> (result == 1'b0)
    );

    // If bit 2 is equal, result must be 0.
    check_zero_if_bit_equal_2: assert property (
        @(posedge clk) (a[2] == b[2]) |-> (result == 1'b0)
    );

    // If bit 1 is equal, result must be 0.
    check_zero_if_bit_equal_1: assert property (
        @(posedge clk) (a[1] == b[1]) |-> (result == 1'b0)
    );

    // If LSB bits are equal, result must be 0.
    check_zero_if_bit_equal_0: assert property (
        @(posedge clk) (a[0] == b[0]) |-> (result == 1'b0)
    );
endmodule

rtl:
module binary_comparator (
    input [3:0] num1,
    input [3:0] num2,
    output reg [3:0] larger_num
);

reg [3:0] pipeline_reg1;
reg [3:0] pipeline_reg2;

// Pipeline stage 1
always @(num1) begin
    pipeline_reg1 <= num1;
end

// Pipeline stage 2
always @(num2) begin
    pipeline_reg2 <= num2;
end

// Comparator module
always @(*) begin
    if (pipeline_reg1 > pipeline_reg2) begin
        larger_num <= pipeline_reg1;
    end else begin
        larger_num <= pipeline_reg2;
    end
end

endmodule

sva:
module binary_comparator_sva (
    input logic [3:0] num1,
    input logic [3:0] num2,
    input logic [3:0] larger_num,
    input logic [3:0] pipeline_reg1,
    input logic [3:0] pipeline_reg2
);
    // Note: No clock/reset in RTL; asynchronous staging + combinational compare. Assertions are sampled on any edge of larger_num bits.

    // larger_num must equal the max of pipeline_reg1 and pipeline_reg2 whenever it changes.
    check_output_is_max: assert property (
        @(posedge larger_num[0] or negedge larger_num[0] or
          posedge larger_num[1] or negedge larger_num[1] or
          posedge larger_num[2] or negedge larger_num[2] or
          posedge larger_num[3] or negedge larger_num[3])
        larger_num == (pipeline_reg1 > pipeline_reg2 ? pipeline_reg1 : pipeline_reg2)
    );

    // If pipeline_reg1 > pipeline_reg2, larger_num must select pipeline_reg1 when it changes.
    check_select_reg1_when_greater: assert property (
        @(posedge larger_num[0] or negedge larger_num[0] or
          posedge larger_num[1] or negedge larger_num[1] or
          posedge larger_num[2] or negedge larger_num[2] or
          posedge larger_num[3] or negedge larger_num[3])
        (pipeline_reg1 > pipeline_reg2) |-> (larger_num == pipeline_reg1)
    );

    // If pipeline_reg1 <= pipeline_reg2, larger_num must select pipeline_reg2 when it changes.
    check_select_reg2_when_not_greater: assert property (
        @(posedge larger_num[0] or negedge larger_num[0] or
          posedge larger_num[1] or negedge larger_num[1] or
          posedge larger_num[2] or negedge larger_num[2] or
          posedge larger_num[3] or negedge larger_num[3])
        (pipeline_reg1 <= pipeline_reg2) |-> (larger_num == pipeline_reg2)
    );

    // Ties must be resolved in favor of pipeline_reg2 whenever larger_num changes.
    check_tie_prefers_reg2: assert property (
        @(posedge larger_num[0] or negedge larger_num[0] or
          posedge larger_num[1] or negedge larger_num[1] or
          posedge larger_num[2] or negedge larger_num[2] or
          posedge larger_num[3] or negedge larger_num[3])
        (pipeline_reg1 == pipeline_reg2) |-> (larger_num == pipeline_reg2)
    );

    // larger_num must equal either pipeline_reg1 or pipeline_reg2 on any change.
    check_output_is_one_of_inputs: assert property (
        @(posedge larger_num[0] or negedge larger_num[0] or
          posedge larger_num[1] or negedge larger_num[1] or
          posedge larger_num[2] or negedge larger_num[2] or
          posedge larger_num[3] or negedge larger_num[3])
        (larger_num == pipeline_reg1) || (larger_num == pipeline_reg2)
    );

    // If larger_num equals pipeline_reg1, then pipeline_reg1 must be >= pipeline_reg2.
    check_consistency_when_eq_reg1: assert property (
        @(posedge larger_num[0] or negedge larger_num[0] or
          posedge larger_num[1] or negedge larger_num[1] or
          posedge larger_num[2] or negedge larger_num[2] or
          posedge larger_num[3] or negedge larger_num[3])
        (larger_num == pipeline_reg1) |-> (pipeline_reg1 >= pipeline_reg2)
    );

    // If larger_num equals pipeline_reg2, then pipeline_reg2 must be >= pipeline_reg1.
    check_consistency_when_eq_reg2: assert property (
        @(posedge larger_num[0] or negedge larger_num[0] or
          posedge larger_num[1] or negedge larger_num[1] or
          posedge larger_num[2] or negedge larger_num[2] or
          posedge larger_num[3] or negedge larger_num[3])
        (larger_num == pipeline_reg2) |-> (pipeline_reg2 >= pipeline_reg1)
    );

    // larger_num must be >= pipeline_reg1 whenever it changes.
    check_output_ge_reg1: assert property (
        @(posedge larger_num[0] or negedge larger_num[0] or
          posedge larger_num[1] or negedge larger_num[1] or
          posedge larger_num[2] or negedge larger_num[2] or
          posedge larger_num[3] or negedge larger_num[3])
        larger_num >= pipeline_reg1
    );

    // larger_num must be >= pipeline_reg2 whenever it changes.
    check_output_ge_reg2: assert property (
        @(posedge larger_num[0] or negedge larger_num[0] or
          posedge larger_num[1] or negedge larger_num[1] or
          posedge larger_num[2] or negedge larger_num[2] or
          posedge larger_num[3] or negedge larger_num[3])
        larger_num >= pipeline_reg2
    );
endmodule

rtl:
module adder (
    input [7:0] a,
    input [7:0] b,
    output [8:0] c
);

    wire [8:0] sum;
    wire carry;

    assign {carry, sum[7:0]} = a + b;

    assign c = {carry, sum[7:0]};

endmodule

sva:
module adder_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [8:0] c
);
    // c equals a + b as a 9-bit unsigned sum.
    check_sum_9bit: assert property (
        @(posedge clk) c == ({1'b0, a} + {1'b0, b})
    );

    // Lower 8 bits of c equal 8-bit sum of a and b.
    check_lower_byte: assert property (
        @(posedge clk) c[7:0] == (a + b)
    );

    // Carry bit equals wrap-around detection from 8-bit addition.
    check_carry_wrap: assert property (
        @(posedge clk) c[8] == ((a + b) < a)
    );

    // Sum is at least a (unsigned).
    check_ge_a: assert property (
        @(posedge clk) c >= {1'b0, a}
    );

    // Sum is at least b (unsigned).
    check_ge_b: assert property (
        @(posedge clk) c >= {1'b0, b}
    );

    // Adding zero on b leaves a unchanged.
    check_identity_b_zero: assert property (
        @(posedge clk) (b == 8'h00) |-> (c == {1'b0, a})
    );

    // Adding zero on a leaves b unchanged.
    check_identity_a_zero: assert property (
        @(posedge clk) (a == 8'h00) |-> (c == {1'b0, b})
    );

    // LSB of sum is XOR of operand LSBs.
    check_lsb_xor: assert property (
        @(posedge clk) c[0] == (a[0] ^ b[0])
    );

    // Bit1 sum equals XOR of operand bit1 with carry from bit0.
    check_bit1_sum: assert property (
        @(posedge clk) c[1] == ((a[1] ^ b[1]) ^ (a[0] & b[0]))
    );

    // Sum range is within 0..510.
    check_sum_range: assert property (
        @(posedge clk) c <= 9'd510
    );
endmodule

rtl:
module niosII_system_nios2_0_nios2_oci_td_mode (
    input [8:0] ctrl,
    output reg [3:0] td_mode
);

always @(*) begin
    case(ctrl[7:5])
        3'b000: td_mode = 4'b0000;
        3'b001: td_mode = 4'b1000;
        3'b010: td_mode = 4'b0100;
        3'b011: td_mode = 4'b1100;
        3'b100: td_mode = 4'b0010;
        3'b101: td_mode = 4'b1010;
        3'b110: td_mode = 4'b0101;
        3'b111: td_mode = 4'b1111;
        default: td_mode = 4'bxxxx;
    endcase
end

endmodule

sva:
module niosII_system_nios2_0_nios2_oci_td_mode_sva (
    input logic [8:0] ctrl,
    input logic [3:0] td_mode
);
    // Analysis: no clock/reset in RTL; pure combinational decode of ctrl[7:5] to td_mode.
    // Note: Assertions are sampled on posedge of ctrl[0] as a proxy clock.

    ///// Decode mapping /////
    // ctrl[7:5]==000 -> td_mode=0000
    decode_000: assert property (
        @(posedge ctrl[0]) (ctrl[7:5] == 3'b000) |-> (td_mode == 4'b0000)
    );
    // ctrl[7:5]==001 -> td_mode=1000
    decode_001: assert property (
        @(posedge ctrl[0]) (ctrl[7:5] == 3'b001) |-> (td_mode == 4'b1000)
    );
    // ctrl[7:5]==010 -> td_mode=0100
    decode_010: assert property (
        @(posedge ctrl[0]) (ctrl[7:5] == 3'b010) |-> (td_mode == 4'b0100)
    );
    // ctrl[7:5]==011 -> td_mode=1100
    decode_011: assert property (
        @(posedge ctrl[0]) (ctrl[7:5] == 3'b011) |-> (td_mode == 4'b1100)
    );
    // ctrl[7:5]==100 -> td_mode=0010
    decode_100: assert property (
        @(posedge ctrl[0]) (ctrl[7:5] == 3'b100) |-> (td_mode == 4'b0010)
    );
    // ctrl[7:5]==101 -> td_mode=1010
    decode_101: assert property (
        @(posedge ctrl[0]) (ctrl[7:5] == 3'b101) |-> (td_mode == 4'b1010)
    );
    // ctrl[7:5]==110 -> td_mode=0101
    decode_110: assert property (
        @(posedge ctrl[0]) (ctrl[7:5] == 3'b110) |-> (td_mode == 4'b0101)
    );
    // ctrl[7:5]==111 -> td_mode=1111
    decode_111: assert property (
        @(posedge ctrl[0]) (ctrl[7:5] == 3'b111) |-> (td_mode == 4'b1111)
    );

    ///// Bit-level relationships implied by the case /////
    // td_mode[3] mirrors ctrl[5]
    bit_map_msb: assert property (
        @(posedge ctrl[0]) td_mode[3] == ctrl[5]
    );
    // td_mode[2] mirrors ctrl[6]
    bit_map_b2: assert property (
        @(posedge ctrl[0]) td_mode[2] == ctrl[6]
    );
    // td_mode[0] equals ctrl[7] & ctrl[6]
    bit_map_b0: assert property (
        @(posedge ctrl[0]) td_mode[0] == (ctrl[7] & ctrl[6])
    );
    // td_mode[1] equals ctrl[7] & (~ctrl[6] | ctrl[5])
    bit_map_b1: assert property (
        @(posedge ctrl[0]) td_mode[1] == (ctrl[7] & (~ctrl[6] | ctrl[5]))
    );

    ///// Consistency checks derived from mapping /////
    // If td_mode[0] is 1 then td_mode[2] must be 1
    consistency_b0_implies_b2: assert property (
        @(posedge ctrl[0]) td_mode[0] |-> td_mode[2]
    );
    // When td_mode is 0000, ctrl[7:5] must be 000
    inverse_000: assert property (
        @(posedge ctrl[0]) (td_mode == 4'b0000) |-> (ctrl[7:5] == 3'b000)
    );
    // When td_mode is 1000, ctrl[7:5] must be 001
    inverse_1000: assert property (
        @(posedge ctrl[0]) (td_mode == 4'b1000) |-> (ctrl[7:5] == 3'b001)
    );
    // When td_mode is 1111, ctrl[7:5] must be 111
    inverse_1111: assert property (
        @(posedge ctrl[0]) (td_mode == 4'b1111) |-> (ctrl[7:5] == 3'b111)
    );
endmodule

rtl:
module my_uart_rx7to7(
