module binary_counter_4bit(
    input clk,
    input rst_n,
    output reg [3:0] count
);

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        count <= 4'b0;
    end else begin
        count <= count + 1;
        if (count == 4'b1111) begin
            count <= 4'b0;
        end
    end
end

endmodule

sva:
module binary_counter_4bit_sva (
    input logic clk,
    input logic rst_n,
    input logic [3:0] count
);

    // When reset is asserted low at a clock edge, count must be zero.
    reset_level_forces_zero: assert property (
        @(posedge clk) (!rst_n) |-> (count == 4'b0000)
    );

    // If reset is held low across consecutive clock edges, count remains zero.
    reset_held_keeps_zero: assert property (
        @(posedge clk) (!rst_n && $past(!rst_n)) |-> (count == 4'b0000)
    );

    // On a falling edge of rst_n (detected at the clock), count is zero.
    reset_fall_clears_count: assert property (
        @(posedge clk) $fell(rst_n) |-> (count == 4'b0000)
    );

    // On reset deassertion (rising edge of rst_n sampled at the clock), count becomes 1.
    reset_release_sets_one: assert property (
        @(posedge clk) $rose(rst_n) |-> (count == 4'b0001)
    );

    // In non-reset cycles, next value is either prior+1 (mod 16) or 1 if an async reset occurred between clocks.
    next_value_inc_or_one: assert property (
        @(posedge clk) disable iff (!rst_n)
            (count == (($past(count) + 4'd1) & 4'hF)) || (count == 4'h1)
    );

    // In non-reset cycles, observing count==0 implies prior sample was 15 (wrap event).
    zero_only_from_wrap: assert property (
        @(posedge clk) disable iff (!rst_n)
            (count == 4'h0) |-> ($past(count) == 4'hF)
    );

endmodule

rtl:
module adder (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] sum
);

    always @(posedge clk) begin
        if (reset) begin
            sum <= 8'b0;
        end else begin
            sum <= a + b;
        end
    end

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    input select,
    output [7:0] sum
);

    wire [7:0] sum1, sum2;

    adder adder1 (
        .clk(clk),
        .reset(reset),
        .a(a),
        .b(b),
        .sum(sum1)
    );

    adder adder2 (
        .clk(clk),
        .reset(reset),
        .a(a),
        .b(b),
        .sum(sum2)
    );

    assign sum = select ? sum2 : sum1;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic select,
    input logic [7:0] sum
);
    ///// Reset behavior (synchronous active-high) /////
    // After a reset cycle, sum must be zero.
    check_sum_zero_after_prev_reset: assert property (
        @(posedge clk) disable iff (reset)
            ($past(reset) == 1'b1) |-> (sum == 8'h00)
    );

    ///// Functional behavior (registered one-cycle adder) /////
    // When not previously in reset, sum equals last cycle's a + b (8-bit wrap).
    check_sum_from_prev_inputs: assert property (
        @(posedge clk) disable iff (reset)
            ($past(reset) == 1'b0) |-> (sum == ($past(a) + $past(b)))
    );

    // On reset deassertion this cycle, sum remains zero (was cleared last cycle).
    check_sum_zero_on_reset_fall: assert property (
        @(posedge clk) disable iff (reset)
            $fell(reset) |-> (sum == 8'h00)
    );

    // Adding zero on b (prev cycle) passes a through.
    check_sum_prev_b_zero: assert property (
        @(posedge clk) disable iff (reset)
            (($past(reset) == 1'b0) && ($past(b) == 8'h00)) |-> (sum == $past(a))
    );

    // Adding zero on a (prev cycle) passes b through.
    check_sum_prev_a_zero: assert property (
        @(posedge clk) disable iff (reset)
            (($past(reset) == 1'b0) && ($past(a) == 8'h00)) |-> (sum == $past(b))
    );

    // LSB of sum equals XOR of LSBs of a and b from previous cycle.
    check_lsb_xor: assert property (
        @(posedge clk) disable iff (reset)
            ($past(reset) == 1'b0) |-> (sum[0] == ($past(a[0]) ^ $past(b[0])))
    );

    // Example overflow: FF + 01 wraps to 00 (prev cycle operands).
    check_overflow_ff_plus_01_wrap: assert property (
        @(posedge clk) disable iff (reset)
            (($past(reset) == 1'b0) && ($past(a) == 8'hFF) && ($past(b) == 8'h01)) |-> (sum == 8'h00)
    );

    // Example overflow: 80 + 80 wraps to 00 (prev cycle operands).
    check_overflow_80_plus_80_wrap: assert property (
        @(posedge clk) disable iff (reset)
            (($past(reset) == 1'b0) && ($past(a) == 8'h80) && ($past(b) == 8'h80)) |-> (sum == 8'h00)
    );

    // When operands are equal (prev cycle), sum equals 2*a (8-bit wrap).
    check_double_when_equal_operands: assert property (
        @(posedge clk) disable iff (reset)
            (($past(reset) == 1'b0) && ($past(a) == $past(b))) |-> (sum == ($past(a) + $past(a)))
    );

    // Changing select does not affect computed sum (both branches are identical).
    check_select_toggle_irrelevant: assert property (
        @(posedge clk) disable iff (reset)
            (($past(reset) == 1'b0) && $changed(select)) |-> (sum == ($past(a) + $past(b)))
    );
endmodule

rtl:
module MUX2to1 (a, b, sel, out);
input a, b, sel;
output out;

   assign out = (sel) ? b : a;

endmodule

sva:
module MUX2to1_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic sel,
    input logic out
);

    ///// MUX functional correctness /////
    // Out equals selected input by sel.
    check_mux_function: assert property (
        @(posedge clk) out == (sel ? b : a)
    );

    // When sel is 0, out equals a.
    check_sel0_routes_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == a)
    );

    // When sel is 1, out equals b.
    check_sel1_routes_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == b)
    );

    ///// Change propagation and independence /////
    // A change on out implies sel changed or the currently selected input changed.
    check_out_change_cause: assert property (
        @(posedge clk) $changed(out) |-> ($changed(sel) || ((sel == 1'b1) && $changed(b)) || ((sel == 1'b0) && $changed(a)))
    );

    // When sel=0 and a,sel are stable, changes on b do not affect out.
    check_ignore_b_when_sel0: assert property (
        @(posedge clk) (sel == 1'b0) && $stable(sel) && $stable(a) && $changed(b) |-> $stable(out)
    );

    // When sel=1 and b,sel are stable, changes on a do not affect out.
    check_ignore_a_when_sel1: assert property (
        @(posedge clk) (sel == 1'b1) && $stable(sel) && $stable(b) && $changed(a) |-> $stable(out)
    );

    // When sel=0 and a changes (sel stable), out changes accordingly.
    check_selected_a_change_propagates: assert property (
        @(posedge clk) (sel == 1'b0) && $stable(sel) && $changed(a) |-> $changed(out)
    );

    // When sel=1 and b changes (sel stable), out changes accordingly.
    check_selected_b_change_propagates: assert property (
        @(posedge clk) (sel == 1'b1) && $stable(sel) && $changed(b) |-> $changed(out)
    );

endmodule

