  assign ps2_clk_rx_1 = ps2_mouse_clk_I;
  assign ps2_clk_rx_2 = ps2_keyb_clk_I;
  assign ps2_d_rx_1   = ps2_mouse_data_I;
  assign ps2_d_rx_2   = ps2_keyb_data_I;

  assign ps2_mouse_clk_O  = 1'b0;
  assign ps2_mouse_clk_T  = ~ps2_clk_tx_1;
  assign ps2_mouse_data_O = 1'b0;
  assign ps2_mouse_data_T = ~ps2_d_tx_1;
  assign ps2_keyb_clk_O   = 1'b0;
  assign ps2_keyb_clk_T   = ~ps2_clk_tx_2;
  assign ps2_keyb_data_O  = 1'b0;
  assign ps2_keyb_data_T  = ~ps2_d_tx_2;

endmodule

sva:
module dual_ps2_ioadapter_sva (
  input logic ps2_clk_rx_1,
  input logic ps2_clk_rx_2,
  input logic ps2_clk_tx_1,
  input logic ps2_clk_tx_2,
  input logic ps2_d_rx_1,
  input logic ps2_d_rx_2,
  input logic ps2_d_tx_1,
  input logic ps2_d_tx_2,
  input logic ps2_mouse_clk_I,
  input logic ps2_mouse_clk_O,
  input logic ps2_mouse_clk_T,
  input logic ps2_mouse_data_I,
  input logic ps2_mouse_data_O,
  input logic ps2_mouse_data_T,
  input logic ps2_keyb_clk_I,
  input logic ps2_keyb_clk_O,
  input logic ps2_keyb_clk_T,
  input logic ps2_keyb_data_I,
  input logic ps2_keyb_data_O,
  input logic ps2_keyb_data_T
);

  ///// RX mappings /////
  // Mouse clock RX mirrors mouse clock input (posedge).
  mirror_mouse_clk_rx_pos: assert property (
    @(posedge ps2_mouse_clk_I) ##0 (ps2_clk_rx_1 == ps2_mouse_clk_I)
  );
  // Mouse clock RX mirrors mouse clock input (negedge).
  mirror_mouse_clk_rx_neg: assert property (
    @(negedge ps2_mouse_clk_I) ##0 (ps2_clk_rx_1 == ps2_mouse_clk_I)
  );
  // Keyboard clock RX mirrors keyboard clock input (posedge).
  mirror_keyb_clk_rx_pos: assert property (
    @(posedge ps2_keyb_clk_I) ##0 (ps2_clk_rx_2 == ps2_keyb_clk_I)
  );
  // Keyboard clock RX mirrors keyboard clock input (negedge).
  mirror_keyb_clk_rx_neg: assert property (
    @(negedge ps2_keyb_clk_I) ##0 (ps2_clk_rx_2 == ps2_keyb_clk_I)
  );
  // Mouse data RX mirrors mouse data input (posedge).
  mirror_mouse_data_rx_pos: assert property (
    @(posedge ps2_mouse_data_I) ##0 (ps2_d_rx_1 == ps2_mouse_data_I)
  );
  // Mouse data RX mirrors mouse data input (negedge).
  mirror_mouse_data_rx_neg: assert property (
    @(negedge ps2_mouse_data_I) ##0 (ps2_d_rx_1 == ps2_mouse_data_I)
  );
  // Keyboard data RX mirrors keyboard data input (posedge).
  mirror_keyb_data_rx_pos: assert property (
    @(posedge ps2_keyb_data_I) ##0 (ps2_d_rx_2 == ps2_keyb_data_I)
  );
  // Keyboard data RX mirrors keyboard data input (negedge).
  mirror_keyb_data_rx_neg: assert property (
    @(negedge ps2_keyb_data_I) ##0 (ps2_d_rx_2 == ps2_keyb_data_I)
  );

  ///// Tri-state control mappings /////
  // Mouse clock T is inverse of tx_1 (posedge).
  inv_mouse_clk_T_pos: assert property (
    @(posedge ps2_clk_tx_1) ##0 (ps2_mouse_clk_T == ~ps2_clk_tx_1)
  );
  // Mouse clock T is inverse of tx_1 (negedge).
  inv_mouse_clk_T_neg: assert property (
    @(negedge ps2_clk_tx_1) ##0 (ps2_mouse_clk_T == ~ps2_clk_tx_1)
  );
  // Mouse data T is inverse of d_tx_1 (posedge).
  inv_mouse_data_T_pos: assert property (
    @(posedge ps2_d_tx_1) ##0 (ps2_mouse_data_T == ~ps2_d_tx_1)
  );
  // Mouse data T is inverse of d_tx_1 (negedge).
  inv_mouse_data_T_neg: assert property (
    @(negedge ps2_d_tx_1) ##0 (ps2_mouse_data_T == ~ps2_d_tx_1)
  );
  // Keyboard clock T is inverse of tx_2 (posedge).
  inv_keyb_clk_T_pos: assert property (
    @(posedge ps2_clk_tx_2) ##0 (ps2_keyb_clk_T == ~ps2_clk_tx_2)
  );
  // Keyboard clock T is inverse of tx_2 (negedge).
  inv_keyb_clk_T_neg: assert property (
    @(negedge ps2_clk_tx_2) ##0 (ps2_keyb_clk_T == ~ps2_clk_tx_2)
  );
  // Keyboard data T is inverse of d_tx_2 (posedge).
  inv_keyb_data_T_pos: assert property (
    @(posedge ps2_d_tx_2) ##0 (ps2_keyb_data_T == ~ps2_d_tx_2)
  );
  // Keyboard data T is inverse of d_tx_2 (negedge).
  inv_keyb_data_T_neg: assert property (
    @(negedge ps2_d_tx_2) ##0 (ps2_keyb_data_T == ~ps2_d_tx_2)
  );

  ///// Constant drive on O pins /////
  // Mouse clock O is constant 0.
  const_mouse_clk_O: assert property (
    @(posedge ps2_clk_tx_1) ##0 (ps2_mouse_clk_O == 1'b0)
  );
  // Mouse data O is constant 0.
  const_mouse_data_O: assert property (
    @(posedge ps2_d_tx_1) ##0 (ps2_mouse_data_O == 1'b0)
  );
  // Keyboard clock O is constant 0.
  const_keyb_clk_O: assert property (
    @(posedge ps2_clk_tx_2) ##0 (ps2_keyb_clk_O == 1'b0)
  );
  // Keyboard data O is constant 0.
  const_keyb_data_O: assert property (
    @(posedge ps2_d_tx_2) ##0 (ps2_keyb_data_O == 1'b0)
  );

endmodule

rtl:
module max_8bit (
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] max_val
);

    always @* begin
        if (A > B)
            max_val = A;
        else
            max_val = B;
    end

endmodule

sva:
module max_8bit_sva (
    input logic clk,           // sampling clock for assertions
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] max_val
);
    // Analysis: no clock/reset in DUT; pure combinational; max_val = (A > B) ? A : B.

    // Functional equivalence to ternary form.
    check_functional_spec: assert property (
        @(posedge clk) max_val == ((A > B) ? A : B)
    );

    // If A is strictly greater than B, output must be A.
    check_select_A_when_gt: assert property (
        @(posedge clk) (A > B) |-> (max_val == A)
    );

    // If A is less than or equal to B, output must be B.
    check_select_B_when_le: assert property (
        @(posedge clk) (A <= B) |-> (max_val == B)
    );

    // On ties, output equals both inputs (they are equal).
    check_tie_outputs_equal: assert property (
        @(posedge clk) (A == B) |-> ((max_val == A) && (max_val == B))
    );

    // Output must equal one of the inputs.
    check_output_is_input_value: assert property (
        @(posedge clk) (max_val == A) || (max_val == B)
    );

    // Output is not less than A.
    check_output_ge_A: assert property (
        @(posedge clk) max_val >= A
    );

    // Output is not less than B.
    check_output_ge_B: assert property (
        @(posedge clk) max_val >= B
    );

    // If output equals A, then A is at least B.
    check_output_eq_A_implies_A_ge_B: assert property (
        @(posedge clk) (max_val == A) |-> (A >= B)
    );

    // If output equals B, then B is at least A.
    check_output_eq_B_implies_B_ge_A: assert property (
        @(posedge clk) (max_val == B) |-> (B >= A)
    );

    // If A is strictly less than B, output cannot be A.
    check_no_A_when_A_lt_B: assert property (
        @(posedge clk) (A < B) |-> (max_val != A)
    );
endmodule

rtl:
module intr_capturer #(
  parameter NUM_INTR = 32
  )(
  input                clk,
  input                rst_n,
  input [NUM_INTR-1:0] interrupt_in,
  input                addr,
  input                read,
  output [31:0]        rddata
);

  reg  [NUM_INTR-1:0]  interrupt_reg;
  reg  [31:0]          readdata_with_waitstate;
  wire [31:0]          act_readdata;
  wire [31:0]          readdata_lower_intr;
  wire [31:0]          readdata_higher_intr;
  wire                 access_lower_32;
  wire                 access_higher_32;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) interrupt_reg <= 'b0;
    else        interrupt_reg <= interrupt_in;
    end

  generate
  if (NUM_INTR>32) begin : two_intr_reg_needed
    assign readdata_lower_intr  = interrupt_reg[31:0] & {(32){access_lower_32}};
    assign readdata_higher_intr = interrupt_reg[NUM_INTR-1:32] & {(NUM_INTR-32){access_higher_32}};
    end
  else begin : only_1_reg
    assign readdata_lower_intr  = interrupt_reg & {(NUM_INTR){access_lower_32}};
    assign readdata_higher_intr = {32{1'b0}};
    end
  endgenerate

  assign access_lower_32 = read & (addr == 0);
  assign access_higher_32 = read & (addr == 1);
  assign act_readdata = readdata_lower_intr | readdata_higher_intr;
  assign rddata = readdata_with_waitstate;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) readdata_with_waitstate <= 32'b0;
    else        readdata_with_waitstate <= act_readdata;
    end

endmodule

sva:
module intr_capturer_sva #(
    parameter int unsigned NUM_INTR = 32
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic [NUM_INTR-1:0]  interrupt_in,
    input  logic                 addr,
    input  logic                 read,
    input  logic [31:0]          rddata,

    // Internal RTL signals (to be connected via bind)
    input  logic [NUM_INTR-1:0]  interrupt_reg,
    input  logic [31:0]          readdata_with_waitstate,
    input  logic [31:0]          act_readdata,
    input  logic [31:0]          readdata_lower_intr,
    input  logic [31:0]          readdata_higher_intr,
    input  logic                 access_lower_32,
    input  logic                 access_higher_32
);

    ///// Reset behavior /////
    // interrupt_reg clears to 0 during reset.
    reset_clears_interrupt_reg: assert property (
        @(posedge clk) !rst_n |-> (interrupt_reg == '0)
    );
    // readdata_with_waitstate clears to 0 during reset.
    reset_clears_readdata_with_waitstate: assert property (
        @(posedge clk) !rst_n |-> (readdata_with_waitstate == 32'b0)
    );
    // rddata clears to 0 during reset.
    reset_clears_rddata: assert property (
        @(posedge clk) !rst_n |-> (rddata == 32'b0)
    );

    ///// Simple structural relationships /////
    // rddata is driven by readdata_with_waitstate.
    rddata_matches_reg: assert property (
        @(posedge clk) disable iff (!rst_n) rddata == readdata_with_waitstate
    );
    // access_lower_32 definition matches read & (addr==0).
    access_lower_definition: assert property (
        @(posedge clk) disable iff (!rst_n) access_lower_32 == (read && (addr == 1'b0))
    );
    // access_higher_32 definition matches read & (addr==1).
    access_higher_definition: assert property (
        @(posedge clk) disable iff (!rst_n) access_higher_32 == (read && (addr == 1'b1))
    );
    // Only one access (lower/higher) can be active at a time.
    access_mutex: assert property (
        @(posedge clk) disable iff (!rst_n) !(access_lower_32 && access_higher_32)
    );
    // act_readdata is the OR of lower and higher read data.
    act_is_or_of_segments: assert property (
        @(posedge clk) disable iff (!rst_n) act_readdata == (readdata_lower_intr | readdata_higher_intr)
    );

    ///// Gating behavior /////
    // No read => both segment data outputs are zero.
    segments_zero_when_no_read: assert property (
        @(posedge clk) disable iff (!rst_n) (!read) |-> ((readdata_lower_intr == 32'b0) && (readdata_higher_intr == 32'b0))
    );
    // No read => act_readdata is zero.
    act_zero_when_no_read: assert property (
        @(posedge clk) disable iff (!rst_n) (!read) |-> (act_readdata == 32'b0)
    );
    // Next cycle after no read => rddata is zero.
    rddata_zero_next_when_no_read: assert property (
        @(posedge clk) disable iff (!rst_n) (!read) |=> (rddata == 32'b0)
    );
    // If lower bank is selected, higher segment must be zero.
    higher_zero_when_lower_selected: assert property (
        @(posedge clk) disable iff (!rst_n) access_lower_32 |-> (readdata_higher_intr == 32'b0)
    );
    // If higher bank is selected, lower segment must be zero.
    lower_zero_when_higher_selected: assert property (
        @(posedge clk) disable iff (!rst_n) access_higher_32 |-> (readdata_lower_intr == 32'b0)
    );
    // When lower selected, act_readdata equals lower segment.
    act_equals_lower_on_lower_select: assert property (
        @(posedge clk) disable iff (!rst_n) access_lower_32 |-> (act_readdata == readdata_lower_intr)
    );
    // When higher selected, act_readdata equals higher segment.
    act_equals_higher_on_higher_select: assert property (
        @(posedge clk) disable iff (!rst_n) access_higher_32 |-> (act_readdata == readdata_higher_intr)
    );

    ///// Segment construction per NUM_INTR /////
    if (NUM_INTR > 32) begin : bigN_checks
        // Lower segment = low 32 interrupt_reg bits masked by access_lower_32.
        lower_segment_bigN: assert property (
            @(posedge clk) disable iff (!rst_n)
                readdata_lower_intr == ( {32{access_lower_32}} & interrupt_reg[31:0] )
        );
        // Higher segment low (NUM_INTR-32) bits = upper interrupt_reg bits masked; upper bits zero.
        higher_segment_bits_bigN: assert property (
            @(posedge clk) disable iff (!rst_n)
                readdata_higher_intr[(NUM_INTR-33):0] == ( ({(NUM_INTR-32){access_higher_32}}) & interrupt_reg[NUM_INTR-1:32] )
        );
        // Higher segment upper unused bits are zero.
        higher_segment_upper_zero_bigN: assert property (
            @(posedge clk) disable iff (!rst_n)
                readdata_higher_intr[31:(NUM_INTR-32)] == '0
        );
    end else begin : smallN_checks
        // Lower segment low NUM_INTR bits = interrupt_reg masked by access; upper bits zero.
        lower_segment_lowbits_smallN: assert property (
            @(posedge clk) disable iff (!rst_n)
                readdata_lower_intr[NUM_INTR-1:0] == ( ({NUM_INTR{access_lower_32}}) & interrupt_reg[NUM_INTR-1:0] )
        );
        // Lower segment upper bits are zero when NUM_INTR<32.
        lower_segment_upper_zero_smallN: assert property (
            @(posedge clk) disable iff (!rst_n)
                readdata_lower_intr[31:NUM_INTR] == '0
        );
        // Higher segment is always zero when NUM_INTR<=32.
        higher_segment_zero_smallN: assert property (
            @(posedge clk) disable iff (!rst_n) readdata_higher_intr == 32'b0
        );
    end

endmodule

rtl:
module sky130_fd_sc_ms__fahcin (
    COUT,
    SUM ,
    A   ,
    B   ,
    CIN
);

    output COUT;
    output SUM ;
    input  A   ;
    input  B   ;
    input  CIN ;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire ci          ;
    wire xor0_out_SUM;
    wire a_b         ;
    wire a_ci        ;
    wire b_ci        ;
    wire or0_out_COUT;

    not not0 (ci          , CIN            );
    xor xor0 (xor0_out_SUM, A, B, ci       );
    buf buf0 (SUM         , xor0_out_SUM   );
    and and0 (a_b         , A, B           );
    and and1 (a_ci        , A, ci          );
    and and2 (b_ci        , B, ci          );
    or  or0  (or0_out_COUT, a_b, a_ci, b_ci);
    buf buf1 (COUT        , or0_out_COUT   );

endmodule

sva:
module sky130_fd_sc_ms__fahcin_sva (
    input logic CLK,
    input logic COUT,
    input logic SUM,
    input logic A,
    input logic B,
    input logic CIN
);
    ///// Functional equivalence to gate-level logic /////
    // SUM equals 3-input XOR of A, B, and ~CIN.
    check_sum_eq_xor3_inv_cin: assert property (
        @(posedge CLK) disable iff (1'b0) SUM == (A ^ B ^ (~CIN))
    );
    // COUT equals (A & B) | (A & ~CIN) | (B & ~CIN).
    check_cout_eq_or3_of_ands: assert property (
        @(posedge CLK) disable iff (1'b0) COUT == ((A & B) | (A & (~CIN)) | (B & (~CIN)))
    );

    ///// Derived behaviors for CIN = 1 /////
    // When CIN=1, SUM reduces to A ^ B.
    check_sum_when_cin_1: assert property (
        @(posedge CLK) disable iff (1'b0) (CIN == 1'b1) |-> (SUM == (A ^ B))
    );
    // When CIN=1, COUT reduces to A & B.
    check_cout_when_cin_1: assert property (
        @(posedge CLK) disable iff (1'b0) (CIN == 1'b1) |-> (COUT == (A & B))
    );

    ///// Derived behaviors for CIN = 0 /////
    // When CIN=0, SUM reduces to ~(A ^ B).
    check_sum_when_cin_0: assert property (
        @(posedge CLK) disable iff (1'b0) (CIN == 1'b0) |-> (SUM == ~(A ^ B))
    );
    // When CIN=0, COUT reduces to A | B.
    check_cout_when_cin_0: assert property (
        @(posedge CLK) disable iff (1'b0) (CIN == 1'b0) |-> (COUT == (A | B))
    );

    ///// Partition by A == B vs A != B /////
    // If A == B, SUM equals ~CIN.
    check_sum_when_a_eq_b: assert property (
        @(posedge CLK) disable iff (1'b0) (A == B) |-> (SUM == (~CIN))
    );
    // If A == B, COUT equals A (same as A & B).
    check_cout_when_a_eq_b: assert property (
        @(posedge CLK) disable iff (1'b0) (A == B) |-> (COUT == A)
    );
    // If A != B, SUM equals CIN.
    check_sum_when_a_neq_b: assert property (
        @(posedge CLK) disable iff (1'b0) (A != B) |-> (SUM == CIN)
    );
    // If A != B, COUT equals ~CIN.
    check_cout_when_a_neq_b: assert property (
        @(posedge CLK) disable iff (1'b0) (A != B) |-> (COUT == (~CIN))
    );
endmodule

rtl:
module sky130_fd_sc_hdll__and3 (
    X,
    A,
    B,
    C
);

    output X;
    input  A;
    input  B;
    input  C;

    wire and0_out_X;

    and and0 (and0_out_X, C, A, B        );
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_hdll__and3_sva (
    input logic X,
    input logic A,
    input logic B,
    input logic C
);
    // No clock/reset in RTL; pure combinational AND3 with buffer to X.
    // Assertions are sampled on any edge of A, B, C, or X.

    // X must equal A & B & C at all times.
    check_functional_equivalence: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            X == (A & B & C)
    );

    // If any input is 0, X must be 0.
    check_zero_dominance: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            ((!A) || (!B) || (!C)) |-> (X == 1'b0)
    );

    // If all inputs are 1, X must be 1.
    check_all_high_implies_one: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            (A && B && C) |-> (X == 1'b1)
    );

    // A&B high makes X follow C.
    check_ab_high_passthru_c: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            (A && B) |-> (X == C)
    );

    // A&C high makes X follow B.
    check_ac_high_passthru_b: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            (A && C) |-> (X == B)
    );

    // B&C high makes X follow A.
    check_bc_high_passthru_a: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            (B && C) |-> (X == A)
    );

    // A rising transition of the 3-input AND forces X to rise.
    check_and_rise_causes_x_rise: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            $rose(A && B && C) |-> $rose(X)
    );

    // A falling transition of the 3-input AND forces X to fall.
    check_and_fall_causes_x_fall: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            $fell(A && B && C) |-> $fell(X)
    );

    // X can only rise when all inputs are 1.
    check_x_rise_requires_all_high: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            $rose(X) |-> (A && B && C)
    );

    // X can only fall when not all inputs are 1.
    check_x_fall_requires_not_all_high: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            $fell(X) |-> !(A && B && C)
    );

    // Any change on X must be due to a change on at least one input.
    check_x_change_requires_input_change: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            $changed(X) |-> ($changed(A) || $changed(B) || $changed(C))
    );

endmodule

rtl:
module arithmetic(
  input signed [7:0] A,
  input signed [7:0] B,
  output reg signed [7:0] sum,
  output reg signed [7:0] diff,
  output reg signed [15:0] product,
  output reg signed [7:0] quotient
);

  always @ (A or B) begin
    sum = A + B;
    diff = A - B;
    product = A * B;
    if (B == 0) begin
      quotient = 0;
    end else begin
      quotient = A / B;
    end
  end

endmodule

sva:
module arithmetic_sva (
    input logic CLK,
    input logic signed [7:0] A,
    input logic signed [7:0] B,
    input logic signed [7:0] sum,
    input logic signed [7:0] diff,
    input logic signed [15:0] product,
    input logic signed [7:0] quotient
);
    // Sum must equal A + B (8-bit signed)
    check_sum_equals_A_plus_B: assert property (
        @(posedge CLK) sum == (A + B)
    );

    // Diff must equal A - B (8-bit signed)
    check_diff_equals_A_minus_B: assert property (
        @(posedge CLK) diff == (A - B)
    );

    // Product must equal A * B (16-bit signed)
    check_product_equals_A_times_B: assert property (
        @(posedge CLK) product == (A * B)
    );

    // When divisor is zero, quotient must be zero
    check_quotient_zero_when_div_by_zero: assert property (
        @(posedge CLK) (B == 0) |-> (quotient == 0)
    );

    // When divisor is nonzero, quotient must be A / B (8-bit signed)
    check_quotient_equals_A_div_B_when_B_nonzero: assert property (
        @(posedge CLK) (B != 0) |-> (quotient == (A / B))
    );

    // If A is zero, product must be zero
    check_product_zero_if_A_zero: assert property (
        @(posedge CLK) (A == 0) |-> (product == 0)
    );

    // If B is zero, product must be zero
    check_product_zero_if_B_zero: assert property (
        @(posedge CLK) (B == 0) |-> (product == 0)
    );

    // Outputs must be stable when inputs are stable (pure combinational behavior)
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(A) && $stable(B)) |-> ($stable(sum) && $stable(diff) && $stable(product) && $stable(quotient))
    );
endmodule

