module top_module(
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    output reg out_always
);

    always @(*) begin
        case ({sel_b2, sel_b1})
            2'b00: out_always = a;
            2'b01: out_always = a;
            2'b10: out_always = b;
            2'b11: out_always = b;
        endcase
    end

endmodule

sva:
module top_module_sva (
    input logic a,
    input logic b,
    input logic sel_b1,
    input logic sel_b2,
    input logic out_always
);
    // Sample on any edge of inputs (no clock/reset in RTL; combinational mux).
    // Output equals a whenever sel_b2 is 0.
    route_a_when_sel0: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2)
        (sel_b2 == 1'b0) |-> (out_always == a)
    );
    // Output equals b whenever sel_b2 is 1.
    route_b_when_sel1: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2)
        (sel_b2 == 1'b1) |-> (out_always == b)
    );
    // If selecting a and select is stable, any output change must be due to a changing.
    out_change_requires_a_when_sel0: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2)
        ($stable(sel_b2) && (sel_b2 == 1'b0) && $changed(out_always)) |-> $changed(a)
    );
    // If selecting b and select is stable, any output change must be due to b changing.
    out_change_requires_b_when_sel1: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2)
        ($stable(sel_b2) && (sel_b2 == 1'b1) && $changed(out_always)) |-> $changed(b)
    );
    // If selecting a and a changes with stable select, output must change to match a.
    a_change_updates_out_when_sel0: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2)
        ($stable(sel_b2) && (sel_b2 == 1'b0) && $changed(a)) |-> ($changed(out_always) && (out_always == a))
    );
    // If selecting b and b changes with stable select, output must change to match b.
    b_change_updates_out_when_sel1: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2)
        ($stable(sel_b2) && (sel_b2 == 1'b1) && $changed(b)) |-> ($changed(out_always) && (out_always == b))
    );
    // If a, b, and sel_b2 are stable, output must be stable.
    out_stable_if_inputs_and_select_stable: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2)
        ($stable(a) && $stable(b) && $stable(sel_b2)) |-> $stable(out_always)
    );
    // Changing sel_b1 alone (with a, b, sel_b2 stable) must not affect the output.
    selb1_change_no_effect: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2)
        ($changed(sel_b1) && $stable(a) && $stable(b) && $stable(sel_b2)) |-> $stable(out_always)
    );
    // On rising edge of sel_b2, output selects b.
    out_b_on_selb2_rise: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2)
        $rose(sel_b2) |-> (out_always == b)
    );
    // On falling edge of sel_b2, output selects a.
    out_a_on_selb2_fall: assert property (
        @(posedge a or negedge a or posedge b or negedge b or posedge sel_b1 or negedge sel_b1 or posedge sel_b2 or negedge sel_b2)
        $fell(sel_b2) |-> (out_always == a)
    );
endmodule

rtl:
module calculator(
    input [7:0] a,
    input [7:0] b,
    input [1:0] op,
    output reg [7:0] result
);

always @*
begin
    case(op)
        2'b00: result = a + b;
        2'b01: result = a - b;
        2'b10: result = a * b;
        2'b11: result = a / b;
    endcase
end

endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] op,
    input logic [7:0] result
);

    // 8-bit add (wraps to 8 bits)
    function automatic [7:0] add8 (input [7:0] x, input [7:0] y);
        add8 = x + y;
    endfunction
    // 8-bit sub (wraps to 8 bits)
    function automatic [7:0] sub8 (input [7:0] x, input [7:0] y);
        sub8 = x - y;
    endfunction
    // 8-bit mul (low 8 bits of product)
    function automatic [7:0] mul8 (input [7:0] x, input [7:0] y);
        mul8 = x * y;
    endfunction
    // 8-bit div (truncated integer divide)
    function automatic [7:0] div8 (input [7:0] x, input [7:0] y);
        div8 = x / y;
    endfunction

    ///// Functional correctness for each op /////
    // When op==00, result is 8-bit a+b (wrap).
    check_add_correct: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == add8(a, b))
    );
    // When op==01, result is 8-bit a-b (wrap).
    check_sub_correct: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == sub8(a, b))
    );
    // When op==10, result is low 8 bits of a*b.
    check_mul_correct: assert property (
        @(posedge clk) (op == 2'b10) |-> (result == mul8(a, b))
    );
    // When op==11, result is a/b (8-bit integer divide).
    check_div_correct: assert property (
        @(posedge clk) (op == 2'b11) |-> (result == div8(a, b))
    );

    ///// Combinational purity /////
    // If a, b, op are stable, result must be stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({a, b, op}) |-> $stable(result)
    );

    ///// Simple algebraic identities per operation /////
    // Add: +0 is identity.
    check_add_identity_b0: assert property (
        @(posedge clk) (op == 2'b00) && (b == 8'h00) |-> (result == a)
    );
    // Add: 0+ is identity.
    check_add_identity_a0: assert property (
        @(posedge clk) (op == 2'b00) && (a == 8'h00) |-> (result == b)
    );
    // Sub: -0 is identity.
    check_sub_identity_b0: assert property (
        @(posedge clk) (op == 2'b01) && (b == 8'h00) |-> (result == a)
    );
    // Sub: x-x = 0 (8-bit wrap).
    check_sub_self_zero: assert property (
        @(posedge clk) (op == 2'b01) && (a == b) |-> (result == 8'h00)
    );
    // Mul: 0 is annihilator.
    check_mul_zero: assert property (
        @(posedge clk) (op == 2'b10) && ((a == 8'h00) || (b == 8'h00)) |-> (result == 8'h00)
    );
    // Mul: 1 is identity (a*1 = a).
    check_mul_identity_b1: assert property (
        @(posedge clk) (op == 2'b10) && (b == 8'h01) |-> (result == a)
    );
    // Mul: 1 is identity (1*b = b).
    check_mul_identity_a1: assert property (
        @(posedge clk) (op == 2'b10) && (a == 8'h01) |-> (result == b)
    );
    // Div: /1 is identity.
    check_div_by_one: assert property (
        @(posedge clk) (op == 2'b11) && (b == 8'h01) |-> (result == a)
    );
    // Div: 0/x = 0 for nonzero x.
    check_div_zero_numer: assert property (
        @(posedge clk) (op == 2'b11) && (a == 8'h00) && (b != 8'h00) |-> (result == 8'h00)
    );
    // Div: x/x = 1 for nonzero x.
    check_div_self_one: assert property (
        @(posedge clk) (op == 2'b11) && (a == b) && (b != 8'h00) |-> (result == 8'h01)
    );

endmodule

rtl:
module compare_op (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] Y
);

    always @(*) begin
        if (A > B)
            Y = A - B;
        else
            Y = B - A;
    end

endmodule

sva:
module compare_op_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] Y
);
    // Y implements absolute difference |A-B|.
    check_absdiff_definition: assert property (
        @(posedge A[0] or posedge B[0]) Y == ((A > B) ? (A - B) : (B - A))
    );

    // When A > B, Y equals A - B.
    check_Y_when_A_gt_B: assert property (
        @(posedge A[0] or posedge B[0]) (A > B) |-> (Y == (A - B))
    );

    // When A <= B, Y equals B - A.
    check_Y_when_A_le_B: assert property (
        @(posedge A[0] or posedge B[0]) !(A > B) |-> (Y == (B - A))
    );

    // When A == B, Y is zero.
    check_zero_when_equal: assert property (
        @(posedge A[0] or posedge B[0]) (A == B) |-> (Y == 4'd0)
    );

    // Y is zero only when A == B.
    check_zero_implies_equal: assert property (
        @(posedge A[0] or posedge B[0]) (Y == 4'd0) |-> (A == B)
    );

    // If A >= B, then B + Y equals A.
    check_add_inverse_when_A_ge_B: assert property (
        @(posedge A[0] or posedge B[0]) (A >= B) |-> ((B + Y) == A)
    );

    // If B >= A, then A + Y equals B.
    check_add_inverse_when_B_ge_A: assert property (
        @(posedge A[0] or posedge B[0]) (B >= A) |-> ((A + Y) == B)
    );

    // For A > B, Y does not exceed A.
    check_upper_bound_when_A_gt_B: assert property (
        @(posedge A[0] or posedge B[0]) (A > B) |-> (Y <= A)
    );

    // For A <= B, Y does not exceed B.
    check_upper_bound_when_A_le_B: assert property (
        @(posedge A[0] or posedge B[0]) !(A > B) |-> (Y <= B)
    );

    // If B is zero, Y equals A.
    check_B_zero_pass_through: assert property (
        @(posedge A[0] or posedge B[0]) (B == 4'd0) |-> (Y == A)
    );

    // If A is zero, Y equals B.
    check_A_zero_pass_through: assert property (
        @(posedge A[0] or posedge B[0]) (A == 4'd0) |-> (Y == B)
    );
endmodule

rtl:
module mux2to1 (
    A   ,
    B   ,
    SEL ,
    OUT 
);

    input A   ;
    input B   ;
    input SEL ;
    output reg OUT ;

    always @(SEL or A or B)
    begin
        if (SEL == 0)
            OUT = A;
        else
            OUT = B;
    end

endmodule

sva:
module mux2to1_sva (
    input logic CLK,   // Sampling clock for assertions (RTL has no clock/reset)
    input logic A,
    input logic B,
    input logic SEL,
    input logic OUT
);
    // When SEL is 0, OUT must equal A.
    check_sel0_routes_A: assert property (
        @(posedge CLK) (SEL == 1'b0) |-> (OUT == A)
    );

    // When SEL is 1, OUT must equal B.
    check_sel1_routes_B: assert property (
        @(posedge CLK) (SEL == 1'b1) |-> (OUT == B)
    );

    // If SEL=0 and both SEL and A are stable, OUT remains stable.
    check_out_stable_when_sel0_and_A_stable: assert property (
        @(posedge CLK) (SEL == 1'b0 && $stable(SEL) && $stable(A)) |-> $stable(OUT)
    );

    // If SEL=1 and both SEL and B are stable, OUT remains stable.
    check_out_stable_when_sel1_and_B_stable: assert property (
        @(posedge CLK) (SEL == 1'b1 && $stable(SEL) && $stable(B)) |-> $stable(OUT)
    );

    // If SEL=0 is stable and A changes, OUT must change to match A.
    check_out_updates_with_A_when_sel0: assert property (
        @(posedge CLK) (SEL == 1'b0 && $stable(SEL) && !$stable(A)) |-> (!$stable(OUT) && (OUT == A))
    );

    // If SEL=1 is stable and B changes, OUT must change to match B.
    check_out_updates_with_B_when_sel1: assert property (
        @(posedge CLK) (SEL == 1'b1 && $stable(SEL) && !$stable(B)) |-> (!$stable(OUT) && (OUT == B))
    );

    // If SEL=0 is stable and only B changes, OUT remains stable.
    check_out_unchanged_when_unselected_B_changes_sel0: assert property (
        @(posedge CLK) (SEL == 1'b0 && $stable(SEL) && $stable(A) && !$stable(B)) |-> $stable(OUT)
    );

    // If SEL=1 is stable and only A changes, OUT remains stable.
    check_out_unchanged_when_unselected_A_changes_sel1: assert property (
        @(posedge CLK) (SEL == 1'b1 && $stable(SEL) && $stable(B) && !$stable(A)) |-> $stable(OUT)
    );

    // If SEL=0 is stable and OUT changes, A must have changed.
    check_out_change_needs_A_when_sel0: assert property (
        @(posedge CLK) (SEL == 1'b0 && $stable(SEL) && !$stable(OUT)) |-> !$stable(A)
    );

    // If SEL=1 is stable and OUT changes, B must have changed.
    check_out_change_needs_B_when_sel1: assert property (
        @(posedge CLK) (SEL == 1'b1 && $stable(SEL) && !$stable(OUT)) |-> !$stable(B)
    );
endmodule

rtl:
module and_or (
    input A,
    input B,
    input C,
    input D,
    output Y
);

    wire and_gate_out;
    wire or_gate_out;

    // AND gate implementation
    assign and_gate_out = A & B & C;

    // OR gate implementation
    assign or_gate_out = A | B;

    // Final output implementation
    assign Y = and_gate_out | D | or_gate_out;

endmodule

sva:
module and_or_sva (
    input logic CLK,  // external clock for sampling assertions
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);
    // DUT is purely combinational with no reset; use disable iff (1'b0).

    // Y equals A|B|D (absorbing (A&B&C) into A|B).
    check_y_function_equivalence: assert property (
        @(posedge CLK) disable iff (1'b0) Y === (A | B | D)
    );

    // Y must be 1 whenever D is 1.
    check_y_high_if_d_high: assert property (
        @(posedge CLK) disable iff (1'b0) D |-> (Y === 1'b1)
    );

    // Y must be 1 whenever A is 1.
    check_y_high_if_a_high: assert property (
        @(posedge CLK) disable iff (1'b0) A |-> (Y === 1'b1)
    );

    // Y must be 1 whenever B is 1.
    check_y_high_if_b_high: assert property (
        @(posedge CLK) disable iff (1'b0) B |-> (Y === 1'b1)
    );

    // With D==0, Y equals A|B.
    check_y_eq_a_or_b_when_d_low: assert property (
        @(posedge CLK) disable iff (1'b0) (D === 1'b0) |-> (Y === (A | B))
    );

    // With A==0 and B==0, Y equals D.
    check_y_eq_d_when_a_b_low: assert property (
        @(posedge CLK) disable iff (1'b0) (A === 1'b0) && (B === 1'b0) |-> (Y === D)
    );

    // With B==0 and D==0, Y equals A.
    check_y_eq_a_when_b_d_low: assert property (
        @(posedge CLK) disable iff (1'b0) (B === 1'b0) && (D === 1'b0) |-> (Y === A)
    );

    // With A==0 and D==0, Y equals B.
    check_y_eq_b_when_a_d_low: assert property (
        @(posedge CLK) disable iff (1'b0) (A === 1'b0) && (D === 1'b0) |-> (Y === B)
    );

    // If A,B,D are stable, Y must be stable (C has no effect).
    check_y_stable_when_abd_stable: assert property (
        @(posedge CLK) disable iff (1'b0) $stable(A) && $stable(B) && $stable(D) |-> $stable(Y)
    );

    // Changes on C alone cannot change Y.
    check_c_independence: assert property (
        @(posedge CLK) disable iff (1'b0) $changed(C) && $stable(A) && $stable(B) && $stable(D) |-> $stable(Y)
    );

    // Y rising requires at least one of A,B,D to be 1.
    check_y_rise_requires_input_high: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(Y) |-> (A || B || D)
    );

    // Y falling requires A,B,D all 0.
    check_y_fall_requires_inputs_low: assert property (
        @(posedge CLK) disable iff (1'b0) $fell(Y) |-> (!A && !B && !D)
    );
endmodule

rtl:
module comparator (
  input [7:0] in1,
  input [7:0] in2,
  output reg out_eq,
  output reg out_gt,
  output reg out_lt
);

  always @(*) begin
    if (in1 == in2) begin
      out_eq = 1;
      out_gt = 0;
      out_lt = 0;
    end else if (in1 > in2) begin
      out_eq = 0;
      out_gt = 1;
      out_lt = 0;
    end else begin
      out_eq = 0;
      out_gt = 0;
      out_lt = 1;
    end
  end

endmodule

sva:
module comparator_sva (
    input logic clk,
    input logic [7:0] in1,
    input logic [7:0] in2,
    input logic out_eq,
    input logic out_gt,
    input logic out_lt
);
    // Outputs exactly match the comparator functions of inputs.
    check_functional_mapping: assert property (
        @(posedge clk) (out_eq == (in1 == in2)) && (out_gt == (in1 > in2)) && (out_lt == (in1 < in2))
    );

    // Exactly one output is HIGH at any time (one-hot).
    check_outputs_onehot: assert property (
        @(posedge clk) $onehot({out_eq, out_gt, out_lt})
    );

    // Outputs are never all zero.
    check_outputs_not_all_zero: assert property (
        @(posedge clk) (out_eq || out_gt || out_lt)
    );

    // When inputs are equal, only out_eq is HIGH.
    check_eq_when_equal: assert property (
        @(posedge clk) (in1 == in2) |-> (out_eq && !out_gt && !out_lt)
    );

    // When in1 > in2, only out_gt is HIGH.
    check_gt_when_greater: assert property (
        @(posedge clk) (in1 > in2) |-> (!out_eq && out_gt && !out_lt)
    );

    // When in1 < in2, only out_lt is HIGH.
    check_lt_when_less: assert property (
        @(posedge clk) (in1 < in2) |-> (!out_eq && !out_gt && out_lt)
    );

    // If out_eq is HIGH, inputs must be equal.
    check_eq_implies_equal: assert property (
        @(posedge clk) out_eq |-> (in1 == in2)
    );

    // If out_gt is HIGH, in1 must be greater than in2.
    check_gt_implies_greater: assert property (
        @(posedge clk) out_gt |-> (in1 > in2)
    );

    // If out_lt is HIGH, in1 must be less than in2.
    check_lt_implies_less: assert property (
        @(posedge clk) out_lt |-> (in1 < in2)
    );

    // No two outputs can be HIGH simultaneously (mutual exclusion).
    check_mutex_pairs: assert property (
        @(posedge clk) !(out_eq && out_gt) && !(out_eq && out_lt) && !(out_gt && out_lt)
    );
endmodule

rtl:
module ID_EX(
	clk,rst,
	id_a, id_b, id_td, id_d2, id_Aluc, id_WREG, id_WMEM, id_LW,id_instr,
	ex_a, ex_b, ex_td, ex_d2, ex_Aluc, ex_WREG, ex_WMEM, ex_LW,ex_instr
    );
	input clk,rst;
	input wire [31:0] id_a,id_b,id_d2,id_instr;
	input wire [4:0] id_td,id_Aluc;
	input wire id_WREG,id_WMEM,id_LW;
	output reg [31:0] ex_a,ex_b,ex_d2,ex_instr;
	output reg [4:0] ex_td,ex_Aluc;
	output reg ex_WREG,ex_WMEM,ex_LW;

	always @(posedge clk or posedge rst)
	begin
		if(rst)
		begin
			ex_a <= 0;
			ex_b <= 0;
			ex_d2 <= 0;
			ex_td <= 0;
			ex_Aluc <= 0;
			ex_WREG <= 0;
			ex_WMEM <= 0;
			ex_LW <= 0;
			ex_instr<=32'b100000;
		end
else
		begin
			ex_a <= id_a;
			ex_b <= id_b;
			ex_d2 <= id_d2;
			ex_td <= id_td;
			ex_Aluc <= id_Aluc;
			ex_WREG <= id_WREG;
			ex_WMEM <= id_WMEM;
			ex_LW <= id_LW;
			ex_instr<=id_instr;
		end
	end

endmodule

sva:
module ID_EX_sva (
    input logic clk,
    input logic rst,
    input logic [31:0] id_a,
    input logic [31:0] id_b,
    input logic [4:0]  id_td,
    input logic [31:0] id_d2,
    input logic [4:0]  id_Aluc,
    input logic        id_WREG,
    input logic        id_WMEM,
    input logic        id_LW,
    input logic [31:0] id_instr,
    input logic [31:0] ex_a,
    input logic [31:0] ex_b,
    input logic [4:0]  ex_td,
    input logic [31:0] ex_d2,
    input logic [4:0]  ex_Aluc,
    input logic        ex_WREG,
    input logic        ex_WMEM,
    input logic        ex_LW,
    input logic [31:0] ex_instr
);
    // Clock: clk; Reset: rst (active-high async). Sequential pipeline register with async reset. Pass-through of id_* to ex_* on each clk when rst==0.

    ///// Reset behavior /////
    // While reset is asserted, outputs hold their reset values.
    reset_values_all: assert property (
        @(posedge clk) rst |-> (ex_a == 32'b0) && (ex_b == 32'b0) && (ex_d2 == 32'b0) &&
                               (ex_td == 5'b0) && (ex_Aluc == 5'b0) &&
                               (ex_WREG == 1'b0) && (ex_WMEM == 1'b0) && (ex_LW == 1'b0) &&
                               (ex_instr == 32'b100000)
    );

    ///// Pipeline pass-through (one-cycle latency) /////
    // ex_a updates to prior-cycle id_a when out of reset.
    pipe_ex_a: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst)) |-> (ex_a == $past(id_a))
    );
    // ex_b updates to prior-cycle id_b when out of reset.
    pipe_ex_b: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst)) |-> (ex_b == $past(id_b))
    );
    // ex_d2 updates to prior-cycle id_d2 when out of reset.
    pipe_ex_d2: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst)) |-> (ex_d2 == $past(id_d2))
    );
    // ex_td updates to prior-cycle id_td when out of reset.
    pipe_ex_td: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst)) |-> (ex_td == $past(id_td))
    );
    // ex_Aluc updates to prior-cycle id_Aluc when out of reset.
    pipe_ex_Aluc: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst)) |-> (ex_Aluc == $past(id_Aluc))
    );
    // ex_WREG updates to prior-cycle id_WREG when out of reset.
    pipe_ex_WREG: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst)) |-> (ex_WREG == $past(id_WREG))
    );
    // ex_WMEM updates to prior-cycle id_WMEM when out of reset.
    pipe_ex_WMEM: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst)) |-> (ex_WMEM == $past(id_WMEM))
    );
    // ex_LW updates to prior-cycle id_LW when out of reset.
    pipe_ex_LW: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst)) |-> (ex_LW == $past(id_LW))
    );
    // ex_instr updates to prior-cycle id_instr when out of reset.
    pipe_ex_instr: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst)) |-> (ex_instr == $past(id_instr))
    );

endmodule

rtl:
module RegisterAdd
	# (parameter W = 16)
	(
		input wire clk, input wire rst, input wire load, input wire [W-1:0] D, output reg [W-1:0] Q );

	always @(posedge clk, posedge rst)
		if(rst)
			Q <= 0;
		else if(load)
			Q <= D;
		else
			Q <= Q;

endmodule

module FFD_NoCE
	# (parameter W = 16)
	(
		input wire clk, input wire rst, input wire [W-1:0] D, output reg [W-1:0] Q );

	always @(posedge clk, posedge rst)
		if(rst)
			Q <= 0;
		else
			Q <= D;

endmodule

sva:
module RegisterAdd_sva #(
    parameter W = 16
) (
    input logic clk,
    input logic rst,
    input logic load,
    input logic [W-1:0] D,
    input logic [W-1:0] Q
);
    // Clock: clk; Reset: rst (active-high async)

    // Reset drives Q to zero whenever rst is HIGH.
    registeradd_check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (Q == '0)
    );

    // When not in reset (now and last cycle) and load is LOW, Q holds its value.
    registeradd_check_hold_when_not_load: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && !load) |=> (Q == $past(Q))
    );

    // When not in reset (now and last cycle) and load is HIGH, Q updates to D.
    registeradd_check_load_captures_d: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && load) |=> (Q == $past(D))
    );

    // Immediately after reset deasserts, if load is LOW, Q remains zero.
    registeradd_check_after_reset_no_load_q_zero: assert property (
        @(posedge clk) disable iff (rst)
            ($past(rst) && !load) |-> (Q == '0)
    );

    // Immediately after reset deasserts, if load is HIGH, next Q equals current D.
    registeradd_check_after_reset_with_load_captures_d: assert property (
        @(posedge clk) disable iff (rst)
            ($past(rst) && load) |=> (Q == $past(D))
    );

    // If load stayed LOW across two cycles with no reset, Q must be stable.
    registeradd_check_two_cycle_hold: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && !load && !$past(load)) |-> (Q == $past(Q))
    );

endmodule


module FFD_NoCE_sva #(
    parameter W = 16
) (
    input logic clk,
    input logic rst,
    input logic [W-1:0] D,
    input logic [W-1:0] Q
);
    // Clock: clk; Reset: rst (active-high async)

    // Reset drives Q to zero whenever rst is HIGH.
    ffd_check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (Q == '0)
    );

    // With no reset in the previous cycle, Q equals prior D on this cycle.
    ffd_check_d_captured_no_reset: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst)) |-> (Q == $past(D))
    );

    // On the first cycle after reset deasserts, next Q equals current D.
    ffd_check_after_reset_capture: assert property (
        @(posedge clk) disable iff (rst)
            ($past(rst)) |=> (Q == $past(D))
    );

    // While reset remains asserted across cycles, Q stays at zero.
    ffd_check_reset_holds_zero: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (Q == '0)
    );

endmodule

rtl:
module vco_interface #(
  parameter n = 8 // number of bits used to represent the control voltage
)(
  input wire clk,
  input wire rst,
  input wire [n-1:0] vctrl,
  output reg vco_out
);

parameter fmin = 1000000; // minimum output frequency of VCO
parameter fmax = 2000000; // maximum output frequency of VCO

reg [31:0] count; // counter for VCO output waveform
reg [31:0] threshold; // threshold value for VCO output waveform

always @(*) begin
  threshold = ((fmax - fmin) * vctrl) / (2 ** n) + fmin;
end

always @(posedge clk) begin
  if (rst) begin
    count <= 0;
    vco_out <= 0;
  end else begin
    count <= count + 1;
    if (count >= threshold) begin
      count <= 0;
      vco_out <= ~vco_out;
    end
  end
end

endmodule

sva:
module vco_interface_sva #(
    parameter int n = 8,
    parameter int unsigned fmin = 1000000,
    parameter int unsigned fmax = 2000000
)(
    input  logic              clk,
    input  logic              rst,
    input  logic [n-1:0]      vctrl,
    input  logic              vco_out,
    input  logic [31:0]       count,
    input  logic [31:0]       threshold
);
    localparam int unsigned TWO_TO_N = (1 << n);

    // During reset, count and vco_out are driven to 0.
    reset_state_is_zero: assert property (
        @(posedge clk) rst |-> (count == 32'd0) && (vco_out == 1'b0)
    );

    // Count update: increment by 1 unless at/over threshold, then reset to 0.
    count_update_rule: assert property (
        @(posedge clk) disable iff (rst)
            count == (($past(count) >= $past(threshold)) ? 32'd0 : ($past(count) + 32'd1))
    );

    // vco_out toggles only when previous count reached/exceeded threshold.
    vco_toggle_only_when_threshold_reached: assert property (
        @(posedge clk) disable iff (rst)
            (vco_out ^ $past(vco_out)) |-> ($past(count) >= $past(threshold))
    );

    // When previous count reached/exceeded threshold, vco_out must toggle.
    vco_toggle_on_threshold_reached: assert property (
        @(posedge clk) disable iff (rst)
            ($past(count) >= $past(threshold)) |-> (vco_out ^ $past(vco_out))
    );

    // When previous count was below threshold, vco_out must hold its value.
    vco_stable_when_below_threshold: assert property (
        @(posedge clk) disable iff (rst)
            ($past(count) < $past(threshold)) |-> (vco_out == $past(vco_out))
    );

    // A vco_out toggle coincides with count being reset to 0.
    toggle_implies_count_zero: assert property (
        @(posedge clk) disable iff (rst)
            (vco_out ^ $past(vco_out)) |-> (count == 32'd0)
    );

    // If not coming out of reset, count==0 implies previous count hit/exceeded threshold.
    count_zero_implies_previous_threshold_reached: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && (count == 32'd0)) |-> ($past(count) >= $past(threshold))
    );

    // Threshold computation matches the RTL formula.
    threshold_computation_equation: assert property (
        @(posedge clk) disable iff (rst)
            threshold == (((fmax - fmin) * vctrl) / TWO_TO_N) + fmin
    );

    // Threshold is never below fmin.
    threshold_min_bound_fmin: assert property (
        @(posedge clk) disable iff (rst)
            threshold >= fmin
    );

    // Threshold is never above fmax.
    threshold_max_bound_fmax: assert property (
        @(posedge clk) disable iff (rst)
            threshold <= fmax
    );

    // Threshold is non-decreasing when vctrl increases.
    threshold_non_decreasing_with_vctrl: assert property (
        @(posedge clk) disable iff (rst)
            ($past(vctrl) < vctrl) |-> (threshold >= $past(threshold))
    );

    // Threshold holds constant when vctrl is unchanged.
    threshold_stable_when_vctrl_constant: assert property (
        @(posedge clk) disable iff (rst)
            (vctrl == $past(vctrl)) |-> (threshold == $past(threshold))
    );

endmodule

