rtl:
module div8(input [7:0] a, b, input [7:0] wa, wb, output reg [7:0] result, output reg [7:0] wresult);

always @(*) begin
    if (b == 0) begin
        result = 8'b0;
        wresult = 8'b0;
    end
    else if (a != 0 && b != 0) begin
        result = a / b;
        wresult = wa / wb;
    end
    else begin
        result = 8'hFF;
        wresult = 8'hFF;
    end
end

endmodule

sva:
module div8_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] wa,
    input logic [7:0] wb,
    input logic [7:0] result,
    input logic [7:0] wresult
);

    // If b is zero, both outputs are driven to 0.
    check_b_zero_outputs_zero: assert property (
        @(posedge clk) (b == 8'd0) |-> (result == 8'd0) && (wresult == 8'd0)
    );

    // If a and b are non-zero, result equals a / b.
    check_result_div_when_a_b_nonzero: assert property (
        @(posedge clk) (a != 8'd0) && (b != 8'd0) |-> (result == (a / b))
    );

    // If a and b are non-zero and wb is non-zero, wresult equals wa / wb.
    check_wresult_div_when_branch_and_wb_nonzero: assert property (
        @(posedge clk) (a != 8'd0) && (b != 8'd0) && (wb != 8'd0) |-> (wresult == (wa / wb))
    );

    // If a is zero and b is non-zero, both outputs are 0xFF.
    check_a_zero_b_nonzero_outputs_ff: assert property (
        @(posedge clk) (a == 8'd0) && (b != 8'd0) |-> (result == 8'hFF) && (wresult == 8'hFF)
    );

    // If b == 1 and a is non-zero, result equals a.
    check_result_identity_when_b_eq_1: assert property (
        @(posedge clk) (b == 8'd1) && (a != 8'd0) |-> (result == a)
    );

    // If a == b and both are non-zero, result equals 1.
    check_result_one_when_a_eq_b_nonzero: assert property (
        @(posedge clk) (a == b) && (a != 8'd0) |-> (result == 8'd1)
    );

    // If a < b with both non-zero, result equals 0 (integer division).
    check_result_zero_when_a_lt_b_nonzero: assert property (
        @(posedge clk) (a != 8'd0) && (b != 8'd0) && (a < b) |-> (result == 8'd0)
    );

    // If wb == 1 and branch a!=0 && b!=0 is taken, wresult equals wa.
    check_wresult_identity_when_wb_eq_1: assert property (
        @(posedge clk) (a != 8'd0) && (b != 8'd0) && (wb == 8'd1) |-> (wresult == wa)
    );

endmodule

rtl:
module traffic_light_controller (
  input clk,
  input reset,
  output reg green_led,
  output reg yellow_led,
  output reg red_led
);

  // Define states and their corresponding values
  parameter GREEN = 2'b00;
  parameter YELLOW = 2'b01;
  parameter RED = 2'b10;

  // Define state register and initialize to GREEN
  reg [1:0] state = GREEN;

  // Define counter for each state
  reg [3:0] green_counter = 0;
  reg [1:0] yellow_counter = 0;
  reg [4:0] red_counter = 0;

  // Define state transitions and counter values
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= GREEN;
      green_counter <= 0;
      yellow_counter <= 0;
      red_counter <= 0;
    end else begin
      case (state)
        GREEN: begin
          if (green_counter == 10) begin
            state <= YELLOW;
            green_counter <= 0;
            yellow_counter <= 0;
            red_counter <= 0;
          end else begin
            green_counter <= green_counter + 1;
          end
        end
        YELLOW: begin
          if (yellow_counter == 2) begin
            state <= RED;
            green_counter <= 0;
            yellow_counter <= 0;
            red_counter <= 0;
          end else begin
            yellow_counter <= yellow_counter + 1;
          end
        end
        RED: begin
          if (red_counter == 15) begin
            state <= GREEN;
            green_counter <= 0;
            yellow_counter <= 0;
            red_counter <= 0;
          end else begin
            red_counter <= red_counter + 1;
          end
        end
      endcase
    end
  end

  // Define output logic based on state
  always @(state) begin
    case (state)
      GREEN: begin
        green_led <= 1;
        yellow_led <= 0;
        red_led <= 0;
      end
      YELLOW: begin
        green_led <= 0;
        yellow_led <= 1;
        red_led <= 0;
      end
      RED: begin
        green_led <= 0;
        yellow_led <= 0;
        red_led <= 1;
      end
    endcase
  end

endmodule

sva:
module traffic_light_controller_sva (
  input logic clk,
  input logic reset,
  input logic green_led,
  input logic yellow_led,
  input logic red_led,
  input logic [1:0] state,
  input logic [3:0] green_counter,
  input logic [1:0] yellow_counter,
  input logic [4:0] red_counter
);
  // Local copies of state encodings
  localparam logic [1:0] GREEN  = 2'b00;
  localparam logic [1:0] YELLOW = 2'b01;
  localparam logic [1:0] RED    = 2'b10;

  ///// Reset behavior /////
  // On a clock edge while reset is HIGH, state/counters are in reset values.
  reset_state_counters: assert property (
    @(posedge clk) reset |-> (state == GREEN) && (green_counter == 4'd0) && (yellow_counter == 2'd0) && (red_counter == 5'd0)
  );
  // On a clock edge while reset is HIGH, outputs reflect GREEN.
  reset_outputs_green: assert property (
    @(posedge clk) reset |-> (green_led == 1'b1) && (yellow_led == 1'b0) && (red_led == 1'b0)
  );

  ///// State encoding and outputs /////
  // State must always be one of GREEN/YELLOW/RED.
  state_valid_encoding: assert property (
    @(posedge clk) disable iff (reset) (state == GREEN) || (state == YELLOW) || (state == RED)
  );
  // Output decode for GREEN.
  decode_green: assert property (
    @(posedge clk) disable iff (reset) (state == GREEN) |-> (green_led == 1'b1) && (yellow_led == 1'b0) && (red_led == 1'b0)
  );
  // Output decode for YELLOW.
  decode_yellow: assert property (
    @(posedge clk) disable iff (reset) (state == YELLOW) |-> (green_led == 1'b0) && (yellow_led == 1'b1) && (red_led == 1'b0)
  );
  // Output decode for RED.
  decode_red: assert property (
    @(posedge clk) disable iff (reset) (state == RED) |-> (green_led == 1'b0) && (yellow_led == 1'b0) && (red_led == 1'b1)
  );
  // Exactly one LED is ON at a time.
  leds_onehot: assert property (
    @(posedge clk) disable iff (reset) $onehot({green_led, yellow_led, red_led})
  );

  ///// GREEN state behavior /////
  // While in GREEN and count < 10, stay in GREEN and increment green_counter; others unchanged.
  green_count_increments: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) && (state == GREEN) && (green_counter != 4'd10)
      |=> (state == GREEN)
       && (green_counter == $past(green_counter) + 1)
       && (yellow_counter == $past(yellow_counter))
       && (red_counter == $past(red_counter))
  );
  // When green_counter == 10, transition to YELLOW and clear all counters.
  green_to_yellow_on_10: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) && (state == GREEN) && (green_counter == 4'd10)
      |=> (state == YELLOW)
       && (green_counter == 4'd0) && (yellow_counter == 2'd0) && (red_counter == 5'd0)
  );
  // In GREEN, green_counter never exceeds 10.
  green_counter_bounded: assert property (
    @(posedge clk) disable iff (reset) (state == GREEN) |-> (green_counter <= 4'd10)
  );

  ///// YELLOW state behavior /////
  // While in YELLOW and count < 2, stay in YELLOW and increment yellow_counter; others unchanged.
  yellow_count_increments: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) && (state == YELLOW) && (yellow_counter != 2'd2)
      |=> (state == YELLOW)
       && (yellow_counter == $past(yellow_counter) + 1)
       && (green_counter == $past(green_counter))
       && (red_counter == $past(red_counter))
  );
  // When yellow_counter == 2, transition to RED and clear all counters.
  yellow_to_red_on_2: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) && (state == YELLOW) && (yellow_counter == 2'd2)
      |=> (state == RED)
       && (green_counter == 4'd0) && (yellow_counter == 2'd0) && (red_counter == 5'd0)
  );
  // In YELLOW, yellow_counter never exceeds 2.
  yellow_counter_bounded: assert property (
    @(posedge clk) disable iff (reset) (state == YELLOW) |-> (yellow_counter <= 2'd2)
  );

  ///// RED state behavior /////
  // While in RED and count < 15, stay in RED and increment red_counter; others unchanged.
  red_count_increments: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) && (state == RED) && (red_counter != 5'd15)
      |=> (state == RED)
       && (red_counter == $past(red_counter) + 1)
       && (green_counter == $past(green_counter))
       && (yellow_counter == $past(yellow_counter))
  );
  // When red_counter == 15, transition to GREEN and clear all counters.
  red_to_green_on_15: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) && (state == RED) && (red_counter == 5'd15)
      |=> (state == GREEN)
       && (green_counter == 4'd0) && (yellow_counter == 2'd0) && (red_counter == 5'd0)
  );
  // In RED, red_counter never exceeds 15.
  red_counter_bounded: assert property (
    @(posedge clk) disable iff (reset) (state == RED) |-> (red_counter <= 5'd15)
  );

  ///// Counters outside active state /////
  // green_counter is 0 outside GREEN.
  green_zero_outside_green: assert property (
    @(posedge clk) disable iff (reset) (state != GREEN) |-> (green_counter == 4'd0)
  );
  // yellow_counter is 0 outside YELLOW.
  yellow_zero_outside_yellow: assert property (
    @(posedge clk) disable iff (reset) (state != YELLOW) |-> (yellow_counter == 2'd0)
  );
  // red_counter is 0 outside RED.
  red_zero_outside_red: assert property (
    @(posedge clk) disable iff (reset) (state != RED) |-> (red_counter == 5'd0)
  );

endmodule

rtl:
module gray_code_conversion (
  input [3:0] binary,
  output [1:0] gray
);

  assign gray[0] = binary[0] ^ binary[1];
  assign gray[1] = binary[1] ^ binary[2];

endmodule

sva:
module gray_code_conversion_sva (
    input logic clk,
    input logic [3:0] binary,
    input logic [1:0] gray
);
    // gray[0] must equal binary[0] XOR binary[1].
    check_gray0_is_b0_xor_b1: assert property (
        @(posedge clk) gray[0] == (binary[0] ^ binary[1])
    );

    // gray[1] must equal binary[1] XOR binary[2].
    check_gray1_is_b1_xor_b2: assert property (
        @(posedge clk) gray[1] == (binary[1] ^ binary[2])
    );

    // Vector equivalence for gray encoding.
    check_gray_vector_equiv: assert property (
        @(posedge clk) gray == {binary[1] ^ binary[2], binary[0] ^ binary[1]}
    );

    // Changing binary[3] alone must not affect gray.
    check_gray_independent_of_b3: assert property (
        @(posedge clk) ($changed(binary[3]) && $stable(binary[2:0])) |-> $stable(gray)
    );

    // If only binary[0] changes, gray[0] toggles and gray[1] stays stable.
    check_b0_only_changes_g0: assert property (
        @(posedge clk) ($changed(binary[0]) && $stable(binary[3:1])) |-> ($changed(gray[0]) && $stable(gray[1]))
    );

    // If only binary[1] changes, both gray[0] and gray[1] toggle.
    check_b1_only_changes_both: assert property (
        @(posedge clk) ($changed(binary[1]) && $stable({binary[3:2], binary[0]})) |-> ($changed(gray[0]) && $changed(gray[1]))
    );

    // If only binary[2] changes, gray[1] toggles and gray[0] stays stable.
    check_b2_only_changes_g1: assert property (
        @(posedge clk) ($changed(binary[2]) && $stable({binary[3], binary[1:0]})) |-> ($changed(gray[1]) && $stable(gray[0]))
    );

    // If binary[0] and binary[1] change (others stable), gray[0] stays and gray[1] toggles.
    check_b0_b1_change_effect: assert property (
        @(posedge clk) ($changed(binary[0]) && $changed(binary[1]) && $stable(binary[3:2])) |-> ($stable(gray[0]) && $changed(gray[1]))
    );

    // Parity relation implied by definitions: gray[0]^gray[1] == binary[0]^binary[2].
    check_parity_relation: assert property (
        @(posedge clk) (gray[0] ^ gray[1]) == (binary[0] ^ binary[2])
    );
endmodule

rtl:
module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  wire [3:0] sum;
  wire C1, C2, C3;

  // Full-adder for bit 0
  full_adder fa0(A[0], B[0], Cin, sum[0], C1);

  // Full-adder for bit 1
  full_adder fa1(A[1], B[1], C1, sum[1], C2);

  // Full-adder for bit 2
  full_adder fa2(A[2], B[2], C2, sum[2], C3);

  // Full-adder for bit 3
  full_adder fa3(A[3], B[3], C3, sum[3], Cout);

  assign S = sum;

endmodule

// Full-adder module
module full_adder(
  input A,
  input B,
  input Cin,
  output S,
  output Cout
);

  assign S = A ^ B ^ Cin;
  assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

sva:
module four_bit_adder_sva (
    input logic clk,          // SVA sample clock (RTL is purely combinational; no reset)
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);
    // Full 5-bit sum must equal zero-extended A+B+Cin.
    check_sum_matches_arithmetic: assert property (
        @(posedge clk) disable iff (1'b0)
        {Cout, S} == ({1'b0, A} + {1'b0, B} + {4'b0, Cin})
    );

    // Bit0 sum is XOR of A[0], B[0], and Cin.
    check_sum_bit0_xor: assert property (
        @(posedge clk) disable iff (1'b0)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit1 sum equals XOR with carry from bit0.
    check_sum_bit1_xor_with_c1: assert property (
        @(posedge clk) disable iff (1'b0)
        S[1] == (A[1] ^ B[1] ^ ( (A[0] & B[0]) | (Cin & (A[0] ^ B[0])) ))
    );

    // Bit2 sum equals XOR with carry from bit1.
    check_sum_bit2_xor_with_c2: assert property (
        @(posedge clk) disable iff (1'b0)
        S[2] == (A[2] ^ B[2] ^ (
                    (A[1] & B[1]) |
                    ( ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]) )
                ))
    );

    // Bit3 sum equals XOR with carry from bit2.
    check_sum_bit3_xor_with_c3: assert property (
        @(posedge clk) disable iff (1'b0)
        S[3] == (A[3] ^ B[3] ^ (
                    (A[2] & B[2]) |
                    ( ( (A[1] & B[1]) |
                        ( ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]) )
                      ) & (A[2] ^ B[2]) )
                ))
    );

    // Carry-out equals ripple-carry chain through all bits.
    check_cout_matches_ripple: assert property (
        @(posedge clk) disable iff (1'b0)
        Cout == (
            (A[3] & B[3]) |
            ( (
                (A[2] & B[2]) |
                ( ( (A[1] & B[1]) |
                    ( ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]) )
                  ) & (A[2] ^ B[2]) )
              ) & (A[3] ^ B[3]) )
        )
    );

    // If inputs do not change, outputs must not change.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (1'b0)
        ($stable(A) && $stable(B) && $stable(Cin)) |-> ($stable(S) && $stable(Cout))
    );

    // 0 + 0 + 0 -> S=0, Cout=0.
    check_zero_plus_zero_no_carry: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 4'b0000) && (B == 4'b0000) && (Cin == 1'b0)) |-> ((S == 4'b0000) && (Cout == 1'b0))
    );

    // 0 + 0 + 1 -> S=1, Cout=0.
    check_zero_plus_zero_with_cin: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 4'b0000) && (B == 4'b0000) && (Cin == 1'b1)) |-> ((S == 4'b0001) && (Cout == 1'b0))
    );

    // A + ~A + 0 -> S=4'hF, Cout=0.
    check_complement_no_cin_saturates: assert property (
        @(posedge clk) disable iff (1'b0)
        ((B == ~A) && (Cin == 1'b0)) |-> ((S == 4'hF) && (Cout == 1'b0))
    );

    // A + ~A + 1 -> S=0, Cout=1.
    check_complement_with_cin_wraps: assert property (
        @(posedge clk) disable iff (1'b0)
        ((B == ~A) && (Cin == 1'b1)) |-> ((S == 4'h0) && (Cout == 1'b1))
    );
endmodule

rtl:
module count3(
	input wire clk,
	input wire reset,
	input wire enable,
	output wire out
);

	reg [1:0] cnt = 0;

	always @(posedge clk) begin
		if(reset) begin
			cnt <= 0;
		end else if(enable && cnt != 3) begin
			cnt <= cnt + 2'b1;
		end else begin
			cnt <= 0;
		end
	end

	assign out = cnt == 3;

endmodule

sva:
module count3_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic out,
    input logic [1:0] cnt
);
    // out reflects cnt==3 exactly.
    check_out_matches_cnt: assert property (
        @(posedge clk) disable iff (reset) out == (cnt == 2'd3)
    );

    // When enabled and not at 3, cnt increments by 1 on the next cycle.
    check_inc_on_enable: assert property (
        @(posedge clk) disable iff (reset) (enable && (cnt != 2'd3)) |=> (cnt == $past(cnt) + 2'd1)
    );

    // When cnt==3, it clears to 0 on the next cycle.
    check_clear_after_3: assert property (
        @(posedge clk) disable iff (reset) (cnt == 2'd3) |=> (cnt == 2'd0)
    );

    // When disabled, cnt clears to 0 on the next cycle.
    check_clear_on_disable: assert property (
        @(posedge clk) disable iff (reset) (!enable) |=> (cnt == 2'd0)
    );

    // out pulses are single-cycle.
    check_out_single_cycle: assert property (
        @(posedge clk) disable iff (reset) out |=> !out
    );

    // There are at least three low cycles of out between pulses.
    check_out_min_gap_3: assert property (
        @(posedge clk) disable iff (reset) out |=> !out[*3]
    );

    // A rising out implies previous cnt==2 and enable was 1.
    check_out_rise_preconds: assert property (
        @(posedge clk) disable iff (reset) $rose(out) |-> ($past(cnt) == 2'd2) && $past(enable)
    );

    // If cnt==2 and enabled, out is high in the next cycle.
    check_cnt2_enable_leads_out: assert property (
        @(posedge clk) disable iff (reset) (enable && (cnt == 2'd2)) |=> out
    );

    // If cnt==0 or 1 and enabled, out is low in the next cycle.
    check_cnt01_enable_no_out_next: assert property (
        @(posedge clk) disable iff (reset) (enable && ((cnt == 2'd0) || (cnt == 2'd1))) |=> !out
    );
endmodule

module up_down_counter_sva (
  input logic clk,
  input logic reset,      // active-high async reset
  input logic up_down,    // 1=up, 0=down
  input logic [2:0] count
);

  ///// Reset behavior /////
  // When reset is asserted at a clock edge, count must be 0.
  reset_forces_zero: assert property (
    @(posedge clk) reset |-> (count == 3'd0)
  );

  // While reset stays asserted across cycles, count remains 0.
  reset_holds_zero: assert property (
    @(posedge clk) ($past(reset) && reset) |-> (count == 3'd0)
  );

  ///// State update rules /////
  // On the cycle after reset deasserts, next count is based on current up_down from 0.
  post_reset_first_update: assert property (
    @(posedge clk) disable iff (reset)
      ($past(reset) && !reset) |-> (count == (up_down ? 3'd1 : 3'd7))
  );

  // If previous cycle was up mode and not at 7, increment by 1.
  count_up_increment: assert property (
    @(posedge clk) disable iff (reset)
      ($past(!reset) && $past(up_down) && ($past(count) != 3'd7)) |-> (count == ($past(count) + 3'd1))
  );

  // If previous cycle was up mode at 7, wrap to 0.
  count_up_wrap: assert property (
    @(posedge clk) disable iff (reset)
      ($past(!reset) && $past(up_down) && ($past(count) == 3'd7)) |-> (count == 3'd0)
  );

  // If previous cycle was down mode and not at 0, decrement by 1.
  count_down_decrement: assert property (
    @(posedge clk) disable iff (reset)
      ($past(!reset) && !$past(up_down) && ($past(count) != 3'd0)) |-> (count == ($past(count) - 3'd1))
  );

  // If previous cycle was down mode at 0, wrap to 7.
  count_down_wrap: assert property (
    @(posedge clk) disable iff (reset)
      ($past(!reset) && !$past(up_down) && ($past(count) == 3'd0)) |-> (count == 3'd7)
  );

  ///// General invariants derived from the update rules /////
  // Out of reset, count must change every cycle (either +1 or -1 mod 8).
  count_changes_every_cycle: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) |-> (count != $past(count))
  );

  // Out of reset, the step size is exactly +/-1 modulo 8.
  one_step_only: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) |-> ((count == ($past(count) + 3'd1)) || (count == ($past(count) - 3'd1)))
  );

  // Out of reset, LSB toggles every cycle due to +/-1 update.
  lsb_toggles: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) |-> (count[0] != $past(count[0]))
  );

endmodule

module ascending_order_sva (
    input logic CLK,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] C,
    input logic Y
);
    ///// Functional equivalence /////
    // Y reflects strict ascending order A < B < C.
    check_y_definition: assert property (
        @(posedge CLK) Y == ((A < B) && (B < C))
    );

    ///// Consequences of the definition /////
    // If A >= B, Y must be 0.
    check_y_zero_when_A_ge_B: assert property (
        @(posedge CLK) (A >= B) |-> (Y == 1'b0)
    );
    // If B >= C, Y must be 0.
    check_y_zero_when_B_ge_C: assert property (
        @(posedge CLK) (B >= C) |-> (Y == 1'b0)
    );
    // If Y is 1, then A < C (implied by A < B and B < C).
    check_transitive_A_lt_C_when_Y_one: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (A < C)
    );

    ///// Combinational determinism /////
    // If A,B,C are unchanged from the previous cycle, Y must be unchanged.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge CLK) (A == $past(A) && B == $past(B) && C == $past(C)) |-> (Y == $past(Y))
    );
    // If Y changes, at least one of A,B,C must have changed.
    check_output_change_requires_input_change: assert property (
        @(posedge CLK) (Y != $past(Y)) |-> ((A != $past(A)) || (B != $past(B)) || (C != $past(C)))
    );
endmodule

module figuras_Gato_sva (
    input logic        video_mostrar,
    input logic [3:0]  entrada,
    input logic [9:0]  pixel_x,
    input logic [9:0]  pixel_y,
    input logic [2:0]  salida_rgb
);

    // salida_rgb outputs only 000, 001, or 111.
    check_rgb_value_domain: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (salida_rgb == 3'b000) || (salida_rgb == 3'b001) || (salida_rgb == 3'b111)
    );

    // When video_mostrar=1 and entrada=0011 in rect (150..200,100..150), output 111.
    check_video_on_rect1_white: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b1) &&
        (entrada == 4'b0011) &&
        (pixel_x >= 10'd150) && (pixel_x <= 10'd200) &&
        (pixel_y >= 10'd100) && (pixel_y <= 10'd150)
        |-> (salida_rgb == 3'b111)
    );

    // When video_mostrar=1 and not in rect1 with entrada=0011, output 000.
    check_video_on_else_black: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b1) &&
        !((entrada == 4'b0011) &&
          (pixel_x >= 10'd150) && (pixel_x <= 10'd200) &&
          (pixel_y >= 10'd100) && (pixel_y <= 10'd150))
        |-> (salida_rgb == 3'b000)
    );

    // When video_mostrar=0 and entrada=0100 in rect (100..200,50..150), output 001.
    check_video_off_rect2_blue: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b0) &&
        (entrada == 4'b0100) &&
        (pixel_x >= 10'd100) && (pixel_x <= 10'd200) &&
        (pixel_y >= 10'd50)  && (pixel_y <= 10'd150)
        |-> (salida_rgb == 3'b001)
    );

    // When video_mostrar=0 and not in rect2 with entrada=0100, output 000.
    check_video_off_else_black: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b0) &&
        !((entrada == 4'b0100) &&
          (pixel_x >= 10'd100) && (pixel_x <= 10'd200) &&
          (pixel_y >= 10'd50)  && (pixel_y <= 10'd150))
        |-> (salida_rgb == 3'b000)
    );

    // Output 111 occurs only when video_mostrar=1 with entrada=0011 in rect1.
    check_white_implies_video_on_rect1: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (salida_rgb == 3'b111)
        |-> (video_mostrar == 1'b1) &&
            (entrada == 4'b0011) &&
            (pixel_x >= 10'd150) && (pixel_x <= 10'd200) &&
            (pixel_y >= 10'd100) && (pixel_y <= 10'd150)
    );

    // Output 001 occurs only when video_mostrar=0 with entrada=0100 in rect2.
    check_blue_implies_video_off_rect2: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (salida_rgb == 3'b001)
        |-> (video_mostrar == 1'b0) &&
            (entrada == 4'b0100) &&
            (pixel_x >= 10'd100) && (pixel_x <= 10'd200) &&
            (pixel_y >= 10'd50)  && (pixel_y <= 10'd150)
    );

    // When video_mostrar=1, output is either 000 or 111.
    check_video_on_output_domain: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b1) |-> (salida_rgb == 3'b000) || (salida_rgb == 3'b111)
    );

    // When video_mostrar=1, all RGB bits are equal (000 or 111).
    check_video_on_bits_equal: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b1) |-> (salida_rgb[2] == salida_rgb[1]) && (salida_rgb[1] == salida_rgb[0])
    );

    // When video_mostrar=0, upper RGB bits are 0 (outputs 000 or 001).
    check_video_off_upper_bits_zero: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b0) |-> (salida_rgb[2] == 1'b0) && (salida_rgb[1] == 1'b0)
    );

endmodule

rtl:
module barrel_shifter (
    input [15:0] in,
    input [3:0] shift,
    output [15:0] out
);

    assign out = (shift >= 0) ? (in << shift) : (in >> -shift);

endmodule

sva:
module barrel_shifter_sva (
    input logic CLK,
    input logic [15:0] in,
    input logic [3:0] shift,
    input logic [15:0] out
);
    ///// Functional mapping to left shift /////
    // For known shift, out equals in left-shifted by shift.
    check_out_eq_left_shift_when_shift_known: assert property (
        @(posedge CLK) (!$isunknown(shift)) |-> (out == (in << shift))
    );

    // Zero shift passes input through unchanged.
    check_zero_shift_passthrough: assert property (
        @(posedge CLK) (shift == 4'd0) |-> (out == in)
    );

    // One-bit shift produces {in[14:0], 1'b0}.
    check_one_shift_behavior: assert property (
        @(posedge CLK) (shift == 4'd1) |-> (out == {in[14:0], 1'b0})
    );

    // Max shift (15) produces {in[0], 15'b0}.
    check_max_shift_behavior: assert property (
        @(posedge CLK) (shift == 4'd15) |-> (out == {in[0], 15'b0})
    );

    ///// Structural bit properties of left shift /////
    // For known positive shift, LSBs are zero-filled.
    check_lsb_zero_fill_mask: assert property (
        @(posedge CLK) (!$isunknown(shift) && (shift > 4'd0)) |-> ((out & ((16'h0001 << shift) - 16'h0001)) == 16'h0000)
    );

    // For known shift, right-shifting out by shift restores masked in.
    check_out_right_shift_mask_relation: assert property (
        @(posedge CLK) (!$isunknown(shift)) |-> ((out >> shift) == (in & (16'hFFFF >> shift)))
    );

    // For known shift, MSB of out equals in[15 - shift].
    check_msb_maps_from_in: assert property (
        @(posedge CLK) (!$isunknown(shift)) |-> (out[15] == in[15 - shift])
    );

    // For known positive shift, LSB is 0.
    check_lsb_zero_when_shift_pos: assert property (
        @(posedge CLK) (!$isunknown(shift) && (shift > 4'd0)) |-> (out[0] == 1'b0)
    );

    ///// Stability /////
    // If inputs are stable, output remains stable.
    check_output_stability_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(in) && $stable(shift)) |-> $stable(out)
    );

    ///// Per-bit movement (only when destination index is in range) /////
    // For known shift, a '1' at in[i] moves to out[i+shift] if i+shift <= 15.
    genvar i;
    generate
        for (i = 0; i < 16; i++) begin : gen_move_bits
            check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );
        end
    endgenerate
endmodule

rtl:
module bit_counter(
    input [3:0] in,
    output reg [1:0] out
);

always @(*) begin
    case(in)
        4'b0000: out = 2'b00;
        4'b0001: out = 2'b01;
        4'b0010: out = 2'b01;
        4'b0011: out = 2'b10;
        4'b0100: out = 2'b01;
        4'b0101: out = 2'b10;
        4'b0110: out = 2'b10;
        4'b0111: out = 2'b11;
        4'b1000: out = 2'b01;
        4'b1001: out = 2'b10;
        4'b1010: out = 2'b10;
        4'b1011: out = 2'b11;
        4'b1100: out = 2'b10;
        4'b1101: out = 2'b11;
        4'b1110: out = 2'b11;
        4'b1111: out = 2'b11;
        default: out = 2'b00;
    endcase
end

endmodule

