endmodule

rtl:
module Divisor_Frecuencia (
		input  C_100Mhz, output  C_1Hz
	);

	reg[31:0] contador = 0; reg C_1Hz=0;

	always @(posedge C_100Mhz)
		begin
				if (contador == 50000000-1)          begin
					C_1Hz <= ~C_1Hz;
					contador <=0;
					end

				else
					begin
					contador <= contador + 1;        end
	  end
endmodule

sva:
module Divisor_Frecuencia_sva (
    input  logic        C_100Mhz,   // clock
    input  logic        C_1Hz,      // output from DUT
    input  logic [31:0] contador    // internal counter from DUT
);
    // Clock: C_100Mhz (posedge). No reset present in RTL.
    // Sequential logic: contador increments to LIMIT then toggles C_1Hz and clears.

    localparam int unsigned LIMIT = 32'd50000000 - 1;

    // Counter never exceeds terminal count.
    check_counter_within_range: assert property (
        @(posedge C_100Mhz) contador <= LIMIT
    );

    // When not at terminal count, counter increments by 1.
    check_counter_increments_when_not_limit: assert property (
        @(posedge C_100Mhz) ($past(contador) != LIMIT) |-> (contador == $past(contador) + 1)
    );

    // When not at terminal count, output remains stable.
    check_output_stable_when_not_limit: assert property (
        @(posedge C_100Mhz) ($past(contador) != LIMIT) |-> (C_1Hz == $past(C_1Hz))
    );

    // At terminal count, counter clears and output toggles.
    check_rollover_behavior: assert property (
        @(posedge C_100Mhz) ($past(contador) == LIMIT) |-> (contador == 32'd0) && (C_1Hz == ~$past(C_1Hz))
    );

    // Output can change only when previous count was terminal.
    check_toggle_only_on_rollover: assert property (
        @(posedge C_100Mhz) $changed(C_1Hz) |-> ($past(contador) == LIMIT)
    );

    // Any change on output is a true toggle (complement).
    check_toggle_is_complement: assert property (
        @(posedge C_100Mhz) $changed(C_1Hz) |-> (C_1Hz == ~$past(C_1Hz))
    );

    // Any toggle coincides with counter cleared to zero.
    check_toggle_clears_counter: assert property (
        @(posedge C_100Mhz) $changed(C_1Hz) |-> (contador == 32'd0)
    );

    // Next counter value is either previous+1 or zero (rollover).
    check_next_count_inc_or_zero: assert property (
        @(posedge C_100Mhz) (contador == ($past(contador) + 1)) || (contador == 32'd0)
    );

    // If counter becomes zero without having been zero, previous must have been terminal.
    check_zero_arrival_cause: assert property (
        @(posedge C_100Mhz) ((contador == 32'd0) && ($past(contador) != 32'd0)) |-> ($past(contador) == LIMIT)
    );

    // No consecutive-cycle toggles on the output.
    check_no_back_to_back_toggles: assert property (
        @(posedge C_100Mhz) $changed(C_1Hz) |-> ##1 !$changed(C_1Hz)
    );

endmodule

rtl:
module switch_to_leds (
    input [15:0] switch_input,
    input reset,
    output reg [7:0] red_led_output,
    output reg [7:0] green_led_output
);

    always @(*) begin
        if (reset) begin
            red_led_output <= 8'b0;
            green_led_output <= 8'b0;
        end else begin
            red_led_output <= ~switch_input[7:0];
            green_led_output <= ~switch_input[15:8];
        end
    end

endmodule

sva:
module switch_to_leds_sva (
    input  logic [15:0] switch_input,
    input  logic        reset,
    input  logic [7:0]  red_led_output,
    input  logic [7:0]  green_led_output
);
    // Using $global_clock for combinational sampling; reset is active-high.

    // During reset, both LED outputs are driven to zero.
    reset_forces_zeros: assert property (
        @($global_clock) reset |-> (red_led_output == 8'b0) && (green_led_output == 8'b0)
    );

    // When not in reset, red LED equals bitwise NOT of switch_input[7:0].
    red_mapping_when_not_reset: assert property (
        @($global_clock) disable iff (reset) red_led_output == ~switch_input[7:0]
    );

    // When not in reset, green LED equals bitwise NOT of switch_input[15:8].
    green_mapping_when_not_reset: assert property (
        @($global_clock) disable iff (reset) green_led_output == ~switch_input[15:8]
    );

    // When not in reset, concatenated {green,red} equals bitwise NOT of full switch_input.
    concat_mapping_when_not_reset: assert property (
        @($global_clock) disable iff (reset) {green_led_output, red_led_output} == ~switch_input
    );

    // With reset deasserted, if switch_input is stable, both LED outputs remain stable.
    stable_inputs_imply_stable_outputs: assert property (
        @($global_clock) disable iff (reset) $stable(switch_input) |-> $stable({green_led_output, red_led_output})
    );

    // With reset deasserted, change only in low byte changes only red LEDs; green LEDs stay stable.
    low_half_change_affects_only_red: assert property (
        @($global_clock) disable iff (reset) ($changed(switch_input[7:0]) && $stable(switch_input[15:8])) |-> ($changed(red_led_output) && $stable(green_led_output))
    );

    // With reset deasserted, change only in high byte changes only green LEDs; red LEDs stay stable.
    high_half_change_affects_only_green: assert property (
        @($global_clock) disable iff (reset) ($changed(switch_input[15:8]) && $stable(switch_input[7:0])) |-> ($changed(green_led_output) && $stable(red_led_output))
    );

    // With reset deasserted, any change to switch_input changes the concatenated LED outputs.
    any_input_change_changes_outputs: assert property (
        @($global_clock) disable iff (reset) $changed(switch_input) |-> $changed({green_led_output, red_led_output})
    );

    // With reset deasserted, a change in red LEDs implies the low byte of switch_input changed.
    red_change_implies_low_input_change: assert property (
        @($global_clock) disable iff (reset) ($changed(red_led_output) && $stable(switch_input[15:8])) |-> $changed(switch_input[7:0])
    );

    // With reset deasserted, a change in green LEDs implies the high byte of switch_input changed.
    green_change_implies_high_input_change: assert property (
        @($global_clock) disable iff (reset) ($changed(green_led_output) && $stable(switch_input[7:0])) |-> $changed(switch_input[15:8])
    );

endmodule

rtl:
module nios_system_switches (
  // inputs:
  address,
  clk,
  in_port,
  reset_n,

  // outputs:
  readdata
);

  output  [ 31: 0] readdata;
  input   [  1: 0] address;
  input            clk;
  input   [  9: 0] in_port;
  input            reset_n;

  wire             clk_en;
  wire    [  9: 0] data_in;
  wire    [  9: 0] read_mux_out;
  reg     [ 31: 0] readdata;

  // Select the data to be read from the input port
  assign read_mux_out = {10 {(address == 2'b00)}} & in_port;

  // Enable the clock signal
  assign clk_en = 1;

  // Assign the selected data to the data_in signal
  assign data_in = read_mux_out;

  // Update the readdata signal on the rising edge of the clock signal
  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      readdata <= 0;
    end else if (clk_en) begin
      readdata <= {32'b0 | data_in};
    end
  end

endmodule

sva:
module nios_system_switches_sva (
    input logic        clk,
    input logic        reset_n,    // active-low, async in RTL
    input logic [1:0]  address,
    input logic [9:0]  in_port,
    input logic [31:0] readdata
);
    // Clock: clk (posedge). Logic: combinational mux into a registered 32-bit output.

    // During reset, readdata must be cleared to 0.
    reset_clears_readdata: assert property (
        @(posedge clk) (!reset_n) |-> (readdata == 32'd0)
    );

    // After one cycle out of reset, upper 22 bits are always zero (zero-extension).
    upper_bits_zero_postreset: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) |-> (readdata[31:10] == 22'd0)
    );

    // After one cycle out of reset, LSBs equal prior-cycle muxed input: (address==0)? in_port : 0.
    lsb_matches_masked_in_port: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) |-> (readdata[9:0] == $past((address == 2'b00) ? in_port : 10'd0))
    );

    // When prior address was 0, full word is zero-extended prior in_port.
    full_word_zeroext_on_addr00: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) && ($past(address) == 2'b00) |-> (readdata == {22'd0, $past(in_port)})
    );

    // When prior address was not 0, the full word must be zero.
    full_word_zero_when_addr_not00: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) && ($past(address) != 2'b00) |-> (readdata == 32'd0)
    );

    // Nonzero LSBs imply prior address selected the port (address==0).
    lsb_nonzero_implies_addr00: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) && (readdata[9:0] != 10'd0) |-> ($past(address) == 2'b00)
    );
endmodule

rtl:
module swap_first_last_16_bits (
  input clk,
  input reset,
  input [31:0] in_vec,
  input control,
  output reg [31:0] out_vec
);

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      out_vec <= 0;
    end else begin
      if (control) begin
        out_vec[15:0] <= in_vec[31:16];
        out_vec[31:16] <= in_vec[15:0];
      end else begin
        out_vec <= in_vec;
      end
    end
  end

endmodule

sva:
module swap_first_last_16_bits_sva (
  input logic clk,
  input logic reset,
  input logic [31:0] in_vec,
  input logic control,
  input logic [31:0] out_vec
);

  // While reset is HIGH, out_vec must be zero.
  reset_clears_outvec: assert property (
    @(posedge clk) reset |-> (out_vec == 32'd0)
  );

  // Next-cycle out_vec equals previous in_vec or its 16-bit-swapped version based on previous control.
  deterministic_next_state: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |=> (out_vec == ($past(control) ? {$past(in_vec[15:0]), $past(in_vec[31:16])} : $past(in_vec)))
  );

  // Next-cycle upper 16 bits reflect previous control selection (swap or passthrough).
  next_upper_half_function: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |=> (out_vec[31:16] == ($past(control) ? $past(in_vec[15:0]) : $past(in_vec[31:16])))
  );

  // Next-cycle lower 16 bits reflect previous control selection (swap or passthrough).
  next_lower_half_function: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |=> (out_vec[15:0] == ($past(control) ? $past(in_vec[31:16]) : $past(in_vec[15:0])))
  );

  // If control is LOW, next-cycle out_vec passes through previous in_vec.
  passthrough_when_control0: assert property (
    @(posedge clk) disable iff (reset)
      (!control) |=> (out_vec == $past(in_vec))
  );

  // If control is HIGH, next-cycle out_vec swaps previous in_vec upper/lower 16 bits.
  swap_when_control1: assert property (
    @(posedge clk) disable iff (reset)
      (control) |=> ((out_vec[31:16] == $past(in_vec[15:0])) && (out_vec[15:0] == $past(in_vec[31:16])))
  );

endmodule

rtl:
module xor_gate(
    input a,
    input b,
    output out
);

assign out = a ^ b;

endmodule

module top_module(
    input a,
    input b,
    output reg out_always_comb
);

wire out_from_xor_gate;

xor_gate xor_gate_inst(
    .a(a),
    .b(b),
    .out(out_from_xor_gate)
);

always @(*)
begin
    out_always_comb = out_from_xor_gate;
end

endmodule

sva:
module top_module_sva (
    input logic a,
    input logic b,
    input logic out_always_comb
);
    // Out equals XOR of inputs.
    check_xor_equivalence: assert property (
        @($global_clock) out_always_comb == (a ^ b)
    );

    // When inputs are equal, output is 0.
    check_equal_inputs_low: assert property (
        @($global_clock) (a == b) |-> (out_always_comb == 1'b0)
    );

    // When inputs differ, output is 1.
    check_diff_inputs_high: assert property (
        @($global_clock) (a != b) |-> (out_always_comb == 1'b1)
    );

    // For a=0,b=0, output is 0.
    check_case_00_low: assert property (
        @($global_clock) (!a && !b) |-> (out_always_comb == 1'b0)
    );

    // For a=1,b=1, output is 0.
    check_case_11_low: assert property (
        @($global_clock) (a && b) |-> (out_always_comb == 1'b0)
    );

    // For a=0,b=1, output is 1.
    check_case_01_high: assert property (
        @($global_clock) (!a && b) |-> (out_always_comb == 1'b1)
    );

    // For a=1,b=0, output is 1.
    check_case_10_high: assert property (
        @($global_clock) (a && !b) |-> (out_always_comb == 1'b1)
    );

    // If exactly one input changes, output changes.
    check_one_input_change_implies_out_change: assert property (
        @($global_clock) $onehot({$changed(a), $changed(b)}) |-> $changed(out_always_comb)
    );

    // If both inputs change together, output remains stable.
    check_both_inputs_change_keeps_out_stable: assert property (
        @($global_clock) ($changed(a) && $changed(b)) |-> $stable(out_always_comb)
    );

    // If output changes, exactly one input must have changed.
    check_out_change_implies_one_input_change: assert property (
        @($global_clock) $changed(out_always_comb) |-> $onehot({$changed(a), $changed(b)})
    );
endmodule

module d_ff_en_sva (
    input logic D,
    input logic EN,
    input logic CLK,
    input logic Q
);
    ///// Functional next-state behavior /////
    // Next cycle Q equals (EN ? D : Q) from the previous cycle.
    check_next_state_equation: assert property (
        @(posedge CLK) 1'b1 |=> (Q == ($past(EN) ? $past(D) : $past(Q)))
    );

    ///// Update behavior /////
    // When EN is 1, Q on the next cycle equals D from this cycle.
    check_update_on_enable: assert property (
        @(posedge CLK) EN |=> (Q == $past(D))
    );

    // When EN is 0, Q holds its previous value.
    check_hold_on_disable: assert property (
        @(posedge CLK) !EN |=> (Q == $past(Q))
    );

    ///// Change conditions /////
    // Any change in Q must be caused by EN being 1 in the previous cycle.
    check_q_change_implies_prev_enable: assert property (
        @(posedge CLK) $changed(Q) |-> $past(EN)
    );

    // If EN=1 and D equals prior Q, Q does not change next cycle.
    check_no_change_when_assigning_same_value: assert property (
        @(posedge CLK) EN && (D == $past(Q)) |=> (Q == $past(Q))
    );

    // If EN=1 and D differs from prior Q, Q changes next cycle.
    check_change_when_enabled_and_data_differs: assert property (
        @(posedge CLK) EN && (D != $past(Q)) |=> (Q != $past(Q))
    );

    ///// Multi-cycle consistency /////
    // If EN=0 for two consecutive cycles, Q two cycles later equals its value two cycles ago.
    check_two_cycle_hold_when_disabled: assert property (
        @(posedge CLK) !EN ##1 !EN |=> (Q == $past(Q,2))
    );

    // If EN=1 for two consecutive cycles, Q two cycles later equals D from one cycle ago.
    check_two_cycle_enable_latest_data: assert property (
        @(posedge CLK) EN ##1 EN |=> (Q == $past(D,1))
    );

endmodule

rtl:
module cpx_fpbuf_p0(
   fp_cpx_req_bufp0_cq, 
   fp_cpx_req_bufpt_cq_l
   );

input	[7:0]	fp_cpx_req_bufpt_cq_l;

output	[7:0]	fp_cpx_req_bufp0_cq;


assign               fp_cpx_req_bufp0_cq[7:0]                =        ~fp_cpx_req_bufpt_cq_l[7:0];


endmodule

sva:
module cpx_fpbuf_p0_sva (
    input  logic        clk,
    input  logic        reset_n,
    input  logic [7:0]  fp_cpx_req_bufpt_cq_l,
    input  logic [7:0]  fp_cpx_req_bufp0_cq
);
    // Output is bitwise inversion of input each cycle.
    check_bitwise_inversion: assert property (
        @(posedge clk) disable iff (!reset_n)
        fp_cpx_req_bufp0_cq == ~fp_cpx_req_bufpt_cq_l
    );

    // Out XOR In is all ones (complement relation).
    check_xor_all_ones: assert property (
        @(posedge clk) disable iff (!reset_n)
        (fp_cpx_req_bufp0_cq ^ fp_cpx_req_bufpt_cq_l) == 8'hFF
    );

    // Out OR In is all ones (no bit can be 0 on both).
    check_or_all_ones: assert property (
        @(posedge clk) disable iff (!reset_n)
        (fp_cpx_req_bufp0_cq | fp_cpx_req_bufpt_cq_l) == 8'hFF
    );

    // Out AND In is all zeros (no bit can be 1 on both).
    check_and_all_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (fp_cpx_req_bufp0_cq & fp_cpx_req_bufpt_cq_l) == 8'h00
    );

    // The inversion relation also holds for the previous cycle.
    check_past_inversion: assert property (
        @(posedge clk) disable iff (!reset_n)
        $past(fp_cpx_req_bufp0_cq) == ~ $past(fp_cpx_req_bufpt_cq_l)
    );

    // If input is unchanged cycle-to-cycle, output is unchanged too.
    check_hold_when_input_holds: assert property (
        @(posedge clk) disable iff (!reset_n)
        (fp_cpx_req_bufpt_cq_l == $past(fp_cpx_req_bufpt_cq_l)) |-> (fp_cpx_req_bufp0_cq == $past(fp_cpx_req_bufp0_cq))
    );

    // Bits that rise on output equal bits that fall on input.
    check_rising_out_equals_falling_in: assert property (
        @(posedge clk) disable iff (!reset_n)
        ((~$past(fp_cpx_req_bufp0_cq)) & fp_cpx_req_bufp0_cq) == (($past(fp_cpx_req_bufpt_cq_l)) & ~fp_cpx_req_bufpt_cq_l)
    );

    // Bits that fall on output equal bits that rise on input.
    check_falling_out_equals_rising_in: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(fp_cpx_req_bufp0_cq)) & ~fp_cpx_req_bufp0_cq) == ((~$past(fp_cpx_req_bufpt_cq_l)) & fp_cpx_req_bufpt_cq_l)
    );

    // The set of toggling bits matches between input and output.
    check_toggle_set_matches: assert property (
        @(posedge clk) disable iff (!reset_n)
        (fp_cpx_req_bufpt_cq_l ^ $past(fp_cpx_req_bufpt_cq_l)) == (fp_cpx_req_bufp0_cq ^ $past(fp_cpx_req_bufp0_cq))
    );
endmodule

rtl:
module spll (
	areset,
	inclk0,
	c0,
	c1,
	locked);

	input	  areset;
	input	  inclk0;
	output	  c0;
	output	  c1;
	output	  locked;

	reg c0_reg;
	reg c1_reg;
	reg locked_reg;

	always @(posedge inclk0 or negedge areset) begin
		if (!areset) begin
			c0_reg <= 1'b0;
			c1_reg <= 1'b1;
			locked_reg <= 1'b0;
		end else begin
			if (c0_reg & c1_reg) begin
				c0_reg <= 1'b1;
				c1_reg <= 1'b0;
				locked_reg <= 1'b1;
			end else begin
				c0_reg <= c1_reg;
				c1_reg <= ~c0_reg;
				locked_reg <= 1'b0;
			end
		end
	end

	assign c0 = c0_reg;
	assign c1 = c1_reg;
	assign locked = locked_reg;

endmodule

sva:
module spll_sva (
    input logic areset,
    input logic inclk0,
    input logic c0,
    input logic c1,
    input logic locked
);
    ///// Reset behavior /////
    // While reset is asserted (low), outputs drive c0=0, c1=1, locked=0.
    check_reset_values: assert property (
        @(posedge inclk0) !areset |-> (c0 == 1'b0) && (c1 == 1'b1) && (locked == 1'b0)
    );

    ///// Locked relation /////
    // locked equals c0 AND NOT c1 every active cycle.
    check_locked_matches_outputs: assert property (
        @(posedge inclk0) disable iff (!areset) locked == (c0 & ~c1)
    );

    ///// State transitions /////
    // From state 00, next state is 01 and locked=0.
    check_transition_from_00: assert property (
        @(posedge inclk0) disable iff (!areset)
            (c0 == 1'b0 && c1 == 1'b0) |=> (c0 == 1'b0 && c1 == 1'b1 && locked == 1'b0)
    );

    // From state 01, next state is 11 and locked=0.
    check_transition_from_01: assert property (
        @(posedge inclk0) disable iff (!areset)
            (c0 == 1'b0 && c1 == 1'b1) |=> (c0 == 1'b1 && c1 == 1'b1 && locked == 1'b0)
    );

    // From state 11, next state is 10 and locked=1.
    check_transition_from_11: assert property (
        @(posedge inclk0) disable iff (!areset)
            (c0 == 1'b1 && c1 == 1'b1) |=> (c0 == 1'b1 && c1 == 1'b0 && locked == 1'b1)
    );

    // From state 10, next state is 00 and locked=0.
    check_transition_from_10: assert property (
        @(posedge inclk0) disable iff (!areset)
            (c0 == 1'b1 && c1 == 1'b0) |=> (c0 == 1'b0 && c1 == 1'b0 && locked == 1'b0)
    );

    ///// Locked pulse behavior /////
    // locked cannot stay HIGH for two consecutive cycles.
    check_locked_single_cycle_pulse: assert property (
        @(posedge inclk0) disable iff (!areset) locked |=> !locked
    );

    ///// Post-reset sequencing /////
    // On the first cycle after reset deasserts, state is 11 with locked=0.
    check_first_cycle_after_reset_deassert: assert property (
        @(posedge inclk0) disable iff (!areset) $rose(areset) |-> (c0 == 1'b1) && (c1 == 1'b1) && (locked == 1'b0)
    );

    ///// Locked next-state when not in 11 /////
    // If current state is not 11, next locked is 0.
    check_locked_next_zero_when_not_11: assert property (
        @(posedge inclk0) disable iff (!areset)
            !(c0 && c1) |=> (locked == 1'b0)
    );
endmodule

rtl:
module scan_chain_interface (
    input ctu_tst_pre_grst_l,
    input arst_l,
    input global_shift_enable,
    input ctu_tst_scan_disable,
    input ctu_tst_scanmode,
    input ctu_tst_macrotest,
    input ctu_tst_short_chain,
    input long_chain_so_0,
    input short_chain_so_0,
    input long_chain_so_1,
    input short_chain_so_1,
    input long_chain_so_2,
    input short_chain_so_2,
    output mux_drive_disable,
    output mem_write_disable,
    output sehold,
    output se,
    output testmode_l,
    output mem_bypass,
    output so_0,
    output so_1,
    output so_2
);

    wire pin_based_scan;
    wire short_chain_en;
    wire short_chain_select;

    assign pin_based_scan = ctu_tst_scan_disable;
    assign se = global_shift_enable;
    assign testmode_l = ~ctu_tst_scanmode;
    assign mem_bypass = ~ctu_tst_macrotest & ~testmode_l;
    assign short_chain_en = ~(pin_based_scan & se);
    assign short_chain_select = ctu_tst_short_chain & ~testmode_l & short_chain_en;
    assign so_0 = short_chain_select ? short_chain_so_0 : long_chain_so_0;
    assign so_1 = short_chain_select ? short_chain_so_1 : long_chain_so_1;
    assign so_2 = short_chain_select ? short_chain_so_2 : long_chain_so_2;
    assign mux_drive_disable = ~ctu_tst_pre_grst_l | short_chain_select | se;
    assign mem_write_disable = ~ctu_tst_pre_grst_l | se;
    assign sehold = ctu_tst_macrotest & ~se;

endmodule

sva:
module scan_chain_interface_sva (
    input logic ctu_tst_pre_grst_l,
    input logic arst_l,
    input logic global_shift_enable,
    input logic ctu_tst_scan_disable,
    input logic ctu_tst_scanmode,
    input logic ctu_tst_macrotest,
    input logic ctu_tst_short_chain,
    input logic long_chain_so_0,
    input logic short_chain_so_0,
    input logic long_chain_so_1,
    input logic short_chain_so_1,
    input logic long_chain_so_2,
    input logic short_chain_so_2,
    input logic mux_drive_disable,
    input logic mem_write_disable,
    input logic sehold,
    input logic se,
    input logic testmode_l,
    input logic mem_bypass,
    input logic so_0,
    input logic so_1,
    input logic so_2
);
    // No explicit clock in RTL; sample on posedge of global_shift_enable.
    // Active-low reset: ctu_tst_pre_grst_l (arst_l is unused).
    // Purely combinational logic; assertions check combinational definitions.

    ///// Direct signal definitions /////
    // se equals global_shift_enable.
    check_se_equals_gse: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) se == global_shift_enable
    );
    // testmode_l is inverse of ctu_tst_scanmode.
    check_testmode_l_inverse: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) testmode_l == ~ctu_tst_scanmode
    );
    // mem_bypass equals ~ctu_tst_macrotest & ~testmode_l.
    check_mem_bypass_def: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) mem_bypass == (~ctu_tst_macrotest & ~testmode_l)
    );
    // sehold equals ctu_tst_macrotest & ~se.
    check_sehold_def: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) sehold == (ctu_tst_macrotest & ~se)
    );
    // mem_write_disable equals ~ctu_tst_pre_grst_l | se.
    check_mem_write_disable_def: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) mem_write_disable == (~ctu_tst_pre_grst_l | se)
    );
    // mux_drive_disable equals ~ctu_tst_pre_grst_l | short_chain_select | se.
    check_mux_drive_disable_def: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l)
            mux_drive_disable == (~ctu_tst_pre_grst_l |
                                  (ctu_tst_short_chain & ~testmode_l & ~(ctu_tst_scan_disable & se)) |
                                  se)
    );

    ///// Scan-out mux selection /////
    // so_0 selects between short/long chain based on short_chain_select.
    check_so0_mux: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l)
            so_0 == ((ctu_tst_short_chain & ~testmode_l & ~(ctu_tst_scan_disable & se)) ? short_chain_so_0 : long_chain_so_0)
    );
    // so_1 selects between short/long chain based on short_chain_select.
    check_so1_mux: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l)
            so_1 == ((ctu_tst_short_chain & ~testmode_l & ~(ctu_tst_scan_disable & se)) ? short_chain_so_1 : long_chain_so_1)
    );
    // so_2 selects between short/long chain based on short_chain_select.
    check_so2_mux: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l)
            so_2 == ((ctu_tst_short_chain & ~testmode_l & ~(ctu_tst_scan_disable & se)) ? short_chain_so_2 : long_chain_so_2)
    );

    ///// Derived implications (from direct definitions) /////
    // When testmode_l is HIGH, mem_bypass must be LOW.
    check_testmode_blocks_mem_bypass: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) testmode_l |-> (mem_bypass == 1'b0)
    );
    // When se is HIGH, sehold must be LOW.
    check_shift_disables_sehold: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) se |-> (sehold == 1'b0)
    );
    // mem_write_disable implies mux_drive_disable (mux_disable = memw_disable | short_chain_select).
    check_memw_implies_mux_disable: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) mem_write_disable |-> mux_drive_disable
    );
endmodule

rtl:
module barrel_shifter (
    input [7:0] data,
    input [1:0] shift,
    output [7:0] shifted_data
);

    assign shifted_data = (shift[1]) ? {data[0], data[7:1]} : 
                          (shift[0]) ? {data[1:0], data[7:2]} : 
                                       {data[2:0], data[7:3]};

endmodule

module shift_register (
    input clk,
    input load,
    input [7:0] data_in,
    output [7:0] data_out
);

    reg [7:0] shift_reg;

    always @(posedge clk) begin
        if (load) begin
            shift_reg <= data_in;
        end else begin
            shift_reg <= {shift_reg[6:0], shift_reg[7]};
        end
    end

    assign data_out = shift_reg;

endmodule

module functional_module (
    input [7:0] shifted_data,
    input [7:0] shift_reg_data,
    output [7:0] sum
);

    assign sum = shifted_data + shift_reg_data;

endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] data,
    input [1:0] shift,
    input load,
    output [7:0] q
);

    wire [7:0] shifted_data;
    wire [7:0] shift_reg_data;
    wire [7:0] sum;

    barrel_shifter barrel_shifter_inst (
        .data(data),
        .shift(shift),
        .shifted_data(shifted_data)
    );

    shift_register shift_register_inst (
        .clk(clk),
        .load(load),
        .data_in(shifted_data),
        .data_out(shift_reg_data)
    );

    functional_module functional_module_inst (
        .shifted_data(shifted_data),
        .shift_reg_data(shift_reg_data),
        .sum(sum)
    );

    assign q = sum;

endmodule

sva:
module top_module_sva (
    input  logic        clk,
    input  logic        reset,
    input  logic [7:0]  data,
    input  logic [1:0]  shift,
    input  logic        load,
    input  logic [7:0]  q
);

    // Helper: same barrel shift as RTL
    function automatic logic [7:0] barrel8 (input logic [7:0] d, input logic [1:0] s);
        barrel8 = (s[1]) ? {d[0], d[7:1]} :
                  (s[0]) ? {d[1:0], d[7:2]} :
                           {d[2:0], d[7:3]};
    endfunction

    // Helper: rotate-left by 1
    function automatic logic [7:0] rotl8 (input logic [7:0] a);
        rotl8 = {a[6:0], a[7]};
    endfunction

    // Combinational shifted_data computed from top-level inputs
    logic [7:0] sh_now;
    assign sh_now = barrel8(data, shift);

    // Derive current shift register content from q and shifted_data (q = sh_now + sr_now)
    logic [7:0] sr_now;
    assign sr_now = q - sh_now;

    // On load, next shift register equals previous shifted_data.
    check_sr_update_on_load: assert property (
        @(posedge clk) disable iff (reset)
            $past(load) |-> (sr_now == $past(sh_now))
    );

    // Without load, next shift register is previous value rotated left by 1.
    check_sr_rotate_when_no_load: assert property (
        @(posedge clk) disable iff (reset)
            !$past(load) |-> (sr_now == rotl8($past(q) - $past(sh_now)))
    );

    // After load, q equals current shifted_data plus previous shifted_data.
    check_q_next_after_load: assert property (
        @(posedge clk) disable iff (reset)
            $past(load) |-> (q == (sh_now + $past(sh_now)))
    );

    // Without load, q equals current shifted_data plus rotated previous shift register.
    check_q_next_after_no_load: assert property (
        @(posedge clk) disable iff (reset)
            !$past(load) |-> (q == (sh_now + rotl8($past(q) - $past(sh_now))))
    );

    // Two consecutive no-load cycles rotate the shift register twice.
    check_sr_double_rotate_two_no_loads: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(load,2) && !$past(load,1)) |-> (sr_now == rotl8(rotl8($past(q,2) - $past(sh_now,2))))
    );

    // Load followed by no-load rotates the captured shifted_data once.
    check_sr_load_then_rotate: assert property (
        @(posedge clk) disable iff (reset)
            ($past(load,2) && !$past(load,1)) |-> (sr_now == rotl8($past(sh_now,2)))
    );

    // Two consecutive loads make the shift register equal last cycle's shifted_data.
    check_sr_two_consecutive_loads: assert property (
        @(posedge clk) disable iff (reset)
            ($past(load,2) && $past(load,1)) |-> (sr_now == $past(sh_now,1))
    );

    // Eight no-load cycles return the shift register to its original value.
    check_sr_invariant_after_eight_rotates: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(load,1) && !$past(load,2) && !$past(load,3) && !$past(load,4) &&
             !$past(load,5) && !$past(load,6) && !$past(load,7) && !$past(load,8))
            |-> (sr_now == $past(sr_now,8))
    );

    // After eight no-load cycles, q delta equals shifted_data delta (sr returns to original).
    check_q_delta_matches_shifted_delta_after_eight_rotates: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(load,1) && !$past(load,2) && !$past(load,3) && !$past(load,4) &&
             !$past(load,5) && !$past(load,6) && !$past(load,7) && !$past(load,8))
            |-> ((q - $past(q,8)) == (sh_now - $past(sh_now,8)))
    );

    // Two consecutive no-load cycles: q equals current shifted_data plus double-rotated previous sr.
    check_q_after_two_no_loads: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(load,2) && !$past(load,1)) |-> (q == (sh_now + rotl8(rotl8($past(q,2) - $past(sh_now,2)))))
    );

endmodule

module shift_register_sva (
    input logic clk,
    input logic load,
    input logic [3:0] data,
    input logic [3:0] out
);
    // Clock: clk; no reset present in RTL.
    // Sequential behavior: on posedge clk, if load=1 load data; else shift left and insert data[3] at LSB.

    // Next-cycle out matches RTL next-state function based on prior cycle inputs.
    check_next_state_function: assert property (
        @(posedge clk) 1'b1 |=> (out == ($past(load) ? $past(data) : {$past(out[2:0]), $past(data[3])}))
    );

    // When load is 1, next-cycle out equals prior-cycle data.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (out == $past(data))
    );

    // When load is 0, next-cycle out equals prior out shifted with prior data[3] into LSB.
    check_shift_concat: assert property (
        @(posedge clk) !load |=> (out == {$past(out[2:0]), $past(data[3])})
    );

    // In shift mode, upper bits move from lower bits of prior out.
    check_shift_upper_bits_move: assert property (
        @(posedge clk) !load |=> (out[3:1] == $past(out[2:0]))
    );

    // In shift mode, LSB becomes prior-cycle data[3].
    check_shift_lsb_source: assert property (
        @(posedge clk) !load |=> (out[0] == $past(data[3]))
    );

endmodule

rtl:
module shift_adder (
    input CLK,
    input LOAD,
    input SHIFT,
    input [7:0] DATA_IN,
    output [7:0] Q_OUT,
    output [7:0] Q_BAR_OUT
);

reg [7:0] shift_reg;
wire [3:0] constant = 4'b1111;

assign Q_OUT = shift_reg;
assign Q_BAR_OUT = ~shift_reg;

always @(posedge CLK) begin
    if (LOAD) begin
        shift_reg <= DATA_IN;
    end else if (SHIFT) begin
        shift_reg <= {DATA_IN[7], shift_reg[7:1]};
    end
end

wire [7:0] sum;
adder add_inst (
    .A(shift_reg),
    .B(constant),
    .C(sum)
);

endmodule
module adder (
    input [7:0] A,
    input [3:0] B,
    output [7:0] C
);

assign C = A + B;

endmodule

sva:
module shift_adder_sva (
    input logic CLK,
    input logic LOAD,
    input logic SHIFT,
    input logic [7:0] DATA_IN,
    input logic [7:0] Q_OUT,
    input logic [7:0] Q_BAR_OUT
);
    // Clock: CLK (posedge). No reset present.
    // Logic: Mixed (sequential shift_reg; combinational complement and adder).
    // Behavior: LOAD captures DATA_IN; else if SHIFT shifts right with MSB from DATA_IN[7]; else hold. Q_BAR_OUT is ~Q_OUT.

    // Q_BAR_OUT is always the bitwise complement of Q_OUT.
    check_complement_always: assert property (
        @(posedge CLK) (Q_BAR_OUT == ~Q_OUT)
    );

    // LOAD updates Q_OUT with DATA_IN on the next cycle (SHIFT ignored if also high).
    check_load_updates_qout: assert property (
        @(posedge CLK) LOAD |-> ##1 (Q_OUT == $past(DATA_IN))
    );

    // When SHIFT and not LOAD, next Q_OUT equals {DATA_IN[7], previous Q_OUT[7:1]}.
    check_shift_right_vector: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |-> ##1 (Q_OUT == { $past(DATA_IN[7]), $past(Q_OUT[7:1]) })
    );

    // SHIFT (without LOAD) updates MSB with DATA_IN[7] on the next cycle.
    check_shift_msb_update: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |-> ##1 (Q_OUT[7] == $past(DATA_IN[7]))
    );

    // SHIFT (without LOAD) shifts lower bits right by one on the next cycle.
    check_shift_lower_bits_update: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |-> ##1 (Q_OUT[6:0] == $past(Q_OUT[7:1]))
    );

    // When neither LOAD nor SHIFT, Q_OUT holds its value to the next cycle.
    check_hold_when_idle: assert property (
        @(posedge CLK) (!LOAD && !SHIFT) |-> ##1 (Q_OUT == $past(Q_OUT))
    );

    // After LOAD, Q_BAR_OUT reflects the complement of the loaded DATA_IN.
    check_load_updates_qbar: assert property (
        @(posedge CLK) LOAD |-> ##1 (Q_BAR_OUT == ~($past(DATA_IN)))
    );

    // After SHIFT (without LOAD), Q_BAR_OUT reflects complement of the shifted result.
    check_shift_updates_qbar: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |-> ##1 (Q_BAR_OUT == ~{ $past(DATA_IN[7]), $past(Q_OUT[7:1]) })
    );

    // Any change in Q_OUT by next cycle requires LOAD or SHIFT in the previous cycle.
    check_change_requires_enable: assert property (
        @(posedge CLK) 1'b1 |-> ##1 ( (Q_OUT == $past(Q_OUT)) || ($past(LOAD) || $past(SHIFT)) )
    );

    // LOAD has priority over SHIFT when both are asserted.
    check_load_priority_over_shift: assert property (
        @(posedge CLK) (LOAD && SHIFT) |-> ##1 (Q_OUT == $past(DATA_IN))
    );
endmodule

rtl:
module kb_code
  (
    input wire clk, reset,scan_done_tick,
    input wire [7:0] scan_out,
    output reg got_code_tick
   );

   localparam BRK = 8'hf0; localparam
      wait_brk = 1'b0,
      get_code = 1'b1;

   reg state_reg, state_next;

   always @(posedge clk, posedge reset)
      if (reset)
         state_reg <= wait_brk;
      else
         state_reg <= state_next;

   always @*
   begin
      got_code_tick = 1'b0;
      state_next = state_reg;
      case (state_reg)
         wait_brk:  if (scan_done_tick==1'b1 && scan_out==BRK)
               state_next = get_code;
         get_code:  if (scan_done_tick)
               begin
                  got_code_tick =1'b1;
                  state_next = wait_brk;
               end
      endcase
   end

endmodule

sva:
module kb_code_sva (
    input logic clk,
    input logic reset,
    input logic scan_done_tick,
    input logic [7:0] scan_out,
    input logic got_code_tick
);
    localparam logic [7:0] BRK = 8'hf0;

    // While reset is asserted, output tick must be LOW.
    reset_clears_tick: assert property (
        @(posedge clk) reset |-> (got_code_tick == 1'b0)
    );

    // No tick when scan_done_tick is LOW.
    tick_requires_done: assert property (
        @(posedge clk) disable iff (reset) (scan_done_tick == 1'b0) |-> (got_code_tick == 1'b0)
    );

    // got_code_tick is a single-cycle pulse.
    tick_one_cycle_pulse: assert property (
        @(posedge clk) disable iff (reset) got_code_tick |=> !got_code_tick
    );

    // After a tick, remain LOW until a BRK code is observed with scan_done_tick.
    holdoff_until_break_after_tick: assert property (
        @(posedge clk) disable iff (reset) got_code_tick |=> (!got_code_tick until (scan_done_tick && (scan_out == BRK)))
    );

    // If previous cycle was BRK with done and no tick, then current done must raise tick.
    break_then_next_done_yields_tick: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) && $past(scan_done_tick && (scan_out == BRK) && !got_code_tick) && scan_done_tick |-> got_code_tick
    );

    // With back-to-back done pulses, if prior was not BRK in wait_brk, then no tick now.
    consecutive_done_without_break_no_tick: assert property (
        @(posedge clk) disable iff (reset)
            scan_done_tick && $past(!reset) && $past(scan_done_tick) && !($past(scan_out == BRK) && !$past(got_code_tick)) |-> !got_code_tick
    );

    // With back-to-back done pulses, a tick now implies prior was BRK and no tick.
    consecutive_done_tick_implies_prev_break: assert property (
        @(posedge clk) disable iff (reset)
            scan_done_tick && $past(!reset) && $past(scan_done_tick) && got_code_tick |-> $past(scan_out == BRK) && !$past(got_code_tick)
    );

    // After reset deasserts, no tick until a BRK code is seen with scan_done_tick.
    after_reset_block_tick_until_break: assert property (
        @(posedge clk) $fell(reset) |-> (!got_code_tick until (scan_done_tick && (scan_out == BRK)))
    );

    // On the first cycle after reset deasserts, a BRK done does not raise tick.
    first_cycle_after_reset_break_no_tick: assert property (
        @(posedge clk) $past(reset) && !reset && scan_done_tick && (scan_out == BRK) |-> !got_code_tick
    );
endmodule

