module voltage_level_shifter (
    VPWR,
    VGND,
    VPB,
    VNB,
    VPB_OUT,
    VNB_OUT,
    VPWR_OUT,
    VGND_OUT
);

    input VPWR;
    input VGND;
    input VPB;
    input VNB;
    output VPB_OUT;
    output VNB_OUT;
    output VPWR_OUT;
    output VGND_OUT;

    assign VPWR_OUT = VPWR;
    assign VGND_OUT = VGND;

    assign VPB_OUT = (VPB == 1'b1) ? VPWR : VGND;
    assign VNB_OUT = (VNB == 1'b1) ? VPWR : VGND;

endmodule

sva:
module voltage_level_shifter_sva (
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic VPB_OUT,
    input logic VNB_OUT,
    input logic VPWR_OUT,
    input logic VGND_OUT
);
    // No clock/reset in DUT; combinational only. Sample on any edge of DUT inputs.

    // VPWR_OUT must equal VPWR.
    check_vpwr_passthrough: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VPWR_OUT == VPWR)
    );

    // VGND_OUT must equal VGND.
    check_vgnd_passthrough: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VGND_OUT == VGND)
    );

    // When VPB is 1, VPB_OUT must equal VPWR.
    check_vpb_selects_vpwr_when_one: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VPB == 1'b1) |-> (VPB_OUT == VPWR)
    );

    // When VPB is 0, VPB_OUT must equal VGND.
    check_vpb_selects_vgnd_when_zero: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VPB == 1'b0) |-> (VPB_OUT == VGND)
    );

    // When VNB is 1, VNB_OUT must equal VPWR.
    check_vnb_selects_vpwr_when_one: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VNB == 1'b1) |-> (VNB_OUT == VPWR)
    );

    // When VNB is 0, VNB_OUT must equal VGND.
    check_vnb_selects_vgnd_when_zero: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VNB == 1'b0) |-> (VNB_OUT == VGND)
    );

    // VPB_OUT must be either VPWR or VGND.
    check_vpb_out_is_supply: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VPB_OUT == VPWR) || (VPB_OUT == VGND)
    );

    // VNB_OUT must be either VPWR or VGND.
    check_vnb_out_is_supply: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VNB_OUT == VPWR) || (VNB_OUT == VGND)
    );

    // If supplies are equal, all outputs must equal that value.
    check_equal_supplies_make_all_outs_equal: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VPWR == VGND) |-> ((VPWR_OUT == VGND_OUT) && (VPB_OUT == VPWR) && (VNB_OUT == VPWR) && (VGND_OUT == VPWR))
    );

    // If VPB and VNB are equal, VPB_OUT and VNB_OUT must be equal.
    check_equal_controls_equal_body_outs: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VPB == VNB) |-> (VPB_OUT == VNB_OUT)
    );

    // If VPB!=VNB and supplies differ, VPB_OUT and VNB_OUT must differ.
    check_unequal_controls_and_supplies_give_diff_outs: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        ((VPB != VNB) && (VPWR != VGND)) |-> (VPB_OUT != VNB_OUT)
    );

endmodule

rtl:
module adder(
  input [7:0] A,
  input [7:0] B,
  input C,
  output reg [7:0] sum
);

  always @(*)
  begin
    // add the inputs
    sum = A + B;

    // truncate if necessary
    if(sum > 8'b11111111)
      sum = sum[7:0];

    // convert to two's complement if required
    if(C)
      sum = ~sum + 1;
  end

endmodule

sva:
module adder_sva (
    input logic CLK,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic C,
    input logic [7:0] sum
);
    // When C=0 the sum equals A+B (8-bit truncation).
    check_sum_when_C0: assert property (
        @(posedge CLK) (C == 1'b0) |-> (sum == (A + B))
    );

    // When C=1 the sum equals two's complement of (A+B).
    check_sum_when_C1: assert property (
        @(posedge CLK) (C == 1'b1) |-> (sum == (~(A + B) + 8'd1))
    );

    // Sum is zero whenever (A+B) is zero, regardless of C.
    check_zero_result_on_zero_input_sum: assert property (
        @(posedge CLK) ((A + B) == 8'h00) |-> (sum == 8'h00)
    );

    // Sum changes only if at least one input (A,B,C) changes.
    check_output_only_changes_on_input_change: assert property (
        @(posedge CLK) $changed(sum) |-> ($changed(A) || $changed(B) || $changed(C))
    );

    // If inputs are stable cycle-to-cycle, sum is stable.
    check_stable_output_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && $stable(C)) |-> $stable(sum)
    );

    // Rising C edge with stable A,B complements previous sum.
    check_c_rise_complements_sum: assert property (
        @(posedge CLK) ($rose(C) && $stable(A) && $stable(B)) |-> (sum == (~$past(sum) + 8'd1))
    );

    // Falling C edge with stable A,B complements previous sum.
    check_c_fall_complements_sum: assert property (
        @(posedge CLK) ($fell(C) && $stable(A) && $stable(B)) |-> (sum == (~$past(sum) + 8'd1))
    );

    // Sum is always within 8-bit range.
    check_sum_within_range: assert property (
        @(posedge CLK) (sum <= 8'hFF)
    );

    // For C=1, sum plus (A+B) wraps to zero (8-bit).
    check_twos_complement_sum_cancel: assert property (
        @(posedge CLK) (C == 1'b1) |-> (((sum + (A + B)) == 8'h00))
    );

    // For C=0, sum cancels with two's complement of (A+B) to zero.
    check_normal_sum_cancel_with_negated_ab: assert property (
        @(posedge CLK) (C == 1'b0) |-> (((sum + (~(A + B) + 8'd1)) == 8'h00))
    );
endmodule

