module mux_2_to_1 (
    input A,
    input B,
    input S,
    input clk,
    output reg Y
);

reg reg_A;
reg reg_B;

always @(posedge clk) begin
    reg_A <= A;
    reg_B <= B;
end

always @(posedge clk) begin
    if (S == 0) begin
        Y <= reg_A;
    end
    else begin
        Y <= reg_B;
    end
end

endmodule

sva:
module mux_2_to_1_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic S,
    input logic Y,
    input logic reg_A,
    input logic reg_B
);
    // Clock: clk (posedge). No reset. Sequential pipeline: reg_A/reg_B capture A/B; Y selects previous regs using current S.

    // reg_A equals previous-cycle A.
    check_regA_captures_A: assert property (
        @(posedge clk) $past(1'b1) |-> (reg_A == $past(A))
    );

    // reg_B equals previous-cycle B.
    check_regB_captures_B: assert property (
        @(posedge clk) $past(1'b1) |-> (reg_B == $past(B))
    );

    // Y equals previous-cycle selected reg using current S.
    check_Y_mux_prev_regs_with_curr_S: assert property (
        @(posedge clk) $past(1'b1) |-> (Y == (S ? $past(reg_B) : $past(reg_A)))
    );

    // When S==0, Y equals previous-cycle A.
    check_Y_prev_A_when_S0: assert property (
        @(posedge clk) ($past(1'b1) && (S == 1'b0)) |-> (Y == $past(A))
    );

    // When S==1, Y equals previous-cycle B.
    check_Y_prev_B_when_S1: assert property (
        @(posedge clk) ($past(1'b1) && (S == 1'b1)) |-> (Y == $past(B))
    );

    // On S rising edge, Y selects previous-cycle reg_B.
    check_Y_on_S_rise_selects_prev_regB: assert property (
        @(posedge clk) $rose(S) |-> (Y == $past(reg_B))
    );

    // On S falling edge, Y selects previous-cycle reg_A.
    check_Y_on_S_fall_selects_prev_regA: assert property (
        @(posedge clk) $fell(S) |-> (Y == $past(reg_A))
    );

    // Y equals mux of previous-cycle A/B using current S.
    check_Y_prev_data_based_on_curr_S: assert property (
        @(posedge clk) $past(1'b1) |-> (Y == (S ? $past(B) : $past(A)))
    );

endmodule

module d_ff_async_reset_sva (
    input logic clk,
    input logic d,
    input logic r,
    input logic q
);
    // If reset is HIGH at a clock edge, q must be 0 on the next clock edge.
    check_reset_clears_next: assert property (
        @(posedge clk) r |-> ##1 (q == 1'b0)
    );

    // While reset is HIGH at consecutive sampled cycles, q is 0 now.
    check_q_zero_while_reset_held: assert property (
        @(posedge clk) (r && $past(r)) |-> (q == 1'b0)
    );

    // On a sampled falling edge of reset, q is 0 in that cycle.
    check_q_zero_on_reset_release_sample: assert property (
        @(posedge clk) $fell(r) |-> (q == 1'b0)
    );
endmodule

rtl:
module mbus_wire_ctrl(
	input RESETn,
	input DOUT_FROM_BUS,
	input CLKOUT_FROM_BUS,
	`ifdef POWER_GATING
	input DIN,
	input CLKIN,
	input RELEASE_ISO_FROM_SLEEP_CTRL,
	input EXTERNAL_INT,
	`endif
	output reg DOUT,
	output reg CLKOUT
);

`ifdef POWER_GATING
always @ *
begin
	if (~RESETn)
		CLKOUT <= 1'b1;
	else if (RELEASE_ISO_FROM_SLEEP_CTRL==`IO_HOLD)
		CLKOUT <= CLKIN;
	else
		CLKOUT <= CLKOUT_FROM_BUS;

	if (~RESETn)
		DOUT <= 1'b1;
	else if (EXTERNAL_INT)
		DOUT <= 0;
	else
	begin
		if (RELEASE_ISO_FROM_SLEEP_CTRL==`IO_HOLD)
			DOUT <= DIN;
		else
			DOUT <= DOUT_FROM_BUS;
	end
end
`else
always @ *
begin
	if (~RESETn)
		CLKOUT <= 1'b1;
	else
		CLKOUT <= CLKOUT_FROM_BUS;

	if (~RESETn)
		DOUT <= 1'b1;
	else
		DOUT <= DOUT_FROM_BUS;
end
`endif

endmodule

sva:
module mbus_wire_ctrl_sva (
    input logic RESETn,
    input logic DOUT_FROM_BUS,
    input logic CLKOUT_FROM_BUS,
`ifdef POWER_GATING
    input logic DIN,
    input logic CLKIN,
    input logic RELEASE_ISO_FROM_SLEEP_CTRL,
    input logic EXTERNAL_INT,
`endif
    input logic DOUT,
    input logic CLKOUT
);
    // During reset, outputs are forced HIGH.
    reset_outputs_high: assert property (
        @(posedge CLKOUT_FROM_BUS) !RESETn |-> (CLKOUT == 1'b1) && (DOUT == 1'b1)
    );

`ifdef POWER_GATING
    // When ISO hold is active, CLKOUT mirrors CLKIN.
    clkout_select_clkin_when_hold: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        (RELEASE_ISO_FROM_SLEEP_CTRL == `IO_HOLD) |-> (CLKOUT == CLKIN)
    );
    // When not in ISO hold, CLKOUT mirrors CLKOUT_FROM_BUS.
    clkout_select_bus_when_not_hold: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        (RELEASE_ISO_FROM_SLEEP_CTRL != `IO_HOLD) |-> (CLKOUT == CLKOUT_FROM_BUS)
    );
    // EXTERNAL_INT forces DOUT LOW.
    dout_forced_low_on_external_int: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        EXTERNAL_INT |-> (DOUT == 1'b0)
    );
    // Without EXTERNAL_INT and in ISO hold, DOUT mirrors DIN.
    dout_select_din_when_hold_no_int: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        (!EXTERNAL_INT && (RELEASE_ISO_FROM_SLEEP_CTRL == `IO_HOLD)) |-> (DOUT == DIN)
    );
    // Without EXTERNAL_INT and not in ISO hold, DOUT mirrors DOUT_FROM_BUS.
    dout_select_bus_when_not_hold_no_int: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        (!EXTERNAL_INT && (RELEASE_ISO_FROM_SLEEP_CTRL != `IO_HOLD)) |-> (DOUT == DOUT_FROM_BUS)
    );
    // If ISO hold and CLKIN are stable, CLKOUT is stable.
    clkout_stable_when_hold_and_clkin_stable: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        ($stable(RELEASE_ISO_FROM_SLEEP_CTRL) && (RELEASE_ISO_FROM_SLEEP_CTRL == `IO_HOLD) && $stable(CLKIN)) |-> $stable(CLKOUT)
    );
    // If not in ISO hold and bus clock is stable, CLKOUT is stable.
    clkout_stable_when_not_hold_and_busclk_stable: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        ($stable(RELEASE_ISO_FROM_SLEEP_CTRL) && (RELEASE_ISO_FROM_SLEEP_CTRL != `IO_HOLD) && $stable(CLKOUT_FROM_BUS)) |-> $stable(CLKOUT)
    );
    // If EXTERNAL_INT stays HIGH, DOUT stays LOW.
    dout_stable_low_when_extint_stable_high: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        ($stable(EXTERNAL_INT) && EXTERNAL_INT) |-> ($stable(DOUT) && (DOUT == 1'b0))
    );
    // If no EXTERNAL_INT, ISO hold and DIN are stable, DOUT is stable.
    dout_stable_when_hold_no_int_and_din_stable: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        ($stable(EXTERNAL_INT) && !EXTERNAL_INT &&
         $stable(RELEASE_ISO_FROM_SLEEP_CTRL) && (RELEASE_ISO_FROM_SLEEP_CTRL == `IO_HOLD) &&
         $stable(DIN)) |-> $stable(DOUT)
    );
    // If no EXTERNAL_INT, not in ISO hold and bus data is stable, DOUT is stable.
    dout_stable_when_not_hold_no_int_and_busdata_stable: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        ($stable(EXTERNAL_INT) && !EXTERNAL_INT &&
         $stable(RELEASE_ISO_FROM_SLEEP_CTRL) && (RELEASE_ISO_FROM_SLEEP_CTRL != `IO_HOLD) &&
         $stable(DOUT_FROM_BUS)) |-> $stable(DOUT)
    );
`else
    // When not in reset, CLKOUT mirrors CLKOUT_FROM_BUS.
    clkout_follows_bus_no_pg: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        (CLKOUT == CLKOUT_FROM_BUS)
    );
    // When not in reset, DOUT mirrors DOUT_FROM_BUS.
    dout_follows_bus_no_pg: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        (DOUT == DOUT_FROM_BUS)
    );
    // If bus clock is stable, CLKOUT is stable.
    clkout_stable_when_busclk_stable_no_pg: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        $stable(CLKOUT_FROM_BUS) |-> $stable(CLKOUT)
    );
    // If bus data is stable, DOUT is stable.
    dout_stable_when_busdata_stable_no_pg: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        $stable(DOUT_FROM_BUS) |-> $stable(DOUT)
    );
`endif
endmodule

module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);
    // Clock: clk (posedge). Reset: rst (active-high, asynchronous). Logic: sequential counter with wrap to 0 at 15.

    // After reset deassertion, count is 0 on that sampled clock edge.
    check_count_zero_on_reset_release: assert property (
        @(posedge clk) disable iff (rst) $fell(rst) |-> (count == 4'd0)
    );

    // When not at max (15), count increments by 1 on the next clock.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (rst) (count != 4'hF) |=> (count == $past(count) + 4'd1)
    );

    // When at max (15), count wraps to 0 on the next clock.
    check_wrap_when_max: assert property (
        @(posedge clk) disable iff (rst) (count == 4'hF) |=> (count == 4'd0)
    );

    // Every cycle out of reset, the transition is either +1 or wrap-to-0 from 15.
    check_valid_transition_each_cycle: assert property (
        @(posedge clk) disable iff (rst)
            1'b1 |=> ((($past(count) != 4'hF) && (count == $past(count) + 4'd1)) ||
                      (($past(count) == 4'hF) && (count == 4'd0)))
    );

    // From reset release, the counter produces the full 0..15..0 sequence if reset stays low.
    check_full_sequence_from_reset_release: assert property (
        @(posedge clk) disable iff (rst)
            $fell(rst) |-> (count == 4'd0)
                        ##1 (count == 4'd1)
                        ##1 (count == 4'd2)
                        ##1 (count == 4'd3)
                        ##1 (count == 4'd4)
                        ##1 (count == 4'd5)
                        ##1 (count == 4'd6)
                        ##1 (count == 4'd7)
                        ##1 (count == 4'd8)
                        ##1 (count == 4'd9)
                        ##1 (count == 4'd10)
                        ##1 (count == 4'd11)
                        ##1 (count == 4'd12)
                        ##1 (count == 4'd13)
                        ##1 (count == 4'd14)
                        ##1 (count == 4'd15)
                        ##1 (count == 4'd0)
    );

endmodule

rtl:
module magnitude_comparator (
    input [3:0] a,
    input [3:0] b,
    output [1:0] out
);

    assign out = (a > b) ? 2'b01 : (a < b) ? 2'b10 : 2'b00;

endmodule

sva:
module magnitude_comparator_sva (
    input logic CLK,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [1:0] out
);
    ///// Magnitude comparison encoding /////
    // 'out' matches the ternary mapping of a and b.
    check_functional_equivalence: assert property (
        @(posedge CLK) out == ((a > b) ? 2'b01 : (a < b) ? 2'b10 : 2'b00)
    );
    // out[0] is 1 iff a > b.
    check_out0_maps_gt: assert property (
        @(posedge CLK) out[0] == (a > b)
    );
    // out[1] is 1 iff a < b.
    check_out1_maps_lt: assert property (
        @(posedge CLK) out[1] == (a < b)
    );
    // out never takes invalid value 2'b11.
    check_out_not_11: assert property (
        @(posedge CLK) out != 2'b11
    );
    // If a > b then out must be 2'b01.
    check_gt_implies_out01: assert property (
        @(posedge CLK) (a > b) |-> (out == 2'b01)
    );
    // If a < b then out must be 2'b10.
    check_lt_implies_out10: assert property (
        @(posedge CLK) (a < b) |-> (out == 2'b10)
    );
    // If a == b then out must be 2'b00.
    check_eq_implies_out00: assert property (
        @(posedge CLK) (a == b) |-> (out == 2'b00)
    );
    // If out is 2'b01 then a must be > b.
    check_out01_implies_gt: assert property (
        @(posedge CLK) (out == 2'b01) |-> (a > b)
    );
    // If out is 2'b10 then a must be < b.
    check_out10_implies_lt: assert property (
        @(posedge CLK) (out == 2'b10) |-> (a < b)
    );
    // If out is 2'b00 then a must equal b.
    check_out00_implies_eq: assert property (
        @(posedge CLK) (out == 2'b00) |-> (a == b)
    );
endmodule

rtl:
module priority_encoder (
    input [7:0] D,
    output [2:0] EN
);

reg [2:0] EN_reg;

always @(*) begin
    EN_reg[2] = (D[7] && !D[6] && !D[5]);
    EN_reg[1] = (!D[7] && D[6] && !D[5]);
    EN_reg[0] = (!D[7] && !D[6] && D[5]);
end

assign EN = EN_reg;

endmodule

sva:
module priority_encoder_sva (
    input logic clk,
    input logic [7:0] D,
    input logic [2:0] EN
);
    // EN matches the combinational function of D[7:5].
    check_function_equivalence: assert property (
        @(posedge clk) EN == { (D[7] && !D[6] && !D[5]),
                               (!D[7] && D[6] && !D[5]),
                               (!D[7] && !D[6] && D[5]) }
    );

    // EN is one-hot or zero at all times.
    check_en_is_onehot0: assert property (
        @(posedge clk) $onehot0(EN)
    );

    // If none of D[7:5] are HIGH, EN must be 000.
    check_none_high_results_zero: assert property (
        @(posedge clk) (D[7:5] == 3'b000) |-> (EN == 3'b000)
    );

    // If exactly one of D[7:5] is HIGH, EN mirrors D[7:5].
    check_onehot_maps_directly: assert property (
        @(posedge clk) $onehot(D[7:5]) |-> (EN == D[7:5])
    );

    // If two or more of D[7:5] are HIGH, EN must be 000.
    check_multi_high_results_zero: assert property (
        @(posedge clk) ((D[7] & D[6]) | (D[7] & D[5]) | (D[6] & D[5])) |-> (EN == 3'b000)
    );

    // EN[2]==1 implies D7=1, D6=0, D5=0.
    check_en2_implies_d7_only: assert property (
        @(posedge clk) EN[2] |-> (D[7] && !D[6] && !D[5])
    );

    // EN[1]==1 implies D6=1, D7=0, D5=0.
    check_en1_implies_d6_only: assert property (
        @(posedge clk) EN[1] |-> (!D[7] && D[6] && !D[5])
    );

    // EN[0]==1 implies D5=1, D7=0, D6=0.
    check_en0_implies_d5_only: assert property (
        @(posedge clk) EN[0] |-> (!D[7] && !D[6] && D[5])
    );
endmodule

rtl:
module MUX4to1_using_2to1 (D0, D1, D2, D3, S0, S1, Y);
input D0, D1, D2, D3, S0, S1;
output Y;

wire w1, w2, w3;

// first stage of multiplexing
mux_2to1 m1 (.A(D0), .B(D1), .S(S0), .Y(w1));
mux_2to1 m2 (.A(D2), .B(D3), .S(S0), .Y(w2));

// second stage of multiplexing
mux_2to1 m3 (.A(w1), .B(w2), .S(S1), .Y(w3));

assign Y = w3;

endmodule

module mux_2to1 (A, B, S, Y);
input A, B, S;
output Y;

assign Y = (S == 1'b0) ? A : B;

endmodule

sva:
module MUX4to1_using_2to1_sva (
    input logic D0,
    input logic D1,
    input logic D2,
    input logic D3,
    input logic S0,
    input logic S1,
    input logic Y
);
    // Y implements 4:1 mux function built from nested 2:1 muxes.
    check_mux_function_direct: assert property (
        @(posedge D0 or negedge D0 or posedge D1 or negedge D1 or posedge D2 or negedge D2 or posedge D3 or negedge D3 or posedge S0 or negedge S0 or posedge S1 or negedge S1)
            Y == ((S1 == 1'b0) ? ((S0 == 1'b0) ? D0 : D1) : ((S0 == 1'b0) ? D2 : D3))
    );

    // When S1=0 and S0=0, output equals D0.
    check_decode_s1_0_s0_0: assert property (
        @(posedge D0 or negedge D0 or posedge D1 or negedge D1 or posedge D2 or negedge D2 or posedge D3 or negedge D3 or posedge S0 or negedge S0 or posedge S1 or negedge S1)
            (!S1 && !S0) |-> (Y == D0)
    );

    // When S1=0 and S0=1, output equals D1.
    check_decode_s1_0_s0_1: assert property (
        @(posedge D0 or negedge D0 or posedge D1 or negedge D1 or posedge D2 or negedge D2 or posedge D3 or negedge D3 or posedge S0 or negedge S0 or posedge S1 or negedge S1)
            (!S1 && S0) |-> (Y == D1)
    );

    // When S1=1 and S0=0, output equals D2.
    check_decode_s1_1_s0_0: assert property (
        @(posedge D0 or negedge D0 or posedge D1 or negedge D1 or posedge D2 or negedge D2 or posedge D3 or negedge D3 or posedge S0 or negedge S0 or posedge S1 or negedge S1)
            (S1 && !S0) |-> (Y == D2)
    );

    // When S1=1 and S0=1, output equals D3.
    check_decode_s1_1_s0_1: assert property (
        @(posedge D0 or negedge D0 or posedge D1 or negedge D1 or posedge D2 or negedge D2 or posedge D3 or negedge D3 or posedge S0 or negedge S0 or posedge S1 or negedge S1)
            (S1 && S0) |-> (Y == D3)
    );

    // If D0==D1 and S1=0, S0 has no effect and Y equals D0.
    check_group0_data_equality_bypasses_s0: assert property (
        @(posedge D0 or negedge D0 or posedge D1 or negedge D1 or posedge D2 or negedge D2 or posedge D3 or negedge D3 or posedge S0 or negedge S0 or posedge S1 or negedge S1)
            (!S1 && (D0 == D1)) |-> (Y == D0)
    );

    // If D2==D3 and S1=1, S0 has no effect and Y equals D2.
    check_group1_data_equality_bypasses_s0: assert property (
        @(posedge D0 or negedge D0 or posedge D1 or negedge D1 or posedge D2 or negedge D2 or posedge D3 or negedge D3 or posedge S0 or negedge S0 or posedge S1 or negedge S1)
            (S1 && (D2 == D3)) |-> (Y == D2)
    );

    // If all data inputs are equal, Y equals that common value.
    check_all_data_equal_constant_output: assert property (
        @(posedge D0 or negedge D0 or posedge D1 or negedge D1 or posedge D2 or negedge D2 or posedge D3 or negedge D3 or posedge S0 or negedge S0 or posedge S1 or negedge S1)
            ((D0 == D1) && (D1 == D2) && (D2 == D3)) |-> (Y == D0)
    );

    // With S0=0, Y selects between D0 and D2 by S1.
    check_s0_low_path: assert property (
        @(posedge D0 or negedge D0 or posedge D1 or negedge D1 or posedge D2 or negedge D2 or posedge D3 or negedge D3 or posedge S0 or negedge S0 or posedge S1 or negedge S1)
            (!S0) |-> (Y == ((S1 == 1'b0) ? D0 : D2))
    );

    // With S0=1, Y selects between D1 and D3 by S1.
    check_s0_high_path: assert property (
        @(posedge D0 or negedge D0 or posedge D1 or negedge D1 or posedge D2 or negedge D2 or posedge D3 or negedge D3 or posedge S0 or negedge S0 or posedge S1 or negedge S1)
            (S0) |-> (Y == ((S1 == 1'b0) ? D1 : D3))
    );

    // With S1=0, Y selects between D0 and D1 by S0.
    check_s1_low_path: assert property (
        @(posedge D0 or negedge D0 or posedge D1 or negedge D1 or posedge D2 or negedge D2 or posedge D3 or negedge D3 or posedge S0 or negedge S0 or posedge S1 or negedge S1)
            (!S1) |-> (Y == ((S0 == 1'b0) ? D0 : D1))
    );

    // With S1=1, Y selects between D2 and D3 by S0.
    check_s1_high_path: assert property (
        @(posedge D0 or negedge D0 or posedge D1 or negedge D1 or posedge D2 or negedge D2 or posedge D3 or negedge D3 or posedge S0 or negedge S0 or posedge S1 or negedge S1)
            (S1) |-> (Y == ((S0 == 1'b0) ? D2 : D3))
    );
endmodule

rtl:
module cpu_mem(rst, clk, cpu_stall, ex_c_rfw, ex_c_wbsource, ex_c_drw,
		ex_alu_r, ex_rfb, ex_rf_waddr, ex_jalra, ex_rt,
		wb_wdata, p_c_rfw, p_c_wbsource, p_alu_r, dmem_data,
		p_rf_waddr, p_jalra, dmem_addr, dmem_drw, dmem_in,
		p_dout);
	input 		rst, clk, cpu_stall;
	input 		ex_c_rfw;
	input [1:0]	ex_c_wbsource;
	input [1:0]	ex_c_drw;
	input [31:0]	ex_alu_r;
	input [31:0]	ex_rfb;
	input [4:0]	ex_rf_waddr;
	input [31:0]	ex_jalra;
	input [4:0]	ex_rt;
	input [31:0]	wb_wdata;
	output reg 	p_c_rfw;
	output reg [1:0] p_c_wbsource;
	output reg [31:0] p_alu_r;
	output [31:0] dmem_data;
	output reg [4:0] p_rf_waddr;
	output reg [31:0] p_jalra;
	output [31:0] dmem_addr;
	output [1:0] dmem_drw;
	input [31:0]	dmem_in;
	output reg [31:0] p_dout;

	assign dmem_addr = ex_alu_r;
	assign dmem_drw  = ex_c_drw;


	wire forward = p_c_rfw & (ex_rt == p_rf_waddr) & (p_rf_waddr != 0);
	assign dmem_data = forward ? wb_wdata : ex_rfb;

	always @(posedge clk) begin
		if (!cpu_stall) begin
		if (rst) begin
			p_c_rfw <= 0;
			p_c_wbsource <= 0;
			p_alu_r <= 0;
			p_rf_waddr <= 0;
			p_jalra <= 0;
			p_dout <= 0;
		end else begin
			p_c_rfw <= ex_c_rfw;
			p_c_wbsource <= ex_c_wbsource;
			p_alu_r <= ex_alu_r;
			p_rf_waddr <= ex_rf_waddr;
			p_jalra <= ex_jalra;
			p_dout <= dmem_in;
		end


		end
	end

endmodule

sva:
module cpu_mem_sva (
    input logic rst,
    input logic clk,
    input logic cpu_stall,
    input logic ex_c_rfw,
    input logic [1:0] ex_c_wbsource,
    input logic [1:0] ex_c_drw,
    input logic [31:0] ex_alu_r,
    input logic [31:0] ex_rfb,
    input logic [4:0] ex_rf_waddr,
    input logic [31:0] ex_jalra,
    input logic [4:0] ex_rt,
    input logic [31:0] wb_wdata,
    input logic p_c_rfw,
    input logic [1:0] p_c_wbsource,
    input logic [31:0] p_alu_r,
    input logic [31:0] dmem_data,
    input logic [4:0] p_rf_waddr,
    input logic [31:0] p_jalra,
    input logic [31:0] dmem_addr,
    input logic [1:0] dmem_drw,
    input logic [31:0] dmem_in,
    input logic [31:0] p_dout
);

    ///// Reset and stall behavior /////
    // On !cpu_stall and rst, all pipeline registers clear to 0 on next cycle.
    reset_clears_regs: assert property (
        @(posedge clk) (!cpu_stall && rst) |=> (p_c_rfw == 1'b0) && (p_c_wbsource == 2'b00) &&
                                           (p_alu_r == 32'b0) && (p_rf_waddr == 5'b0) &&
                                           (p_jalra == 32'b0) && (p_dout == 32'b0)
    );

    // When cpu_stall is asserted, all pipeline registers hold their value.
    hold_regs_on_stall: assert property (
        @(posedge clk) disable iff (rst) cpu_stall |=> $stable({p_c_rfw, p_c_wbsource, p_alu_r, p_rf_waddr, p_jalra, p_dout})
    );

    ///// Register captures when enabled (!cpu_stall and !rst) /////
    // p_c_rfw captures ex_c_rfw on next cycle.
    capture_p_c_rfw: assert property (
        @(posedge clk) disable iff (rst) (!cpu_stall) |=> (p_c_rfw == $past(ex_c_rfw))
    );

    // p_c_wbsource captures ex_c_wbsource on next cycle.
    capture_p_c_wbsource: assert property (
        @(posedge clk) disable iff (rst) (!cpu_stall) |=> (p_c_wbsource == $past(ex_c_wbsource))
    );

    // p_alu_r captures ex_alu_r on next cycle.
    capture_p_alu_r: assert property (
        @(posedge clk) disable iff (rst) (!cpu_stall) |=> (p_alu_r == $past(ex_alu_r))
    );

    // p_rf_waddr captures ex_rf_waddr on next cycle.
    capture_p_rf_waddr: assert property (
        @(posedge clk) disable iff (rst) (!cpu_stall) |=> (p_rf_waddr == $past(ex_rf_waddr))
    );

    // p_jalra captures ex_jalra on next cycle.
    capture_p_jalra: assert property (
        @(posedge clk) disable iff (rst) (!cpu_stall) |=> (p_jalra == $past(ex_jalra))
    );

    // p_dout captures dmem_in on next cycle.
    capture_p_dout: assert property (
        @(posedge clk) disable iff (rst) (!cpu_stall) |=> (p_dout == $past(dmem_in))
    );

    ///// Combinational pass-throughs /////
    // dmem_addr is a pure pass-through of ex_alu_r.
    comb_dmem_addr_passthrough: assert property (
        @(posedge clk) disable iff (rst) dmem_addr == ex_alu_r
    );

    // dmem_drw is a pure pass-through of ex_c_drw.
    comb_dmem_drw_passthrough: assert property (
        @(posedge clk) disable iff (rst) dmem_drw == ex_c_drw
    );

    // dmem_data selects wb_wdata when forward, else ex_rfb.
    comb_dmem_data_forward_mux: assert property (
        @(posedge clk) disable iff (rst)
            dmem_data == ((p_c_rfw && (ex_rt == p_rf_waddr) && (p_rf_waddr != 5'd0)) ? wb_wdata : ex_rfb)
    );

endmodule

rtl:
module or_gate(
    input a,
    input b,
    output reg out
);

always @(*) begin
    out = a | b;
end

endmodule
module final_output(
    input a,
    input b,
    output reg [1:0] out
);

always @(*) begin
    out[0] = a | b;
    out[1] = a | b;
end

endmodule
module top_module(
    input a,
    input b,
    output out
);

wire [1:0] internal_out;
or_gate or_inst(
    .a(a),
    .b(b),
    .out(internal_out[0])
);

final_output final_inst(
    .a(a),
    .b(b),
    .out({out, internal_out[0]})
);

endmodule

sva:
module top_module_sva (
    input logic a,
    input logic b,
    input logic out,
    input logic [1:0] internal_out
);
    // Top-level out equals a|b on any input edge.
    check_top_out_is_or_any_edge: assert property (
        @(posedge a or negedge a or posedge b or negedge b) out == (a | b)
    );

    // Internal bit0 equals a|b on any input edge.
    check_internal_out0_is_or_any_edge: assert property (
        @(posedge a or negedge a or posedge b or negedge b) internal_out[0] == (a | b)
    );

    // Top-level out matches internal_out[0] on any input edge.
    check_out_matches_internal0_any_edge: assert property (
        @(posedge a or negedge a or posedge b or negedge b) out == internal_out[0]
    );

    // If both inputs are 0, top-level out must be 0.
    check_out_zero_when_both_zero: assert property (
        @(posedge a or negedge a or posedge b or negedge b) (!a && !b) |-> (out == 1'b0)
    );

    // If a is 1, top-level out must be 1.
    check_out_one_when_a_one: assert property (
        @(posedge a or negedge a or posedge b or negedge b) a |-> (out == 1'b1)
    );

    // If b is 1, top-level out must be 1.
    check_out_one_when_b_one: assert property (
        @(posedge a or negedge a or posedge b or negedge b) b |-> (out == 1'b1)
    );

    // If top-level out is 0, both inputs must be 0.
    check_inputs_zero_when_out_zero: assert property (
        @(posedge a or negedge a or posedge b or negedge b) (out == 1'b0) |-> (!a && !b)
    );

    // If top-level out is 1, at least one input must be 1.
    check_either_input_one_when_out_one: assert property (
        @(posedge a or negedge a or posedge b or negedge b) (out == 1'b1) |-> (a || b)
    );

    // If internal_out[0] is 0, both inputs must be 0.
    check_inputs_zero_when_internal0_zero: assert property (
        @(posedge a or negedge a or posedge b or negedge b) (internal_out[0] == 1'b0) |-> (!a && !b)
    );

    // If internal_out[0] is 1, at least one input must be 1.
    check_either_input_one_when_internal0_one: assert property (
        @(posedge a or negedge a or posedge b or negedge b) (internal_out[0] == 1'b1) |-> (a || b)
    );
endmodule

rtl:
module simple_logic (
    input A,
    output Y
);

    assign Y = ~A;

endmodule

sva:
module simple_logic_sva (
    input logic CLK,
    input logic RESETn,
    input logic A,
    input logic Y
);
    // Output is always the bitwise inverse of input.
    check_inversion: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y === ~A)
    );

    // If A is stable this cycle, Y must also be stable.
    check_stability_propagation: assert property (
        @(posedge CLK) disable iff (!RESETn) $stable(A) |-> $stable(Y)
    );

    // If Y changes between cycles, A must have changed.
    check_change_dependency: assert property (
        @(posedge CLK) disable iff (!RESETn) $changed(Y) |-> $changed(A)
    );

    // A rising edge implies Y falls (due to inversion).
    check_edge_rise: assert property (
        @(posedge CLK) disable iff (!RESETn) $rose(A) |-> $fell(Y)
    );

    // A falling edge implies Y rises (due to inversion).
    check_edge_fall: assert property (
        @(posedge CLK) disable iff (!RESETn) $fell(A) |-> $rose(Y)
    );
endmodule

rtl:
module BitShifting (
  input [31:0] a,
  input [4:0] n,
  output [31:0] b
);

  assign b = (n > 0) ? ((n > 31) ? 0 : ((n > 0) ? (a << n) : (a >>> -n))) : a;

endmodule

sva:
module BitShifting_sva (
    input logic CLK,
    input logic [31:0] a,
    input logic [4:0] n,
    input logic [31:0] b
);
    // When n==0, output passes through input a.
    check_passthrough_when_n_zero: assert property (
        @(posedge CLK) (n == 5'd0) |-> (b == a)
    );

    // When n>0, output equals a left-shifted by n.
    check_shift_when_n_positive: assert property (
        @(posedge CLK) (n > 5'd0) |-> (b == (a << n))
    );

    // When n>0, the lower n bits of b are zero after left shift.
    check_lower_bits_zero_after_shift: assert property (
        @(posedge CLK) (n > 5'd0) |-> ((b & (((32'h1 << n) - 32'h1))) == 32'h0)
    );

    // When n>0, bit b[n] equals a[0] after left shift.
    check_bit_n_equals_a0: assert property (
        @(posedge CLK) (n > 5'd0) |-> (b[n] == a[0])
    );

    // When n>0, MSB of b equals a[31-n].
    check_msb_matches_source_bit: assert property (
        @(posedge CLK) (n > 5'd0) |-> (b[31] == a[31 - n])
    );

    // If n hypothetically exceeded 31, b would be forced to zero per RTL branch.
    check_large_n_forces_zero: assert property (
        @(posedge CLK) (n > 5'd31) |-> (b == 32'h0)
    );

    // If a is zero, b is zero regardless of n.
    check_zero_input_produces_zero_output: assert property (
        @(posedge CLK) (a == 32'h0) |-> (b == 32'h0)
    );

    // If a is stable and n increments by 1 (and was <31), b shifts left by 1 from prior b.
    check_incremental_n_shifts_output: assert property (
        @(posedge CLK) ($past(a) === a) && ($past(n) < 5'd31) && (n == ($past(n) + 5'd1)) |-> (b == ($past(b) << 1))
    );

    // If a and n are stable, b remains stable (pure combinational function).
    check_stable_inputs_keep_output_stable: assert property (
        @(posedge CLK) $stable(a) && $stable(n) |-> $stable(b)
    );

    // For n==31, b equals {a[0], 31'b0}.
    check_shift_by_31_behavior: assert property (
        @(posedge CLK) (n == 5'd31) |-> (b == {a[0], 31'b0})
    );
endmodule

module interrupt_controller_sva (
    input logic clk,
    input logic clk7_en,
    input logic wr,
    input logic reset,
    input logic icrs,
    input logic ta,
    input logic tb,
    input logic alrm,
    input logic flag,
    input logic ser,
    input logic [7:0] data_in,
    input logic [7:0] data_out,
    input logic irq,
    // Internal DUT signals (for binding)
    input logic [4:0] icr,
    input logic [4:0] icrmask
);
    ///// Combinational outputs /////
    // irq equals masked-OR of icr bits.
    check_irq_definition: assert property (
        @(posedge clk) disable iff (reset)
        irq == ((icrmask[0] & icr[0])
              | (icrmask[1] & icr[1])
              | (icrmask[2] & icr[2])
              | (icrmask[3] & icr[3])
              | (icrmask[4] & icr[4]))
    );

    // When reading ICR (icrs && !wr), data_out is {irq,2'b00,icr}.
    check_data_out_on_read: assert property (
        @(posedge clk) disable iff (reset)
        (icrs && !wr) |-> (data_out == {irq, 2'b00, icr})
    );

    // When not reading ICR, data_out is 8'h00.
    check_data_out_when_not_read: assert property (
        @(posedge clk) disable iff (reset)
        !(icrs && !wr) |-> (data_out == 8'h00)
    );

    ///// Synchronous reset behavior (gated by clk7_en) /////
    // When clk7_en and reset are high, icrmask clears next cycle.
    reset_clears_icrmask: assert property (
        @(posedge clk)
        (clk7_en && reset) |=> (icrmask == 5'b0_00000)
    );

    // When clk7_en and reset are high, icr clears next cycle.
    reset_clears_icr: assert property (
        @(posedge clk)
        (clk7_en && reset) |=> (icr == 5'b0_00000)
    );

    ///// icrmask write semantics /////
    // On write with data_in[7]==1, set selected icrmask bits next cycle.
    write_sets_mask_bits: assert property (
        @(posedge clk) disable iff (reset)
        (clk7_en && icrs && wr && (data_in[7] == 1'b1)) |=> (icrmask == ($past(icrmask) | $past(data_in[4:0])))
    );

    // On write with data_in[7]==0, clear selected icrmask bits next cycle.
    write_clears_mask_bits: assert property (
        @(posedge clk) disable iff (reset)
        (clk7_en && icrs && wr && (data_in[7] == 1'b0)) |=> (icrmask == ($past(icrmask) & (~$past(data_in[4:0]))))
    );

    // Without a qualifying write, icrmask holds value on next cycle.
    icrmask_holds_without_write: assert property (
        @(posedge clk) disable iff (reset)
        (clk7_en && !(icrs && wr)) |=> (icrmask == $past(icrmask))
    );

    ///// clk7_en gating /////
    // When clk7_en is low, icr and icrmask hold.
    regs_hold_when_clk7_en_low: assert property (
        @(posedge clk) disable iff (reset)
        (!clk7_en) |=> (icr == $past(icr)) && (icrmask == $past(icrmask))
    );

    ///// icr update semantics /////
    // On read (icrs && !wr), icr captures current input sources next cycle.
    icr_captures_inputs_on_read: assert property (
        @(posedge clk) disable iff (reset)
        (clk7_en && icrs && !wr) |=> (icr[0] == $past(ta))
                                && (icr[1] == $past(tb))
                                && (icr[2] == $past(alrm))
                                && (icr[3] == $past(ser))
                                && (icr[4] == $past(flag))
    );

    // When not reading, icr bits OR-latch with their respective sources next cycle.
    icr_or_latches_when_not_read: assert property (
        @(posedge clk) disable iff (reset)
        (clk7_en && !(icrs && !wr)) |=> (icr[0] == ($past(icr[0]) | $past(ta)))
                                   && (icr[1] == ($past(icr[1]) | $past(tb)))
                                   && (icr[2] == ($past(icr[2]) | $past(alrm)))
                                   && (icr[3] == ($past(icr[3]) | $past(ser)))
                                   && (icr[4] == ($past(icr[4]) | $past(flag)))
    );

endmodule

rtl:
module FA_17 ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  wire   n1, n2, n3, n4;

  xor ( n1, A, B );
  xor ( S, n1, Ci );
  and ( n2, A, B );
  and ( n3, n1, Ci );
  or  ( Co, n2, n3 );
endmodule

sva:
module FA_17_sva (
    input logic CLK,
    input logic RESETn,
    input logic A,
    input logic B,
    input logic Ci,
    input logic S,
    input logic Co
);
    // Analysis: No clock/reset in RTL; purely combinational full adder: S=A^B^Ci, Co=(A&B)|((A^B)&Ci). Assertions sampled on CLK, gated by RESETn.

    // Sum equals three-input XOR of A, B, Ci.
    check_sum_is_xor3: assert property (
        @(posedge CLK) disable iff (!RESETn) S == (A ^ B ^ Ci)
    );

    // Carry equals (A&B) | ((A^B)&Ci) as implemented.
    check_carry_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) Co == ((A & B) | ((A ^ B) & Ci))
    );

    // Carry equals majority-of-three equivalent form.
    check_carry_majority_equiv: assert property (
        @(posedge CLK) disable iff (!RESETn) Co == ((A & B) | (A & Ci) | (B & Ci))
    );

    // With Ci=0, sum reduces to A^B and carry to A&B.
    check_ci0_case: assert property (
        @(posedge CLK) disable iff (!RESETn) (Ci == 1'b0) |-> ((S == (A ^ B)) && (Co == (A & B)))
    );

    // With Ci=1, sum is XNOR of A and B; carry is A|B.
    check_ci1_case: assert property (
        @(posedge CLK) disable iff (!RESETn) (Ci == 1'b1) |-> ((S == !(A ^ B)) && (Co == (A | B)))
    );

    // When A equals B, sum equals Ci; carry equals A&B.
    check_a_eq_b_case: assert property (
        @(posedge CLK) disable iff (!RESETn) (A == B) |-> ((S == Ci) && (Co == (A & B)))
    );

    // When A differs from B, sum is ~Ci and carry equals Ci.
    check_a_xor_b_case: assert property (
        @(posedge CLK) disable iff (!RESETn) (A ^ B) |-> ((S == !Ci) && (Co == Ci))
    );

    // If both A and B are 1, carry must be 1 and sum equals Ci.
    check_ab_both1_implies_carry: assert property (
        @(posedge CLK) disable iff (!RESETn) (A & B) |-> ((Co == 1'b1) && (S == Ci))
    );

    // If Ci=1 and exactly one of A,B is 1, carry must be 1.
    check_ci_and_axorb_implies_carry: assert property (
        @(posedge CLK) disable iff (!RESETn) (Ci & (A ^ B)) |-> (Co == 1'b1)
    );

    // All inputs zero produce S=0 and Co=0.
    check_all_zero_case: assert property (
        @(posedge CLK) disable iff (!RESETn) (!(A | B | Ci)) |-> ((S == 1'b0) && (Co == 1'b0))
    );

    // All inputs one produce S=1 and Co=1.
    check_all_one_case: assert property (
        @(posedge CLK) disable iff (!RESETn) (A & B & Ci) |-> ((S == 1'b1) && (Co == 1'b1))
    );
endmodule

rtl:
module sky130_fd_sc_ls__nand4b (
    Y  ,
    A_N,
    B  ,
    C  ,
    D
);

    output Y  ;
    input  A_N;
    input  B  ;
    input  C  ;
    input  D  ;

    wire not0_out   ;
    wire nand0_out_Y;

    not  not0  (not0_out   , A_N              );
    nand nand0 (nand0_out_Y, D, C, B, not0_out);
    buf  buf0  (Y          , nand0_out_Y      );

endmodule

sva:
module sky130_fd_sc_ls__nand4b_sva (
    input logic CLK,
    input logic Y,
    input logic A_N,
    input logic B,
    input logic C,
    input logic D
);
    // Functional equivalence to NAND4 with inverted A_N.
    check_func_nand4b: assert property (
        @(posedge CLK) Y == ~(D & C & B & ~A_N)
    );

    // Equivalent OR-of-literals form.
    check_func_or_form: assert property (
        @(posedge CLK) Y == (A_N | ~B | ~C | ~D)
    );

    // A_N high forces Y high.
    check_an_high_forces_y_high: assert property (
        @(posedge CLK) A_N |-> (Y == 1'b1)
    );

    // B low forces Y high.
    check_b_low_forces_y_high: assert property (
        @(posedge CLK) (B == 1'b0) |-> (Y == 1'b1)
    );

    // C low forces Y high.
    check_c_low_forces_y_high: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Y == 1'b1)
    );

    // D low forces Y high.
    check_d_low_forces_y_high: assert property (
        @(posedge CLK) (D == 1'b0) |-> (Y == 1'b1)
    );

    // Y low only when A_N low and B,C,D high.
    check_y_low_only_when_all_ones: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (A_N == 1'b0 && B == 1'b1 && C == 1'b1 && D == 1'b1)
    );

    // Y changes only when at least one input changes.
    check_y_changes_only_when_inputs_change: assert property (
        @(posedge CLK) $changed(Y) |-> $changed({A_N,B,C,D})
    );

    // If inputs are stable, Y remains stable.
    check_y_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable({A_N,B,C,D}) |-> $stable(Y)
    );

    // Rising A_N forces Y high.
    check_an_rise_forces_y_high: assert property (
        @(posedge CLK) $rose(A_N) |-> (Y == 1'b1)
    );

    // Falling B forces Y high.
    check_b_fall_forces_y_high: assert property (
        @(posedge CLK) $fell(B) |-> (Y == 1'b1)
    );

    // Falling C forces Y high.
    check_c_fall_forces_y_high: assert property (
        @(posedge CLK) $fell(C) |-> (Y == 1'b1)
    );

    // Falling D forces Y high.
    check_d_fall_forces_y_high: assert property (
        @(posedge CLK) $fell(D) |-> (Y == 1'b1)
    );

    // Falling A_N with B,C,D high forces Y low.
    check_an_fall_with_others_one_forces_y_low: assert property (
        @(posedge CLK) ($fell(A_N) && B && C && D) |-> (Y == 1'b0)
    );

    // Rising B with A_N low and C,D high forces Y low.
    check_b_rise_with_others_one_forces_y_low: assert property (
        @(posedge CLK) ($rose(B) && (A_N == 1'b0) && C && D) |-> (Y == 1'b0)
    );

    // Rising C with A_N low and B,D high forces Y low.
    check_c_rise_with_others_one_forces_y_low: assert property (
        @(posedge CLK) ($rose(C) && (A_N == 1'b0) && B && D) |-> (Y == 1'b0)
    );

    // Rising D with A_N low and B,C high forces Y low.
    check_d_rise_with_others_one_forces_y_low: assert property (
        @(posedge CLK) ($rose(D) && (A_N == 1'b0) && B && C) |-> (Y == 1'b0)
    );
endmodule

rtl:
module mux12_v10(
  input [11:0] I,
  input [1:0] select,
  output reg O
);

  always @(*) begin
    case (select)
      2'b00: O = I[0];
      2'b01: O = I[1];
      2'b10: O = I[2];
      2'b11: O = I[3];
    endcase
    case (select)
      2'b00: O = I[4];
      2'b01: O = I[5];
      2'b10: O = I[6];
      2'b11: O = I[7];
    endcase
    case (select)
      2'b00: O = I[8];
      2'b01: O = I[9];
      2'b10: O = I[10];
      2'b11: O = I[11];
    endcase
  end

endmodule

sva:
module mux12_v10_sva (
    input  logic        CLK,
    input  logic [11:0] I,
    input  logic [1:0]  select,
    input  logic        O
);
    // O equals the final case mapping (I[8..11] selected by select).
    check_func_equiv_to_last_case: assert property (
        @(posedge CLK) O == (select == 2'b00 ? I[8] :
                             select == 2'b01 ? I[9] :
                             select == 2'b10 ? I[10] : I[11])
    );

    // When select==00, O equals I[8].
    check_map_sel_00: assert property (
        @(posedge CLK) (select == 2'b00) |-> (O == I[8])
    );
    // When select==01, O equals I[9].
    check_map_sel_01: assert property (
        @(posedge CLK) (select == 2'b01) |-> (O == I[9])
    );
    // When select==10, O equals I[10].
    check_map_sel_10: assert property (
        @(posedge CLK) (select == 2'b10) |-> (O == I[10])
    );
    // When select==11, O equals I[11].
    check_map_sel_11: assert property (
        @(posedge CLK) (select == 2'b11) |-> (O == I[11])
    );

    // If select and I[8..11] are stable, O must be stable.
    check_stable_when_relevant_stable: assert property (
        @(posedge CLK) (!$initstate && $stable(select) && $stable(I[8]) && $stable(I[9]) && $stable(I[10]) && $stable(I[11]))
                       |-> $stable(O)
    );

    // If O changes, then select or one of I[8..11] changed.
    check_output_change_has_cause: assert property (
        @(posedge CLK) (!$initstate && !$stable(O))
                       |-> (!$stable(select) || !$stable(I[8]) || !$stable(I[9]) || !$stable(I[10]) || !$stable(I[11]))
    );

    // With select stable at 00, O changes when I[8] changes.
    check_follow_sel00_input_changes: assert property (
        @(posedge CLK) (!$initstate && $stable(select) && (select == 2'b00) && !$stable(I[8]))
                       |-> (!$stable(O))
    );
    // With select stable at 01, O changes when I[9] changes.
    check_follow_sel01_input_changes: assert property (
        @(posedge CLK) (!$initstate && $stable(select) && (select == 2'b01) && !$stable(I[9]))
                       |-> (!$stable(O))
    );
    // With select stable at 10, O changes when I[10] changes.
    check_follow_sel10_input_changes: assert property (
        @(posedge CLK) (!$initstate && $stable(select) && (select == 2'b10) && !$stable(I[10]))
                       |-> (!$stable(O))
    );
    // With select stable at 11, O changes when I[11] changes.
    check_follow_sel11_input_changes: assert property (
        @(posedge CLK) (!$initstate && $stable(select) && (select == 2'b11) && !$stable(I[11]))
                       |-> (!$stable(O))
    );
endmodule

rtl:
module trigterm_range_bit (
  input  wire sti_data,
  input  wire clk,
  input  wire wrenb,
  input  wire din,
  output wire dout,
  input  wire cin,
  output wire cout,
  output wire hit
);

wire       hit_internal;
reg [15:0] mem;

always @(posedge clk)
if (wrenb) mem <= {mem, din};

assign hit_internal  = mem[{3'b000, sti_data}];
assign dout = mem[15];

assign hit = hit_internal;
assign cout = hit_internal ? cin : din;

endmodule

sva:
module trigterm_range_bit_sva (
    input logic sti_data,
    input logic clk,
    input logic wrenb,
    input logic din,
    input logic dout,
    input logic cin,
    input logic cout,
    input logic hit,
    // Internal signal from RTL
    input logic [15:0] mem
);

    ///// Sequential memory behavior /////
    // When wrenb is HIGH, mem shifts left and loads din into bit 0 on next cycle.
    check_mem_shift_on_write: assert property (
        @(posedge clk) disable iff ($initstate)
            wrenb |=> (mem == { $past(mem[14:0]), $past(din) })
    );

    // When wrenb is LOW, mem holds its previous value.
    check_mem_hold_without_write: assert property (
        @(posedge clk) disable iff ($initstate)
            !wrenb |=> (mem == $past(mem))
    );

    ///// Output tap and update timing /////
    // dout reflects the MSB of mem.
    check_dout_is_msb_of_mem: assert property (
        @(posedge clk) disable iff ($initstate)
            dout == mem[15]
    );

    // On a write, next-cycle dout equals previous mem[14].
    check_dout_updates_on_write: assert property (
        @(posedge clk) disable iff ($initstate)
            wrenb |=> (dout == $past(mem[14]))
    );

    // Without write, dout holds its previous value.
    check_dout_stable_when_no_write: assert property (
        @(posedge clk) disable iff ($initstate)
            !wrenb |=> (dout == $past(dout))
    );

    ///// Combinational selects /////
    // hit equals the selected mem bit indexed by {3'b000, sti_data}.
    check_hit_equals_selected_mem_bit: assert property (
        @(posedge clk) disable iff ($initstate)
            hit == mem[{3'b000, sti_data}]
    );

    // cout implements mux: if hit is 1 choose cin, else choose din.
    check_cout_mux_function: assert property (
        @(posedge clk) disable iff ($initstate)
            cout == (hit ? cin : din)
    );

    // cout must always equal one of its inputs.
    check_cout_is_one_of_inputs: assert property (
        @(posedge clk) disable iff ($initstate)
            (cout == cin) || (cout == din)
    );

    // If cout differs from din, hit must be HIGH.
    check_cout_ne_din_implies_hit: assert property (
        @(posedge clk) disable iff ($initstate)
            (cout != din) |-> hit
    );

    // If cout differs from cin, hit must be LOW.
    check_cout_ne_cin_implies_not_hit: assert property (
        @(posedge clk) disable iff ($initstate)
            (cout != cin) |-> !hit
    );

endmodule

rtl:
module compare_module(
  input [1:0] A,
  input B,
  output Z
);

  assign Z = (A >= B) ? 1 : 0;

endmodule

sva:
module compare_module_sva (
    input logic [1:0] A,
    input logic       B,
    input logic       Z
);
    // No clock or reset in DUT; combinational logic only. Sample on posedges of inputs.

    // Z equals (A >= B) when sampled on B's rising edge.
    check_func_eq_on_B: assert property (
        @(posedge B) Z == (A >= B)
    );

    // Z equals (A >= B) when sampled on A[0]'s rising edge.
    check_func_eq_on_A0: assert property (
        @(posedge A[0]) Z == (A >= B)
    );

    // Z equals (A >= B) when sampled on A[1]'s rising edge.
    check_func_eq_on_A1: assert property (
        @(posedge A[1]) Z == (A >= B)
    );

    // If B is 0, Z must be 1 (A is unsigned and >= 0).
    check_b0_implies_z1: assert property (
        @(posedge A[0]) (B == 1'b0) |-> (Z == 1'b1)
    );

    // If B is 1 and A is 0, Z must be 0 (0 >= 1 is false).
    check_b1_a0_implies_z0: assert property (
        @(posedge A[1]) (B == 1'b1 && A == 2'b00) |-> (Z == 1'b0)
    );

    // If B is 1 and A != 0, Z must be 1 (A in {1,2,3} >= 1).
    check_b1_a_nonzero_implies_z1: assert property (
        @(posedge A[0]) (B == 1'b1 && A != 2'b00) |-> (Z == 1'b1)
    );
endmodule

rtl:
module my_full_adder(
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

    assign S = A ^ B ^ C_in;
    assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

module my_4_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S
);

    wire [3:0] c;

    my_full_adder fa0(.A(A[0]), .B(B[0]), .C_in(1'b0), .S(S[0]), .C_out(c[0]));
    my_full_adder fa1(.A(A[1]), .B(B[1]), .C_in(c[0]), .S(S[1]), .C_out(c[1]));
    my_full_adder fa2(.A(A[2]), .B(B[2]), .C_in(c[1]), .S(S[2]), .C_out(c[2]));
    my_full_adder fa3(.A(A[3]), .B(B[3]), .C_in(c[2]), .S(S[3]), .C_out(c[3]));

endmodule

sva:
module my_4_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S
);
    ///// Functional correctness of 4-bit ripple adder (Cin=0) /////
    // Sum matches 4-bit addition A+B modulo 16.
    check_sum_mod16: assert property (
        @(posedge clk) S == (A + B)
    );

    // LSB is XOR of LSBs (no carry-in).
    check_lsb_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // Bit[1] sum equals A1^B1 with carry from bit[0] = A0&B0.
    check_bit1_sum: assert property (
        @(posedge clk) S[1] == ((A[1] ^ B[1]) ^ (A[0] & B[0]))
    );

    // Bit[2] sum equals A2^B2 with carry c1 = g1 | (p1 & c0).
    check_bit2_sum: assert property (
        @(posedge clk) S[2] == ((A[2] ^ B[2]) ^ ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))
    );

    // Bit[3] sum equals A3^B3 with carry c2 = g2 | (p2 & c1).
    check_bit3_sum: assert property (
        @(posedge clk) S[3] == ((A[3] ^ B[3]) ^ ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))))
    );

    ///// Useful arithmetic identities that must hold /////
    // Adding zero leaves the other operand unchanged (A==0).
    check_identity_A_zero: assert property (
        @(posedge clk) (A == 4'b0000) |-> (S == B)
    );

    // Adding zero leaves the other operand unchanged (B==0).
    check_identity_B_zero: assert property (
        @(posedge clk) (B == 4'b0000) |-> (S == A)
    );

    // When A==B, sum equals A<<1 modulo 16.
    check_double_when_equal: assert property (
        @(posedge clk) (A == B) |-> (S == {A[2:0], 1'b0})
    );

    // Complementary operands sum to all ones (modulo 16).
    check_complement_all_ones: assert property (
        @(posedge clk) (A == ~B) |-> (S == 4'hF)
    );

    // Adding 0xF decrements the other operand modulo 16.
    check_minus_one_when_A_all_ones: assert property (
        @(posedge clk) (A == 4'hF) |-> (S == (B - 4'd1))
    );
endmodule

module Incrementer_sva (
    input logic clk,                // external verification clock (RTL has no clock/reset)
    input logic [7:0] inValue,
    input logic [7:0] outValue
);
    // When input is 0xFF, output wraps to 0x00.
    check_wrap_when_max: assert property (
        @(posedge clk) (inValue == 8'hFF) |-> (outValue == 8'h00)
    );

    // When input is not 0xFF, output equals input + 1.
    check_increment_nonmax: assert property (
        @(posedge clk) (inValue != 8'hFF) |-> (outValue == inValue + 8'd1)
    );

    // Only max input (0xFF) can produce output 0x00.
    check_zero_only_from_max: assert property (
        @(posedge clk) (outValue == 8'h00) |-> (inValue == 8'hFF)
    );

    // Output 0xFF occurs only when input is 0xFE.
    check_out_ff_implies_in_fe: assert property (
        @(posedge clk) (outValue == 8'hFF) |-> (inValue == 8'hFE)
    );

    // Output is never equal to input (no fixed point for +1 mod 256).
    check_out_never_equals_in: assert property (
        @(posedge clk) (outValue != inValue)
    );

    // Output minus input is always 1 mod 256.
    check_modulo_difference_one: assert property (
        @(posedge clk) ((outValue - inValue) == 8'h01)
    );

    // If input is stable across cycles, output is stable as well.
    check_stable_when_input_stable: assert property (
        @(posedge clk) $stable(inValue) |-> $stable(outValue)
    );

    // For non-max input, output is strictly greater than input.
    check_monotonic_nonmax: assert property (
        @(posedge clk) (inValue != 8'hFF) |-> (outValue > inValue)
    );
endmodule

rtl:
module synchronous_counter
(
    input clk,
    input reset,
    output reg [3:0] count
);

always @(posedge clk, posedge reset) begin
    if (reset) begin
        count <= 4'b0000;
    end else if (count == 4'b1001) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module synchronous_counter_sva (
    input logic clk,
    input logic reset,          // active-HIGH asynchronous reset
    input logic [3:0] count
);

    ///// Reset behavior /////
    // While reset is asserted at the clock edge, count must be zero.
    reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

    ///// Counting behavior (clocked) /////
    // If previous cycle was not in reset and count was within 0..9, it remains within 0..9.
    range_closed_no_reset: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(count) <= 4'd9)) |-> (count <= 4'd9)
    );

    // No two consecutive 9s when not in reset across the boundary.
    no_back_to_back_nine: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset)) |-> !($past(count) == 4'd9 && count == 4'd9)
    );

    // If count is 0 when not in reset, the previous value must have been 9.
    zero_implies_prev_nine: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && (count == 4'd0)) |-> ($past(count) == 4'd9)
    );

    // From a previous value 0..8 without reset, next is prev+1 or 1 (if async reset occurred mid-cycle).
    prev_lt9_inc_or_one: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(count) <= 4'd8)) |-> ((count == $past(count) + 1) || (count == 4'd1))
    );

    // From a previous value 9 without reset, next is 0 (wrap) or 1 (if async reset occurred mid-cycle).
    prev_nine_zero_or_one: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(count) == 4'd9)) |-> ((count == 4'd0) || (count == 4'd1))
    );

    // On reset deassertion (1->0 at this clock), the counter advances to 1.
    count_one_after_reset_release: assert property (
        @(posedge clk) disable iff (reset)
            ($past(reset) && !reset) |-> (count == 4'd1)
    );

    // If the count decreases across cycles without reset, it can only drop to 0 or 1.
    decrease_only_to_zero_or_one: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && (count < $past(count))) |-> ((count == 4'd0) || (count == 4'd1))
    );

    // When count is 9 (not in reset), the next cycle must be 0 or 1.
    next_after_nine_is_zero_or_one: assert property (
        @(posedge clk) disable iff (reset)
            (count == 4'd9) |-> ##1 (count == 4'd0 || count == 4'd1)
    );

    // From previous 0 with no reset, next value is 1.
    prev_zero_advances_to_one: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(count) == 4'd0)) |-> (count == 4'd1)
    );

endmodule

module decoder_4to16_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [15:0] Y
);
    // Output equals one-hot value of 1 shifted by A.
    check_decode_equivalence: assert property (
        @(posedge clk) Y == (16'h0001 << A)
    );

    // Exactly one output bit is HIGH.
    check_onehot_output: assert property (
        @(posedge clk) $onehot(Y)
    );

    // Output is never all zero for 4-bit binary A.
    check_nonzero_output: assert property (
        @(posedge clk) Y != 16'h0000
    );

    // When MSB of A is 0, upper half of Y must be zero.
    check_upper_zero_when_msb0: assert property (
        @(posedge clk) (A[3] == 1'b0) |-> (Y[15:8] == 8'h00)
    );

    // When MSB of A is 1, lower half of Y must be zero.
    check_lower_zero_when_msb1: assert property (
        @(posedge clk) (A[3] == 1'b1) |-> (Y[7:0] == 8'h00)
    );

    // When A[3:2]==00, only Y[3:0] may be nonzero.
    check_quarter00_zero_upper12: assert property (
        @(posedge clk) (A[3:2] == 2'b00) |-> (Y[15:4] == 12'h000)
    );

    // When A[3:2]==01, only Y[7:4] may be nonzero.
    check_quarter01_zero_elsewhere: assert property (
        @(posedge clk) (A[3:2] == 2'b01) |-> (Y[15:8] == 8'h00 && Y[3:0] == 4'h0)
    );

    // When A[3:2]==10, only Y[11:8] may be nonzero.
    check_quarter10_zero_elsewhere: assert property (
        @(posedge clk) (A[3:2] == 2'b10) |-> (Y[15:12] == 4'h0 && Y[7:0] == 8'h00)
    );

    // When A[3:2]==11, only Y[15:12] may be nonzero.
    check_quarter11_zero_lower12: assert property (
        @(posedge clk) (A[3:2] == 2'b11) |-> (Y[11:0] == 12'h000)
    );

    // Corner case: A==0 decodes to Y==0x0001.
    check_decode_A0: assert property (
        @(posedge clk) (A == 4'd0) |-> (Y == 16'h0001)
    );
endmodule

rtl:
module program_counter2a (next_pc,rst,clk);

	output [0:31] next_pc;




	input clk;
	input rst;






	reg [0:31] next_pc;		always @(posedge clk)
	begin
		if(rst)
		begin
			next_pc<=32'd0;
		end
		else
		begin
			next_pc<=next_pc+32'd4;
		end
	end




endmodule

sva:
module program_counter2a_sva (
    input logic clk,
    input logic rst,
    input logic [0:31] next_pc
);
    // When rst is asserted, next_pc is driven to 0 on the same clock.
    check_reset_drives_zero: assert property (
        @(posedge clk) rst |-> (next_pc == 32'd0)
    );

    // If two consecutive cycles are in reset, next_pc stays at 0 and stable.
    check_stable_zero_during_reset: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (next_pc == 32'd0) && (next_pc == $past(next_pc))
    );

    // When running (both current and previous cycles not in reset), next_pc increments by 4.
    check_increment_by_4_when_running: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst)) |-> (next_pc == $past(next_pc) + 32'd4)
    );

    // On reset deassertion edge, next_pc increments by 4 from the prior value.
    check_increment_by_4_on_reset_fall: assert property (
        @(posedge clk) $fell(rst) |-> (next_pc == $past(next_pc) + 32'd4)
    );

    // While running, next_pc changes every cycle.
    check_changes_each_cycle_when_running: assert property (
        @(posedge clk) disable iff (rst) (next_pc != $past(next_pc))
    );

    // While running, next_pc is monotonically non-decreasing (unsigned).
    check_monotonic_when_running: assert property (
        @(posedge clk) disable iff (rst) (next_pc >= $past(next_pc))
    );

    // While running, the two LSBs remain 0 (word-aligned).
    check_lsb_alignment_when_running: assert property (
        @(posedge clk) disable iff (rst) (next_pc[31:30] == 2'b00)
    );
endmodule

