sva:
module and5_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic B1,
    input logic X
);
    // Output equals the AND of all five inputs.
    check_output_equals_and_all: assert property (
        @(posedge clk) X == (A1 & A2 & A3 & A4 & B1)
    );

    // If A1 is LOW, X must be LOW.
    check_a1_low_forces_x_low: assert property (
        @(posedge clk) (A1 == 1'b0) |-> (X == 1'b0)
    );

    // If A2 is LOW, X must be LOW.
    check_a2_low_forces_x_low: assert property (
        @(posedge clk) (A2 == 1'b0) |-> (X == 1'b0)
    );

    // If A3 is LOW, X must be LOW.
    check_a3_low_forces_x_low: assert property (
        @(posedge clk) (A3 == 1'b0) |-> (X == 1'b0)
    );

    // If A4 is LOW, X must be LOW.
    check_a4_low_forces_x_low: assert property (
        @(posedge clk) (A4 == 1'b0) |-> (X == 1'b0)
    );

    // If B1 is LOW, X must be LOW.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) (B1 == 1'b0) |-> (X == 1'b0)
    );

    // If all inputs are HIGH, X must be HIGH.
    check_all_high_drives_x_high: assert property (
        @(posedge clk) (A1 & A2 & A3 & A4 & B1) |-> (X == 1'b1)
    );

    // X can be HIGH only if all inputs are HIGH.
    check_x_high_implies_all_high: assert property (
        @(posedge clk) (X == 1'b1) |-> (A1 & A2 & A3 & A4 & B1)
    );

    // X can only rise when all inputs are HIGH.
    check_x_rise_requires_all_high: assert property (
        @(posedge clk) $rose(X) |-> (A1 & A2 & A3 & A4 & B1)
    );

    // X can only fall when at least one input is LOW.
    check_x_fall_requires_some_low: assert property (
        @(posedge clk) $fell(X) |-> (!A1 || !A2 || !A3 || !A4 || !B1)
    );
endmodule

rtl:
module sky130_fd_sc_hd__or2b (
    input A,
    input B_N,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output X
);

    reg A_reg;
    reg B_N_reg;
    reg X_reg;

    wire A_stable;
    wire B_N_stable;
    wire X_stable;

    assign A_stable = (A_reg === A);
    assign B_N_stable = (B_N_reg === B_N);
    assign X_stable = (X_reg === X);

    always @(posedge VPWR) begin // Using posedge operator for VPWR
        A_reg <= A;
        B_N_reg <= B_N;
    end

    always @(A or B_N or A_stable or B_N_stable or X_stable) begin
        if (A_stable && B_N_stable) begin
            X_reg <= A | B_N;
        end else begin
            X_reg <= #2 A | B_N;
        end
    end

    assign X = X_reg;

endmodule

sva:
module sky130_fd_sc_hd__or2b_sva (
    input logic A,
    input logic B_N,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic X
);

    // Output is never Z at any VPWR rising edge.
    check_output_never_z: assert property (
        @(posedge VPWR) X !== 1'bz
    );

    // When A and B_N are unchanged since last VPWR edge, X equals A | B_N.
    check_or_when_inputs_stable: assert property (
        @(posedge VPWR) (($past(A) === A) && ($past(B_N) === B_N)) |-> (X === (A | B_N))
    );

    // Stable 0/0 inputs across a VPWR cycle yield X=0.
    check_tt_00: assert property (
        @(posedge VPWR) (($past(A) === 1'b0) && (A === 1'b0) && ($past(B_N) === 1'b0) && (B_N === 1'b0)) |-> (X === 1'b0)
    );

    // Stable 0/1 inputs across a VPWR cycle yield X=1.
    check_tt_01: assert property (
        @(posedge VPWR) (($past(A) === 1'b0) && (A === 1'b0) && ($past(B_N) === 1'b1) && (B_N === 1'b1)) |-> (X === 1'b1)
    );

    // Stable 1/0 inputs across a VPWR cycle yield X=1.
    check_tt_10: assert property (
        @(posedge VPWR) (($past(A) === 1'b1) && (A === 1'b1) && ($past(B_N) === 1'b0) && (B_N === 1'b0)) |-> (X === 1'b1)
    );

    // Stable 1/1 inputs across a VPWR cycle yield X=1.
    check_tt_11: assert property (
        @(posedge VPWR) (($past(A) === 1'b1) && (A === 1'b1) && ($past(B_N) === 1'b1) && (B_N === 1'b1)) |-> (X === 1'b1)
    );

    // If inputs are unchanged for two VPWR cycles, X does not change across the last cycle.
    check_output_stable_after_two_cycles_of_input_stability: assert property (
        @(posedge VPWR) (($past(A,2) === A) && ($past(B_N,2) === B_N)) |-> (X === $past(X))
    );

    // With known inputs unchanged for two VPWR cycles, X is known (not X/Z).
    check_known_output_after_two_stable_cycles: assert property (
        @(posedge VPWR)
            ((A === 1'b0 || A === 1'b1) && (B_N === 1'b0 || B_N === 1'b1) &&
             ($past(A,2) === A) && ($past(B_N,2) === B_N))
            |-> ((X !== 1'bx) && (X !== 1'bz))
    );

    // Changes on VPB/VGND/VNB do not affect X when A and B_N are stable across a VPWR cycle.
    check_supplies_no_effect_when_inputs_stable: assert property (
        @(posedge VPWR)
            (($past(A) === A) && ($past(B_N) === B_N) &&
             (($past(VPB) !== VPB) || ($past(VGND) !== VGND) || ($past(VNB) !== VNB)))
            |-> (X === (A | B_N))
    );

    // With inputs stable for two cycles, X remains unchanged even if supplies toggle between cycles.
    check_supplies_no_effect_after_two_stable_cycles: assert property (
        @(posedge VPWR)
            (($past(A,2) === A) && ($past(B_N,2) === B_N) &&
             (($past(VPB) !== VPB) || ($past(VGND) !== VGND) || ($past(VNB) !== VNB)))
            |-> (X === $past(X))
    );

endmodule

rtl:
module fa1 (
    A, 
    B, 
    CI, 
    S, 
    CO);
   input A;
   input B;
   input CI;
   output S;
   output CO;
   assign S = A ^ B ^ CI;
   assign CO = (A & B) | (CI & (A ^ B));
endmodule

module addsub4 (
    A, 
    B, 
    M, 
    Y);
   input [3:0] A;
   input [3:0] B;
   input M;
   output [3:0] Y;
   wire [3:0] C;
   wire [3:0] S;
   fa1 fa1_0(A[0], B[0], M, S[0], C[0]);
   fa1 fa1_1(A[1], B[1], C[0], S[1], C[1]);
   fa1 fa1_2(A[2], B[2], C[1], S[2], C[2]);
   fa1 fa1_3(A[3], B[3], C[2], S[3], C[3]);
   assign Y = M ? A - B : A + B;
endmodule

sva:
module addsub4_sva (
    // No clock/reset in RTL; pure combinational. Sampling clock provided here.
    input logic CLK,
    // DUT ports
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       M,
    input logic [3:0] Y,
    // Internal nets from RTL (fa1 chain)
    input logic [3:0] C,
    input logic [3:0] S
);

    ///// Y functional behavior /////
    // When M==0, Y is A+B (truncated to 4 bits).
    y_add: assert property (
        @(posedge CLK) (M == 1'b0) |-> (Y == ((A + B) & 4'hF))
    );
    // When M==1, Y is A-B (truncated to 4 bits).
    y_sub: assert property (
        @(posedge CLK) (M == 1'b1) |-> (Y == ((A - B) & 4'hF))
    );

    ///// fa1_0 (bit 0) behavior /////
    // S[0] equals A[0] ^ B[0] ^ M.
    fa0_sum_def: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0] ^ M)
    );
    // C[0] equals (A[0]&B[0]) | (M & (A[0]^B[0])).
    fa0_carry_def: assert property (
        @(posedge CLK) C[0] == ((A[0] & B[0]) | (M & (A[0] ^ B[0])))
    );

    ///// fa1_1 (bit 1) behavior /////
    // S[1] equals A[1] ^ B[1] ^ C[0].
    fa1_sum_def: assert property (
        @(posedge CLK) S[1] == (A[1] ^ B[1] ^ C[0])
    );
    // C[1] equals (A[1]&B[1]) | (C[0] & (A[1]^B[1])).
    fa1_carry_def: assert property (
        @(posedge CLK) C[1] == ((A[1] & B[1]) | (C[0] & (A[1] ^ B[1])))
    );

    ///// fa1_2 (bit 2) behavior /////
    // S[2] equals A[2] ^ B[2] ^ C[1].
    fa2_sum_def: assert property (
        @(posedge CLK) S[2] == (A[2] ^ B[2] ^ C[1])
    );
    // C[2] equals (A[2]&B[2]) | (C[1] & (A[2]^B[2])).
    fa2_carry_def: assert property (
        @(posedge CLK) C[2] == ((A[2] & B[2]) | (C[1] & (A[2] ^ B[2])))
    );

    ///// fa1_3 (bit 3) behavior /////
    // S[3] equals A[3] ^ B[3] ^ C[2].
    fa3_sum_def: assert property (
        @(posedge CLK) S[3] == (A[3] ^ B[3] ^ C[2])
    );
    // C[3] equals (A[3]&B[3]) | (C[2] & (A[3]^B[3])).
    fa3_carry_def: assert property (
        @(posedge CLK) C[3] == ((A[3] & B[3]) | (C[2] & (A[3] ^ B[3])))
    );

endmodule

