module mux4to1 (
    input A,
    input B,
    input C,
    input D,
    input [1:0] S,
    output Y
);

wire w1, w2, w3;

assign w1 = (S == 2'b00) ? A : B;
assign w2 = (S == 2'b00 || S == 2'b01) ? w1 : C;
assign w3 = (S == 2'b00 || S == 2'b01 || S == 2'b10) ? w2 : D;
assign Y = w3;

endmodule

sva:
module mux4to1_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic [1:0] S,
    input logic Y
);
    ///// Functional mapping /////
    // Y equals the 4:1 mux function of S selecting A/B/C/D.
    check_mux_equation: assert property (
        @(posedge CLK) Y == ((S == 2'b00) ? A :
                             (S == 2'b01) ? B :
                             (S == 2'b10) ? C : D)
    );

    // When S==00, Y must equal A.
    check_sel_00: assert property (
        @(posedge CLK) (S == 2'b00) |-> (Y == A)
    );

    // When S==01, Y must equal B.
    check_sel_01: assert property (
        @(posedge CLK) (S == 2'b01) |-> (Y == B)
    );

    // When S==10, Y must equal C.
    check_sel_10: assert property (
        @(posedge CLK) (S == 2'b10) |-> (Y == C)
    );

    // When S==11, Y must equal D.
    check_sel_11: assert property (
        @(posedge CLK) (S == 2'b11) |-> (Y == D)
    );

    ///// Independence from non-selected inputs /////
    // If S!=11 and only D changes, Y is unaffected (D not selected).
    independence_d_not_s11: assert property (
        @(posedge CLK) (S != 2'b11) && $stable(S) && $stable(A) && $stable(B) && $stable(C) && $changed(D) |-> $stable(Y)
    );

    // If S in {00,01} and only C changes, Y is unaffected (C not selected).
    independence_c_s00_or_s01: assert property (
        @(posedge CLK) (S inside {2'b00,2'b01}) && $stable(S) && $stable(A) && $stable(B) && $stable(D) && $changed(C) |-> $stable(Y)
    );

    // If S==00 and only B changes, Y is unaffected (B not selected).
    independence_b_s00: assert property (
        @(posedge CLK) (S == 2'b00) && $stable(S) && $stable(A) && $stable(C) && $stable(D) && $changed(B) |-> $stable(Y)
    );

    // If S!=00 and only A changes, Y is unaffected (A not selected).
    independence_a_not_s00: assert property (
        @(posedge CLK) (S != 2'b00) && $stable(S) && $stable(B) && $stable(C) && $stable(D) && $changed(A) |-> $stable(Y)
    );

    ///// Stability /////
    // If S and all data inputs are stable, Y must be stable.
    output_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable(S) && $stable(A) && $stable(B) && $stable(C) && $stable(D) |-> $stable(Y)
    );
endmodule

module counter_sva (
  input logic clk,
  input logic ce,
  input logic clr,
  input logic [7:0] count
);

  // Synchronous clear drives count to zero on that clock.
  sync_clear_zero: assert property (
    @(posedge clk) clr |=> (count == 8'h00)
  );

  // With enable and no clear (prev cycle not in clear), count increments by 1.
  inc_on_ce: assert property (
    @(posedge clk) disable iff (clr)
      (ce && $past(!clr)) |=> (count == $past(count) + 8'd1)
  );

  // With ce low and no clear (prev cycle not in clear), count holds.
  hold_when_ce_low: assert property (
    @(posedge clk) disable iff (clr)
      (!ce && $past(!clr)) |=> (count == $past(count))
  );

  // clr dominates ce when both are high.
  clr_priority_over_ce: assert property (
    @(posedge clk) (clr && ce) |=> (count == 8'h00)
  );

  // With enable and no clear, 0xFF rolls over to 0x00.
  rollover_ff_to_00: assert property (
    @(posedge clk) disable iff (clr)
      (ce && ($past(count) == 8'hFF) && $past(!clr)) |=> (count == 8'h00)
  );

  // Two consecutive enables (no clear) produce a net +2 increment.
  two_cycle_increment: assert property (
    @(posedge clk) disable iff (clr)
      (ce && $past(ce) && $past(!clr) && $past(!clr,2)) |=> (count == $past(count,2) + 8'd2)
  );

  // Two consecutive cycles with ce low (no clear) hold count over 2 cycles.
  hold_two_cycles_no_enable: assert property (
    @(posedge clk) disable iff (clr)
      (!ce && $past(!ce) && $past(!clr) && $past(!clr,2)) |=> (count == $past(count,2))
  );

  // Any change in count must be caused by clr or ce.
  change_implies_cause: assert property (
    @(posedge clk) $changed(count) |=> (clr || ce)
  );

endmodule

rtl:
module RCA_N4_17 ( A, B, Ci, S, Co );
  input [3:0] A;
  input [3:0] B;
  output [3:0] S;
  input Ci;
  output Co;

  wire   [3:1] CTMP;

  FA_71 FAI_1 ( .A(A[0]), .B(B[0]), .Ci(Ci), .S(S[0]), .Co(CTMP[1]) );
  FA_70 FAI_2 ( .A(A[1]), .B(B[1]), .Ci(CTMP[1]), .S(S[1]), .Co(CTMP[2]) );
  FA_69 FAI_3 ( .A(A[2]), .B(B[2]), .Ci(CTMP[2]), .S(S[2]), .Co(CTMP[3]) );
  FA_68 FAI_4 ( .A(A[3]), .B(B[3]), .Ci(CTMP[3]), .S(S[3]), .Co(Co) );

endmodule

module FA_71 ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  assign S = A ^ B ^ Ci;
  assign Co = (A & B) | (A & Ci) | (B & Ci);
endmodule

module FA_70 ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  assign S = A ^ B ^ Ci;
  assign Co = (A & B) | (A & Ci) | (B & Ci);
endmodule

module FA_69 ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  assign S = A ^ B ^ Ci;
  assign Co = (A & B) | (A & Ci) | (B & Ci);
endmodule

module FA_68 ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  assign S = A ^ B ^ Ci;
  assign Co = (A & B) | (A & Ci) | (B & Ci);
endmodule

sva:
module RCA_N4_17_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Ci,
    input logic [3:0] S,
    input logic Co
);
    // Sum and carry must equal 5-bit addition of A+B+Ci.
    check_sum_matches_adder: assert property (
        @(posedge CLK) {Co, S} == ({1'b0, A} + {1'b0, B} + Ci)
    );

    // Carry-out equals MSB of 5-bit sum.
    check_carry_is_msb_of_sum: assert property (
        @(posedge CLK) Co == (({1'b0, A} + {1'b0, B} + Ci) >= 5'd16)
    );

    // Bit 0 sum is XOR of A[0], B[0], Ci.
    check_s0_xor: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0] ^ Ci)
    );

    // Bit 1 sum is XOR of A[1], B[1], and c1.
    check_s1_xor: assert property (
        @(posedge CLK) S[1] == (A[1] ^ B[1] ^ ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
    );

    // Bit 2 sum is XOR of A[2], B[2], and c2.
    check_s2_xor: assert property (
        @(posedge CLK) S[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (A[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) )) |
                (B[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
            )
        )
    );

    // Bit 3 sum is XOR of A[3], B[3], and c3.
    check_s3_xor: assert property (
        @(posedge CLK) S[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                (A[2] &
                    (
                        (A[1] & B[1]) |
                        (A[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) )) |
                        (B[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
                    )
                ) |
                (B[2] &
                    (
                        (A[1] & B[1]) |
                        (A[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) )) |
                        (B[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
                    )
                )
            )
        )
    );

    // Carry-out equals chained majority over bit 3 with c3.
    check_co_chained_majority: assert property (
        @(posedge CLK) Co == (
            (A[3] & B[3]) |
            (A[3] &
                (
                    (A[2] & B[2]) |
                    (A[2] &
                        (
                            (A[1] & B[1]) |
                            (A[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) )) |
                            (B[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
                        )
                    ) |
                    (B[2] &
                        (
                            (A[1] & B[1]) |
                            (A[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) )) |
                            (B[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
                        )
                    )
                )
            ) |
            (B[3] &
                (
                    (A[2] & B[2]) |
                    (A[2] &
                        (
                            (A[1] & B[1]) |
                            (A[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) )) |
                            (B[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
                        )
                    ) |
                    (B[2] &
                        (
                            (A[1] & B[1]) |
                            (A[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) )) |
                            (B[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
                        )
                    )
                )
            )
        )
    );

    // When B==0 and Ci==0, output equals A with zero carry.
    check_propagate_A_when_B_zero: assert property (
        @(posedge CLK) ((B == 4'b0000) && (Ci == 1'b0)) |-> ({Co, S} == {1'b0, A})
    );

    // When A==0 and Ci==0, output equals B with zero carry.
    check_propagate_B_when_A_zero: assert property (
        @(posedge CLK) ((A == 4'b0000) && (Ci == 1'b0)) |-> ({Co, S} == {1'b0, B})
    );

    // Outputs remain stable if inputs are stable across cycles.
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && $stable(Ci)) |-> ($stable(S) && $stable(Co))
    );
endmodule

