module bw_ioslave_dl(
	// inputs in alphabetical order
	dqs_in,
	lpf_out,
	se,
	si,
	strobe,
	//outputs in alphabetical order
	dqs_out,
	so          );

	input		dqs_in;
	input [4:0]	lpf_out;
	input		se;
	input		si;
	input		strobe;

	output		dqs_out;
	output		reg so;

       parameter DELAY = 1250;

        reg             dqs_out;
        reg             q1;
        reg             q2;
        reg             q3;
        reg             q4;

        // 1/4 cycle delay line.
        always @(posedge dqs_in)
          begin
            q1 <= #DELAY dqs_in;
            q2 <= #DELAY q1;
            q3 <= #DELAY q2;
            q4 <= #DELAY q3;
            dqs_out <= #DELAY q4;
          end

        // strobe output
        always @(posedge strobe)
          begin
            if (se == 1)
              so <= si;
          end

endmodule

sva:
module bw_ioslave_dl_sva (
    input logic dqs_in,
    input logic [4:0] lpf_out,
    input logic se,
    input logic si,
    input logic strobe,
    input logic dqs_out,
    input logic so
);
    // Clocks: posedge dqs_in, posedge strobe; no reset in RTL.
    // Sequential logic: 5-stage delay line on dqs_in; so is registered on strobe when se=1.

    ///// dqs_in delay line behavior /////
    // dqs_out equals dqs_in delayed by 5 posedges of dqs_in.
    check_dqsout_delay_5: assert property (
        @(posedge dqs_in) 1'b1 |-> ##5 (dqs_out == $past(dqs_in,5))
    );

    // An input edge propagates to an output edge 5 cycles later.
    check_dqs_edge_propagation: assert property (
        @(posedge dqs_in) $changed(dqs_in) |-> ##5 $changed(dqs_out)
    );

    // If input does not change at a cycle, output does not change 5 cycles later.
    check_dqs_noedge_propagation: assert property (
        @(posedge dqs_in) !$changed(dqs_in) |-> ##5 !$changed(dqs_out)
    );

    // An output change implies the input changed 5 cycles earlier.
    check_dqsout_change_origin: assert property (
        @(posedge dqs_in) $changed(dqs_out) |-> ($past(dqs_in,5) != $past(dqs_in,6))
    );

    // If output does not change at a cycle, input did not change 5 cycles earlier.
    check_dqsout_nochange_origin: assert property (
        @(posedge dqs_in) !$changed(dqs_out) |-> ($past(dqs_in,5) == $past(dqs_in,6))
    );

    ///// strobe/so register behavior /////
    // When se==1 at strobe edge, so captures si.
    check_so_captures_si_when_se: assert property (
        @(posedge strobe) se |=> (so == $past(si))
    );

    // When se==0 at strobe edge, so holds its previous value.
    check_so_holds_when_se_low: assert property (
        @(posedge strobe) !se |=> (so == $past(so))
    );

    // A change on so can only occur when previous strobe had se==1.
    check_so_change_implies_se: assert property (
        @(posedge strobe) $changed(so) |-> $past(se)
    );

    // If previous strobe had se==1 and si differed from old so, so changes to that si.
    check_so_changes_when_si_differs: assert property (
        @(posedge strobe) se && (si != $past(so)) |=> ($changed(so) && (so == $past(si)))
    );

    // If previous strobe had se==1 and si equaled old so, so remains unchanged.
    check_so_stable_when_si_matches: assert property (
        @(posedge strobe) se && (si == $past(so)) |=> (!$changed(so) && (so == $past(so)))
    );

endmodule

rtl:
module binary_adder (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] S
);

always @(*) begin
    S = A + B;
    if (S > 15) begin
        S = S - 16;
    end
end

endmodule

sva:
module binary_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S
);
    // S equals (A+B) modulo 16.
    check_sum_mod16: assert property (
        @(posedge clk) S == ((A + B) & 4'hF)
    );

    // If inputs hold their values, S holds as well.
    check_stable_if_inputs_hold: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> $stable(S)
    );

    // Adding zero on B leaves S equal to A.
    check_identity_B_zero: assert property (
        @(posedge clk) (B == 4'd0) |-> (S == A)
    );

    // Adding zero on A leaves S equal to B.
    check_identity_A_zero: assert property (
        @(posedge clk) (A == 4'd0) |-> (S == B)
    );

    // Both inputs zero results in zero sum.
    check_zero_plus_zero: assert property (
        @(posedge clk) (A == 4'd0 && B == 4'd0) |-> (S == 4'd0)
    );

    // If A is stable and B increments by 1 (mod 16), S increments by 1 (mod 16).
    check_increment_B: assert property (
        @(posedge clk) ($stable(A) && (B == $past(B) + 4'd1)) |-> (S == $past(S) + 4'd1)
    );

    // If A is stable and B decrements by 1 (mod 16), S decrements by 1 (mod 16).
    check_decrement_B: assert property (
        @(posedge clk) ($stable(A) && (B == $past(B) - 4'd1)) |-> (S == $past(S) - 4'd1)
    );

    // If B is stable and A increments by 1 (mod 16), S increments by 1 (mod 16).
    check_increment_A: assert property (
        @(posedge clk) ($stable(B) && (A == $past(A) + 4'd1)) |-> (S == $past(S) + 4'd1)
    );

    // If B is stable and A decrements by 1 (mod 16), S decrements by 1 (mod 16).
    check_decrement_A: assert property (
        @(posedge clk) ($stable(B) && (A == $past(A) - 4'd1)) |-> (S == $past(S) - 4'd1)
    );

    // Swapping A and B across cycles leaves S unchanged (commutativity).
    check_swap_commutativity: assert property (
        @(posedge clk) (A == $past(B) && B == $past(A)) |-> (S == $past(S))
    );
endmodule

module barrel_shifter_sva (
    input logic clk,
    input logic load,
    input logic [3:0] data,
    input logic [1:0] shift,
    input logic [3:0] result
);
    // Clock: clk (posedge). No reset in RTL.
    // Sequential: result updates on clk; load has priority; else shift by shift.

    // When load was HIGH last cycle, result now equals last cycle's data.
    load_captures_data: assert property (
        @(posedge clk) $past(load) |-> (result == $past(data))
    );

    // With no load and shift==00 last cycle, result holds its previous value.
    no_shift_holds: assert property (
        @(posedge clk) $past(!load && (shift == 2'b00)) |-> (result == $past(result))
    );

    // With no load and shift==01 last cycle, result = {old result[2:0], old data[3]}.
    shift_left_by_1: assert property (
        @(posedge clk) $past(!load && (shift == 2'b01)) |-> (result == {$past(result[2:0]), $past(data[3])})
    );

    // With no load and shift==10 last cycle, result = {old data[0], old result[3:1]}.
    shift_right_by_1: assert property (
        @(posedge clk) $past(!load && (shift == 2'b10)) |-> (result == {$past(data[0]), $past(result[3:1])})
    );

    // With no load and shift==11 last cycle, result = {old data[1:0], old result[3:2]}.
    shift_right_by_2: assert property (
        @(posedge clk) $past(!load && (shift == 2'b11)) |-> (result == {$past(data[1:0]), $past(result[3:2])})
    );

    // Bit check for shift==01: upper three bits move down by one.
    shift_left_by_1_upper_bits: assert property (
        @(posedge clk) $past(!load && (shift == 2'b01)) |-> (result[3:1] == $past(result[2:0]))
    );

    // Bit check for shift==01: LSB comes from data[3].
    shift_left_by_1_lsb_from_data3: assert property (
        @(posedge clk) $past(!load && (shift == 2'b01)) |-> (result[0] == $past(data[3]))
    );

    // Bit check for shift==10: MSB comes from data[0].
    shift_right_by_1_msb_from_data0: assert property (
        @(posedge clk) $past(!load && (shift == 2'b10)) |-> (result[3] == $past(data[0]))
    );

    // Bit check for shift==11: top two bits come from data[1:0].
    shift_right_by_2_top_from_data10: assert property (
        @(posedge clk) $past(!load && (shift == 2'b11)) |-> (result[3:2] == $past(data[1:0]))
    );
endmodule

