module mux_2to1(
    input A,
    input B,
    input S,
    output Y
);

    wire not_S;
    assign not_S = ~S;

    wire Y_A;
    wire Y_B;

    and gate_A(Y_A, A, not_S);
    and gate_B(Y_B, B, S);

    or gate_C(Y, Y_A, Y_B);

endmodule

sva:
module mux_2to1_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic S,
    input logic Y
);
    // Y implements 2:1 mux function: Y = (~S & A) | (S & B).
    check_mux_function: assert property (
        @(posedge CLK) Y == ((~S & A) | (S & B))
    );

    // When S=0, Y equals A.
    check_select_low: assert property (
        @(posedge CLK) (S == 1'b0) |-> (Y == A)
    );

    // When S=1, Y equals B.
    check_select_high: assert property (
        @(posedge CLK) (S == 1'b1) |-> (Y == B)
    );

    // If A and B are equal, Y equals that value.
    check_equal_inputs: assert property (
        @(posedge CLK) (A == B) |-> (Y == A)
    );

    // If A, B, and S do not change between cycles, Y does not change.
    check_output_stable_if_inputs_stable: assert property (
        @(posedge CLK) (!$changed(A) && !$changed(B) && !$changed(S)) |-> (!$changed(Y))
    );

    // With S held low across cycles, Y change matches A change.
    check_track_A_when_S_low_stable: assert property (
        @(posedge CLK) ($past(1'b1) && (S == 1'b0) && ($past(S) == 1'b0)) |-> ($changed(Y) == $changed(A))
    );

    // With S held high across cycles, Y change matches B change.
    check_track_B_when_S_high_stable: assert property (
        @(posedge CLK) ($past(1'b1) && (S == 1'b1) && ($past(S) == 1'b1)) |-> ($changed(Y) == $changed(B))
    );

    // On S rising edge, Y equals B in the same cycle.
    check_on_S_rise: assert property (
        @(posedge CLK) $rose(S) |-> (Y == B)
    );

    // On S falling edge, Y equals A in the same cycle.
    check_on_S_fall: assert property (
        @(posedge CLK) $fell(S) |-> (Y == A)
    );

    // With S low across cycles and A stable, Y is stable regardless of B.
    check_B_irrelevant_when_S_low: assert property (
        @(posedge CLK) ($past(1'b1) && (S == 1'b0) && ($past(S) == 1'b0) && !$changed(A)) |-> (!$changed(Y))
    );

    // With S high across cycles and B stable, Y is stable regardless of A.
    check_A_irrelevant_when_S_high: assert property (
        @(posedge CLK) ($past(1'b1) && (S == 1'b1) && ($past(S) == 1'b1) && !$changed(B)) |-> (!$changed(Y))
    );
endmodule

module BinaryCounter_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] count
);
    // Next state follows: if previous reset then 0 else previous count + 1 (mod 16).
    check_state_update_from_prev: assert property (
        @(posedge clk) $past(1'b1) |-> (count == ( $past(reset) ? 4'd0 : ($past(count) + 4'd1) ))
    );

    // A reset high sets count to 0 on the next clock.
    check_reset_sets_zero_next: assert property (
        @(posedge clk) reset |=> (count == 4'd0)
    );

    // When not in reset, count increments by 1 each cycle.
    check_increment_by_one_no_reset: assert property (
        @(posedge clk) disable iff (reset) $past(1'b1) |-> (count == ($past(count) + 4'd1))
    );

    // When not in reset and previous count was 15, wrap to 0.
    check_wrap_from_15_to_0: assert property (
        @(posedge clk) disable iff (reset) ($past(1'b1) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

    // LSB toggles every increment when not in reset.
    check_lsb_toggles_when_incrementing: assert property (
        @(posedge clk) disable iff (reset) $past(1'b1) |-> (count[0] == ~$past(count[0]))
    );

    // After 16 cycles without reset, count returns to its value from 16 cycles ago.
    check_return_to_prior_after_16_no_reset: assert property (
        @(posedge clk) disable iff (reset) (!reset[*16]) |=> (count == $past(count, 16))
    );

    // If reset is held high across cycles, count stays 0.
    check_hold_zero_while_reset_held: assert property (
        @(posedge clk) ($past(1'b1) && reset && $past(reset)) |-> (count == 4'd0)
    );
endmodule

