module bus_fsm (
	output reg gnt,
	output reg [1:0] state,
	input dly,
	input done,
	input req,
	input clk,
	input rst_n
);

	// Define the states of the FSM
	parameter [1:0] IDLE = 2'b00,
					BBUSY = 2'b01,
					BWAIT = 2'b10,
					BFREE = 2'b11;

	// Declare the state and next state variables
	reg [1:0] state, next_state;

	// Initialize the state and next state variables
	initial begin
		state <= IDLE;
		next_state <= IDLE;
	end

	// Assign the next state to the current state on the positive clock edge
	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			state <= IDLE;
		end
		else begin
			state <= next_state;
		end
	end

	// Implement the FSM logic using a case statement
	always @(*) begin
		case (state)
			IDLE: if (req) next_state = BBUSY; else next_state = IDLE;
			BBUSY: if (!done) next_state = BBUSY; else if (dly) next_state = BWAIT; else next_state = BFREE;
			BWAIT: if (!dly) next_state = BFREE; else next_state = BWAIT;
			BFREE: if (req) next_state = BBUSY; else next_state = IDLE;
			default: next_state = IDLE;
		endcase
		gnt = (state == BBUSY) | (state == BWAIT);
	end
endmodule

sva:
module bus_fsm_sva (
    input logic gnt,
    input logic [1:0] state,
    input logic dly,
    input logic done,
    input logic req,
    input logic clk,
    input logic rst_n
);
    // State encodings (match RTL)
    localparam [1:0] IDLE  = 2'b00;
    localparam [1:0] BBUSY = 2'b01;
    localparam [1:0] BWAIT = 2'b10;
    localparam [1:0] BFREE = 2'b11;

    ///// Reset behavior /////
    // While reset is asserted, state is IDLE and gnt is 0.
    check_reset_idle_gnt0: assert property (
        @(posedge clk) !rst_n |-> (state == IDLE) && (gnt == 1'b0)
    );
    // On the first cycle after reset deasserts, state is IDLE and gnt is 0.
    check_first_cycle_after_reset_idle: assert property (
        @(posedge clk) disable iff (!rst_n) $rose(rst_n) |-> (state == IDLE) && (gnt == 1'b0)
    );

    ///// Next-state function /////
    // From IDLE: next = (req ? BBUSY : IDLE).
    check_state_trans_from_idle: assert property (
        @(posedge clk) disable iff (!rst_n)
        $past(rst_n) && ($past(state) == IDLE) |-> state == ($past(req) ? BBUSY : IDLE)
    );
    // From BBUSY: next = (!done ? BBUSY : (dly ? BWAIT : BFREE)).
    check_state_trans_from_bbusy: assert property (
        @(posedge clk) disable iff (!rst_n)
        $past(rst_n) && ($past(state) == BBUSY) |-> state == ( !$past(done) ? BBUSY : ($past(dly) ? BWAIT : BFREE) )
    );
    // From BWAIT: next = (dly ? BWAIT : BFREE).
    check_state_trans_from_bwait: assert property (
        @(posedge clk) disable iff (!rst_n)
        $past(rst_n) && ($past(state) == BWAIT) |-> state == ( $past(dly) ? BWAIT : BFREE )
    );
    // From BFREE: next = (req ? BBUSY : IDLE).
    check_state_trans_from_bfree: assert property (
        @(posedge clk) disable iff (!rst_n)
        $past(rst_n) && ($past(state) == BFREE) |-> state == ($past(req) ? BBUSY : IDLE)
    );

    ///// gnt definition /////
    // gnt is asserted iff state is BBUSY or BWAIT (matches RTL combinational definition).
    check_gnt_definition: assert property (
        @(posedge clk) disable iff (!rst_n) gnt == ((state == BBUSY) | (state == BWAIT))
    );
    // In IDLE, gnt must be 0.
    check_gnt_low_in_idle: assert property (
        @(posedge clk) disable iff (!rst_n) (state == IDLE) |-> (gnt == 1'b0)
    );
    // In BFREE, gnt must be 0.
    check_gnt_low_in_bfree: assert property (
        @(posedge clk) disable iff (!rst_n) (state == BFREE) |-> (gnt == 1'b0)
    );
    // A rising gnt implies we entered BBUSY or BWAIT this cycle.
    check_gnt_rise_targets_busy_or_wait: assert property (
        @(posedge clk) disable iff (!rst_n) $rose(gnt) |-> ((state == BBUSY) || (state == BWAIT))
    );
    // A falling gnt implies we entered IDLE or BFREE this cycle.
    check_gnt_fall_targets_idle_or_free: assert property (
        @(posedge clk) disable iff (!rst_n) $fell(gnt) |-> ((state == IDLE) || (state == BFREE))
    );
endmodule

rtl:
module four_to_one (
    X ,
    A1,
    A2,
    B1,
    B2
);

    output X ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign X = (A1 | A2 | B1 | B2);

endmodule

sva:
module four_to_one_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2
);
    // No clock/reset in RTL; pure combinational X = A1 | A2 | B1 | B2.
    // Sample on any input/output edge.

    // X must equal the OR of inputs on any change.
    check_or_equation: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge X or negedge X)
            (X === (A1 | A2 | B1 | B2))
    );

    // If X is HIGH, at least one input is HIGH.
    check_x_high_implies_some_input_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge X or negedge X)
            (X === 1'b1) |-> ##0 ((A1 === 1'b1) || (A2 === 1'b1) || (B1 === 1'b1) || (B2 === 1'b1))
    );

    // If X is LOW, all inputs are LOW.
    check_x_low_implies_all_inputs_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge X or negedge X)
            (X === 1'b0) |-> ##0 ((A1 === 1'b0) && (A2 === 1'b0) && (B1 === 1'b0) && (B2 === 1'b0))
    );

    // A1 HIGH implies X HIGH.
    check_a1_high_implies_x_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge X or negedge X)
            (A1 === 1'b1) |-> ##0 (X === 1'b1)
    );

    // A2 HIGH implies X HIGH.
    check_a2_high_implies_x_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge X or negedge X)
            (A2 === 1'b1) |-> ##0 (X === 1'b1)
    );

    // B1 HIGH implies X HIGH.
    check_b1_high_implies_x_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge X or negedge X)
            (B1 === 1'b1) |-> ##0 (X === 1'b1)
    );

    // B2 HIGH implies X HIGH.
    check_b2_high_implies_x_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge X or negedge X)
            (B2 === 1'b1) |-> ##0 (X === 1'b1)
    );

    // A1 controls X when other inputs are LOW: X equals A1.
    check_a1_controls_when_others_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge X or negedge X)
            ((A2 === 1'b0) && (B1 === 1'b0) && (B2 === 1'b0)) |-> ##0 (X === A1)
    );

    // A2 controls X when other inputs are LOW: X equals A2.
    check_a2_controls_when_others_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge X or negedge X)
            ((A1 === 1'b0) && (B1 === 1'b0) && (B2 === 1'b0)) |-> ##0 (X === A2)
    );

    // B1 controls X when other inputs are LOW: X equals B1.
    check_b1_controls_when_others_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge X or negedge X)
            ((A1 === 1'b0) && (A2 === 1'b0) && (B2 === 1'b0)) |-> ##0 (X === B1)
    );

    // B2 controls X when other inputs are LOW: X equals B2.
    check_b2_controls_when_others_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1 or negedge B1 or posedge B2 or negedge B2 or posedge X or negedge X)
            ((A1 === 1'b0) && (A2 === 1'b0) && (B1 === 1'b0)) |-> ##0 (X === B2)
    );

    // A rising edge on X implies at least one input is now HIGH.
    check_x_rise_requires_input_high: assert property (
        @(posedge X) ##0 ((A1 === 1'b1) || (A2 === 1'b1) || (B1 === 1'b1) || (B2 === 1'b1))
    );

    // A falling edge on X implies all inputs are now LOW.
    check_x_fall_requires_all_inputs_low: assert property (
        @(negedge X) ##0 ((A1 === 1'b0) && (A2 === 1'b0) && (B1 === 1'b0) && (B2 === 1'b0))
    );

endmodule

rtl:
module adder (
  input [3:0] a,
  input [3:0] b,
  input cin,
  output [3:0] sum,
  output cout
);

  assign sum = a + b + cin;
  assign cout = (a[3] & b[3]) | (a[3] & cin) | (b[3] & cin);

endmodule

sva:
module adder_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic       cin,
    input logic [3:0] sum,
    input logic       cout
);
    // sum equals a + b + cin
    check_sum_add_pos_cin: assert property (
        @(posedge cin) sum == (a + b + cin)
    );

    // cout matches majority of a[3], b[3], cin
    check_cout_majority_pos_cin: assert property (
        @(posedge cin) cout == ((a[3] & b[3]) | (a[3] & cin) | (b[3] & cin))
    );

    // sum[0] is XOR of a[0], b[0], cin
    check_sum0_xor_pos_cin: assert property (
        @(posedge cin) sum[0] == (a[0] ^ b[0] ^ cin)
    );

    // When cin=0, sum=a+b and cout=a[3]&b[3]
    check_cin0_behavior_negedge: assert property (
        @(negedge cin) (sum == (a + b)) && (cout == (a[3] & b[3]))
    );

    // When cin=1, sum=a+b+1 and cout=a[3]|b[3]
    check_cin1_behavior_posedge: assert property (
        @(posedge cin) (sum == (a + b + 1'b1)) && (cout == (a[3] | b[3]))
    );

    // If both MSBs are 0 then cout is 0
    check_cout_zero_when_msb_zero: assert property (
        @(posedge cin) ((a[3] == 1'b0) && (b[3] == 1'b0)) |-> (cout == 1'b0)
    );

    // If both MSBs are 1 then cout is 1
    check_cout_one_when_msb_one: assert property (
        @(posedge cin) ((a[3] == 1'b1) && (b[3] == 1'b1)) |-> (cout == 1'b1)
    );

    // If MSBs differ, cout equals cin
    check_cout_tracks_cin_when_msb_mismatch: assert property (
        @(posedge cin) (a[3] ^ b[3]) |-> (cout == cin)
    );

    // cout equals ab + (a^b)cin equivalent form
    check_cout_alt_form: assert property (
        @(posedge cin) cout == ((a[3] & b[3]) | ((a[3] ^ b[3]) & cin))
    );

    // With a=0 and b=0, sum=cin and cout=0
    check_zero_inputs_behavior: assert property (
        @(posedge cin) ((a == 4'b0000) && (b == 4'b0000)) |-> ((sum == {3'b000, cin}) && (cout == 1'b0))
    );
endmodule

rtl:
module majority (
    A,
    B,
    C,
    D,
    Y
);

    input A, B, C, D;
    output Y;

    wire AandB, AandC, AandD, BandC, BandD, CandD;
    wire majority1, majority2, majority3, majority4;

    // Calculate all possible pairs of AND gates
    and (AandB, A, B);
    and (AandC, A, C);
    and (AandD, A, D);
    and (BandC, B, C);
    and (BandD, B, D);
    and (CandD, C, D);

    // Calculate majority for each group of 3 inputs
    assign majority1 = (AandB & C) | (AandC & B) | (AandD & B) | (BandC & A) | (BandD & A) | (CandD & A);
    assign majority2 = (AandB & D) | (AandC & D) | (AandD & C) | (BandC & D) | (BandD & C) | (CandD & B);
    assign majority3 = (AandB & C) | (AandC & D) | (AandD & B) | (BandC & D) | (BandD & A) | (CandD & B);
    assign majority4 = (AandB & D) | (AandC & B) | (AandD & C) | (BandC & A) | (BandD & C) | (CandD & A);

    // Calculate final majority function
    assign Y = majority1 & majority2 | majority1 & majority3 | majority1 & majority4 | majority2 & majority3 | majority2 & majority4 | majority3 & majority4;

endmodule

sva:
module majority_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);
    // Combinational RTL with no clock/reset; assertions sample on any input edge.

    // Y equals the 3-of-4 majority of A,B,C,D.
    check_y_equiv_majority3: assert property (
        @(posedge A or posedge B or posedge C or posedge D or negedge A or negedge B or negedge C or negedge D)
        disable iff (1'b0)
        (Y == ((A & B & C) | (A & B & D) | (A & C & D) | (B & C & D)))
    );

    // Y is 0 when all inputs are 0.
    check_y_zero_when_all_zero: assert property (
        @(posedge A or posedge B or posedge C or posedge D or negedge A or negedge B or negedge C or negedge D)
        disable iff (1'b0)
        ((!A && !B && !C && !D) |-> (Y == 1'b0))
    );

    // Y is 0 when exactly A and B are 1.
    check_y_zero_when_AB_only: assert property (
        @(posedge A or posedge B or posedge C or posedge D or negedge A or negedge B or negedge C or negedge D)
        disable iff (1'b0)
        ((A && B && !C && !D) |-> (Y == 1'b0))
    );

    // Y is 0 when exactly A and C are 1.
    check_y_zero_when_AC_only: assert property (
        @(posedge A or posedge B or posedge C or posedge D or negedge A or negedge B or negedge C or negedge D)
        disable iff (1'b0)
        ((A && C && !B && !D) |-> (Y == 1'b0))
    );

    // Y is 0 when exactly A and D are 1.
    check_y_zero_when_AD_only: assert property (
        @(posedge A or posedge B or posedge C or posedge D or negedge A or negedge B or negedge C or negedge D)
        disable iff (1'b0)
        ((A && D && !B && !C) |-> (Y == 1'b0))
    );

    // Y is 0 when exactly B and C are 1.
    check_y_zero_when_BC_only: assert property (
        @(posedge A or posedge B or posedge C or posedge D or negedge A or negedge B or negedge C or negedge D)
        disable iff (1'b0)
        ((B && C && !A && !D) |-> (Y == 1'b0))
    );

    // Y is 0 when exactly B and D are 1.
    check_y_zero_when_BD_only: assert property (
        @(posedge A or posedge B or posedge C or posedge D or negedge A or negedge B or negedge C or negedge D)
        disable iff (1'b0)
        ((B && D && !A && !C) |-> (Y == 1'b0))
    );

    // Y is 0 when exactly C and D are 1.
    check_y_zero_when_CD_only: assert property (
        @(posedge A or posedge B or posedge C or posedge D or negedge A or negedge B or negedge C or negedge D)
        disable iff (1'b0)
        ((C && D && !A && !B) |-> (Y == 1'b0))
    );

    // Y is 1 when A, B, and C are 1.
    check_y_one_when_ABC: assert property (
        @(posedge A or posedge B or posedge C or posedge D or negedge A or negedge B or negedge C or negedge D)
        disable iff (1'b0)
        ((A && B && C) |-> (Y == 1'b1))
    );

    // Y is 1 when A, B, and D are 1.
    check_y_one_when_ABD: assert property (
        @(posedge A or posedge B or posedge C or posedge D or negedge A or negedge B or negedge C or negedge D)
        disable iff (1'b0)
        ((A && B && D) |-> (Y == 1'b1))
    );

    // Y is 1 when A, C, and D are 1.
    check_y_one_when_ACD: assert property (
        @(posedge A or posedge B or posedge C or posedge D or negedge A or negedge B or negedge C or negedge D)
        disable iff (1'b0)
        ((A && C && D) |-> (Y == 1'b1))
    );

    // Y is 1 when B, C, and D are 1.
    check_y_one_when_BCD: assert property (
        @(posedge A or posedge B or posedge C or posedge D or negedge A or negedge B or negedge C or negedge D)
        disable iff (1'b0)
        ((B && C && D) |-> (Y == 1'b1))
    );

endmodule

rtl:
module mux #(
    parameter DEFAULT_VALUE = 75
) (
    input ctrl,
    input [0:0] D0,
    input [0:0] D1,
    output [0:0] S
);

    wire [0:0] S;

    assign S = (ctrl == 1'b0) ? D0 : D1;

endmodule

sva:
module mux_sva (
    input logic clk,
    input logic ctrl,
    input logic [0:0] D0,
    input logic [0:0] D1,
    input logic [0:0] S
);
    // Output equals the mux expression.
    check_mux_equation: assert property (
        @(posedge clk) S == ((ctrl == 1'b0) ? D0 : D1)
    );

    // When ctrl is 0, S must equal D0.
    check_ctrl_low_selects_D0: assert property (
        @(posedge clk) (ctrl == 1'b0) |-> (S == D0)
    );

    // When ctrl is 1, S must equal D1.
    check_ctrl_high_selects_D1: assert property (
        @(posedge clk) (ctrl == 1'b1) |-> (S == D1)
    );

    // On rising ctrl edge, S must reflect D1.
    check_output_updates_on_ctrl_rise: assert property (
        @(posedge clk) $rose(ctrl) |-> (S == D1)
    );

    // On falling ctrl edge, S must reflect D0.
    check_output_updates_on_ctrl_fall: assert property (
        @(posedge clk) $fell(ctrl) |-> (S == D0)
    );

    // If ctrl, D0, and D1 are stable, S must be stable.
    check_output_stable_if_inputs_stable: assert property (
        @(posedge clk) $stable(ctrl) && $stable(D0) && $stable(D1) |-> $stable(S)
    );

    // With ctrl stable at 0, changes on D1 must not affect S.
    check_ignore_unselected_D1: assert property (
        @(posedge clk) $stable(ctrl) && (ctrl == 1'b0) && $changed(D1) |-> $stable(S)
    );

    // With ctrl stable at 1, changes on D0 must not affect S.
    check_ignore_unselected_D0: assert property (
        @(posedge clk) $stable(ctrl) && (ctrl == 1'b1) && $changed(D0) |-> $stable(S)
    );

    // With ctrl stable at 0, changes on D0 must propagate to S.
    check_selected_input_propagates_low: assert property (
        @(posedge clk) $stable(ctrl) && (ctrl == 1'b0) && $changed(D0) |-> $changed(S)
    );

    // With ctrl stable at 1, changes on D1 must propagate to S.
    check_selected_input_propagates_high: assert property (
        @(posedge clk) $stable(ctrl) && (ctrl == 1'b1) && $changed(D1) |-> $changed(S)
    );
endmodule

rtl:
module sky130_fd_sc_hd__and2 (
    X,
    A,
    B
);

    output X;
    input  A;
    input  B;

    wire and0_out_X;

    and and0 (and0_out_X, A, B           );
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_hd__and2_sva (
    input logic CLK,
    input logic X,
    input logic A,
    input logic B
);
    // X equals A AND B each cycle.
    check_and_equivalence: assert property (
        @(posedge CLK) X == (A & B)
    );

    // If X is HIGH, both inputs are HIGH.
    check_x_high_implies_inputs_high: assert property (
        @(posedge CLK) (X == 1'b1) |-> (A == 1'b1) && (B == 1'b1)
    );

    // If A is LOW, X must be LOW.
    check_a_low_forces_x_low: assert property (
        @(posedge CLK) (A == 1'b0) |-> (X == 1'b0)
    );

    // If B is LOW, X must be LOW.
    check_b_low_forces_x_low: assert property (
        @(posedge CLK) (B == 1'b0) |-> (X == 1'b0)
    );

    // If both inputs are HIGH, X must be HIGH.
    check_inputs_high_force_x_high: assert property (
        @(posedge CLK) (A == 1'b1 && B == 1'b1) |-> (X == 1'b1)
    );

    // Output rises only when at least one input rises.
    check_x_rise_requires_input_rise: assert property (
        @(posedge CLK) $rose(X) |-> ($rose(A) || $rose(B))
    );

    // When X rises, both inputs are HIGH that cycle.
    check_x_rise_inputs_high_now: assert property (
        @(posedge CLK) $rose(X) |-> (A == 1'b1) && (B == 1'b1)
    );

    // Output falls only when at least one input falls.
    check_x_fall_requires_input_fall: assert property (
        @(posedge CLK) $fell(X) |-> ($fell(A) || $fell(B))
    );

    // When X falls, at least one input is LOW that cycle.
    check_x_fall_inputs_low_now: assert property (
        @(posedge CLK) $fell(X) |-> (!A || !B)
    );

    // If both inputs are stable, the output is stable.
    check_stability_with_stable_inputs: assert property (
        @(posedge CLK) ($stable(A) && $stable(B)) |-> $stable(X)
    );

    // Output changes only if some input changes.
    check_x_change_requires_input_change: assert property (
        @(posedge CLK) $changed(X) |-> ($changed(A) || $changed(B))
    );
endmodule

rtl:
module nor_gate (
    input a,
    input b,
    output out
);

wire nand1_out, nand2_out;

nand nand1 (nand1_out, a, a);
nand nand2 (nand2_out, b, b);
nand nand3 (out, nand1_out, nand2_out);

endmodule

sva:
module nor_gate_sva (
    input logic a,
    input logic b,
    input logic out
);
    // Note: No clock/reset in RTL; combinational logic; sample on any edge of a or b.

    // Functional equivalence: out equals a OR b.
    check_out_is_or: assert property (
        @(posedge a or negedge a or posedge b or negedge b) out == (a | b)
    );

    // De Morgan form: out equals ~(~a & ~b).
    check_demorgan_equiv: assert property (
        @(posedge a or negedge a or posedge b or negedge b) out == ~(~a & ~b)
    );

    // When both inputs are 0, out must be 0.
    check_both_zero_out_zero: assert property (
        @(posedge a or negedge a or posedge b or negedge b) (!a && !b) |-> (out == 1'b0)
    );

    // When a is 1, out must be 1.
    check_a_high_out_high: assert property (
        @(posedge a or negedge a or posedge b or negedge b) (a == 1'b1) |-> (out == 1'b1)
    );

    // When b is 1, out must be 1.
    check_b_high_out_high: assert property (
        @(posedge a or negedge a or posedge b or negedge b) (b == 1'b1) |-> (out == 1'b1)
    );

    // If out is 0, both inputs must be 0.
    check_out_zero_implies_inputs_zero: assert property (
        @(posedge a or negedge a or posedge b or negedge b) (out == 1'b0) |-> (!a && !b)
    );

endmodule

rtl:
module sky130_fd_sc_ms__o32a (
    X ,
    A1,
    A2,
    A3,
    B1,
    B2
);

    output X ;
    input  A1;
    input  A2;
    input  A3;
    input  B1;
    input  B2;

    wire or0_out   ;
    wire or1_out   ;
    wire and0_out_X;

    or  or0  (or0_out   , A2, A1, A3      );
    or  or1  (or1_out   , B2, B1          );
