module counterB (
    output reg [3:0] cntB_reg, // Registered version of cntA
    input decrementB, // 0=Up-counting, 1=down-counting
    input dual_countB, // Advance counter by 2 steps at a time
    input cntB_en, // Enable counter B
    input clk, // Clock
    input rst // Synchronous reset
);

    // Counter B - tried to write sequential only, but ended up without
    // SystemVerilog.

    always @(posedge clk) begin
        if (rst)
            cntB_reg <= 4'b0000;
        else if (cntB_en) begin
            if (decrementB) begin
                if (dual_countB)
                    cntB_reg <= cntB_reg - 2;
                else
                    cntB_reg <= cntB_reg - 1;
            end
            else begin
                if (dual_countB)
                    cntB_reg <= cntB_reg + 2;
                else
                    cntB_reg <= cntB_reg + 1;
            end
        end
    end // always @

endmodule

sva:
module counterB_sva (
    input logic [3:0] cntB_reg,
    input logic decrementB,
    input logic dual_countB,
    input logic cntB_en,
    input logic clk,
    input logic rst
);
    // Synchronous reset drives cntB_reg to zero.
    reset_clears_cntB: assert property (
        @(posedge clk) rst |-> (cntB_reg == 4'b0000)
    );

    // When disabled, cntB_reg holds its previous value.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) (!cntB_en) |-> (cntB_reg == $past(cntB_reg))
    );

    // Any state change requires enable to be high.
    update_requires_enable: assert property (
        @(posedge clk) disable iff (rst) (cntB_reg != $past(cntB_reg)) |-> cntB_en
    );

    // Enabled up-count single-step: +1 modulo 16.
    inc_by1_when_enabled_up_single: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && !decrementB && !dual_countB) |-> (cntB_reg == ($past(cntB_reg) + 4'd1))
    );

    // Enabled up-count dual-step: +2 modulo 16.
    inc_by2_when_enabled_up_dual: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && !decrementB && dual_countB) |-> (cntB_reg == ($past(cntB_reg) + 4'd2))
    );

    // Enabled down-count single-step: -1 modulo 16.
    dec_by1_when_enabled_down_single: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && decrementB && !dual_countB) |-> (cntB_reg == ($past(cntB_reg) - 4'd1))
    );

    // Enabled down-count dual-step: -2 modulo 16.
    dec_by2_when_enabled_down_dual: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && decrementB && dual_countB) |-> (cntB_reg == ($past(cntB_reg) - 4'd2))
    );

    // Wrap: up-count single-step from 0xF goes to 0x0.
    wrap_up_single_from_F: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && !decrementB && !dual_countB && ($past(cntB_reg) == 4'hF)) |-> (cntB_reg == 4'h0)
    );

    // Wrap: up-count dual-step from 0xE goes to 0x0.
    wrap_up_dual_from_E: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && !decrementB && dual_countB && ($past(cntB_reg) == 4'hE)) |-> (cntB_reg == 4'h0)
    );

    // Wrap: down-count single-step from 0x0 goes to 0xF.
    wrap_down_single_from_0: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && decrementB && !dual_countB && ($past(cntB_reg) == 4'h0)) |-> (cntB_reg == 4'hF)
    );

    // Wrap: down-count dual-step from 0x0 goes to 0xE.
    wrap_down_dual_from_0: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && decrementB && dual_countB && ($past(cntB_reg) == 4'h0)) |-> (cntB_reg == 4'hE)
    );

    // Wrap: down-count dual-step from 0x1 goes to 0xF.
    wrap_down_dual_from_1: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && decrementB && dual_countB && ($past(cntB_reg) == 4'h1)) |-> (cntB_reg == 4'hF)
    );
endmodule

module mux16_sva #(
    parameter W = 1
) (
    input logic CLK,
    input logic RESETn,
    input logic [3:0] sel,
    input logic [W-1:0]
        i1111,
        i1110,
        i1101,
        i1100,
        i1011,
        i1010,
        i1001,
        i1000,
        i0111,
        i0110,
        i0101,
        i0100,
        i0011,
        i0010,
        i0001,
        i0000,
    input logic [W-1:0] o
);

    ///// 16:1 mux selection mapping /////
    // When sel==0, output equals i0000.
    sel_0_maps_to_i0000: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd0) |-> (o == i0000)
    );
    // When sel==1, output equals i0001.
    sel_1_maps_to_i0001: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd1) |-> (o == i0001)
    );
    // When sel==2, output equals i0010.
    sel_2_maps_to_i0010: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd2) |-> (o == i0010)
    );
    // When sel==3, output equals i0011.
    sel_3_maps_to_i0011: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd3) |-> (o == i0011)
    );
    // When sel==4, output equals i0100.
    sel_4_maps_to_i0100: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd4) |-> (o == i0100)
    );
    // When sel==5, output equals i0101.
    sel_5_maps_to_i0101: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd5) |-> (o == i0101)
    );
    // When sel==6, output equals i0110.
    sel_6_maps_to_i0110: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd6) |-> (o == i0110)
    );
    // When sel==7, output equals i0111.
    sel_7_maps_to_i0111: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd7) |-> (o == i0111)
    );
    // When sel==8, output equals i1000.
    sel_8_maps_to_i1000: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd8) |-> (o == i1000)
    );
    // When sel==9, output equals i1001.
    sel_9_maps_to_i1001: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd9) |-> (o == i1001)
    );
    // When sel==10, output equals i1010.
    sel_10_maps_to_i1010: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd10) |-> (o == i1010)
    );
    // When sel==11, output equals i1011.
    sel_11_maps_to_i1011: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd11) |-> (o == i1011)
    );
    // When sel==12, output equals i1100.
    sel_12_maps_to_i1100: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd12) |-> (o == i1100)
    );
    // When sel==13, output equals i1101.
    sel_13_maps_to_i1101: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd13) |-> (o == i1101)
    );
    // When sel==14, output equals i1110.
    sel_14_maps_to_i1110: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd14) |-> (o == i1110)
    );
    // When sel==15, output equals i1111 (default case).
    sel_15_maps_to_i1111: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd15) |-> (o == i1111)
    );

    ///// Combinational stability /////
    // If sel and all inputs are stable over a cycle, o is stable too.
    stable_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (!RESETn)
            $stable(sel) &&
            $stable(i0000) && $stable(i0001) && $stable(i0010) && $stable(i0011) &&
            $stable(i0100) && $stable(i0101) && $stable(i0110) && $stable(i0111) &&
            $stable(i1000) && $stable(i1001) && $stable(i1010) && $stable(i1011) &&
            $stable(i1100) && $stable(i1101) && $stable(i1110) && $stable(i1111)
            |-> $stable(o)
    );

endmodule

rtl:
module sky130_fd_sc_lp__sleep_pargate_plv (
    input  SLEEP  ,
    output VIRTPWR
);

    // Voltage supply signals
    supply1 VPWR;
    supply1 VPB ;
    supply0 VNB ;

    assign VPWR = SLEEP ? 1'b0 : 1'b1;
    assign VPB = SLEEP ? 1'b0 : 1'b1;
    assign VNB = 1'b0;
    assign VIRTPWR = SLEEP ? 1'b0 : 1'b1;

endmodule

sva:
module sky130_fd_sc_lp__sleep_pargate_plv_sva (
    input logic SLEEP,
    input logic VIRTPWR
);
    // No clock/reset in DUT; pure combinational logic
    // Behavior: VIRTPWR = ~SLEEP (active-high sleep forces power low)
    // Properties are sampled on edges of SLEEP/VIRTPWR

    // VIRTPWR must always be the inverse of SLEEP at any transition.
    check_virtpwr_complements_sleep: assert property (
        @(posedge SLEEP or negedge SLEEP or posedge VIRTPWR or negedge VIRTPWR)
        (VIRTPWR == ~SLEEP)
    );

    // When SLEEP rises, VIRTPWR must be LOW immediately.
    check_sleep_rise_forces_virtpwr_low: assert property (
        @(posedge SLEEP) (VIRTPWR == 1'b0)
    );

    // When SLEEP falls, VIRTPWR must be HIGH immediately.
    check_sleep_fall_forces_virtpwr_high: assert property (
        @(negedge SLEEP) (VIRTPWR == 1'b1)
    );

    // When VIRTPWR rises, SLEEP must be LOW.
    check_virtpwr_rise_implies_sleep_low: assert property (
        @(posedge VIRTPWR) (SLEEP == 1'b0)
    );

    // When VIRTPWR falls, SLEEP must be HIGH.
    check_virtpwr_fall_implies_sleep_high: assert property (
        @(negedge VIRTPWR) (SLEEP == 1'b1)
    );

    // SLEEP and VIRTPWR cannot both be HIGH.
    check_no_both_high: assert property (
        @(posedge SLEEP or negedge SLEEP or posedge VIRTPWR or negedge VIRTPWR)
        !(SLEEP && VIRTPWR)
    );

    // SLEEP and VIRTPWR cannot both be LOW.
    check_no_both_low: assert property (
        @(posedge SLEEP or negedge SLEEP or posedge VIRTPWR or negedge VIRTPWR)
        !((SLEEP == 1'b0) && (VIRTPWR == 1'b0))
    );

endmodule

rtl:
module DEMUX (
  input in,
  input [1:0] sel,
  output reg [3:0] out
);

parameter n = 2; // number of select bits
parameter m = 4; // number of output signals (2^n)

// Implement the decoding logic using a case statement
always @(*) begin
  case(sel)
    2'b00: out = {in, 3'b000};
    2'b01: out = {3'b000, in};
    2'b10: out = {2'b00, in, 1'b0};
    2'b11: out = {1'b0, in, 2'b00};
    default: out = 4'b0000; // set all output lines to 0 if sel is out of range
  endcase
end

endmodule

sva:
module DEMUX_sva (
    input logic CLK,
    input logic in,
    input logic [1:0] sel,
    input logic [3:0] out
);
    // DEMUX is purely combinational with no reset; assertions are sampled on CLK.

    // For sel==2'b00, out == {in, 3'b000}.
    demux_map_sel00: assert property (
        @(posedge CLK) (sel == 2'b00) |-> (out == {in, 3'b000})
    );

    // For sel==2'b01, out == {3'b000, in}.
    demux_map_sel01: assert property (
        @(posedge CLK) (sel == 2'b01) |-> (out == {3'b000, in})
    );

    // For sel==2'b10, out == {2'b00, in, 1'b0}.
    demux_map_sel10: assert property (
        @(posedge CLK) (sel == 2'b10) |-> (out == {2'b00, in, 1'b0})
    );

    // For sel==2'b11, out == {1'b0, in, 2'b00}.
    demux_map_sel11: assert property (
        @(posedge CLK) (sel == 2'b11) |-> (out == {1'b0, in, 2'b00})
    );

    // Outputs are one-hot or all zero.
    demux_onehot_or_zero: assert property (
        @(posedge CLK) $onehot0(out)
    );

    // When in is 0, all outputs are 0.
    demux_zero_when_in0: assert property (
        @(posedge CLK) (in == 1'b0) |-> (out == 4'b0000)
    );

    // When in is 1, at least one output is 1.
    demux_nonzero_when_in1: assert property (
        @(posedge CLK) (in == 1'b1) |-> (out != 4'b0000)
    );

    // OR-reduce of out equals in.
    demux_or_reduce_matches_in: assert property (
        @(posedge CLK) ((|out) == in)
    );

    // out[3] can be 1 only when sel==2'b00 and in==1.
    demux_out3_only_when_sel00_in1: assert property (
        @(posedge CLK) (out[3] == 1'b1) |-> ((sel == 2'b00) && (in == 1'b1))
    );

    // out[2] can be 1 only when sel==2'b11 and in==1.
    demux_out2_only_when_sel11_in1: assert property (
        @(posedge CLK) (out[2] == 1'b1) |-> ((sel == 2'b11) && (in == 1'b1))
    );

    // out[1] can be 1 only when sel==2'b10 and in==1.
    demux_out1_only_when_sel10_in1: assert property (
        @(posedge CLK) (out[1] == 1'b1) |-> ((sel == 2'b10) && (in == 1'b1))
    );

    // out[0] can be 1 only when sel==2'b01 and in==1.
    demux_out0_only_when_sel01_in1: assert property (
        @(posedge CLK) (out[0] == 1'b1) |-> ((sel == 2'b01) && (in == 1'b1))
    );

endmodule

rtl:
module num_to_digits(input[11:0] _num, output[3:0] _thousands, output [3:0] _hundreds, output [3:0] _tens, output [3:0] _ones);
    assign _thousands = (_num % 10000) / 1000;
    assign _hundreds = (_num % 1000) / 100;
    assign _tens = (_num % 100) / 10;
    assign _ones = _num % 10;
endmodule

sva:
module num_to_digits_sva (
    input  logic        clk,
    input  logic [11:0] _num,
    input  logic [3:0]  _thousands,
    input  logic [3:0]  _hundreds,
    input  logic [3:0]  _tens,
    input  logic [3:0]  _ones
);
    // Thousands equals (_num % 10000)/1000.
    check_thousands_calc: assert property (
        @(posedge clk) disable iff (1'b0)
        _thousands == ((_num % 14'd10000) / 10'd1000)
    );

    // Hundreds equals (_num % 1000)/100.
    check_hundreds_calc: assert property (
        @(posedge clk) disable iff (1'b0)
        _hundreds == ((_num % 10'd1000) / 7'd100)
    );

    // Tens equals (_num % 100)/10.
    check_tens_calc: assert property (
        @(posedge clk) disable iff (1'b0)
        _tens == ((_num % 7'd100) / 4'd10)
    );

    // Ones equals _num % 10.
    check_ones_calc: assert property (
        @(posedge clk) disable iff (1'b0)
        _ones == (_num % 4'd10)
    );

    // Thousands digit is in 0..9.
    check_thousands_range: assert property (
        @(posedge clk) disable iff (1'b0)
        _thousands <= 4'd9
    );

    // Hundreds digit is in 0..9.
    check_hundreds_range: assert property (
        @(posedge clk) disable iff (1'b0)
        _hundreds <= 4'd9
    );

    // Tens digit is in 0..9.
    check_tens_range: assert property (
        @(posedge clk) disable iff (1'b0)
        _tens <= 4'd9
    );

    // Ones digit is in 0..9.
    check_ones_range: assert property (
        @(posedge clk) disable iff (1'b0)
        _ones <= 4'd9
    );

    // Recomposition: 1000*T + 100*H + 10*D + O equals _num % 10000.
    check_decimal_recomposition: assert property (
        @(posedge clk) disable iff (1'b0)
        ((((_thousands * 4'd10) + _hundreds) * 4'd10 + _tens) * 4'd10 + _ones) == (_num % 14'd10000)
    );

    // For _num < 1000, thousands must be 0.
    check_thousands_zero_below_1000: assert property (
        @(posedge clk) disable iff (1'b0)
        (_num < 10'd1000) |-> (_thousands == 4'd0)
    );

    // For _num < 100, hundreds must be 0.
    check_hundreds_zero_below_100: assert property (
        @(posedge clk) disable iff (1'b0)
        (_num < 7'd100) |-> (_hundreds == 4'd0)
    );

    // For _num < 10, tens must be 0.
    check_tens_zero_below_10: assert property (
        @(posedge clk) disable iff (1'b0)
        (_num < 4'd10) |-> (_tens == 4'd0)
    );
endmodule

rtl:
module priority_encoder_4to2 (
    input a,
    input b,
    input c,
    input d,
    output x,
    output y
);

    assign x = (a) ? 2'b00 : (b) ? 2'b01 : (c) ? 2'b10 : (d) ? 2'b11 : 2'b00;
    assign y = (a) ? 2'b00 : (b) ? 2'b00 : (c) ? 2'b01 : (d) ? 2'b01 : 2'b00;

endmodule

sva:
module priority_encoder_4to2_sva (
    input logic CLK,
    input logic a,
    input logic b,
    input logic c,
    input logic d,
    input logic x,
    input logic y
);
    // When a is high, output is 00 regardless of others.
    check_a_selects_00: assert property (
        @(posedge CLK) a |-> (x == 1'b0) && (y == 1'b0)
    );

    // When a is low and b is high, output is 10.
    check_b_selects_10: assert property (
        @(posedge CLK) (!a && b) |-> (x == 1'b1) && (y == 1'b0)
    );

    // When a and b are low and c is high, output is 01.
    check_c_selects_01: assert property (
        @(posedge CLK) (!a && !b && c) |-> (x == 1'b0) && (y == 1'b1)
    );

    // When a,b,c are low and d is high, output is 11.
    check_d_selects_11: assert property (
        @(posedge CLK) (!a && !b && !c && d) |-> (x == 1'b1) && (y == 1'b1)
    );

    // When all inputs are low, output is 00.
    check_none_selects_00: assert property (
        @(posedge CLK) (!a && !b && !c && !d) |-> (x == 1'b0) && (y == 1'b0)
    );

    // b has priority over c when a is low.
    check_b_overrides_c: assert property (
        @(posedge CLK) (!a && b && c) |-> (x == 1'b1) && (y == 1'b0)
    );

    // c has priority over d when a and b are low.
    check_c_overrides_d: assert property (
        @(posedge CLK) (!a && !b && c && d) |-> (x == 1'b0) && (y == 1'b1)
    );

    // x matches the RTL's LSB mapping.
    check_x_functional_equiv: assert property (
        @(posedge CLK) x == (a ? 1'b0 : b ? 1'b1 : c ? 1'b0 : d ? 1'b1 : 1'b0)
    );

    // y matches the RTL's mapping.
    check_y_functional_equiv: assert property (
        @(posedge CLK) y == (a ? 1'b0 : b ? 1'b0 : c ? 1'b1 : d ? 1'b1 : 1'b0)
    );

    // If y is 1, either c is selected or d is selected with higher-priority inputs low.
    check_y_one_implies_c_or_d: assert property (
        @(posedge CLK) y |-> ((!a && !b && c) || (!a && !b && !c && d))
    );
endmodule

rtl:
module and_gate(input a, b, c, output out);
  wire and_output;

  and3_gate and3_inst(.a(a), .b(b), .c(c), .out(and_output));
  or2_gate or2_inst(.a(and_output), .b(c), .out(out));

endmodule

module and3_gate(input a, b, c, output out);
  assign out = a & b & c;
endmodule

module or2_gate(input a, b, output out);
  assign out = a | b;
endmodule

sva:
module and_gate_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic c,
    input logic out
);
    // Analysis: no clock/reset in RTL; pure combinational; out = (a & b & c) | c = c.

    // out must always equal c.
    check_out_equals_c: assert property (
        @(posedge clk) disable iff (1'b0) out == c
    );

    // When c is 1, out must be 1.
    check_out_high_when_c_high: assert property (
        @(posedge clk) disable iff (1'b0) (c == 1'b1) |-> (out == 1'b1)
    );

    // When c is 0, out must be 0.
    check_out_low_when_c_low: assert property (
        @(posedge clk) disable iff (1'b0) (c == 1'b0) |-> (out == 1'b0)
    );

    // A rising edge on c must produce a rising edge on out in the same cycle.
    check_out_rise_follows_c_rise: assert property (
        @(posedge clk) disable iff (1'b0) $rose(c) |-> $rose(out)
    );

    // A falling edge on c must produce a falling edge on out in the same cycle.
    check_out_fall_follows_c_fall: assert property (
        @(posedge clk) disable iff (1'b0) $fell(c) |-> $fell(out)
    );

    // out cannot rise unless c rises.
    check_no_spurious_out_rise: assert property (
        @(posedge clk) disable iff (1'b0) $rose(out) |-> $rose(c)
    );

    // out cannot fall unless c falls.
    check_no_spurious_out_fall: assert property (
        @(posedge clk) disable iff (1'b0) $fell(out) |-> $fell(c)
    );

    // If c is stable across cycles, out must also be stable.
    check_out_stable_when_c_stable: assert property (
        @(posedge clk) disable iff (1'b0) $stable(c) |-> $stable(out)
    );

    // Toggling a while c is stable must not change out.
    check_a_toggle_no_effect_when_c_stable: assert property (
        @(posedge clk) disable iff (1'b0) ($changed(a) && $stable(c)) |-> $stable(out)
    );

    // Toggling b while c is stable must not change out.
    check_b_toggle_no_effect_when_c_stable: assert property (
        @(posedge clk) disable iff (1'b0) ($changed(b) && $stable(c)) |-> $stable(out)
    );
endmodule

rtl:
module master_slave_ff ( input clk, input d, output reg q );
    always @(posedge clk)
        q <= d;
endmodule

module shift_register ( input clk, input d, output q );
    wire q1, q2, q3;
    master_slave_ff ff1(clk, d, q1);
    master_slave_ff ff2(clk, q1, q2);
    master_slave_ff ff3(clk, q2, q3);
    assign q = q3;
endmodule

module top_module ( input clk, input d, output q );
    shift_register sr(clk, d, q);
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic d,
    input logic q
);

    ///// 3-cycle shift behavior /////
    // q equals d delayed by 3 cycles once history is available.
    check_three_cycle_delay: assert property (
        @(posedge clk) (!$isunknown($past(d,3))) |-> (q == $past(d,3))
    );

    // A rising edge on d is followed by a rising edge on q after 3 cycles.
    check_rise_propagates_3: assert property (
        @(posedge clk) $rose(d) |-> ##3 $rose(q)
    );

    // A falling edge on d is followed by a falling edge on q after 3 cycles.
    check_fall_propagates_3: assert property (
        @(posedge clk) $fell(d) |-> ##3 $fell(q)
    );

    // q changes only if d changed 3 cycles earlier (with sufficient history).
    check_q_change_requires_d_change_3ago: assert property (
        @(posedge clk) ($changed(q) && !$isunknown($past(d,3)) && !$isunknown($past(d,4))) |-> $past($changed(d),3)
    );

    // If d changed 3 cycles ago (with sufficient history), q must change now.
    check_d_change_3ago_causes_q_change: assert property (
        @(posedge clk) ($past($changed(d),3) && !$isunknown($past(d,3)) && !$isunknown($past(d,4))) |-> $changed(q)
    );

    // If d was unchanged between 4 and 3 cycles ago, q must be stable now.
    check_q_stable_when_past_d_unchanged: assert property (
        @(posedge clk) (!$isunknown($past(d,3)) && !$isunknown($past(d,4)) && ($past(d,3) == $past(d,4))) |-> $stable(q)
    );

endmodule

