sva:
module sky130_fd_sc_ls__a22oi_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2
);
    // Functional equivalence: Y == ~((A1 & A2) | (B1 & B2))
    check_functional_equivalence: assert property (
        @(posedge clk) disable iff (1'b0) Y == ~((A1 & A2) | (B1 & B2))
    );

    // Y must be LOW if either A-pair or B-pair is HIGH
    check_y_low_when_any_pair_high: assert property (
        @(posedge clk) disable iff (1'b0) ((A1 & A2) || (B1 & B2)) |-> (Y == 1'b0)
    );

    // Y must be HIGH if both A-pair and B-pair are not HIGH
    check_y_high_when_no_pair_high: assert property (
        @(posedge clk) disable iff (1'b0) (!(A1 & A2) && !(B1 & B2)) |-> (Y == 1'b1)
    );

    // A-pair HIGH alone forces Y LOW
    check_y_low_when_a_pair_high: assert property (
        @(posedge clk) disable iff (1'b0) (A1 & A2) |-> (Y == 1'b0)
    );

    // B-pair HIGH alone forces Y LOW
    check_y_low_when_b_pair_high: assert property (
        @(posedge clk) disable iff (1'b0) (B1 & B2) |-> (Y == 1'b0)
    );

    // If A2=0 and B2=0, Y must be HIGH regardless of A1/B1
    check_y_high_when_a2_b2_zero: assert property (
        @(posedge clk) disable iff (1'b0) (!A2 && !B2) |-> (Y == 1'b1)
    );

    // If A1=0 and B1=0, Y must be HIGH regardless of A2/B2
    check_y_high_when_a1_b1_zero: assert property (
        @(posedge clk) disable iff (1'b0) (!A1 && !B1) |-> (Y == 1'b1)
    );

    // A1 rising with A2=1 and B-pair=0 causes Y to FALL
    check_a1_rise_causes_y_fall: assert property (
        @(posedge clk) disable iff (1'b0)
            $rose(A1) && A2 && $past(A2) && !(B1 & B2) && !$past(B1 & B2) |-> $fell(Y)
    );

    // A1 falling with A2=1 and B-pair=0 causes Y to RISE
    check_a1_fall_causes_y_rise: assert property (
        @(posedge clk) disable iff (1'b0)
            $fell(A1) && A2 && $past(A2) && !(B1 & B2) && !$past(B1 & B2) |-> $rose(Y)
    );

    // A2 rising with A1=1 and B-pair=0 causes Y to FALL
    check_a2_rise_causes_y_fall: assert property (
        @(posedge clk) disable iff (1'b0)
            $rose(A2) && A1 && $past(A1) && !(B1 & B2) && !$past(B1 & B2) |-> $fell(Y)
    );

    // A2 falling with A1=1 and B-pair=0 causes Y to RISE
    check_a2_fall_causes_y_rise: assert property (
        @(posedge clk) disable iff (1'b0)
            $fell(A2) && A1 && $past(A1) && !(B1 & B2) && !$past(B1 & B2) |-> $rose(Y)
    );
endmodule

rtl:
module adder_4bit(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C_out
);

    wire [3:0] C;

    full_adder fa0(
        .A(A[0]),
        .B(B[0]),
        .C_in(1'b0),
        .S(S[0]),
        .C_out(C[0])
    );

    full_adder fa1(
        .A(A[1]),
        .B(B[1]),
        .C_in(C[0]),
        .S(S[1]),
        .C_out(C[1])
    );

    full_adder fa2(
        .A(A[2]),
        .B(B[2]),
        .C_in(C[1]),
        .S(S[2]),
        .C_out(C[2])
    );

    full_adder fa3(
        .A(A[3]),
        .B(B[3]),
        .C_in(C[2]),
        .S(S[3]),
        .C_out(C_out)
    );

endmodule

module full_adder(
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

    assign S = A ^ B ^ C_in;
    assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

sva:
module adder_4bit_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic C_out
);
    ///// Functional equivalence to addition /////
    // The 5-bit result equals zero-extended A + B.
    check_sum_matches_addition: assert property (
        @(posedge clk) {C_out, S} == ({1'b0, A} + {1'b0, B})
    );

    ///// Bit 0 (no carry-in) /////
    // LSB sum equals A0 XOR B0.
    check_s0_no_cin: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    ///// Bit 1 with carry from bit 0 /////
    // Bit1 sum equals A1 XOR B1 XOR (A0 & B0).
    check_s1_with_c0: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );
    // If no carry from bit0, S1 is A1 XOR B1.
    check_s1_when_c0_zero: assert property (
        @(posedge clk) (~(A[0] & B[0])) |-> (S[1] == (A[1] ^ B[1]))
    );
    // If carry from bit0, S1 is inverted XOR of A1 and B1.
    check_s1_when_c0_one: assert property (
        @(posedge clk) (A[0] & B[0]) |-> (S[1] == ~(A[1] ^ B[1]))
    );

    ///// Bit 2 with ripple carry /////
    // Bit2 sum equals A2 XOR B2 XOR C1 (expanded C1).
    check_s2_with_c1: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))
    );
    // If C0==0 and A1==B1, then C1==A1&B1 so S2==A2 XOR B2 XOR (A1&B1).
    check_s2_c1_reduction: assert property (
        @(posedge clk) (~(A[0] & B[0]) && (A[1] == B[1])) |-> (S[2] == (A[2] ^ B[2] ^ (A[1] & B[1])))
    );
    // If C0==1 and (A1^B1)==1, then C1==1 so S2==~(A2^B2).
    check_s2_when_carry_generate: assert property (
        @(posedge clk) ((A[0] & B[0]) && (A[1] ^ B[1])) |-> (S[2] == ~(A[2] ^ B[2]))
    );

    ///// Bit 3 with ripple carry /////
    // Bit3 sum equals A3 XOR B3 XOR C2 (expanded C2).
    check_s3_with_c2: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))))
    );

    ///// Final carry-out /////
    // C_out equals C3 (expanded from ripple logic).
    check_cout_with_c3: assert property (
        @(posedge clk) C_out == ((A[3] & B[3]) | ((A[3] ^ B[3]) & ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0])))))))
    );
    // If MSB inputs are both 1, C_out must be 1.
    check_cout_when_msb_both_one: assert property (
        @(posedge clk) (A[3] & B[3]) |-> (C_out == 1'b1)
    );
    // If MSB inputs are both 0, C_out must be 0.
    check_cout_when_msb_both_zero: assert property (
        @(posedge clk) (~A[3] & ~B[3]) |-> (C_out == 1'b0)
    );

    ///// Sanity and stability /////
    // Adding 0 + 0 yields 0 with no carry.
    check_zero_plus_zero: assert property (
        @(posedge clk) ((A == 4'b0000) && (B == 4'b0000)) |-> ((S == 4'b0000) && (C_out == 1'b0))
    );
    // Adding 15 + 15 yields 30 => S=14 and C_out=1.
    check_max_plus_max: assert property (
        @(posedge clk) ((A == 4'b1111) && (B == 4'b1111)) |-> ((S == 4'b1110) && (C_out == 1'b1))
    );
    // If inputs are stable cycle-to-cycle, outputs are stable (pure combinational).
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> ($stable(S) && $stable(C_out))
    );

endmodule

module sync_sva (
    input logic OutputClock,
    input logic reset_b,
    input logic InputData,
    input logic OutputData
);

    ///// Reset behavior /////
    // If reset was LOW in the previous cycle, OutputData must be 0 now.
    reset_prev_low_forces_zero_now: assert property (
        @(posedge OutputClock) $past(!reset_b) |-> (OutputData == 1'b0)
    );

    // If reset is LOW now, OutputData will be 0 on the next cycle.
    reset_low_forces_zero_next: assert property (
        @(posedge OutputClock) (!reset_b) |=> (OutputData == 1'b0)
    );

    // On the cycle reset_b rises, OutputData is 0.
    reset_release_cycle_zero: assert property (
        @(posedge OutputClock) $rose(reset_b) |-> (OutputData == 1'b0)
    );

    // While reset is held LOW across consecutive cycles, OutputData stays 0.
    reset_held_low_keeps_zero: assert property (
        @(posedge OutputClock) (!reset_b && $past(!reset_b)) |-> (OutputData == 1'b0)
    );

    ///// Active behavior /////
    // When not in reset and the previous cycle was also not in reset, OutputData is either 0 (due to any async reset between clocks) or equals the previous InputData.
    active_out_is_zero_or_prev_in: assert property (
        @(posedge OutputClock) disable iff (!reset_b)
            $past(reset_b) |-> ((OutputData == 1'b0) || (OutputData == $past(InputData)))
    );

    // After a reset release, if reset remains HIGH next cycle, OutputData captures InputData from the release cycle.
    capture_after_reset_release: assert property (
        @(posedge OutputClock) $rose(reset_b) |-> ##1 (!reset_b || (OutputData == $past(InputData)))
    );

endmodule

rtl:
module pipelined_or_gate(
    input a, 
    input b,
    input clk,  // Added clk as an input
    input reset,
    output reg out
);

reg stage1_out, stage2_out;

always @(posedge clk or posedge reset) begin  // Added reset to the sensitivity list
    if(reset) begin
        stage1_out <= 1'b0;
        stage2_out <= 1'b0;
        out <= 1'b0;
    end
    else begin
        stage1_out <= a | b;
        stage2_out <= stage1_out;
        out <= stage2_out;
    end
end

endmodule

sva:
module pipelined_or_gate_sva (
    input logic a,
    input logic b,
    input logic clk,
    input logic reset,
    input logic out,
    input logic stage1_out,
    input logic stage2_out
);
    // Clock: clk (posedge). Reset: reset (active-high, async in RTL). Logic: sequential 3-stage pipeline (stage1_out<=a|b, stage2_out<=stage1_out, out<=stage2_out).

    // On any clock where reset is HIGH, all pipeline registers are 0.
    check_reset_clears_pipeline: assert property (
        @(posedge clk) reset |-> (stage1_out == 1'b0) && (stage2_out == 1'b0) && (out == 1'b0)
    );

    // stage1_out equals OR of inputs from previous cycle when prior cycle wasn't in reset.
    check_stage1_captures_or_prev: assert property (
        @(posedge clk) disable iff (reset) !$past(reset) |-> (stage1_out == ($past(a) | $past(b)))
    );

    // stage2_out equals prior cycle's stage1_out when prior cycle wasn't in reset.
    check_stage2_captures_stage1_prev: assert property (
        @(posedge clk) disable iff (reset) !$past(reset) |-> (stage2_out == $past(stage1_out))
    );

    // out equals prior cycle's stage2_out when prior cycle wasn't in reset.
    check_out_captures_stage2_prev: assert property (
        @(posedge clk) disable iff (reset) !$past(reset) |-> (out == $past(stage2_out))
    );

    // stage2_out equals OR of inputs from previous cycle when prior cycle wasn't in reset.
    check_stage2_captures_or_prev: assert property (
        @(posedge clk) disable iff (reset) !$past(reset) |-> (stage2_out == ($past(a) | $past(b)))
    );

    // out equals OR of inputs from two cycles earlier when last two cycles weren't in reset.
    check_out_two_cycle_or: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset,1) && !$past(reset,2)) |-> (out == ($past(a,2) | $past(b,2)))
    );

    // One cycle after a reset cycle, all pipeline registers are still 0 before new updates.
    check_one_cycle_after_reset_holds_zero: assert property (
        @(posedge clk) disable iff (reset) $past(reset) |-> (stage1_out == 1'b0) && (stage2_out == 1'b0) && (out == 1'b0)
    );
endmodule

module myModule_sva (
    input logic [3:0] v0550b6,
    input logic [3:0] v24708e,
    input logic       v4642b6,
    input logic [3:0] v817794
);

    ///// Counter behavior on v4642b6 clock /////
    // Counter increments by 1 on each rising edge of v4642b6 (checked between consecutive edges).
    check_counter_increments: assert property (
        @(posedge v4642b6) 1'b1 |=> (v817794 == $past(v817794) + 4'd1)
    );
    // If counter is 15 on one edge, it wraps to 0 on the next edge.
    check_counter_wrap: assert property (
        @(posedge v4642b6) (v817794 == 4'hF) |=> (v817794 == 4'h0)
    );

    ///// Combinational select logic for v4642b6 /////
    // When sel=0000, v4642b6 equals v24708e[0].
    check_sel_0000: assert property (
        @(posedge v4642b6) (v0550b6 == 4'b0000) |-> (v4642b6 == v24708e[0])
    );
    // When sel=0001, v4642b6 equals v24708e[1].
    check_sel_0001: assert property (
        @(posedge v4642b6) (v0550b6 == 4'b0001) |-> (v4642b6 == v24708e[1])
    );
    // When sel=0010, v4642b6 equals v24708e[2].
    check_sel_0010: assert property (
        @(posedge v4642b6) (v0550b6 == 4'b0010) |-> (v4642b6 == v24708e[2])
    );
    // When sel=0011, v4642b6 equals v24708e[3].
    check_sel_0011: assert property (
        @(posedge v4642b6) (v0550b6 == 4'b0011) |-> (v4642b6 == v24708e[3])
    );
    // When sel=0100, v4642b6 equals v24708e[0] & v24708e[1].
