module and_gate (
    input A,
    input B,
    input C,
    output Y
);

    assign Y = A & B & C;

endmodule

sva:
module and_gate_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic Y
);
    // No clock/reset in RTL; pure combinational AND. Assertions sample on input posedges.

    // Y must equal A & B & C sampled on posedge A.
    check_y_matches_and_on_A: assert property (
        @(posedge A) Y == (A & B & C)
    );

    // Y must equal A & B & C sampled on posedge B.
    check_y_matches_and_on_B: assert property (
        @(posedge B) Y == (A & B & C)
    );

    // Y must equal A & B & C sampled on posedge C.
    check_y_matches_and_on_C: assert property (
        @(posedge C) Y == (A & B & C)
    );

    // When B and C are HIGH, Y follows A on posedge A.
    check_follow_A_when_BC_high: assert property (
        @(posedge A) (B && C) |-> (Y == A)
    );

    // When A and C are HIGH, Y follows B on posedge B.
    check_follow_B_when_AC_high: assert property (
        @(posedge B) (A && C) |-> (Y == B)
    );

    // When A and B are HIGH, Y follows C on posedge C.
    check_follow_C_when_AB_high: assert property (
        @(posedge C) (A && B) |-> (Y == C)
    );

    // If B is LOW, Y must be LOW on posedge A.
    check_y_zero_when_B_zero_on_A: assert property (
        @(posedge A) (!B) |-> (Y == 1'b0)
    );

    // If C is LOW, Y must be LOW on posedge A.
    check_y_zero_when_C_zero_on_A: assert property (
        @(posedge A) (!C) |-> (Y == 1'b0)
    );

    // If Y is HIGH on posedge B, A and C must be HIGH.
    check_y_high_implies_A_and_C_high_on_B: assert property (
        @(posedge B) Y |-> (A && C)
    );

    // If Y is HIGH on posedge C, A and B must be HIGH.
    check_y_high_implies_A_and_B_high_on_C: assert property (
        @(posedge C) Y |-> (A && B)
    );
endmodule

rtl:
module mux_3to4_enable (
  input clk,
  input reset,
  input enable,
  input [2:0] A,
  input [2:0] B,
  input [2:0] C,
  output reg [2:0] W,
  output reg [2:0] X,
  output reg [2:0] Y,
  output reg [2:0] Z
);

  always @(posedge clk) begin
    if (reset) begin
      W <= 3'b0;
      X <= 3'b0;
      Y <= 3'b0;
      Z <= 3'b0;
    end else begin
      if (enable) begin
        W <= A;
        X <= B;
        Y <= B;
        Z <= 3'b0;
      end else begin
        W <= 3'b0;
        X <= 3'b0;
        Y <= 3'b0;
        Z <= C;
      end
    end
  end

endmodule

sva:
module mux_3to4_enable_sva (
  input logic clk,
  input logic reset,
  input logic enable,
  input logic [2:0] A,
  input logic [2:0] B,
  input logic [2:0] C,
  input logic [2:0] W,
  input logic [2:0] X,
  input logic [2:0] Y,
  input logic [2:0] Z
);
  // Clock: clk; Reset: reset (active-high, synchronous)
  // Logic: sequential; outputs registered on posedge clk
  // Function: if enable then W=A, X=Y=B, Z=0; else W=X=Y=0, Z=C (visible next cycle)

  // Synchronous reset drives all outputs to zero on the next cycle.
  reset_clears_outputs_next: assert property (
    @(posedge clk) reset |=> (W == 3'b000) && (X == 3'b000) && (Y == 3'b000) && (Z == 3'b000)
  );

  // W next-cycle equals A when enable is 1, else 0.
  w_next_matches_enable: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (W == ($past(enable) ? $past(A) : 3'b000))
  );

  // X next-cycle equals B when enable is 1, else 0.
  x_next_matches_enable: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (X == ($past(enable) ? $past(B) : 3'b000))
  );

  // Y next-cycle equals B when enable is 1, else 0.
  y_next_matches_enable: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (Y == ($past(enable) ? $past(B) : 3'b000))
  );

  // Z next-cycle equals 0 when enable is 1, else C.
  z_next_matches_enable: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (Z == ($past(enable) ? 3'b000 : $past(C)))
  );

  // X and Y are always equal from the next cycle onward.
  x_equals_y_next_cycle: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (X == Y)
  );
endmodule

rtl:
module karnaugh_map(
  input A, B, C, D, E,
  output reg F
);

  always @(*) begin
    case ({A,B})
      2'b00: begin
        case ({C,D,E})
          3'b000, 3'b001, 3'b011, 3'b010: F = 1;
          3'b110, 3'b111, 3'b101, 3'b100: F = 0;
        endcase
      end
      2'b01: begin
        case ({C,D,E})
          3'b000, 3'b001, 3'b011, 3'b010: F = 1;
          3'b110, 3'b111, 3'b101, 3'b100: F = 0;
        endcase
      end
      2'b11: begin
        case ({C,D,E})
          3'b000, 3'b011, 3'b111, 3'b101: F = 0;
          3'b001, 3'b010, 3'b110, 3'b100: F = 1;
        endcase
      end
      2'b10: begin
        case ({C,D,E})
          3'b000, 3'b011, 3'b111, 3'b101: F = 0;
          3'b001, 3'b010, 3'b110, 3'b100: F = 1;
        endcase
      end
    endcase
  end

endmodule

sva:
module karnaugh_map_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic E,
    input logic F
);
    // No clock/reset in RTL; pure combinational; assertions use the formal $global_clock.

    // For A=0, F equals NOT C regardless of B,D,E.
    check_a0_inverts_C: assert property (
        @($global_clock) (A == 1'b0) |-> (F == ~C)
    );

    // For A=1 and E=0, F equals C OR D.
    check_a1_e0_is_C_or_D: assert property (
        @($global_clock) (A == 1'b1 && E == 1'b0) |-> (F == (C || D))
    );

    // For A=1 and E=1, F equals NOT C AND NOT D.
    check_a1_e1_is_notC_and_notD: assert property (
        @($global_clock) (A == 1'b1 && E == 1'b1) |-> (F == (~C && ~D))
    );

    // B has no functional effect: with A,C,D,E stable, toggling B leaves F unchanged.
    check_B_independence_fixed_inputs: assert property (
        @($global_clock) ($stable(A) && $stable(C) && $stable(D) && $stable(E) && (B != $past(B))) |-> (F == $past(F))
    );

    // Pure combinational behavior: if all inputs are stable, F must remain stable.
    check_stable_inputs_hold_F: assert property (
        @($global_clock) ((A == $past(A)) && (B == $past(B)) && (C == $past(C)) && (D == $past(D)) && (E == $past(E))) |-> (F == $past(F))
    );

    // For A=0, changes on D or E do not affect F when C (and B) are unchanged.
    check_a0_d_or_e_change_no_effect: assert property (
        @($global_clock) (A == 1'b0 && $stable(B) && $stable(C) && ((D != $past(D)) || (E != $past(E)))) |-> (F == $past(F))
    );

    // For A=1 and E=1, if either C or D is 1 then F must be 0.
    check_a1_e1_zero_if_C_or_D_one: assert property (
        @($global_clock) (A == 1'b1 && E == 1'b1 && (C || D)) |-> (F == 1'b0)
    );

    // For A=1 and E=1 with C=0 and D=0, F must be 1.
    check_a1_e1_one_if_C0_D0: assert property (
        @($global_clock) (A == 1'b1 && E == 1'b1 && (C == 1'b0) && (D == 1'b0)) |-> (F == 1'b1)
    );

    // For A=1 and E=0 with C=0 and D=0, F must be 0.
    check_a1_e0_zero_if_C0_D0: assert property (
        @($global_clock) (A == 1'b1 && E == 1'b0 && (C == 1'b0) && (D == 1'b0)) |-> (F == 1'b0)
    );

    // For A=1 and E=0, if C=1 or D=1 then F must be 1.
    check_a1_e0_one_if_C_or_D_one: assert property (
        @($global_clock) (A == 1'b1 && E == 1'b0 && (C || D)) |-> (F == 1'b1)
    );

endmodule

rtl:
module top_module (
    input clk,
    input slowena,
    input reset,
    input select,
    input a,
    input b,
    output reg out
);

reg [3:0] count;
wire xor_out;

// Decade counter
always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 4'b0000;
    end else if (slowena) begin
        count <= count;
    end else begin
        count <= count + 1;
    end
end

// XOR gate
assign xor_out = a ^ b;

// Control logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        out <= 1'b0;
    end else begin
        if (select) begin
            out <= xor_out;
        end else begin
            out <= count[3];
        end
    end
end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic slowena,
    input logic reset,
    input logic select,
    input logic a,
    input logic b,
    input logic out,
    input logic [3:0] count,
    input logic xor_out
);
    // Clock: clk. Reset: reset (active-high async in RTL). Mixed sequential/combinational logic.

    ///// Reset behavior /////
    // During reset, counter is 0.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );
    // During reset, out is 0.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 1'b0)
    );

    ///// XOR gate /////
    // xor_out equals a ^ b.
    check_xor_gate: assert property (
        @(posedge clk) disable iff (reset) xor_out == (a ^ b)
    );

    ///// Counter update rules /////
    // If previous cycle had slowena=1 (and not in reset), counter holds.
    check_count_hold_on_slowena: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) && $past(slowena) |-> (count == $past(count))
    );
    // If previous cycle had slowena=0 (and not in reset), counter increments by 1 (mod 16).
    check_count_inc_on_no_slowena: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) && !$past(slowena) |-> (count == ($past(count) + 4'd1))
    );
    // When incrementing from 15, counter wraps to 0.
    check_count_wrap_from_15: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) && !$past(slowena) && ($past(count) == 4'hF) |-> (count == 4'h0)
    );
    // Across cycles without reset, counter changes only by 0 or +1.
    check_count_step_0_or_1: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> ((count == $past(count)) || (count == ($past(count) + 4'd1)))
    );

    ///// Output selection /////
    // Out reflects previous-cycle mux: select ? xor_out : count[3].
    check_out_mux_function: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) |-> (out == ($past(select) ? $past(xor_out) : $past(count[3])))
    );
    // If XOR path was selected previously, out matches previous a ^ b.
    check_out_matches_xor_inputs: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) && $past(select) |-> (out == ($past(a) ^ $past(b)))
    );
    // If COUNT[3] path was selected previously, out matches previous count[3].
    check_out_matches_count_msb_path: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset)) && !$past(select) |-> (out == $past(count[3]))
    );
endmodule

