    assign read_2 = wire_2;
    assign read_3 = wire_3;
    assign read_4 = wire_4;
    assign read_5 = wire_5;

    always @(posedge CLK) begin
        if (RST_N == 0) begin
            r <= RESET_VAL;
        end else begin
            r <= wire_6;
        end
    end
endmodule

sva:
module EHR_6_sva #(
    parameter DATA_SZ   = 1,
    parameter RESET_VAL = 0
) (
    input logic                CLK,
    input logic                RST_N,
    input logic [DATA_SZ-1:0]  read_0,
    input logic [DATA_SZ-1:0]  write_0,
    input logic                EN_write_0,
    input logic [DATA_SZ-1:0]  read_1,
    input logic [DATA_SZ-1:0]  write_1,
    input logic                EN_write_1,
    input logic [DATA_SZ-1:0]  read_2,
    input logic [DATA_SZ-1:0]  write_2,
    input logic                EN_write_2,
    input logic [DATA_SZ-1:0]  read_3,
    input logic [DATA_SZ-1:0]  write_3,
    input logic                EN_write_3,
    input logic [DATA_SZ-1:0]  read_4,
    input logic [DATA_SZ-1:0]  write_4,
    input logic                EN_write_4,
    input logic [DATA_SZ-1:0]  read_5,
    input logic [DATA_SZ-1:0]  write_5,
    input logic                EN_write_5
);
    ///// Reset behavior /////
    // With reset asserted, next-cycle read_0 reflects RESET_VAL.
    reset_drives_read0_next: assert property (
        @(posedge CLK) !RST_N |-> (read_0 == RESET_VAL)
    );

    ///// Combinational read chain (priority mux) /////
    // read_1 selects write_0 when enabled, else read_0.
    chain_read1_mux: assert property (
        @(posedge CLK) disable iff (!RST_N) read_1 == (EN_write_0 ? write_0 : read_0)
    );
    // read_2 selects write_1 when enabled, else read_1.
    chain_read2_mux: assert property (
        @(posedge CLK) disable iff (!RST_N) read_2 == (EN_write_1 ? write_1 : read_1)
    );
    // read_3 selects write_2 when enabled, else read_2.
    chain_read3_mux: assert property (
        @(posedge CLK) disable iff (!RST_N) read_3 == (EN_write_2 ? write_2 : read_2)
    );
    // read_4 selects write_3 when enabled, else read_3.
    chain_read4_mux: assert property (
        @(posedge CLK) disable iff (!RST_N) read_4 == (EN_write_3 ? write_3 : read_3)
    );
    // read_5 selects write_4 when enabled, else read_4.
    chain_read5_mux: assert property (
        @(posedge CLK) disable iff (!RST_N) read_5 == (EN_write_4 ? write_4 : read_4)
    );

    ///// Sequential state update to r (observed via read_0) /////
    // When not in reset in the previous cycle, read_0 updates to (EN_write_5 ? write_5 : read_5) from the previous cycle.
    next_read0_general: assert property (
        @(posedge CLK) disable iff (!RST_N)
            $past(RST_N) |-> (read_0 == $past(EN_write_5 ? write_5 : read_5))
    );
    // With no writes in the previous cycle, read_0 holds its value.
    next_read0_holds_no_writes: assert property (
        @(posedge CLK) disable iff (!RST_N)
            $past(RST_N && !EN_write_0 && !EN_write_1 && !EN_write_2 && !EN_write_3 && !EN_write_4 && !EN_write_5)
            |-> (read_0 == $past(read_0))
    );

    ///// Priority update cases to r (highest to lowest) /////
    // If EN_write_5 was high, next read_0 equals write_5 from the previous cycle.
    next_read0_prio5: assert property (
        @(posedge CLK) disable iff (!RST_N)
            $past(RST_N && EN_write_5) |-> (read_0 == $past(write_5))
    );
    // If only EN_write_4 was the highest active, next read_0 equals write_4.
    next_read0_prio4: assert property (
        @(posedge CLK) disable iff (!RST_N)
            $past(RST_N && !EN_write_5 && EN_write_4) |-> (read_0 == $past(write_4))
    );
    // If only EN_write_3 was the highest active, next read_0 equals write_3.
    next_read0_prio3: assert property (
        @(posedge CLK) disable iff (!RST_N)
            $past(RST_N && !EN_write_5 && !EN_write_4 && EN_write_3) |-> (read_0 == $past(write_3))
    );
    // If only EN_write_2 was the highest active, next read_0 equals write_2.
    next_read0_prio2: assert property (
        @(posedge CLK) disable iff (!RST_N)
            $past(RST_N && !EN_write_5 && !EN_write_4 && !EN_write_3 && EN_write_2) |-> (read_0 == $past(write_2))
    );
    // If only EN_write_1 was the highest active, next read_0 equals write_1.
    next_read0_prio1: assert property (
        @(posedge CLK) disable iff (!RST_N)
            $past(RST_N && !EN_write_5 && !EN_write_4 && !EN_write_3 && !EN_write_2 && EN_write_1)
            |-> (read_0 == $past(write_1))
    );
    // If only EN_write_0 was the highest active, next read_0 equals write_0.
    next_read0_prio0: assert property (
        @(posedge CLK) disable iff (!RST_N)
            $past(RST_N && !EN_write_5 && !EN_write_4 && !EN_write_3 && !EN_write_2 && !EN_write_1 && EN_write_0)
            |-> (read_0 == $past(write_0))
    );
endmodule

module counter_sva (
    input logic clk,
    input logic LOAD,
    input logic RESET,      // Active-high synchronous reset
    input logic [1:0] DATA,
    input logic [1:0] Q
);
    // Clock: clk (posedge). Reset: RESET (active-high, synchronous).
    // Behavior: if RESET then Q<=0; else if LOAD then Q<=DATA; else Q<=Q+1 (2-bit wrap).

    // Synchronous reset drives Q to 0 on the next clock.
    reset_clears_q: assert property (
        @(posedge clk) RESET |=> (Q == 2'b00)
    );

    // Next-state matches RTL when not in reset: load has priority else increment.
    next_state_matches_rtl: assert property (
        @(posedge clk) disable iff (RESET)
            1'b1 |=> (Q == ($past(LOAD) ? $past(DATA) : ($past(Q) + 2'b01)))
    );

    // When LOAD is asserted (no reset), Q updates to DATA on the next clock.
    next_q_on_load: assert property (
        @(posedge clk) disable iff (RESET)
            LOAD |=> (Q == $past(DATA))
    );

    // When LOAD is deasserted (no reset), Q increments by 1 on the next clock.
    next_q_on_no_load_increment: assert property (
        @(posedge clk) disable iff (RESET)
            !LOAD |=> (Q == ($past(Q) + 2'b01))
    );

    // Increment wraps from 3 to 0 when LOAD is low (no reset).
    increment_wraps_at_3: assert property (
        @(posedge clk) disable iff (RESET)
            (!LOAD && (Q == 2'b11)) |=> (Q == 2'b00)
    );

    // With LOAD low for two cycles (no reset), Q increases by 2 over two clocks.
    two_cycle_increment_when_no_load: assert property (
        @(posedge clk) disable iff (RESET)
            (!LOAD ##1 !LOAD) |=> (Q == ($past(Q,2) + 2'd2))
    );

    // With LOAD high for two cycles (no reset), Q follows DATA from the immediately preceding cycle.
    two_consecutive_loads_follow_data: assert property (
        @(posedge clk) disable iff (RESET)
            (LOAD ##1 LOAD) |=> (Q == $past(DATA,1))
    );

    // LOAD followed by no-LOAD (no reset): Q becomes loaded DATA then increments next.
    load_then_increment: assert property (
        @(posedge clk) disable iff (RESET)
            (LOAD ##1 !LOAD) |=> (Q == ($past(DATA,2) + 2'b01))
    );

endmodule

module mux_2to1_sva (
    input logic out,
    input logic in0,
    input logic in1,
    input logic sel
);
    // No clock/reset in RTL; pure combinational mux: out=in0 when sel==0 else out=in1 (including sel=X/Z).

    // When sel is exactly 0, out must equal in0.
    check_out_when_sel0: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1 or posedge sel or negedge sel)
        (sel === 1'b0) |-> (out === in0)
    );

    // When sel is exactly 1, out must equal in1.
    check_out_when_sel1: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1 or posedge sel or negedge sel)
        (sel === 1'b1) |-> (out === in1)
    );

    // When sel is X/Z (not 0 and not 1), out must equal in1 per the else branch.
    check_out_when_selx: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1 or posedge sel or negedge sel)
        ((sel !== 1'b0) && (sel !== 1'b1)) |-> (out === in1)
    );

    // Out must always equal one of the two inputs.
    check_out_is_one_of_inputs: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1 or posedge sel or negedge sel)
        ( (out === in0) || (out === in1) )
    );

    // With sel==0, any out change (not due to sel change) must be caused by in0 changing.
    check_out_change_caused_by_in0_when_sel0: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1 or posedge sel or negedge sel)
        (sel === 1'b0 && !$changed(sel) && $changed(out)) |-> $changed(in0)
    );

    // With sel==1, any out change (not due to sel change) must be caused by in1 changing.
    check_out_change_caused_by_in1_when_sel1: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1 or posedge sel or negedge sel)
        (sel === 1'b1 && !$changed(sel) && $changed(out)) |-> $changed(in1)
    );

    // With sel==X/Z, any out change (not due to sel change) must be caused by in1 changing.
    check_out_change_caused_by_in1_when_selx: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1 or posedge sel or negedge sel)
        ((sel !== 1'b0 && sel !== 1'b1) && !$changed(sel) && $changed(out)) |-> $changed(in1)
    );

    // With sel==0 and in0/sel stable, out must remain stable (in1 changes cannot affect out).
    check_stable_out_when_sel0_and_in0_sel_stable: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1 or posedge sel or negedge sel)
        (sel === 1'b0 && !$changed(in0) && !$changed(sel)) |-> !$changed(out)
    );

    // With sel==1 and in1/sel stable, out must remain stable (in0 changes cannot affect out).
    check_stable_out_when_sel1_and_in1_sel_stable: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1 or posedge sel or negedge sel)
        (sel === 1'b1 && !$changed(in1) && !$changed(sel)) |-> !$changed(out)
    );

    // With sel==X/Z and in1/sel stable, out must remain stable.
    check_stable_out_when_selx_and_in1_sel_stable: assert property (
        @(posedge in0 or negedge in0 or posedge in1 or negedge in1 or posedge sel or negedge sel)
        ((sel !== 1'b0 && sel !== 1'b1) && !$changed(in1) && !$changed(sel)) |-> !$changed(out)
    );

    // Toggling sel does not change out when in0==in1 and inputs are stable since the last sel edge.
    check_no_glitch_on_sel_toggle_when_inputs_equal: assert property (
        @(posedge sel or negedge sel)
        ((in0 === in1) && !$changed(in0) && !$changed(in1)) |-> !$changed(out)
    );

endmodule

rtl:
module clockdivide2(
    input clk,
    input rst,
	 input select,
    output reg [31:0] OUT1,
	 output reg [31:0] OUT2,
    output clkdivided1hz,
	 output clkdivided2hz,
	 output clkselect
    );

	 always @ (posedge clk or posedge rst)
		begin
		if (rst)
			OUT1<=32'd0;
		else
		if (OUT1 == 32'd50000000)
			OUT1<=32'd0;
		else
			OUT1 <= OUT1 + 1;
		end

	 always @ (posedge clk or posedge rst)
		begin
		if (rst)
			OUT2<=32'd0;
		else
		if (OUT2 == 32'd500000)
			OUT2<=32'd0;
		else
			OUT2 <= OUT2 + 1;
		end
assign clkdivided1hz = (OUT1 == 32'd50000000);
assign clkdivided2hz = (OUT2 == 32'd500000);

assign clkselect = (select) ? clkdivided2hz : clkdivided1hz;
endmodule

sva:
module clockdivide2_sva (
    input logic clk,
    input logic rst,
    input logic select,
    input logic [31:0] OUT1,
    input logic [31:0] OUT2,
    input logic clkdivided1hz,
    input logic clkdivided2hz,
    input logic clkselect
);
    // When reset is asserted, both counters are driven to 0.
    reset_counters_zero: assert property (
        @(posedge clk) rst |-> (OUT1 == 32'd0) && (OUT2 == 32'd0)
    );

    // On reset deassertion edge, counters are 0 in that cycle.
    reset_fall_counters_zero: assert property (
        @(posedge clk) disable iff (rst) $fell(rst) |-> (OUT1 == 32'd0) && (OUT2 == 32'd0)
    );

    // OUT1 never exceeds its terminal count when not in reset.
    out1_within_range: assert property (
        @(posedge clk) disable iff (rst) OUT1 <= 32'd50000000
    );

    // OUT2 never exceeds its terminal count when not in reset.
    out2_within_range: assert property (
        @(posedge clk) disable iff (rst) OUT2 <= 32'd500000
    );

    // OUT1 wraps to 0 on the cycle after reaching 50,000,000.
    out1_wraps_to_zero: assert property (
        @(posedge clk) disable iff (rst) (OUT1 == 32'd50000000) |=> (OUT1 == 32'd0)
    );

    // OUT2 wraps to 0 on the cycle after reaching 500,000.
    out2_wraps_to_zero: assert property (
        @(posedge clk) disable iff (rst) (OUT2 == 32'd500000) |=> (OUT2 == 32'd0)
    );

    // clkdivided1hz reflects OUT1 == 50,000,000.
    clkdiv1_definition: assert property (
        @(posedge clk) disable iff (rst) clkdivided1hz == (OUT1 == 32'd50000000)
    );

    // clkdivided2hz reflects OUT2 == 500,000.
    clkdiv2_definition: assert property (
        @(posedge clk) disable iff (rst) clkdivided2hz == (OUT2 == 32'd500000)
    );

    // clkdivided1hz is a single-cycle pulse (cannot be high in two consecutive cycles).
    clkdiv1_one_cycle_pulse: assert property (
        @(posedge clk) disable iff (rst) clkdivided1hz |=> !clkdivided1hz
    );

    // clkdivided2hz is a single-cycle pulse (cannot be high in two consecutive cycles).
    clkdiv2_one_cycle_pulse: assert property (
        @(posedge clk) disable iff (rst) clkdivided2hz |=> !clkdivided2hz
    );

    // clkselect is the mux of the two divided clocks based on select.
    clkselect_mux_behavior: assert property (
        @(posedge clk) disable iff (rst) clkselect == (select ? clkdivided2hz : clkdivided1hz)
    );
endmodule

rtl:
module mux_4to1(
  input [3:0] in,
  input [1:0] sel,
  output reg out
);

always @(*)
begin
  case(sel)
    2'b00: out = in[0];
    2'b01: out = in[1];
    2'b10: out = in[2];
    2'b11: out = in[3];
  endcase
end

endmodule

sva:
module mux_4to1_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [1:0] sel,
    input logic out
);
    // When sel==00, out must equal in[0].
    check_sel00_selects_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

    // When sel==01, out must equal in[1].
    check_sel01_selects_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in[1])
    );

    // When sel==10, out must equal in[2].
    check_sel10_selects_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in[2])
    );

    // When sel==11, out must equal in[3].
    check_sel11_selects_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

    // If inputs and select are stable, output remains stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(in) && $stable(sel)) |-> $stable(out)
    );

    // With sel==00, if in[0] and sel are stable, output is stable.
    check_isolation_sel00: assert property (
        @(posedge clk) (sel == 2'b00 && $stable(in[0]) && $stable(sel)) |-> $stable(out)
    );

    // With sel==01, if in[1] and sel are stable, output is stable.
    check_isolation_sel01: assert property (
        @(posedge clk) (sel == 2'b01 && $stable(in[1]) && $stable(sel)) |-> $stable(out)
    );

    // With sel==10, if in[2] and sel are stable, output is stable.
    check_isolation_sel10: assert property (
        @(posedge clk) (sel == 2'b10 && $stable(in[2]) && $stable(sel)) |-> $stable(out)
    );

    // With sel==11, if in[3] and sel are stable, output is stable.
    check_isolation_sel11: assert property (
        @(posedge clk) (sel == 2'b11 && $stable(in[3]) && $stable(sel)) |-> $stable(out)
    );

    // Output changes only if sel or inputs change.
    check_output_change_has_cause: assert property (
        @(posedge clk) $changed(out) |-> ($changed(sel) || $changed(in))
    );
endmodule

