module mux(input ctrl, input [0:0] D0, input [0:0] D1, output [0:0] S);
  wire [0:0] D0_wire;
  wire [0:0] D1_wire;
  wire [0:0] S_wire;
  wire ctrl_wire;

  assign D0_wire[0] = D0[0];
  assign D1_wire[0] = D1[0];

  assign S[0] = S_wire[0];

  assign ctrl_wire = ctrl;

  assign S_wire[0] = (ctrl_wire) ? D1_wire[0] : D0_wire[0];
endmodule

sva:
module mux_sva (
    input logic ctrl,
    input logic [0:0] D0,
    input logic [0:0] D1,
    input logic [0:0] S
);
    // No clock/reset in DUT; pure combinational 2:1 mux: S[0] = ctrl ? D1[0] : D0[0].
    // Sample properties on input edges (ctrl, D0[0], D1[0]).

    // On ctrl rising edge, S must equal selected input.
    check_mux_equiv_on_ctrl_posedge: assert property (
        @(posedge ctrl) S[0] == (ctrl ? D1[0] : D0[0])
    );

    // On ctrl falling edge, S must equal selected input.
    check_mux_equiv_on_ctrl_negedge: assert property (
        @(negedge ctrl) S[0] == (ctrl ? D1[0] : D0[0])
    );

    // On D0 rising edge, S must equal selected input.
    check_mux_equiv_on_d0_posedge: assert property (
        @(posedge D0[0]) S[0] == (ctrl ? D1[0] : D0[0])
    );

    // On D0 falling edge, S must equal selected input.
    check_mux_equiv_on_d0_negedge: assert property (
        @(negedge D0[0]) S[0] == (ctrl ? D1[0] : D0[0])
    );

    // On D1 rising edge, S must equal selected input.
    check_mux_equiv_on_d1_posedge: assert property (
        @(posedge D1[0]) S[0] == (ctrl ? D1[0] : D0[0])
    );

    // On D1 falling edge, S must equal selected input.
    check_mux_equiv_on_d1_negedge: assert property (
        @(negedge D1[0]) S[0] == (ctrl ? D1[0] : D0[0])
    );

    // If inputs are equal, S must equal that value regardless of ctrl (sampled on ctrl rise).
    check_equal_inputs_ctrl_posedge: assert property (
        @(posedge ctrl) (D0[0] == D1[0]) |-> (S[0] == D0[0])
    );
endmodule

rtl:
module counter_display (
    input clk,
    input reset,               // Synchronous active-high reset
    input direction,           // Input to control the count direction
    output [6:0] seg,          // 7-segment display output
    output reg [3:0] cnt           // 4-bit counter output
);

  // Declare intermediate signals
  wire [7:0] out;
  wire cnt_up, cnt_down;    // Control signals for counter direction

  // Instantiate splitter and XOR modules
  splitter_module splitter(.in({cnt, 4'b0}), .out(out));
  xor_module xor0(.a(cnt[0]), .b(cnt[1]), .out_ff(cnt_up));
  xor_module xor1(.a(cnt[2]), .b(cnt[3]), .out_ff(cnt_down));

  // Assign segment outputs
  assign seg = out;

  // Counter logic
  always @(posedge clk) begin
    if (reset) begin
      cnt <= 4'b0000;
    end else if (direction) begin
      // Count up
      cnt <= cnt + 1'b1;
    end else begin
      // Count down
      cnt <= cnt - 1'b1;
    end
  end

endmodule

module splitter_module (
    input [7:0] in,
    output [7:0] out
);

  assign out = in;

endmodule

module xor_module (
    input a,
    input b,
    output out_ff
);

  assign out_ff = a ^ b; // XOR operation

endmodule

sva:
module counter_display_sva (
    input logic clk,
    input logic reset,              // Synchronous active-high reset
    input logic direction,
    input logic [6:0] seg,
    input logic [3:0] cnt
);
    ///// Reset behavior /////
    // On a clock where reset is 1, cnt must be driven to 0.
    reset_clears_cnt: assert property (
        @(posedge clk) reset |-> (cnt == 4'b0000)
    );

    ///// Counter update rules /////
    // When not in reset and direction=1, cnt increments by 1 from the previous cycle.
    count_up_increments: assert property (
        @(posedge clk) disable iff (reset) direction |-> (cnt == $past(cnt) + 4'd1)
    );
    // When not in reset and direction=0, cnt decrements by 1 from the previous cycle.
    count_down_decrements: assert property (
        @(posedge clk) disable iff (reset) !direction |-> (cnt == $past(cnt) - 4'd1)
    );
    // When not in reset, cnt must change every cycle (no hold behavior).
    cnt_changes_every_cycle: assert property (
        @(posedge clk) disable iff (reset) cnt != $past(cnt)
    );

    ///// seg mapping /////
    // seg reflects {cnt[2:0], 4'b0000} due to splitter pass-through and width truncation.
    seg_exact_mapping: assert property (
        @(posedge clk) disable iff (reset) seg == {cnt[2:0], 4'b0000}
    );
    // Low nibble of seg is always zero.
    seg_low_nibble_zero: assert property (
        @(posedge clk) disable iff (reset) seg[3:0] == 4'b0000
    );
endmodule

