);

    wire w1, w2, w3, w4, w5, w6, w7, w8;

    or or1 (
        X,
        A,
        B,
        C_N
    );

    or or2 (
        w2,
        A,
        w1,
        C_N
    );

    or or3 (
        w3,
        w1,
        B,
        C_N
    );

    or or4 (
        w4,
        w1,
        w1,
        C_N
    );

    or or5 (
