        A,
        B,
        w1
    );

    or or6 (
        w6,
        A,
        w1,
        w1
    );

    or or7 (
        w7,
        w1,
        B,
        w1
    );

    or or8 (
        w8,
        w1,
        w1,
        w1
    );

