sva:
module custom_or3_sva (
    input logic clk,   // Sampling clock for SVA (no clock/reset in RTL)
    input logic A,
    input logic B,
    input logic C_N,
    input logic X
);
    // Analysis: No clock/reset in RTL; purely combinational; functionally X == (A | B | C_N).

    // X equals bitwise OR of inputs every cycle.
    check_or_function: assert property (
        @(posedge clk) X == (A | B | C_N)
    );

    // A high forces X high.
    check_A_high_implies_X_high: assert property (
        @(posedge clk) (A == 1'b1) |-> (X == 1'b1)
    );

    // B high forces X high.
    check_B_high_implies_X_high: assert property (
        @(posedge clk) (B == 1'b1) |-> (X == 1'b1)
    );

    // C_N high forces X high.
    check_C_N_high_implies_X_high: assert property (
        @(posedge clk) (C_N == 1'b1) |-> (X == 1'b1)
    );

    // All inputs low force X low.
    check_all_low_implies_X_low: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b0 && C_N == 1'b0) |-> (X == 1'b0)
    );

    // X low implies all inputs low.
    check_X_low_implies_all_low: assert property (
        @(posedge clk) (X == 1'b0) |-> (A == 1'b0 && B == 1'b0 && C_N == 1'b0)
    );

    // X high implies at least one input high.
    check_X_high_implies_any_high: assert property (
        @(posedge clk) (X == 1'b1) |-> (A == 1'b1 || B == 1'b1 || C_N == 1'b1)
    );

    // If inputs are stable, X is stable.
    check_inputs_stable_implies_X_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $stable(C_N)) |-> $stable(X)
    );

    // X changes only if some input changes.
    check_X_change_implies_input_change: assert property (
        @(posedge clk) (X ^ $past(X)) |-> ((A ^ $past(A)) || (B ^ $past(B)) || (C_N ^ $past(C_N)))
    );

    // When B and C_N are low, X equals A.
    check_reduce_to_A_when_others_low: assert property (
        @(posedge clk) (B == 1'b0 && C_N == 1'b0) |-> (X == A)
    );

endmodule

rtl:
module decoder (
    input A, B, EN,
    output reg Y0, Y1, Y2, Y3
);

    always @ (A, B, EN) begin
        if (EN == 1'b0) begin
            Y0 <= 1'b0;
            Y1 <= 1'b0;
            Y2 <= 1'b0;
            Y3 <= 1'b0;
        end
        else begin
            case ({A, B})
                2'b00: begin
                    Y0 <= 1'b1;
                    Y1 <= 1'b0;
                    Y2 <= 1'b0;
                    Y3 <= 1'b0;
                end
                2'b01: begin
                    Y0 <= 1'b0;
                    Y1 <= 1'b1;
                    Y2 <= 1'b0;
                    Y3 <= 1'b0;
                end
                2'b10: begin
                    Y0 <= 1'b0;
                    Y1 <= 1'b0;
                    Y2 <= 1'b1;
                    Y3 <= 1'b0;
                end
                2'b11: begin
                    Y0 <= 1'b0;
                    Y1 <= 1'b0;
                    Y2 <= 1'b0;
                    Y3 <= 1'b1;
                end
                default: begin
                    Y0 <= 1'b0;
                    Y1 <= 1'b0;
                    Y2 <= 1'b0;
                    Y3 <= 1'b0;
                end
            endcase
        end
    end

endmodule

sva:
module decoder_sva (
    input  logic clk,
    input  logic A,
    input  logic B,
    input  logic EN,
    input  logic Y0,
    input  logic Y1,
    input  logic Y2,
    input  logic Y3
);
    // Outputs implement exact decoding function: EN ? (1 << {A,B}) : 0
    check_decode_function_vector: assert property (
        @(posedge clk) {Y3,Y2,Y1,Y0} == (EN ? (4'b0001 << {A,B}) : 4'b0000)
    );

    // When disabled, all outputs are 0
    check_disabled_all_zero: assert property (
        @(posedge clk) (EN == 1'b0) |-> ({Y3,Y2,Y1,Y0} == 4'b0000)
    );

    // When EN and AB==00, Y0=1 and others 0
    check_decode_00: assert property (
        @(posedge clk) (EN && (A==1'b0) && (B==1'b0)) |-> (Y0 && !Y1 && !Y2 && !Y3)
    );

    // When EN and AB==01, Y1=1 and others 0
    check_decode_01: assert property (
        @(posedge clk) (EN && (A==1'b0) && (B==1'b1)) |-> (!Y0 && Y1 && !Y2 && !Y3)
    );

    // When EN and AB==10, Y2=1 and others 0
    check_decode_10: assert property (
        @(posedge clk) (EN && (A==1'b1) && (B==1'b0)) |-> (!Y0 && !Y1 && Y2 && !Y3)
    );

    // When EN and AB==11, Y3=1 and others 0
    check_decode_11: assert property (
        @(posedge clk) (EN && (A==1'b1) && (B==1'b1)) |-> (!Y0 && !Y1 && !Y2 && Y3)
    );

    // At most one output is HIGH at any time (onehot0)
    check_outputs_onehot0: assert property (
        @(posedge clk) $onehot0({Y3,Y2,Y1,Y0})
    );

    // The OR of outputs equals EN
    check_outputs_or_equals_en: assert property (
        @(posedge clk) ((Y0 || Y1 || Y2 || Y3) == EN)
    );

    // If Y0 is HIGH, decoder must be enabled and AB==00
    check_y0_implies_en_ab00: assert property (
        @(posedge clk) Y0 |-> (EN && (A==1'b0) && (B==1'b0))
    );

    // If Y3 is HIGH, decoder must be enabled and AB==11
    check_y3_implies_en_ab11: assert property (
        @(posedge clk) Y3 |-> (EN && (A==1'b1) && (B==1'b1))
    );
endmodule

rtl:
module fsm_traffic_light_control (
  input clock,
  input reset,
  input pedestrian_crossing_button,
  output reg green_light,
  output reg yellow_light,
  output reg red_light
);

  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  reg [1:0] state, next_state;

  always @(posedge clock) begin
    if (reset) begin
      state <= S0;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      S0: begin
        green_light <= 1;
        yellow_light <= 0;
        red_light <= 0;
        if (pedestrian_crossing_button) begin
          next_state <= S1;
        end else begin
          next_state <= S0;
        end
      end
      S1: begin
        green_light <= 0;
        yellow_light <= 1;
        red_light <= 0;
        next_state <= S2;
      end
      S2: begin
        green_light <= 0;
        yellow_light <= 0;
        red_light <= 1;
        next_state <= S3;
      end
      S3: begin
        green_light <= 0;
        yellow_light <= 1;
        red_light <= 0;
        next_state <= S0;
      end
      default: begin
        green_light <= 0;
        yellow_light <= 0;
        red_light <= 0;
        next_state <= S0;
      end
    endcase
  end

endmodule

sva:
module fsm_traffic_light_control_sva (
  input logic clock,
  input logic reset,
  input logic pedestrian_crossing_button,
  input logic green_light,
  input logic yellow_light,
  input logic red_light,
  input logic [1:0] state,
  input logic [1:0] next_state
);
  // State encodings (match RTL)
  localparam logic [1:0] S0 = 2'b00;
  localparam logic [1:0] S1 = 2'b01;
  localparam logic [1:0] S2 = 2'b10;
  localparam logic [1:0] S3 = 2'b11;

  // Synchronous reset forces state to S0.
  reset_forces_S0: assert property (
    @(posedge clock) reset |-> (state == S0)
  );

  // When not in reset on consecutive cycles, state updates from prior next_state.
  state_updates_from_next_nonreset: assert property (
    @(posedge clock) disable iff (reset) !$past(reset) |-> (state == $past(next_state))
  );

  // Output decode in S0: green=1, yellow=0, red=0.
  outputs_decode_S0: assert property (
    @(posedge clock) disable iff (reset) (state == S0) |-> (green_light == 1'b1 && yellow_light == 1'b0 && red_light == 1'b0)
  );

  // Output decode in S1: green=0, yellow=1, red=0.
  outputs_decode_S1: assert property (
    @(posedge clock) disable iff (reset) (state == S1) |-> (green_light == 1'b0 && yellow_light == 1'b1 && red_light == 1'b0)
  );

  // Output decode in S2: green=0, yellow=0, red=1.
  outputs_decode_S2: assert property (
    @(posedge clock) disable iff (reset) (state == S2) |-> (green_light == 1'b0 && yellow_light == 1'b0 && red_light == 1'b1)
  );

  // Output decode in S3: green=0, yellow=1, red=0.
  outputs_decode_S3: assert property (
    @(posedge clock) disable iff (reset) (state == S3) |-> (green_light == 1'b0 && yellow_light == 1'b1 && red_light == 1'b0)
  );

  // Lights are mutually exclusive (no two ON simultaneously).
  check_lights_mutex: assert property (
    @(posedge clock) disable iff (reset) !(green_light && yellow_light) && !(green_light && red_light) && !(yellow_light && red_light)
  );

  // Combinational next_state in S0 with no pedestrian: stay in S0.
  comb_next_S0_no_ped: assert property (
    @(posedge clock) disable iff (reset) (state == S0 && pedestrian_crossing_button == 1'b0) |-> (next_state == S0)
  );

  // Combinational next_state in S0 with pedestrian: go to S1.
  comb_next_S0_with_ped: assert property (
    @(posedge clock) disable iff (reset) (state == S0 && pedestrian_crossing_button == 1'b1) |-> (next_state == S1)
  );

  // Combinational next_state in S1: go to S2.
  comb_next_S1_to_S2: assert property (
    @(posedge clock) disable iff (reset) (state == S1) |-> (next_state == S2)
  );

  // Combinational next_state in S2: go to S3.
  comb_next_S2_to_S3: assert property (
    @(posedge clock) disable iff (reset) (state == S2) |-> (next_state == S3)
  );

  // Combinational next_state in S3: go to S0.
  comb_next_S3_to_S0: assert property (
    @(posedge clock) disable iff (reset) (state == S3) |-> (next_state == S0)
  );

  // Sequential transition: from S0 with no pedestrian, remain in S0 next cycle unless reset.
  trans_S0_ped0_stay: assert property (
    @(posedge clock) disable iff (reset) (state == S0 && pedestrian_crossing_button == 1'b0) |-> ##1 (reset || state == S0)
  );

  // Sequential transition: from S0 with pedestrian, go to S1 next cycle unless reset.
  trans_S0_ped1_to_S1: assert property (
    @(posedge clock) disable iff (reset) (state == S0 && pedestrian_crossing_button == 1'b1) |-> ##1 (reset || state == S1)
  );

  // Sequential transition: S1 goes to S2 next cycle unless reset.
  trans_S1_to_S2: assert property (
    @(posedge clock) disable iff (reset) (state == S1) |-> ##1 (reset || state == S2)
  );

  // Sequential transition: S2 goes to S3 next cycle unless reset.
  trans_S2_to_S3: assert property (
    @(posedge clock) disable iff (reset) (state == S2) |-> ##1 (reset || state == S3)
  );

  // Sequential transition: S3 goes to S0 next cycle unless reset.
  trans_S3_to_S0: assert property (
    @(posedge clock) disable iff (reset) (state == S3) |-> ##1 (reset || state == S0)
  );

endmodule

rtl:
module alt_ctl(op,func,aluc
    );
	input [5:0] op,func;
	output reg [4:0] aluc;
	always @* 
	begin
		case(op)
			6'b000000 : begin case(func)6'b100000 : aluc =  0;	6'b100001 : aluc =  1;	6'b100010 : aluc =  2;	6'b100011 : aluc =  3;	6'b100100 : aluc =  4;	6'b100101 : aluc =  5;	6'b100110 : aluc =  6;	6'b100111 : aluc =  7; 6'b101010 : aluc =  8;	6'b101011 : aluc =  9;	6'b000000 : aluc = 10;	6'b000010 : aluc = 11;	6'b000011 : aluc = 12;	6'b000100 : aluc = 10;	6'b000110 : aluc = 11;	6'b000111 : aluc = 12;	6'b000001 : aluc = 13;	6'b000010 : aluc = 13;	default   : aluc =  0;
				endcase
			end 6'b001000 : aluc =  0;	6'b001001 : aluc =  1;	6'b001100 : aluc =  4;	6'b001101 : aluc =  5;	6'b001110 : aluc =  6;	6'b001010 : aluc =  8;	6'b001011 : aluc =  9;	6'b001111 : aluc =  14;default : aluc = 0;
		endcase
	end

endmodule

sva:
module alt_ctl_sva (
    input logic clk,
    input logic [5:0] op,
    input logic [5:0] func,
    input logic [4:0] aluc
);
    // aluc is always within 0..14 per decode table.
    check_aluc_range: assert property (
        @(posedge clk) (aluc <= 5'd14)
    );

    ///// R-type (op == 6'b000000) /////
    // R-type func 100000 maps to 0.
    map_op0_func_100000_to_0: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100000) |-> (aluc == 5'd0)
    );
    // R-type func 100001 maps to 1.
    map_op0_func_100001_to_1: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100001) |-> (aluc == 5'd1)
    );
    // R-type func 100010 maps to 2.
    map_op0_func_100010_to_2: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100010) |-> (aluc == 5'd2)
    );
    // R-type func 100011 maps to 3.
    map_op0_func_100011_to_3: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100011) |-> (aluc == 5'd3)
    );
    // R-type func 100100 maps to 4.
    map_op0_func_100100_to_4: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100100) |-> (aluc == 5'd4)
    );
    // R-type func 100101 maps to 5.
    map_op0_func_100101_to_5: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100101) |-> (aluc == 5'd5)
    );
    // R-type func 100110 maps to 6.
    map_op0_func_100110_to_6: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100110) |-> (aluc == 5'd6)
    );
    // R-type func 100111 maps to 7.
    map_op0_func_100111_to_7: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100111) |-> (aluc == 5'd7)
    );
    // R-type func 101010 maps to 8.
    map_op0_func_101010_to_8: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b101010) |-> (aluc == 5'd8)
    );
    // R-type func 101011 maps to 9.
    map_op0_func_101011_to_9: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b101011) |-> (aluc == 5'd9)
    );
    // R-type func 000000 maps to 10.
    map_op0_func_000000_to_10: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b000000) |-> (aluc == 5'd10)
    );
    // R-type func 000010 maps to 11.
    map_op0_func_000010_to_11: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b000010) |-> (aluc == 5'd11)
    );
    // R-type func 000011 maps to 12.
    map_op0_func_000011_to_12: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b000011) |-> (aluc == 5'd12)
    );
    // R-type func 000100 maps to 10.
    map_op0_func_000100_to_10: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b000100) |-> (aluc == 5'd10)
    );
    // R-type func 000110 maps to 11.
    map_op0_func_000110_to_11: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b000110) |-> (aluc == 5'd11)
    );
    // R-type func 000111 maps to 12.
    map_op0_func_000111_to_12: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b000111) |-> (aluc == 5'd12)
    );
    // R-type func 000001 maps to 13.
    map_op0_func_000001_to_13: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b000001) |-> (aluc == 5'd13)
    );
    // R-type default (unlisted func) maps to 0.
    map_op0_default_func_to_0: assert property (
        @(posedge clk) (op == 6'b000000 && !(func inside {
            6'b100000,6'b100001,6'b100010,6'b100011,6'b100100,6'b100101,6'b100110,6'b100111,
            6'b101010,6'b101011,6'b000000,6'b000010,6'b000011,6'b000100,6'b000110,6'b000111,6'b000001
        })) |-> (aluc == 5'd0)
    );

    ///// I-type (op != 6'b000000) /////
    // I-type op 001000 maps to 0.
    map_op_001000_to_0: assert property (
        @(posedge clk) (op == 6'b001000) |-> (aluc == 5'd0)
    );
    // I-type op 001001 maps to 1.
    map_op_001001_to_1: assert property (
        @(posedge clk) (op == 6'b001001) |-> (aluc == 5'd1)
    );
    // I-type op 001100 maps to 4.
    map_op_001100_to_4: assert property (
        @(posedge clk) (op == 6'b001100) |-> (aluc == 5'd4)
    );
    // I-type op 001101 maps to 5.
    map_op_001101_to_5: assert property (
        @(posedge clk) (op == 6'b001101) |-> (aluc == 5'd5)
    );
    // I-type op 001110 maps to 6.
    map_op_001110_to_6: assert property (
        @(posedge clk) (op == 6'b001110) |-> (aluc == 5'd6)
    );
    // I-type op 001010 maps to 8.
    map_op_001010_to_8: assert property (
        @(posedge clk) (op == 6'b001010) |-> (aluc == 5'd8)
    );
    // I-type op 001011 maps to 9.
    map_op_001011_to_9: assert property (
        @(posedge clk) (op == 6'b001011) |-> (aluc == 5'd9)
    );
    // I-type op 001111 maps to 14.
    map_op_001111_to_14: assert property (
        @(posedge clk) (op == 6'b001111) |-> (aluc == 5'd14)
    );
    // I-type default (unlisted op and not R-type) maps to 0.
    map_default_other_ops_to_0: assert property (
        @(posedge clk) ((op != 6'b000000) && !(op inside {
            6'b001000,6'b001001,6'b001100,6'b001101,6'b001110,6'b001010,6'b001011,6'b001111
        })) |-> (aluc == 5'd0)
    );

    ///// Generic decode sanity /////
    // If op and func are stable across cycles, aluc remains stable.
    stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(op) && $stable(func)) |-> $stable(aluc)
    );

endmodule

