module binary_up_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       enable,
    input logic [3:0] count
);

    // Reset clears the counter on the next sampled clock.
    check_reset_clears_count: assert property (
        @(posedge clk) disable iff ($initstate)
        reset |=> (count == 4'd0)
    );

    // Reset overrides enable and still clears the counter.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) disable iff ($initstate)
        reset && enable |=> (count == 4'd0)
    );

    // When disabled and not in reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff ($initstate)
        !reset && !enable |=> (count == $past(count))
    );

    // When enabled below 15, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff ($initstate)
        !reset && enable && (count != 4'd15) |=> (count == ($past(count) + 4'd1))
    );

    // When enabled at 15, the counter wraps back to zero.
    check_wrap_at_max: assert property (
        @(posedge clk) disable iff ($initstate)
        !reset && enable && (count == 4'd15) |=> (count == 4'd0)
    );

    // Every sampled count matches the RTL next-state function.
    check_count_follows_rtl_transition: assert property (
        @(posedge clk) disable iff ($initstate)
        1'b1 |=> (count == ($past(reset) ? 4'd0 :
                            ($past(enable) ? (($past(count) == 4'd15) ? 4'd0 : ($past(count) + 4'd1))
                                           : $past(count))))
    );

endmodule

rtl:
module flip_flop (
    Q   ,
    CLK ,
    D   ,
    DE  ,
    SCD ,
    SCE ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output Q   ;
    input  CLK ;
    input  D   ;
    input  DE  ;
    input  SCD ;
    input  SCE ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    // Scan chain enable/disable
    wire scan_en = SCE & ~SCD;

    // D flip-flop
    reg Q_reg;
    always @(posedge CLK) begin
        if (scan_en & DE) begin
            Q_reg <= D;
        end
    end

    // Output
    assign Q = scan_en ? Q_reg : 1'b0;

    // Power and ground connections
    assign VPWR = 1'b1;
    assign VGND = 1'b0;
    assign VPB = 1'b1;
    assign VNB = 1'b0;

endmodule

sva:
module flip_flop_sva (
    input logic Q,
    input logic CLK,
    input logic D,
    input logic DE,
    input logic SCD,
    input logic SCE,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // When scan is disabled, the output is forced low.
    check_output_zero_when_scan_disabled: assert property (
        @(posedge CLK) (!SCE || SCD) |-> (Q == 1'b0)
    );

    // A high output is only possible when scan is enabled.
    check_q_high_requires_scan_enabled: assert property (
        @(posedge CLK) Q |-> (SCE && !SCD)
    );

    // A qualified load is visible on Q one cycle later if scan stays enabled.
    check_load_updates_q_when_visible: assert property (
        @(posedge CLK) (SCE && !SCD && DE) |=> ((!SCE || SCD) || (Q == $past(D)))
    );

    // Without a qualified load, Q holds its visible value across enabled cycles.
    check_hold_across_enabled_cycles_without_load: assert property (
        @(posedge CLK) (SCE && !SCD && !DE) |=> ((!SCE || SCD) || (Q == $past(Q)))
    );

    // Any visible change on Q across enabled cycles requires a prior load.
    check_visible_q_change_requires_load: assert property (
        @(posedge CLK) ($past(SCE && !SCD) && (SCE && !SCD) && (Q != $past(Q))) |-> $past(DE)
    );

    // VPWR is tied high by the RTL.
    check_vpwr_tied_high: assert property (
        @(posedge CLK) (VPWR == 1'b1)
    );

    // VGND is tied low by the RTL.
    check_vgnd_tied_low: assert property (
        @(posedge CLK) (VGND == 1'b0)
    );

    // VPB is tied high by the RTL.
    check_vpb_tied_high: assert property (
        @(posedge CLK) (VPB == 1'b1)
    );

    // VNB is tied low by the RTL.
    check_vnb_tied_low: assert property (
        @(posedge CLK) (VNB == 1'b0)
    );

endmodule

module DEMUX_sva #(
    parameter n = 4
)(
    input logic clk,
    input logic in,
    input logic [n-1:0] control,
    input logic [n-1:0] out
);

    // Input low forces all outputs low.
    check_input_low_clears_out: assert property (
        @(posedge clk) (in == 1'b0) |-> (out == '0)
    );

    // control 0 selects the 1000 output pattern.
    check_control_zero_selects_1000: assert property (
        @(posedge clk) (in == 1'b1) && (control == 0) |-> (out == 4'b1000)
    );

    // control 1 selects the 0100 output pattern.
    check_control_one_selects_0100: assert property (
        @(posedge clk) (in == 1'b1) && (control == 1) |-> (out == 4'b0100)
    );

    // control 2 selects the 0010 output pattern.
    check_control_two_selects_0010: assert property (
        @(posedge clk) (in == 1'b1) && (control == 2) |-> (out == 4'b0010)
    );

    // control 3 selects the 0001 output pattern.
    check_control_three_selects_0001: assert property (
        @(posedge clk) (in == 1'b1) && (control == 3) |-> (out == 4'b0001)
    );

    // Out-of-range control drives all outputs low.
    check_invalid_control_clears_out: assert property (
        @(posedge clk) (in == 1'b1) && (control > 3) |-> (out == '0)
    );

    // Output is always either zero or one-hot.
    check_output_is_onehot0: assert property (
        @(posedge clk) $onehot0(out)
    );

    // Any asserted output requires input high.
    check_asserted_output_requires_input_high: assert property (
        @(posedge clk) (out != '0) |-> (in == 1'b1)
    );

endmodule

