  reg [WIDTH-1:0] probe0;
  reg [WIDTH-1:0] probe1;
  reg [12:0] inv_in;

  assign data_out = probe1;  // Corrected the line to assign data_out

  always @(posedge clk) begin
    probe0 <= data_in;
    inv_in <= ~{in12, in11, in10, in9, in8, in7, in6, in5, in4, in3, in2, in1, in0};
