rtl:
module mux6to1_pipeline (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

reg [3:0] stage1_out_0, stage1_out_1, stage1_out_2, stage1_out_3, stage1_out_4, stage1_out_5;
reg [3:0] stage2_out_0, stage2_out_1, stage2_out_2;

always @(*) begin
    case(sel)
        3'b000: begin
            stage1_out_0 <= data0;
            stage1_out_1 <= data1;
            stage1_out_2 <= data2;
            stage1_out_3 <= data3;
            stage1_out_4 <= data4;
            stage1_out_5 <= data5;
        end
        3'b001: begin
            stage1_out_0 <= {data0[3], data0[2], data0[1], data0[0]};
            stage1_out_1 <= {data1[3], data1[2], data1[1], data1[0]};
            stage1_out_2 <= {data2[3], data2[2], data2[1], data2[0]};
            stage1_out_3 <= {data3[3], data3[2], data3[1], data3[0]};
            stage1_out_4 <= {data4[3], data4[2], data4[1], data4[0]};
            stage1_out_5 <= {data5[3], data5[2], data5[1], data5[0]};
        end
        3'b010: begin
            stage1_out_0 <= {data0[3], data0[3], data0[3], data0[3]};
            stage1_out_1 <= {data1[3], data1[3], data1[3], data1[3]};
            stage1_out_2 <= {data2[3], data2[3], data2[3], data2[3]};
            stage1_out_3 <= {data3[3], data3[3], data3[3], data3[3]};
            stage1_out_4 <= {data4[3], data4[3], data4[3], data4[3]};
            stage1_out_5 <= {data5[3], data5[3], data5[3], data5[3]};
        end
        3'b011: begin
            stage1_out_0 <= {data0[0], data0[0], data0[0], data0[0]};
            stage1_out_1 <= {data1[0], data1[0], data1[0], data1[0]};
            stage1_out_2 <= {data2[0], data2[0], data2[0], data2[0]};
            stage1_out_3 <= {data3[0], data3[0], data3[0], data3[0]};
            stage1_out_4 <= {data4[0], data4[0], data4[0], data4[0]};
            stage1_out_5 <= {data5[0], data5[0], data5[0], data5[0]};
        end
        3'b100: begin
            stage1_out_0 <= 4'b0;
            stage1_out_1 <= 4'b0;
            stage1_out_2 <= 4'b0;
            stage1_out_3 <= 4'b0;
            stage1_out_4 <= 4'b0;
            stage1_out_5 <= 4'b0;
        end
        default: begin
            stage1_out_0 <= 4'b0;
            stage1_out_1 <= 4'b0;
            stage1_out_2 <= 4'b0;
            stage1_out_3 <= 4'b0;
            stage1_out_4 <= 4'b0;
            stage1_out_5 <= 4'b0;
        end
    endcase
end

always @(*) begin
    stage2_out_0 <= stage1_out_0 | stage1_out_1;
    stage2_out_1 <= stage1_out_2 | stage1_out_3;
    stage2_out_2 <= stage1_out_4 | stage1_out_5;
end

always @(*) begin
    out <= 3'b000;
    case(sel)
        3'b000: out <= stage2_out_0;
        3'b001: out <= stage2_out_0;
        3'b010: out <= stage2_out_1;
        3'b011: out <= stage2_out_1;
        3'b100: out <= stage2_out_2;
        default: out <= 3'b000;
    endcase
end

endmodule

sva:
module mux6to1_pipeline_assertions (
    input logic       clk,
    input logic [2:0] sel,
    input logic [3:0] data0,
    input logic [3:0] data1,
    input logic [3:0] data2,
    input logic [3:0] data3,
    input logic [3:0] data4,
    input logic [3:0] data5,
    input logic [3:0] out
);

    // sel=000 drives out from the OR of data0 and data1.
    check_sel_000_or_data0_data1: assert property (
        @(posedge clk) (sel == 3'b000) |-> (out == (data0 | data1))
    );

    // sel=001 uses the same effective data0/data1 OR result.
    check_sel_001_or_data0_data1: assert property (
        @(posedge clk) (sel == 3'b001) |-> (out == (data0 | data1))
    );

    // sel=010 drives out from replicated OR of data2[3] and data3[3].
    check_sel_010_replicated_msb_or: assert property (
        @(posedge clk) (sel == 3'b010) |-> (out == {4{data2[3] | data3[3]}})
    );

    // sel=011 drives out from replicated OR of data2[0] and data3[0].
    check_sel_011_replicated_lsb_or: assert property (
        @(posedge clk) (sel == 3'b011) |-> (out == {4{data2[0] | data3[0]}})
    );

    // sel=100 forces the output to zero.
    check_sel_100_forces_zero: assert property (
        @(posedge clk) (sel == 3'b100) |-> (out == 4'b0000)
    );

    // Unhandled sel values drive zero.
    check_sel_default_forces_zero: assert property (
        @(posedge clk) ((sel == 3'b101) || (sel == 3'b110) || (sel == 3'b111)) |-> (out == 4'b0000)
    );

endmodule

rtl:
module mux_4to1_enable (
  input [3:0] in0,
  input [3:0] in1,
  input [3:0] in2,
  input [3:0] in3,
  input [1:0] sel,
  input en,
  output [3:0] out
);

  wire [3:0] mux_out;

  assign mux_out[0] = (sel == 2'b00) ? in0[0] : (sel == 2'b01) ? in1[0] : (sel == 2'b10) ? in2[0] : in3[0];
  assign mux_out[1] = (sel == 2'b00) ? in0[1] : (sel == 2'b01) ? in1[1] : (sel == 2'b10) ? in2[1] : in3[1];
  assign mux_out[2] = (sel == 2'b00) ? in0[2] : (sel == 2'b01) ? in1[2] : (sel == 2'b10) ? in2[2] : in3[2];
  assign mux_out[3] = (sel == 2'b00) ? in0[3] : (sel == 2'b01) ? in1[3] : (sel == 2'b10) ? in2[3] : in3[3];

  assign out = (en == 1'b1) ? mux_out : 4'b0000;

endmodule

sva:
module mux_4to1_enable_sva (
    input logic clk,
    input logic [3:0] in0,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] in3,
    input logic [1:0] sel,
    input logic en,
    input logic [3:0] out
);

    // Output must match the complete enable-controlled 4:1 mux function.
    check_full_mux_function: assert property (
        @(posedge clk)
        out == ((en == 1'b1) ?
                ((sel == 2'b00) ? in0 :
                 (sel == 2'b01) ? in1 :
                 (sel == 2'b10) ? in2 : in3) :
                4'b0000)
    );

    // Output must be zero whenever the mux is disabled.
    check_output_zero_when_disabled: assert property (
        @(posedge clk)
        (en == 1'b0) |-> (out == 4'b0000)
    );

    // When enabled with sel=00, output must equal in0.
    check_select_in0_when_enabled: assert property (
        @(posedge clk)
        ((en == 1'b1) && (sel == 2'b00)) |-> (out == in0)
    );

    // When enabled with sel=01, output must equal in1.
    check_select_in1_when_enabled: assert property (
        @(posedge clk)
        ((en == 1'b1) && (sel == 2'b01)) |-> (out == in1)
    );

    // When enabled with sel=10, output must equal in2.
    check_select_in2_when_enabled: assert property (
        @(posedge clk)
        ((en == 1'b1) && (sel == 2'b10)) |-> (out == in2)
    );

    // When enabled with sel=11, output must equal in3.
    check_select_in3_when_enabled: assert property (
        @(posedge clk)
        ((en == 1'b1) && (sel == 2'b11)) |-> (out == in3)
    );

    // With sel=00, changes on unselected inputs must not change the output.
    check_unselected_inputs_do_not_affect_out_sel0: assert property (
        @(posedge clk)
        ((en == 1'b1) && $stable(en) &&
         (sel == 2'b00) && $stable(sel) && $stable(in0) &&
         ($changed(in1) || $changed(in2) || $changed(in3)))
        |-> $stable(out)
    );

    // With sel=01, changes on unselected inputs must not change the output.
    check_unselected_inputs_do_not_affect_out_sel1: assert property (
        @(posedge clk)
        ((en == 1'b1) && $stable(en) &&
         (sel == 2'b01) && $stable(sel) && $stable(in1) &&
         ($changed(in0) || $changed(in2) || $changed(in3)))
        |-> $stable(out)
    );

    // With sel=10, changes on unselected inputs must not change the output.
    check_unselected_inputs_do_not_affect_out_sel2: assert property (
        @(posedge clk)
        ((en == 1'b1) && $stable(en) &&
         (sel == 2'b10) && $stable(sel) && $stable(in2) &&
         ($changed(in0) || $changed(in1) || $changed(in3)))
        |-> $stable(out)
    );

    // With sel=11, changes on unselected inputs must not change the output.
    check_unselected_inputs_do_not_affect_out_sel3: assert property (
        @(posedge clk)
        ((en == 1'b1) && $stable(en) &&
         (sel == 2'b11) && $stable(sel) && $stable(in3) &&
         ($changed(in0) || $changed(in1) || $changed(in2)))
        |-> $stable(out)
    );

    // While disabled, input or select changes must not change the zero output.
    check_disabled_input_changes_do_not_affect_out: assert property (
        @(posedge clk)
        ((en == 1'b0) && $stable(en) &&
         ($changed(in0) || $changed(in1) || $changed(in2) || $changed(in3) || $changed(sel)))
        |-> $stable(out)
    );

endmodule

