rtl:
module comparator_4bit(
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    output EQ,
    output GT
);

wire eq1, eq2, eq3, gt1, gt2, gt3, gt4, gt5;

// Check if A=B
assign eq1 = (A == B);

// Check if B=C
assign eq2 = (B == C);

// Check if C=D
assign eq3 = (C == D);

// Check if A>B
assign gt1 = (A > B);

// Check if B>C
assign gt2 = (B > C);

// Check if C>D
assign gt3 = (C > D);

// Check if A>B>C>D
assign gt4 = (gt1 && gt2 && gt3);

// Check if A=B=C=D
assign gt5 = (eq1 && eq2 && eq3);

// Output EQ
assign EQ = (eq1 && eq2 && eq3);

// Output GT
assign GT = (gt4 || gt5);

endmodule

sva:
module comparator_4bit_sva(
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C,
    input logic [3:0] D,
    input logic EQ,
    input logic GT
);

    // No reset is present in the RTL; sample combinational behavior on clk.

    // EQ is high exactly when all four inputs are equal.
    check_eq_definition: assert property (
        @(posedge clk) EQ === ((A == B) && (B == C) && (C == D))
    );

    // GT is high exactly for strict descending order or the all-equal case.
    check_gt_definition: assert property (
        @(posedge clk) GT === (((A > B) && (B > C) && (C > D)) || ((A == B) && (B == C) && (C == D)))
    );

    // All equal inputs drive both EQ and GT high.
    check_all_equal_outputs_high: assert property (
        @(posedge clk) ((A == B) && (B == C) && (C == D)) |-> ((EQ === 1'b1) && (GT === 1'b1))
    );

    // Strict descending inputs drive GT high and EQ low.
    check_strict_descending_outputs: assert property (
        @(posedge clk) ((A > B) && (B > C) && (C > D)) |-> ((GT === 1'b1) && (EQ === 1'b0))
    );

    // EQ can only be high when GT is also high.
    check_eq_implies_gt: assert property (
        @(posedge clk) (EQ === 1'b1) |-> (GT === 1'b1)
    );

    // GT without EQ means the inputs are strictly descending.
    check_gt_without_eq_means_descending: assert property (
        @(posedge clk) ((GT === 1'b1) && (EQ === 1'b0)) |-> ((A > B) && (B > C) && (C > D))
    );

    // Any break in the equality chain keeps EQ low.
    check_mismatch_clears_eq: assert property (
        @(posedge clk) !((A == B) && (B == C) && (C == D)) |-> (EQ === 1'b0)
    );

    // Inputs outside the two GT cases keep GT low.
    check_nonqualifying_inputs_clear_gt: assert property (
        @(posedge clk) !(((A > B) && (B > C) && (C > D)) || ((A == B) && (B == C) && (C == D))) |-> (GT === 1'b0)
    );

endmodule

module flag_register_sva (
    input logic IN_FLAG,
    input logic LD,
    input logic SET,
    input logic CLR,
    input logic CLK,
    input logic OUT_FLAG
);

    // Load updates OUT_FLAG from IN_FLAG.
    check_load_updates_flag: assert property (
        @(posedge CLK) LD |=> (OUT_FLAG == $past(IN_FLAG))
    );

    // SET drives OUT_FLAG high when load is not selected.
    check_set_updates_flag: assert property (
        @(posedge CLK) (!LD && SET) |=> (OUT_FLAG == 1'b1)
    );

    // CLR drives OUT_FLAG low when neither load nor set is selected.
    check_clear_updates_flag: assert property (
        @(posedge CLK) (!LD && !SET && CLR) |=> (OUT_FLAG == 1'b0)
    );

    // OUT_FLAG holds its value when no control is asserted.
    check_hold_when_idle: assert property (
        @(posedge CLK) (!LD && !SET && !CLR) |=> (OUT_FLAG == $past(OUT_FLAG))
    );

    // LOAD has priority over SET and CLR.
    check_load_priority: assert property (
        @(posedge CLK) (LD && (SET || CLR)) |=> (OUT_FLAG == $past(IN_FLAG))
    );

    // SET has priority over CLR when load is not asserted.
    check_set_priority_over_clear: assert property (
        @(posedge CLK) (!LD && SET && CLR) |=> (OUT_FLAG == 1'b1)
    );

endmodule

rtl:
module OneHotStateMachine #(
  parameter n = 4
)(
  input clk,
  output reg [n-1:0] out
);


reg [n-1:0] state; // register to store the current state of the machine

always @(posedge clk) begin
  // determine the next state of the machine
  case(state)
    0: state = 1;
    1: state = 2;
    2: state = 3;
    3: state = 0;
  endcase
end

// set the output signals based on the current state of the machine
always @* begin
  case(state)
    0: out = 4'b0001;
    1: out = 4'b0010;
    2: out = 4'b0100;
    3: out = 4'b1000;
  endcase
end

endmodule

sva:
module OneHotStateMachine_sva #(
    parameter n = 4
) (
    input logic clk,
    input logic [n-1:0] out,
    input logic [n-1:0] state
);

    localparam logic [n-1:0] OUT_STATE0 = 4'b0001;
    localparam logic [n-1:0] OUT_STATE1 = 4'b0010;
    localparam logic [n-1:0] OUT_STATE2 = 4'b0100;
    localparam logic [n-1:0] OUT_STATE3 = 4'b1000;

    // State 0 advances to state 1.
    check_state_0_to_1: assert property (
        @(posedge clk) (state == 0) |=> (state == 1)
    );

    // State 1 advances to state 2.
    check_state_1_to_2: assert property (
        @(posedge clk) (state == 1) |=> (state == 2)
    );

    // State 2 advances to state 3.
    check_state_2_to_3: assert property (
        @(posedge clk) (state == 2) |=> (state == 3)
    );

    // State 3 wraps back to state 0.
    check_state_3_to_0: assert property (
        @(posedge clk) (state == 3) |=> (state == 0)
    );

    // State 0 drives the first one-hot output.
    check_out_for_state_0: assert property (
        @(posedge clk) (state == 0) |-> (out == OUT_STATE0)
    );

    // State 1 drives the second one-hot output.
    check_out_for_state_1: assert property (
        @(posedge clk) (state == 1) |-> (out == OUT_STATE1)
    );

    // State 2 drives the third one-hot output.
    check_out_for_state_2: assert property (
        @(posedge clk) (state == 2) |-> (out == OUT_STATE2)
    );

    // State 3 drives the fourth one-hot output.
    check_out_for_state_3: assert property (
        @(posedge clk) (state == 3) |-> (out == OUT_STATE3)
    );

    // Known invalid states hold their value.
    check_invalid_state_holds: assert property (
        @(posedge clk)
        !((state == 0) || (state == 1) || (state == 2) || (state == 3))
        |=> $stable(state)
    );

    // Known invalid states leave the output unchanged.
    check_invalid_state_keeps_out_stable: assert property (
        @(posedge clk)
        !((state == 0) || (state == 1) || (state == 2) || (state == 3))
        |=> $stable(out)
    );

endmodule

rtl:
module dff_with_set (
    output Q,
    input D,
    input CLK,
    input SET,
    input NOTIFIER,
    input VPWR,
    input VGND
);

reg Q;

always @ (posedge CLK or negedge SET) begin
    if (!SET) begin
        Q <= 1'b0;
    end else begin
        Q <= D;
    end
end

assign NOTIFIER = (Q != D);

endmodule

sva:
module dff_with_set_sva (
    input logic Q,
    input logic D,
    input logic CLK,
    input logic SET,
    input logic NOTIFIER,
    input logic VPWR,
    input logic VGND
);

    // Sampling clock is CLK; SET is an active-low asynchronous clear.
    // Q is sequential; NOTIFIER is continuously driven from Q and D in the RTL.

    // When SET is asserted low, Q must be low.
    check_set_low_clears_q: assert property (
        @(posedge CLK) !SET |-> (Q == 1'b0)
    );

    // In normal operation, NOTIFIER must match the Q/D mismatch function.
    check_notifier_matches_mismatch_active: assert property (
        @(posedge CLK) disable iff (!SET) (NOTIFIER == (Q != D))
    );

    // During clear, NOTIFIER must still match the Q/D mismatch function.
    check_notifier_matches_mismatch_during_clear: assert property (
        @(posedge CLK) !SET |-> (NOTIFIER == (Q != D))
    );

endmodule

module dff_asynchronous_set_sva (
    input logic CLK,
    input logic D,
    input logic Q,
    input logic SET_B
);

    // Low SET_B overrides D and forces Q high on the next cycle.
    check_set_overrides_data: assert property (
        @(posedge CLK) (SET_B == 1'b0) |=> (Q == 1'b1)
    );

    // With SET_B high and D low, Q captures 0 on the next cycle.
    check_capture_zero: assert property (
        @(posedge CLK) (SET_B == 1'b1) && (D == 1'b0) |=> (Q == 1'b0)
    );

    // With SET_B high and D high, Q captures 1 on the next cycle.
    check_capture_one: assert property (
        @(posedge CLK) (SET_B == 1'b1) && (D == 1'b1) |=> (Q == 1'b1)
    );

endmodule

