									||mem_wb_op==NDC||mem_wb_op==NDZ)&&(mem_wb_CCR_write==1'b0))
							F3 = 2'd2;else if((ex_mem_regA==mem_wb_regA)&&(mem_wb_op[5:2]==LW))
