module adder_subtractor(Z, A, B, ctrl);
  input [3:0] A, B;
  input ctrl;
  output reg [3:0] Z;

  always @ (A, B, ctrl) begin
    if (ctrl == 0) begin
      Z = A + B;
    end
    else begin
      Z = A - B;
    end
  end

endmodule

sva:
module adder_subtractor_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       ctrl,
    input logic [3:0] Z
);

    // In add mode, Z is the 4-bit sum of A and B.
    check_add_mode_result: assert property (
        @(posedge clk) (ctrl == 1'b0) |-> (Z == (A + B))
    );

    // In subtract mode, Z is the 4-bit difference of A and B.
    check_subtract_mode_result: assert property (
        @(posedge clk) (ctrl == 1'b1) |-> (Z == (A - B))
    );

    // Subtracting equal operands produces zero.
    check_equal_operands_subtract_to_zero: assert property (
        @(posedge clk) (ctrl == 1'b1 && A == B) |-> (Z == 4'b0000)
    );

endmodule

rtl:
module sync_ram (
    input clk,
    input datain,
    input write_reset,
    input [2:0] waddr,
    input [2:0] raddr,
    input we,
    output reg dataout
);

    reg [0:5] ram_d;
    reg [0:5] ram_q;

    wire [0:5] data_reg;

    integer i;

    initial begin
        dataout = 0;
        for (i = 0; i <= 5; i = i + 1)
            ram_q[i] <= 1'b0;
    end

    // Write port
    always @(posedge clk or posedge write_reset) begin
        if (write_reset == 1'b1) begin
            for (i = 0; i <= 5; i = i + 1)
                ram_q[i] <= 1'b0;
        end
        else begin
            for (i = 0; i <= 5; i = i + 1)
                ram_q[i] <= ram_d[i];
        end
    end

    always @(we or data_reg or ram_q) begin
        if (we === 1'b1) begin
            ram_d <= data_reg;
        end
        else begin
            ram_d <= ram_q;
        end
    end

    // Read port
    assign data_reg[0] = (waddr == 3'b000) ? datain : ram_q[0];
    assign data_reg[1] = (waddr == 3'b001) ? datain : ram_q[1];
    assign data_reg[2] = (waddr == 3'b010) ? datain : ram_q[2];
    assign data_reg[3] = (waddr == 3'b011) ? datain : ram_q[3];
    assign data_reg[4] = (waddr == 3'b100) ? datain : ram_q[4];
    assign data_reg[5] = (waddr == 3'b101) ? datain : ram_q[5];

    always @(ram_q or we or waddr or raddr) begin
        case (raddr)
            3'b000: dataout <= ram_q[0];
            3'b001: dataout <= ram_q[1];
            3'b010: dataout <= ram_q[2];
            3'b011: dataout <= ram_q[3];
            3'b100: dataout <= ram_q[4];
            3'b101: dataout <= ram_q[5];
            default: dataout <= 0;
        endcase
    end

endmodule

sva:
module sync_ram_sva (
    input logic clk,
    input logic datain,
    input logic write_reset,
    input logic [2:0] waddr,
    input logic [2:0] raddr,
    input logic we,
    input logic dataout
);

    // Invalid read addresses drive zero.
    check_invalid_read_zero: assert property (
        @(posedge clk) disable iff (write_reset)
        ((raddr == 3'b110) || (raddr == 3'b111)) |-> (dataout == 1'b0)
    );

    // A reset seen on the prior cycle clears the visible read data.
    check_post_reset_output_zero: assert property (
        @(posedge clk) disable iff ($initstate)
        $past(write_reset) |-> (dataout == 1'b0)
    );

    // Without a write, a stable read address keeps the same data.
    check_hold_no_write_stable_read: assert property (
        @(posedge clk) disable iff (write_reset || $initstate)
        (!$past(write_reset) && ($past(we) !== 1'b1) && (raddr == $past(raddr)))
        |-> (dataout == $past(dataout))
    );

    // Writing a different address does not disturb the current read data.
    check_hold_write_other_addr: assert property (
        @(posedge clk) disable iff (write_reset || $initstate)
        (!$past(write_reset) && ($past(we) === 1'b1) && (raddr == $past(raddr)) &&
         ($past(waddr) != $past(raddr)))
        |-> (dataout == $past(dataout))
    );

    // A write to address 0 is visible when address 0 is read next cycle.
    check_write_addr0_readback: assert property (
        @(posedge clk) disable iff (write_reset || $initstate)
        (!$past(write_reset) && ($past(we) === 1'b1) &&
         ($past(waddr) == 3'b000) && (raddr == 3'b000))
        |-> (dataout == $past(datain))
    );

    // A write to address 1 is visible when address 1 is read next cycle.
    check_write_addr1_readback: assert property (
        @(posedge clk) disable iff (write_reset || $initstate)
        (!$past(write_reset) && ($past(we) === 1'b1) &&
         ($past(waddr) == 3'b001) && (raddr == 3'b001))
        |-> (dataout == $past(datain))
    );

    // A write to address 2 is visible when address 2 is read next cycle.
    check_write_addr2_readback: assert property (
        @(posedge clk) disable iff (write_reset || $initstate)
        (!$past(write_reset) && ($past(we) === 1'b1) &&
         ($past(waddr) == 3'b010) && (raddr == 3'b010))
        |-> (dataout == $past(datain))
    );

    // A write to address 3 is visible when address 3 is read next cycle.
    check_write_addr3_readback: assert property (
        @(posedge clk) disable iff (write_reset || $initstate)
        (!$past(write_reset) && ($past(we) === 1'b1) &&
         ($past(waddr) == 3'b011) && (raddr == 3'b011))
        |-> (dataout == $past(datain))
    );

    // A write to address 4 is visible when address 4 is read next cycle.
    check_write_addr4_readback: assert property (
        @(posedge clk) disable iff (write_reset || $initstate)
        (!$past(write_reset) && ($past(we) === 1'b1) &&
         ($past(waddr) == 3'b100) && (raddr == 3'b100))
        |-> (dataout == $past(datain))
    );

    // A write to address 5 is visible when address 5 is read next cycle.
    check_write_addr5_readback: assert property (
        @(posedge clk) disable iff (write_reset || $initstate)
        (!$past(write_reset) && ($past(we) === 1'b1) &&
         ($past(waddr) == 3'b101) && (raddr == 3'b101))
        |-> (dataout == $past(datain))
    );

endmodule

