module top_module (
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    input select,
    output [3:0] result,
    output wire eq,
    output wire gt,
    output wire lt
);

    wire [3:0] alu_result;

    alu_module alu_inst (
        .A(A),
        .B(B),
        .OP(OP),
        .result(alu_result)
    );

    comparator_module comparator_inst (
        .A(A),
        .B(B),
        .eq(eq),
        .gt(gt),
        .lt(lt)
    );

    assign result = select ? alu_result : 4'b0;

endmodule

module alu_module (
    input [3:0] A,
    input [3:0] B,
    input [2:0] OP,
    output reg [3:0] result
);

    always @(*) begin
        case (OP)
            3'b000: result = A + B;
            3'b001: result = A - B;
            3'b010: result = A & B;
            3'b011: result = A | B;
            3'b100: result = A ^ B;
            3'b101: result = {A[2:0], 1'b0};
            3'b110: result = A >> 1;
            3'b111: result = ~A;
        endcase
    end

endmodule

module comparator_module (
    input [3:0] A,
    input [3:0] B,
    output reg eq,
    output reg gt,
    output reg lt
);

    always @(*) begin
        eq = (A == B);
        gt = (A > B);
        lt = (A < B);
    end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [2:0] OP,
    input logic select,
    input logic [3:0] result,
    input logic eq,
    input logic gt,
    input logic lt
);

    function automatic logic [3:0] add_wrap (
        input logic [3:0] a,
        input logic [3:0] b
    );
        add_wrap = a + b;
    endfunction

    function automatic logic [3:0] sub_wrap (
        input logic [3:0] a,
        input logic [3:0] b
    );
        sub_wrap = a - b;
    endfunction

    // Result is zero when the ALU output is not selected.
    check_result_zero_when_unselected: assert property (
        @(posedge clk) (select === 1'b0) |-> (result === 4'b0000)
    );

    // Addition opcode returns the wrapped 4-bit sum when selected.
    check_result_add: assert property (
        @(posedge clk) ((select === 1'b1) && (OP === 3'b000)) |-> (result === add_wrap(A, B))
    );

    // Subtraction opcode returns the wrapped 4-bit difference when selected.
    check_result_sub: assert property (
        @(posedge clk) ((select === 1'b1) && (OP === 3'b001)) |-> (result === sub_wrap(A, B))
    );

    // AND opcode returns A & B when selected.
    check_result_and: assert property (
        @(posedge clk) ((select === 1'b1) && (OP === 3'b010)) |-> (result === (A & B))
    );

    // OR opcode returns A | B when selected.
    check_result_or: assert property (
        @(posedge clk) ((select === 1'b1) && (OP === 3'b011)) |-> (result === (A | B))
    );

    // XOR opcode returns A ^ B when selected.
    check_result_xor: assert property (
        @(posedge clk) ((select === 1'b1) && (OP === 3'b100)) |-> (result === (A ^ B))
    );

    // Shift-left opcode returns A shifted left by one when selected.
    check_result_shift_left: assert property (
        @(posedge clk) ((select === 1'b1) && (OP === 3'b101)) |-> (result === {A[2:0], 1'b0})
    );

    // Shift-right opcode returns A shifted right by one when selected.
    check_result_shift_right: assert property (
        @(posedge clk) ((select === 1'b1) && (OP === 3'b110)) |-> (result === (A >> 1))
    );

    // Invert opcode returns bitwise NOT of A when selected.
    check_result_invert: assert property (
        @(posedge clk) ((select === 1'b1) && (OP === 3'b111)) |-> (result === (~A))
    );

    // eq reflects whether A and B are equal.
    check_eq_flag: assert property (
        @(posedge clk) (eq === (A == B))
    );

    // gt reflects whether A is greater than B.
    check_gt_flag: assert property (
        @(posedge clk) (gt === (A > B))
    );

    // lt reflects whether A is less than B.
    check_lt_flag: assert property (
        @(posedge clk) (lt === (A < B))
    );

endmodule

rtl:
module servo_control_block (
  input [9:0] pos_desired,
  input [9:0] pos_current,
  input clk,
  output reg pwm_out
);

parameter freq = 50; // frequency of PWM signal
parameter duty_min = 5; // minimum duty cycle of PWM signal (in percent)
parameter duty_max = 10; // maximum duty cycle of PWM signal (in percent)
parameter pos_min = 0; // minimum position of servo motor
parameter pos_max = 1023; // maximum position of servo motor

reg [9:0] pos_diff;
reg [31:0] pwm_period;
reg [31:0] pwm_counter;
reg [9:0] duty_cycle;

// Calculate the duty cycle of the PWM signal
always @(*) begin
  pos_diff = pos_desired - pos_current;
  pwm_period = 200000000 / freq; // 200MHz clock
  duty_cycle = ((duty_max - duty_min) * (pos_max - pos_diff)) / (pos_max - pos_min) + duty_min;
end

// Generate the PWM signal
always @(posedge clk) begin
  if (pwm_counter < pwm_period * duty_cycle) begin
    pwm_out <= 1;
  end else begin
    pwm_out <= 0;
  end

  pwm_counter <= pwm_counter + 1;
  if (pwm_counter >= pwm_period) begin
    pwm_counter <= 0;
  end
end

endmodule

sva:
module servo_control_block_sva #(
    parameter integer freq     = 50,
    parameter integer duty_min = 5,
    parameter integer duty_max = 10,
    parameter integer pos_min  = 0,
    parameter integer pos_max  = 1023
) (
    input logic [9:0]  pos_desired,
    input logic [9:0]  pos_current,
    input logic        clk,
    input logic        pwm_out,
    input logic [9:0]  pos_diff,
    input logic [31:0] pwm_period,
    input logic [31:0] pwm_counter,
    input logic [9:0]  duty_cycle
);

    // pos_diff matches the 10-bit position subtraction.
    check_pos_diff_calculation: assert property (
        @(posedge clk) pos_diff == (pos_desired - pos_current)
    );

    // pwm_period is the constant period derived from freq.
    check_pwm_period_calculation: assert property (
        @(posedge clk) pwm_period == (200000000 / freq)
    );

    // duty_cycle follows the RTL arithmetic based on pos_diff.
    check_duty_cycle_calculation: assert property (
        @(posedge clk) duty_cycle == ((((duty_max - duty_min) * (pos_max - pos_diff)) / (pos_max - pos_min)) + duty_min)
    );

    // duty_cycle stays within the configured min and max.
    check_duty_cycle_range: assert property (
        @(posedge clk) (duty_cycle >= duty_min) && (duty_cycle <= duty_max)
    );

    // Matching positions produce the maximum duty cycle.
    check_max_duty_when_positions_match: assert property (
        @(posedge clk) (pos_desired == pos_current) |-> (duty_cycle == duty_max)
    );

    // Full-scale pos_diff produces the minimum duty cycle.
    check_min_duty_at_full_scale_diff: assert property (
        @(posedge clk) (pos_diff == pos_max) |-> (duty_cycle == duty_min)
    );

    // Below pwm_period, the counter increments by one on the next clock.
    check_counter_increments_below_period: assert property (
        @(posedge clk) (pwm_counter < pwm_period) |=> (pwm_counter == ($past(pwm_counter) + 32'd1))
    );

    // At or above pwm_period, the counter resets to zero on the next clock.
    check_counter_wraps_at_period: assert property (
        @(posedge clk) (pwm_counter >= pwm_period) |=> (pwm_counter == 32'd0)
    );

    // After one update, the counter is always driven into the valid range.
    check_counter_bounded_after_update: assert property (
        @(posedge clk) 1'b1 |=> (pwm_counter <= pwm_period)
    );

    // A counter value below the compare threshold drives pwm_out high next cycle.
    check_pwm_high_below_threshold: assert property (
        @(posedge clk) (pwm_counter < (pwm_period * duty_cycle)) |=> (pwm_out == 1'b1)
    );

    // A counter value at or above the compare threshold drives pwm_out low next cycle.
    check_pwm_low_at_or_above_threshold: assert property (
        @(posedge clk) (pwm_counter >= (pwm_period * duty_cycle)) |=> (pwm_out == 1'b0)
    );

endmodule

