module counter(
  input clk,
  input reset,
  output reg [3:0] out
);

  reg [3:0] pipeline_reg1;
  reg [3:0] pipeline_reg2;
  reg [3:0] pipeline_reg3;

  always @(posedge clk) begin
    if (reset) begin
      pipeline_reg1 <= 4'b0;
      pipeline_reg2 <= 4'b0;
      pipeline_reg3 <= 4'b0;
      out <= 4'b0;
    end else begin
      pipeline_reg1 <= out;
      pipeline_reg2 <= pipeline_reg1;
      pipeline_reg3 <= pipeline_reg2;
      out <= pipeline_reg3 + 1;
    end
  end

endmodule

sva:
module counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] out,
    input logic [3:0] pipeline_reg1,
    input logic [3:0] pipeline_reg2,
    input logic [3:0] pipeline_reg3
);

    // Reset clears all registers on the next clock.
    check_reset_clears_state: assert property (
        @(posedge clk)
        reset |=> (pipeline_reg1 == 4'b0) &&
                  (pipeline_reg2 == 4'b0) &&
                  (pipeline_reg3 == 4'b0) &&
                  (out == 4'b0)
    );

    // State is all zero immediately after a reset cycle.
    check_post_reset_zero_state: assert property (
        @(posedge clk) disable iff (reset)
        $past(reset) |-> (pipeline_reg1 == 4'b0) &&
                         (pipeline_reg2 == 4'b0) &&
                         (pipeline_reg3 == 4'b0) &&
                         (out == 4'b0)
    );

    // The first active cycle after reset produces out=1 with zeroed pipeline.
    check_first_active_cycle_after_reset: assert property (
        @(posedge clk) disable iff (reset)
        $fell(reset) |=> (pipeline_reg1 == 4'b0) &&
                         (pipeline_reg2 == 4'b0) &&
                         (pipeline_reg3 == 4'b0) &&
                         (out == 4'b1)
    );

    // pipeline_reg1 captures the previous out value.
    check_pipeline_reg1_captures_out: assert property (
        @(posedge clk) disable iff (reset)
        !$past(reset) |-> (pipeline_reg1 == $past(out))
    );

    // pipeline_reg2 captures the previous pipeline_reg1 value.
    check_pipeline_reg2_captures_reg1: assert property (
        @(posedge clk) disable iff (reset)
        !$past(reset) |-> (pipeline_reg2 == $past(pipeline_reg1))
    );

    // pipeline_reg3 captures the previous pipeline_reg2 value.
    check_pipeline_reg3_captures_reg2: assert property (
        @(posedge clk) disable iff (reset)
        !$past(reset) |-> (pipeline_reg3 == $past(pipeline_reg2))
    );

    // out updates from the previous pipeline_reg3 value plus one.
    check_out_updates_from_pipeline_reg3: assert property (
        @(posedge clk) disable iff (reset)
        !$past(reset) |-> (out == ($past(pipeline_reg3) + 4'd1))
    );

    // After two active cycles, pipeline_reg2 matches out from two cycles earlier.
    check_pipeline_reg2_two_cycle_delay: assert property (
        @(posedge clk) disable iff (reset)
        (!$past(reset,1) && !$past(reset,2)) |-> (pipeline_reg2 == $past(out,2))
    );

    // After three active cycles, pipeline_reg3 matches out from three cycles earlier.
    check_pipeline_reg3_three_cycle_delay: assert property (
        @(posedge clk) disable iff (reset)
        (!$past(reset,1) && !$past(reset,2) && !$past(reset,3)) |-> (pipeline_reg3 == $past(out,3))
    );

    // After four active cycles, out matches out from four cycles earlier plus one.
    check_out_four_cycle_recurrence: assert property (
        @(posedge clk) disable iff (reset)
        (!$past(reset,1) && !$past(reset,2) && !$past(reset,3) && !$past(reset,4)) |-> (out == ($past(out,4) + 4'd1))
    );

endmodule

rtl:
module magnitude_comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    input clk,  // Added clk as an input
    output EQ,
    output GT,
    output LT
);

reg [3:0] A_reg, B_reg;
reg [2:0] stage;
wire [3:0] A_next, B_next;
wire EQ_next, GT_next, LT_next;

assign EQ = (stage == 2) ? EQ_next : 1'b0;
assign GT = (stage == 2) ? GT_next : 1'b0;
assign LT = (stage == 2) ? LT_next : 1'b0;

always @(posedge clk) begin  // Corrected the always block to use clk
    case(stage)
        0: begin
            A_reg <= A;
            B_reg <= B;
            stage <= 1;
        end
        1: begin
            A_reg <= A_next;
            B_reg <= B_next;
            stage <= 2;
        end
        2: begin
            stage <= 0;
        end
    endcase
end

assign A_next = (A_reg > B_reg) ? A_reg : B_reg;
assign B_next = (A_reg > B_reg) ? B_reg : A_reg;
assign EQ_next = (A_next == B_next) ? 1'b1 : 1'b0;
assign GT_next = (A_next > B_next) ? 1'b1 : 1'b0;
assign LT_next = (A_next < B_next) ? 1'b1 : 1'b0;

endmodule

sva:
module magnitude_comparator_4bit_assertions (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic clk,
    input logic EQ,
    input logic GT,
    input logic LT,
    input logic [3:0] A_reg,
    input logic [3:0] B_reg,
    input logic [2:0] stage,
    input logic [3:0] A_next,
    input logic [3:0] B_next,
    input logic EQ_next,
    input logic GT_next,
    input logic LT_next
);

    // Stage 0 captures inputs and advances to stage 1.
    check_stage0_captures_inputs: assert property (
        @(posedge clk)
        (stage == 3'd0)
        |=> (stage == 3'd1) &&
            (A_reg == $past(A)) &&
            (B_reg == $past(B))
    );

    // Stage 1 sorts the captured registers and advances to stage 2.
    check_stage1_sorts_registers: assert property (
        @(posedge clk)
        (stage == 3'd1)
        |=> (stage == 3'd2) &&
            (A_reg == (($past(A_reg) > $past(B_reg)) ? $past(A_reg) : $past(B_reg))) &&
            (B_reg == (($past(A_reg) > $past(B_reg)) ? $past(B_reg) : $past(A_reg)))
    );

    // Stage 2 returns to stage 0 and leaves the registers unchanged.
    check_stage2_returns_to_stage0: assert property (
        @(posedge clk)
        (stage == 3'd2)
        |=> (stage == 3'd0) &&
            (A_reg == $past(A_reg)) &&
            (B_reg == $past(B_reg))
    );

    // Unhandled stage values hold state because the case has no default.
    check_invalid_stage_holds_state: assert property (
        @(posedge clk)
        (stage != 3'd0 && stage != 3'd1 && stage != 3'd2)
        |=> (stage == $past(stage)) &&
            (A_reg == $past(A_reg)) &&
            (B_reg == $past(B_reg))
    );

    // Outputs are forced low unless stage 2 is active.
    check_outputs_low_outside_stage2: assert property (
        @(posedge clk)
        (stage != 3'd2)
        |-> (EQ == 1'b0) &&
             (GT == 1'b0) &&
             (LT == 1'b0)
    );

    // In stage 2, outputs report equality or difference of the current registers.
    check_stage2_outputs_match_register_relation: assert property (
        @(posedge clk)
        (stage == 3'd2)
        |-> (EQ == (A_reg == B_reg)) &&
             (GT == (A_reg != B_reg)) &&
             (LT == 1'b0)
    );

    // LT is never asserted by this implementation.
    check_lt_output_always_low: assert property (
        @(posedge clk)
        (LT == 1'b0)
    );

    // A_next is the larger of A_reg and B_reg.
    check_a_next_is_max_of_registers: assert property (
        @(posedge clk)
        A_next == ((A_reg > B_reg) ? A_reg : B_reg)
    );

    // B_next is the smaller of A_reg and B_reg.
    check_b_next_is_min_of_registers: assert property (
        @(posedge clk)
        B_next == ((A_reg > B_reg) ? B_reg : A_reg)
    );

    // The next compare flags encode only equal or greater-than.
    check_compare_next_flags_match_relation: assert property (
        @(posedge clk)
        (EQ_next == (A_reg == B_reg)) &&
        (GT_next == (A_reg != B_reg)) &&
        (LT_next == 1'b0)
    );

endmodule

rtl:
module calculator(a, b, op, add_out, sub_out, mul_out, div_out);

    input signed [15:0] a, b;
    input [1:0] op;
    output reg signed [15:0] add_out, sub_out, mul_out, div_out;

    always @(*) begin
        case(op)
            2'b00: begin // addition
                add_out = a + b;
                sub_out = 16'h0000;
                mul_out = 16'h0000;
                div_out = 16'h0000;
            end
            2'b01: begin // subtraction
                add_out = 16'h0000;
                sub_out = a - b;
                mul_out = 16'h0000;
                div_out = 16'h0000;
            end
            2'b10: begin // multiplication
                add_out = 16'h0000;
                sub_out = 16'h0000;
                mul_out = a * b;
                div_out = 16'h0000;
            end
            2'b11: begin // division
                add_out = 16'h0000;
                sub_out = 16'h0000;
                mul_out = 16'h0000;
                if (b != 16'h0000) begin
                    div_out = a / b;
                end else begin
                    div_out = 16'hFFFF;
                end
            end
        endcase
    end

endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic signed [15:0] a,
    input logic signed [15:0] b,
    input logic [1:0] op,
    input logic signed [15:0] add_out,
    input logic signed [15:0] sub_out,
    input logic signed [15:0] mul_out,
    input logic signed [15:0] div_out
);

    function automatic logic signed [15:0] calc_add (
        input logic signed [15:0] x,
        input logic signed [15:0] y
    );
        calc_add = x + y;
    endfunction

    function automatic logic signed [15:0] calc_sub (
        input logic signed [15:0] x,
        input logic signed [15:0] y
    );
        calc_sub = x - y;
    endfunction

    function automatic logic signed [15:0] calc_mul (
        input logic signed [15:0] x,
        input logic signed [15:0] y
    );
        calc_mul = x * y;
    endfunction

    function automatic logic signed [15:0] calc_div (
        input logic signed [15:0] x,
        input logic signed [15:0] y
    );
        if (y != 16'sh0000)
            calc_div = x / y;
        else
            calc_div = 16'shFFFF;
    endfunction

    // Addition mode drives the sum and clears the other outputs.
    check_addition_mode_outputs: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ((add_out == calc_add(a, b)) &&
                           (sub_out == 16'sh0000) &&
                           (mul_out == 16'sh0000) &&
                           (div_out == 16'sh0000))
    );

    // Subtraction mode drives the difference and clears the other outputs.
    check_subtraction_mode_outputs: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ((add_out == 16'sh0000) &&
                           (sub_out == calc_sub(a, b)) &&
                           (mul_out == 16'sh0000) &&
                           (div_out == 16'sh0000))
    );

    // Multiplication mode drives the product and clears the other outputs.
    check_multiplication_mode_outputs: assert property (
        @(posedge clk)
        (op == 2'b10) |-> ((add_out == 16'sh0000) &&
                           (sub_out == 16'sh0000) &&
                           (mul_out == calc_mul(a, b)) &&
                           (div_out == 16'sh0000))
    );

    // Division mode with a nonzero divisor drives the quotient and clears the other outputs.
    check_division_mode_nonzero_divisor: assert property (
        @(posedge clk)
        ((op == 2'b11) && (b != 16'sh0000)) |-> ((add_out == 16'sh0000) &&
                                                 (sub_out == 16'sh0000) &&
                                                 (mul_out == 16'sh0000) &&
                                                 (div_out == calc_div(a, b)))
    );

    // Division by zero returns 16'hFFFF and clears the other outputs.
    check_division_mode_zero_divisor: assert property (
        @(posedge clk)
        ((op == 2'b11) && (b == 16'sh0000)) |-> ((add_out == 16'sh0000) &&
                                                 (sub_out == 16'sh0000) &&
                                                 (mul_out == 16'sh0000) &&
                                                 (div_out == 16'shFFFF))
    );

endmodule

rtl:
module counter (
  input wire clk,
  input wire rst,
  input wire ld,
  input wire [15:0] d,
  output reg [15:0] q,
  output reg overflow
);

  always @(posedge clk) begin
    if (rst) begin
      q <= 0;
      overflow <= 0;
    end else if (ld) begin
      q <= d;
      overflow <= 0;
    end else if (q == 16'hFFFF) begin
      q <= 0;
      overflow <= 1;
    end else begin
      q <= q + 1'b1;
      overflow <= 0;
    end
  end

endmodule

sva:
module counter_sva (
    input logic        clk,
    input logic        rst,
    input logic        ld,
    input logic [15:0] d,
    input logic [15:0] q,
    input logic        overflow
);

    // Synchronous reset clears q and overflow.
    check_reset_clears_state: assert property (
        @(posedge clk) rst |=> (q == 16'h0000 && overflow == 1'b0)
    );

    // Load captures d into q and clears overflow.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (rst)
        ld |=> (q == $past(d) && overflow == 1'b0)
    );

    // When not loading and not at max, q increments and overflow stays low.
    check_increment_behavior: assert property (
        @(posedge clk) disable iff (rst)
        (!ld && (q != 16'hFFFF)) |=> (q == ($past(q) + 16'h0001) && overflow == 1'b0)
    );

    // When not loading at max count, q wraps to zero and overflow is set.
    check_wrap_sets_overflow: assert property (
        @(posedge clk) disable iff (rst)
        (!ld && (q == 16'hFFFF)) |=> (q == 16'h0000 && overflow == 1'b1)
    );

    // A wrap-generated overflow pulse lasts only one cycle.
    check_overflow_single_cycle_on_wrap: assert property (
        @(posedge clk) disable iff (rst)
        (!ld && (q == 16'hFFFF)) |=> (overflow == 1'b1) ##1 (overflow == 1'b0)
    );

endmodule

rtl:
module mux_2to1(
    input [3:0] A,
    input [3:0] B,
    input sel,
    input clk,
    input reset,
    output reg [3:0] out,
    output reg [3:0] out_a,
    output reg [3:0] out_b
);

always @(posedge clk or negedge reset) begin
    if (!reset) begin
        out <= 4'b0000;
        out_a <= 4'b0000;
        out_b <= 4'b0000;
    end else begin
        if (sel) begin
            out <= B;
            out_a <= 4'b0000;
            out_b <= B;
        end else begin
            out <= A;
            out_a <= A;
            out_b <= 4'b0000;
        end
    end
end

endmodule

sva:
module mux_2to1_sva(
    input logic [3:0] A,
    input logic [3:0] B,
    input logic sel,
    input logic clk,
    input logic reset,
    input logic [3:0] out,
    input logic [3:0] out_a,
    input logic [3:0] out_b
);

    // Reset forces all registered outputs low.
    check_reset_clears_outputs: assert property (
        @(posedge clk) disable iff ($initstate)
        !reset |-> (out == 4'h0 && out_a == 4'h0 && out_b == 4'h0)
    );

    // out captures the selected input on the next active clock.
    check_out_captures_selected_input: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (out == ($past(sel) ? $past(B) : $past(A)))
    );

    // out_a captures A when sel is low, otherwise it clears.
    check_out_a_updates_from_a_or_zero: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (out_a == ($past(sel) ? 4'h0 : $past(A)))
    );

    // out_b captures B when sel is high, otherwise it clears.
    check_out_b_updates_from_b_or_zero: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (out_b == ($past(sel) ? $past(B) : 4'h0))
    );

    // At least one auxiliary output is always zero.
    check_aux_outputs_not_both_active: assert property (
        @(posedge clk) disable iff (!reset)
        !$initstate |-> ((out_a == 4'h0) || (out_b == 4'h0))
    );

    // The main output equals the active auxiliary path.
    check_out_equals_or_of_aux_outputs: assert property (
        @(posedge clk) disable iff (!reset)
        !$initstate |-> (out == (out_a | out_b))
    );

endmodule

