    // adc_clk mirrors rx_clk at the sampling edge.
    check_adc_clk_mirrors_rx_clk: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_clk == rx_clk)
    );

    // adc_or_a is tied low.
    check_adc_or_a_tied_low: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_or_a == 1'b0)
    );

    // adc_or_b is tied low.
    check_adc_or_b_tied_low: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_or_b == 1'b0)
    );

    // adc_data_a[63:48] matches the s3 byte mapping.
    check_adc_data_a_s3_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_a[63:48] == {rx_data[31:24], rx_data[63:56]})
    );

    // adc_data_a[47:32] matches the s2 byte mapping.
    check_adc_data_a_s2_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_a[47:32] == {rx_data[23:16], rx_data[55:48]})
    );

    // adc_data_a[31:16] matches the s1 byte mapping.
    check_adc_data_a_s1_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_a[31:16] == {rx_data[15:8], rx_data[47:40]})
    );

    // adc_data_a[15:0] matches the s0 byte mapping.
    check_adc_data_a_s0_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_a[15:0] == {rx_data[7:0], rx_data[39:32]})
    );

    // adc_data_b[63:48] matches the s3 byte mapping.
    check_adc_data_b_s3_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_b[63:48] == {rx_data[95:88], rx_data[127:120]})
    );

    // adc_data_b[47:32] matches the s2 byte mapping.
    check_adc_data_b_s2_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_b[47:32] == {rx_data[87:80], rx_data[119:112]})
    );

    // adc_data_b[31:16] matches the s1 byte mapping.
    check_adc_data_b_s1_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_b[31:16] == {rx_data[79:72], rx_data[111:104]})
    );

    // adc_data_b[15:0] matches the s0 byte mapping.
    check_adc_data_b_s0_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_b[15:0] == {rx_data[71:64], rx_data[103:96]})
    );

    // adc_status clears one cycle after reset is sampled high.
    check_adc_status_clears_after_reset: assert property (
        @(posedge rx_clk)
        adc_rst |=> (adc_status == 1'b0)
    );

    // adc_status sets one cycle after reset is sampled low.
    check_adc_status_sets_after_nonreset: assert property (
        @(posedge rx_clk)
        !adc_rst |=> (adc_status == 1'b1)
    );

endmodule

rtl:
module shift_register (
    input clk,
    input [3:0] data_in,
    output [3:0] data_out
);

    reg [3:0] q;

    always @(posedge clk) begin
        q <= {q[2:0], data_in[0]};
    end

    assign data_out = q;

endmodule

sva:
module shift_register_sva (
    input logic       clk,
    input logic [3:0] data_in,
    input logic [3:0] data_out,
    input logic [3:0] q
);

    // data_out must mirror the internal register q.
    check_data_out_matches_q: assert property (
        @(posedge clk) data_out == q
    );

    // q must shift left and load the previous data_in[0] each cycle.
    check_q_shift_update: assert property (
        @(posedge clk) 1'b1 |=> q == {$past(q[2:0]), $past(data_in[0])}
    );

    // q[0] must load the previous data_in[0].
    check_q_bit0_loads_data_in0: assert property (
        @(posedge clk) 1'b1 |=> q[0] == $past(data_in[0])
    );

    // q[1] must receive the previous q[0].
    check_q_bit1_shifts_from_bit0: assert property (
        @(posedge clk) 1'b1 |=> q[1] == $past(q[0])
    );

    // q[2] must receive the previous q[1].
    check_q_bit2_shifts_from_bit1: assert property (
        @(posedge clk) 1'b1 |=> q[2] == $past(q[1])
    );

    // q[3] must receive the previous q[2].
    check_q_bit3_shifts_from_bit2: assert property (
        @(posedge clk) 1'b1 |=> q[3] == $past(q[2])
    );

    // data_out must show the shifted register value each cycle.
    check_data_out_shift_update: assert property (
        @(posedge clk) 1'b1 |=> data_out == {$past(data_out[2:0]), $past(data_in[0])}
    );

    // data_out[0] must load the previous data_in[0].
    check_data_out_bit0_loads_data_in0: assert property (
        @(posedge clk) 1'b1 |=> data_out[0] == $past(data_in[0])
    );

    // data_out[1] must receive the previous data_out[0].
    check_data_out_bit1_shifts_from_bit0: assert property (
        @(posedge clk) 1'b1 |=> data_out[1] == $past(data_out[0])
    );

    // data_out[2] must receive the previous data_out[1].
    check_data_out_bit2_shifts_from_bit1: assert property (
        @(posedge clk) 1'b1 |=> data_out[2] == $past(data_out[1])
    );

    // data_out[3] must receive the previous data_out[2].
    check_data_out_bit3_shifts_from_bit2: assert property (
        @(posedge clk) 1'b1 |=> data_out[3] == $past(data_out[2])
    );

endmodule

rtl:
module twos_complement(
  input [3:0] in,
  output reg [3:0] out
);

  always @(*) begin
    if (in[3] == 1) begin
      out = ~(in) + 1;
    end else begin
      out = in;
    end
  end

endmodule

sva:
module twos_complement_sva(
    input logic [3:0] in,
    input logic [3:0] out
);

    // Non-negative inputs pass through unchanged.
    check_non_negative_passthrough: assert property (
        @($global_clock) (!in[3]) |-> (out == in)
    );

    // Negative inputs are converted by bitwise invert plus one.
    check_negative_invert_plus_one: assert property (
        @($global_clock) (in[3]) |-> (out == ((~in) + 4'd1))
    );

    // The most-negative 4-bit input maps to itself.
    check_most_negative_preserved: assert property (
        @($global_clock) (in == 4'b1000) |-> (out == 4'b1000)
    );

endmodule

rtl:
module counter (
    CLK,
    RST,
    EN,
    OUT
);

    input CLK;
    input RST;
    input EN;
    output reg [3:0] OUT;

    always @(posedge CLK or negedge RST)
    begin
        if (!RST) // asynchronous reset
            OUT <= 4'd0;
        else if (EN) // counter enabled
            OUT <= OUT + 1;
    end

endmodule

sva:
module counter_sva (
    input logic       CLK,
    input logic       RST,
    input logic       EN,
    input logic [3:0] OUT
);

    // A sampled low reset clears OUT by the next clock.
    check_reset_clears_out: assert property (
        @(posedge CLK) (!RST) |=> (OUT == 4'd0)
    );

    // On reset deassertion, the sampled counter value starts from zero.
    check_release_reset_starts_from_zero: assert property (
        @(posedge CLK) $rose(RST) |-> (OUT == 4'd0)
    );

    // When enabled, the counter increments by one on the next clock.
    check_increment_when_enabled: assert property (
        @(posedge CLK) disable iff (!RST)
        EN |=> (OUT == ($past(OUT) + 4'd1))
    );

    // When disabled, the counter holds its value on the next clock.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (!RST)
        !EN |=> (OUT == $past(OUT))
    );

    // When enabled at 15, the 4-bit counter wraps to zero.
    check_wrap_from_max: assert property (
        @(posedge CLK) disable iff (!RST)
        (EN && (OUT == 4'hF)) |=> (OUT == 4'h0)
    );

endmodule

module lookahead_assertions (
    input logic clk,
    input logic c_in,
    input logic c_out,
    input logic [2:0] c,
    input logic [3:0] p,
    input logic [3:0] g,
    input logic P,
    input logic G
);

    // c[0] matches the bit-0 carry lookahead equation.
    check_c0_equation: assert property (
        @(posedge clk)
        c[0] == (g[0] | (p[0] & c_in))
    );

    // c[1] matches the bit-1 carry lookahead equation.
    check_c1_equation: assert property (
        @(posedge clk)
        c[1] == (g[1] | (g[0] & p[1]) | (p[1] & p[0] & c_in))
    );

    // c[2] matches the bit-2 carry lookahead equation.
    check_c2_equation: assert property (
        @(posedge clk)
        c[2] == (g[2] | (g[1] & p[2]) | (g[0] & p[1] & p[2]) | (p[2] & p[1] & p[0] & c_in))
    );

    // c_out matches the final carry lookahead equation.
    check_cout_equation: assert property (
        @(posedge clk)
        c_out == (g[3] | (g[2] & p[3]) | (g[1] & p[2] & p[3]) |
                  (g[0] & p[1] & p[2] & p[3]) | (p[3] & p[2] & p[1] & p[0] & c_in))
    );

    // G matches the group-generate equation.
    check_group_generate_equation: assert property (
        @(posedge clk)
        G == (g[3] | (g[2] & p[3]) | (g[1] & p[2] & p[3]) | (p[3] & p[2] & p[1] & g[0]))
    );

    // P matches the group-propagate equation.
    check_group_propagate_equation: assert property (
        @(posedge clk)
        P == (p[3] & p[2] & p[1] & p[0])
    );

    // c[1] is the recursive carry form using c[0].
    check_c1_recursive_form: assert property (
        @(posedge clk)
        c[1] == (g[1] | (p[1] & c[0]))
    );

    // c[2] is the recursive carry form using c[1].
    check_c2_recursive_form: assert property (
        @(posedge clk)
        c[2] == (g[2] | (p[2] & c[1]))
    );

    // c_out is the recursive carry form using c[2].
    check_cout_recursive_form: assert property (
        @(posedge clk)
        c_out == (g[3] | (p[3] & c[2]))
    );

    // c_out must equal group generate OR propagated c_in.
    check_cout_group_relation: assert property (
        @(posedge clk)
        c_out == (G | (P & c_in))
    );

endmodule

rtl:
module top_module (
    input [15:0] in,
    input [3:0] sel,
    input EN,
    input [3:0] A,
    input [3:0] B,
    input [2:0] op,
    output reg [3:0] out,
    output reg valid
);

reg [3:0] mux_out;
reg [3:0] alu_out;

// 16-to-1 multiplexer
always @(*) begin
    case(sel)
        4'd0: mux_out = in[3:0];
        4'd1: mux_out = in[7:4];
        4'd2: mux_out = in[11:8];
        4'd3: mux_out = in[15:12];
        default: mux_out = 4'b0;
    endcase
end

// 4-bit ALU
always @(*) begin
    case(op)
        3'b000: alu_out = A + B;
        3'b001: alu_out = A - B;
        3'b010: alu_out = A & B;
        3'b011: alu_out = A | B;
        3'b100: alu_out = A ^ B;
        default: alu_out = 4'b0;
    endcase
end

// Final output module
always @(*) begin
    if(valid) begin
        out = alu_out;
    end else if(EN) begin
        out = mux_out;
    end else begin
        out = 4'b0;
    end

    valid = (op != 3'b101);
end

endmodule

sva:
module top_module_assertions (
    input logic [15:0] in,
    input logic [3:0]  sel,
    input logic        EN,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic [2:0]  op,
    input logic [3:0]  out,
    input logic        valid
);

    // No RTL clock or reset; sample this combinational logic on the formal global clock.

    // valid is low only for opcode 3'b101.
    check_valid_decode: assert property (
        @($global_clock) (valid == (op != 3'b101))
    );

    // ADD opcode drives the ALU sum to out and keeps valid high.
    check_add_out: assert property (
        @($global_clock) (op == 3'b000) |-> ((valid == 1'b1) && (out == (A + B)))
    );

    // SUB opcode drives the ALU difference to out and keeps valid high.
    check_sub_out: assert property (
        @($global_clock) (op == 3'b001) |-> ((valid == 1'b1) && (out == (A - B)))
    );

    // AND opcode drives the bitwise AND to out and keeps valid high.
    check_and_out: assert property (
        @($global_clock) (op == 3'b010) |-> ((valid == 1'b1) && (out == (A & B)))
    );

    // OR opcode drives the bitwise OR to out and keeps valid high.
    check_or_out: assert property (
        @($global_clock) (op == 3'b011) |-> ((valid == 1'b1) && (out == (A | B)))
    );

    // XOR opcode drives the bitwise XOR to out and keeps valid high.
    check_xor_out: assert property (
        @($global_clock) (op == 3'b100) |-> ((valid == 1'b1) && (out == (A ^ B)))
    );

    // Unhandled ALU opcodes 110 and 111 drive zero while valid stays high.
    check_default_alu_out: assert property (
        @($global_clock) ((op == 3'b110) || (op == 3'b111)) |-> ((valid == 1'b1) && (out == 4'b0000))
    );

    // Opcode 101 with EN low drives zero and deasserts valid.
    check_invalid_op_en_low_zero: assert property (
        @($global_clock) ((op == 3'b101) && (EN == 1'b0)) |-> ((valid == 1'b0) && (out == 4'b0000))
    );

    // Opcode 101 with EN high and sel 0 forwards in[3:0].
    check_mux_sel0: assert property (
        @($global_clock) ((op == 3'b101) && (EN == 1'b1) && (sel == 4'd0)) |-> ((valid == 1'b0) && (out == in[3:0]))
    );

    // Opcode 101 with EN high and sel 1 forwards in[7:4].
    check_mux_sel1: assert property (
        @($global_clock) ((op == 3'b101) && (EN == 1'b1) && (sel == 4'd1)) |-> ((valid == 1'b0) && (out == in[7:4]))
    );

    // Opcode 101 with EN high and sel 2 forwards in[11:8].
    check_mux_sel2: assert property (
        @($global_clock) ((op == 3'b101) && (EN == 1'b1) && (sel == 4'd2)) |-> ((valid == 1'b0) && (out == in[11:8]))
    );

    // Opcode 101 with EN high and sel 3 forwards in[15:12].
    check_mux_sel3: assert property (
        @($global_clock) ((op == 3'b101) && (EN == 1'b1) && (sel == 4'd3)) |-> ((valid == 1'b0) && (out == in[15:12]))
    );

    // Opcode 101 with EN high and unmapped sel values drives zero.
    check_mux_default_zero: assert property (
        @($global_clock) ((op == 3'b101) && (EN == 1'b1) && (sel > 4'd3)) |-> ((valid == 1'b0) && (out == 4'b0000))
    );

endmodule

