module logic_gate_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1,
    input logic X
);

    // A1 high and A2 low forces X high.
    check_a1_high_a2_low_sets_x_high: assert property (
        @($global_clock) (A1 && !A2) |-> (X == 1'b1)
    );

    // A1 low and A2 high forces X low.
    check_a1_low_a2_high_sets_x_low: assert property (
        @($global_clock) (!A1 && A2) |-> (X == 1'b0)
    );

    // With A1 and A2 both low, X equals B1 and not C1.
    check_a1_a2_low_decode: assert property (
        @($global_clock) (!A1 && !A2) |-> (X == (B1 && !C1))
    );

    // With A1 and A2 both high, X equals B1 or not C1.
    check_a1_a2_high_decode: assert property (
        @($global_clock) (A1 && A2) |-> (X == (B1 || !C1))
    );

    // X matches the complete combinational function for all input combinations.
    check_full_boolean_function: assert property (
        @($global_clock) (X == (
            (A1 && !A2) ||
            (!A1 && !A2 && B1 && !C1) ||
            (A1 && A2 && (B1 || !C1))
        ))
    );

endmodule

rtl:
module binary_to_gray (
    input [2:0] B,
    output reg [2:0] G
);

    always @ (B) begin
        G[0] = B[0] ^ B[1];
        G[1] = B[1] ^ B[2];
        G[2] = B[2];
    end

endmodule

sva:
module binary_to_gray_assertions (
    input logic [2:0] B,
    input logic [2:0] G
);

    // Full output must implement the 3-bit binary-to-Gray conversion.
    check_gray_vector: assert property (
        @($global_clock) G == {B[2], (B[1] ^ B[2]), (B[0] ^ B[1])}
    );

    // Gray MSB must match the binary MSB.
    check_gray_msb_passthrough: assert property (
        @($global_clock) G[2] == B[2]
    );

    // Gray middle bit must be B[1] XOR B[2].
    check_gray_middle_xor: assert property (
        @($global_clock) G[1] == (B[1] ^ B[2])
    );

    // Gray LSB must be B[0] XOR B[1].
    check_gray_lsb_xor: assert property (
        @($global_clock) G[0] == (B[0] ^ B[1])
    );

endmodule

module sign_inverter_sva #(parameter W = 32) (
    input logic clk,
    input logic [W-1:0] data,
    input logic [1:0] shift_region_flag,
    input logic operation,
    input logic [W-1:0] data_out
);

    // DUT is combinational with no native clock or reset; clk samples assertions.
    localparam [W-1:0] SIGN_TOGGLE_MASK = ({W{1'b1}} << (W-1));

    // Flags 00 and 11 always pass the input through.
    check_common_regions_passthrough: assert property (
        @(posedge clk)
        ((shift_region_flag == 2'b00) || (shift_region_flag == 2'b11)) |-> (data_out == data)
    );

    // With operation low and region 01, only the sign bit is inverted.
    check_op0_region01_inverts_sign: assert property (
        @(posedge clk)
        ((operation == 1'b0) && (shift_region_flag == 2'b01)) |-> (data_out == (data ^ SIGN_TOGGLE_MASK))
    );

    // With operation low and region 10, the output matches the input.
    check_op0_region10_passthrough: assert property (
        @(posedge clk)
        ((operation == 1'b0) && (shift_region_flag == 2'b10)) |-> (data_out == data)
    );

    // With operation high and region 10, only the sign bit is inverted.
    check_op1_region10_inverts_sign: assert property (
        @(posedge clk)
        ((operation == 1'b1) && (shift_region_flag == 2'b10)) |-> (data_out == (data ^ SIGN_TOGGLE_MASK))
    );

    // With operation high and region 01, the output matches the input.
    check_op1_region01_passthrough: assert property (
        @(posedge clk)
        ((operation == 1'b1) && (shift_region_flag == 2'b01)) |-> (data_out == data)
    );

    // Any output difference from the input is a sign-bit-only change.
    check_only_sign_bit_can_change: assert property (
        @(posedge clk)
        (data_out != data) |-> ((data_out ^ data) == SIGN_TOGGLE_MASK)
    );

    // Output differs from input only in the two active inversion cases.
    check_difference_only_in_active_cases: assert property (
        @(posedge clk)
        (data_out != data) |-> (((operation == 1'b0) && (shift_region_flag == 2'b01)) ||
                                ((operation == 1'b1) && (shift_region_flag == 2'b10)))
    );

    // Complete combinational mapping from inputs to output.
    check_complete_mapping: assert property (
        @(posedge clk)
        data_out == ((((operation == 1'b0) && (shift_region_flag == 2'b01)) ||
                      ((operation == 1'b1) && (shift_region_flag == 2'b10)))
                     ? (data ^ SIGN_TOGGLE_MASK) : data)
    );

endmodule

rtl:
module BCD_to_Binary (
  input [3:0] bcd_in,
  output reg [7:0] bin_out
);

  always @* begin
    case (bcd_in)
      4'b0000: bin_out = 8'b00000000;
      4'b0001: bin_out = 8'b00000001;
      4'b0010: bin_out = 8'b00000010;
      4'b0011: bin_out = 8'b00000011;
      4'b0100: bin_out = 8'b00000100;
      4'b0101: bin_out = 8'b00000101;
      4'b0110: bin_out = 8'b00000110;
      4'b0111: bin_out = 8'b00000111;
      4'b1000: bin_out = 8'b00001000;
      4'b1001: bin_out = 8'b00001001;
      default: bin_out = 8'b00000000;
    endcase
  end

endmodule

sva:
module BCD_to_Binary_sva (
    input logic clk,
    input logic [3:0] bcd_in,
    input logic [7:0] bin_out
);

    // No clock or reset exists in the RTL; sample this combinational decoder on clk.

    // BCD 0 decodes to binary 0.
    check_bcd_0_maps_to_0: assert property (
        @(posedge clk) (bcd_in == 4'b0000) |-> (bin_out == 8'b00000000)
    );

    // BCD 1 decodes to binary 1.
    check_bcd_1_maps_to_1: assert property (
        @(posedge clk) (bcd_in == 4'b0001) |-> (bin_out == 8'b00000001)
    );

    // BCD 2 decodes to binary 2.
    check_bcd_2_maps_to_2: assert property (
        @(posedge clk) (bcd_in == 4'b0010) |-> (bin_out == 8'b00000010)
    );

    // BCD 3 decodes to binary 3.
    check_bcd_3_maps_to_3: assert property (
        @(posedge clk) (bcd_in == 4'b0011) |-> (bin_out == 8'b00000011)
    );

    // BCD 4 decodes to binary 4.
    check_bcd_4_maps_to_4: assert property (
        @(posedge clk) (bcd_in == 4'b0100) |-> (bin_out == 8'b00000100)
    );

    // BCD 5 decodes to binary 5.
    check_bcd_5_maps_to_5: assert property (
        @(posedge clk) (bcd_in == 4'b0101) |-> (bin_out == 8'b00000101)
    );

    // BCD 6 decodes to binary 6.
    check_bcd_6_maps_to_6: assert property (
        @(posedge clk) (bcd_in == 4'b0110) |-> (bin_out == 8'b00000110)
    );

    // BCD 7 decodes to binary 7.
    check_bcd_7_maps_to_7: assert property (
        @(posedge clk) (bcd_in == 4'b0111) |-> (bin_out == 8'b00000111)
    );

    // BCD 8 decodes to binary 8.
    check_bcd_8_maps_to_8: assert property (
        @(posedge clk) (bcd_in == 4'b1000) |-> (bin_out == 8'b00001000)
    );

    // BCD 9 decodes to binary 9.
    check_bcd_9_maps_to_9: assert property (
        @(posedge clk) (bcd_in == 4'b1001) |-> (bin_out == 8'b00001001)
    );

    // Inputs outside valid BCD range use the default zero output.
    check_invalid_bcd_maps_to_zero: assert property (
        @(posedge clk) (bcd_in > 4'd9) |-> (bin_out == 8'b00000000)
    );

    // The output never exceeds the implemented 0-to-9 range.
    check_bin_out_range: assert property (
        @(posedge clk) (bin_out <= 8'd9)
    );

endmodule

rtl:
module GreaterThan (
  input [7:0] in1,
  input [7:0] in2,
  output out
);

  wire [7:0] diff;
  assign diff = in1 - in2;

  assign out = (diff[7] == 1) ? 1 : ((diff[6] == 1) ? 1 :
               ((diff[5] == 1) ? 1 : ((diff[4] == 1) ? 1 :
               ((diff[3] == 1) ? 1 : ((diff[2] == 1) ? 1 :
               ((diff[1] == 1) ? 1 : ((diff[0] == 1) ? 1 : 0)))))));

endmodule

sva:
module GreaterThan_sva (
    input logic [7:0] in1,
    input logic [7:0] in2,
    input logic       out
);

    wire [7:0] diff;
    assign diff = in1 - in2;

    // Output matches the OR-reduction of the subtraction result.
    check_out_matches_diff_or: assert property (
        @($global_clock) out == (|diff)
    );

    // Output is high exactly when the two inputs differ.
    check_out_matches_inequality: assert property (
        @($global_clock) out == (in1 != in2)
    );

    // Equal inputs produce a zero difference and a low output.
    check_equal_inputs_clear_out: assert property (
        @($global_clock) (in1 == in2) |-> (diff == 8'h00 && out == 1'b0)
    );

    // Unequal inputs produce a nonzero difference and a high output.
    check_unequal_inputs_set_out: assert property (
        @($global_clock) (in1 != in2) |-> (diff != 8'h00 && out == 1'b1)
    );

    // A zero internal difference forces the output low.
    check_zero_diff_means_out_low: assert property (
        @($global_clock) (diff == 8'h00) |-> (out == 1'b0)
    );

    // Any nonzero internal difference forces the output high.
    check_nonzero_diff_means_out_high: assert property (
        @($global_clock) (diff != 8'h00) |-> (out == 1'b1)
    );

    // A low output can only occur when the inputs are identical.
    check_out_low_only_on_equal_inputs: assert property (
        @($global_clock) (out == 1'b0) |-> (in1 == in2)
    );

    // A high output can only occur when the inputs are different.
    check_out_high_only_on_unequal_inputs: assert property (
        @($global_clock) (out == 1'b1) |-> (in1 != in2)
    );

endmodule

rtl:
module clk_div(
    input CLKIN,
    input RST,
    input [3:0] BAUD,
    output CLKOUT
    );

    parameter B300    = 19'b1010001011000010100;
    parameter B600    = 19'b0101000101100001010;
    parameter B1200   = 19'b0010100010110000100;
    parameter B2400   = 19'b0001010001011000010;
    parameter B4800   = 19'b0000101000101100000;
    parameter B9600   = 19'b0000010100010110000;
    parameter B19200  = 19'b0000001010001010111;
    parameter B38400  = 19'b0000000101000101011;
    parameter B57600  = 19'b0000000011011000111;
    parameter B115200 = 19'b0000000001101100011; 


    reg [19:0] clk_cntr;

    reg [19:0] baud_rate;


    reg out_clk;


    always @ (BAUD, RST) begin
      if(RST == 1'b1) begin
        baud_rate <= B9600;
      end
      else begin
        case(BAUD)
          4'h0    : baud_rate <= B300;
          4'h1    : baud_rate <= B600;
          4'h2    : baud_rate <= B1200;
          4'h3    : baud_rate <= B2400;
          4'h4    : baud_rate <= B4800;
          4'h5    : baud_rate <= B9600;
          4'h6    : baud_rate <= B19200;
          4'h7    : baud_rate <= B38400;
          4'h8    : baud_rate <= B57600;
          4'h9    : baud_rate <= B115200;
          default : baud_rate <= B9600;
        endcase   
      end
    end


    always @ (posedge CLKIN) begin
      if(RST == 1'b1) begin
        clk_cntr <= 0;
        out_clk <= 0;
      end
      else if(clk_cntr == baud_rate) begin
        clk_cntr <= 0;
        out_clk <= ~out_clk;
      end
      else begin
        clk_cntr <= clk_cntr + 1'b1;
      end
    end

   assign CLKOUT = out_clk; 



endmodule

sva:
module clk_div_sva (
    input logic        CLKIN,
    input logic        RST,
    input logic [3:0]  BAUD,
    input logic        CLKOUT,
    input logic [19:0] clk_cntr,
    input logic [19:0] baud_rate
);

    localparam logic [19:0] B300    = {1'b0, 19'b1010001011000010100};
    localparam logic [19:0] B600    = {1'b0, 19'b0101000101100001010};
    localparam logic [19:0] B1200   = {1'b0, 19'b0010100010110000100};
    localparam logic [19:0] B2400   = {1'b0, 19'b0001010001011000010};
    localparam logic [19:0] B4800   = {1'b0, 19'b0000101000101100000};
    localparam logic [19:0] B9600   = {1'b0, 19'b0000010100010110000};
    localparam logic [19:0] B19200  = {1'b0, 19'b0000001010001010111};
    localparam logic [19:0] B38400  = {1'b0, 19'b0000000101000101011};
    localparam logic [19:0] B57600  = {1'b0, 19'b0000000011011000111};
    localparam logic [19:0] B115200 = {1'b0, 19'b0000000001101100011};

    // Reset forces the default baud divisor.
    check_reset_forces_default_baud: assert property (
        @(posedge CLKIN) RST |-> (baud_rate == B9600)
    );

    // BAUD 0 selects the 300 divisor.
    check_baud_0_maps_to_b300: assert property (
        @(posedge CLKIN) disable iff (RST) (BAUD == 4'h0) |-> (baud_rate == B300)
    );

    // BAUD 1 selects the 600 divisor.
    check_baud_1_maps_to_b600: assert property (
        @(posedge CLKIN) disable iff (RST) (BAUD == 4'h1) |-> (baud_rate == B600)
    );

    // BAUD 2 selects the 1200 divisor.
    check_baud_2_maps_to_b1200: assert property (
        @(posedge CLKIN) disable iff (RST) (BAUD == 4'h2) |-> (baud_rate == B1200)
    );

    // BAUD 3 selects the 2400 divisor.
    check_baud_3_maps_to_b2400: assert property (
        @(posedge CLKIN) disable iff (RST) (BAUD == 4'h3) |-> (baud_rate == B2400)
    );

    // BAUD 4 selects the 4800 divisor.
    check_baud_4_maps_to_b4800: assert property (
        @(posedge CLKIN) disable iff (RST) (BAUD == 4'h4) |-> (baud_rate == B4800)
    );

    // BAUD 5 selects the 9600 divisor.
    check_baud_5_maps_to_b9600: assert property (
        @(posedge CLKIN) disable iff (RST) (BAUD == 4'h5) |-> (baud_rate == B9600)
    );

    // BAUD 6 selects the 19200 divisor.
    check_baud_6_maps_to_b19200: assert property (
        @(posedge CLKIN) disable iff (RST) (BAUD == 4'h6) |-> (baud_rate == B19200)
    );

    // BAUD 7 selects the 38400 divisor.
    check_baud_7_maps_to_b38400: assert property (
        @(posedge CLKIN) disable iff (RST) (BAUD == 4'h7) |-> (baud_rate == B38400)
    );

    // BAUD 8 selects the 57600 divisor.
    check_baud_8_maps_to_b57600: assert property (
        @(posedge CLKIN) disable iff (RST) (BAUD == 4'h8) |-> (baud_rate == B57600)
    );

    // BAUD 9 selects the 115200 divisor.
    check_baud_9_maps_to_b115200: assert property (
        @(posedge CLKIN) disable iff (RST) (BAUD == 4'h9) |-> (baud_rate == B115200)
    );

    // Unsupported BAUD values fall back to the 9600 divisor.
    check_baud_default_maps_to_b9600: assert property (
        @(posedge CLKIN) disable iff (RST) (BAUD > 4'h9) |-> (baud_rate == B9600)
    );

    // A reset cycle clears the counter and output by the next clock.
    check_reset_clears_counter_and_output: assert property (
        @(posedge CLKIN) RST |=> ((clk_cntr == 20'd0) && (CLKOUT == 1'b0))
    );

    // When not at the divisor, the counter increments and output holds.
    check_counter_advances_and_output_holds: assert property (
        @(posedge CLKIN) disable iff (RST)
        (clk_cntr != baud_rate) |=> ((clk_cntr == ($past(clk_cntr) + 20'd1)) && (CLKOUT == $past(CLKOUT)))
    );

    // When the divisor is reached, the counter clears and output toggles.
    check_terminal_count_resets_and_toggles: assert property (
        @(posedge CLKIN) disable iff (RST)
        (clk_cntr == baud_rate) |=> ((clk_cntr == 20'd0) && (CLKOUT != $past(CLKOUT)))
    );

endmodule

module binary_counter_assertions (
    input logic clk,
    input logic rst,
    input logic up_down,
    input logic [3:0] count
);

    // A sampled reset cycle leaves the counter cleared.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'h0)
    );

    // In up mode below 15, the counter increments by one.
    check_up_mode_increments: assert property (
        @(posedge clk) disable iff (rst)
        (up_down && (count != 4'hf)) |=> (count == ($past(count) + 4'h1))
    );

    // In up mode at 15, the counter wraps to 0.
    check_up_mode_wraps_to_zero: assert property (
        @(posedge clk) disable iff (rst)
        (up_down && (count == 4'hf)) |=> (count == 4'h0)
    );

    // In down mode above 0, the counter decrements by one.
    check_down_mode_decrements: assert property (
        @(posedge clk) disable iff (rst)
        ((!up_down) && (count != 4'h0)) |=> (count == ($past(count) - 4'h1))
    );

    // In down mode at 0, the counter wraps to 15.
    check_down_mode_wraps_to_fifteen: assert property (
        @(posedge clk) disable iff (rst)
        ((!up_down) && (count == 4'h0)) |=> (count == 4'hf)
    );

endmodule

rtl:
module up_counter(
    input clk,
    input reset_n,
    output reg [2:0] count
);

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            count <= 3'b0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module up_counter_sva(
    input logic       clk,
    input logic       reset_n,
    input logic [2:0] count
);

    // Reset forces the counter to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) !reset_n |-> (count == 3'b000)
    );

    // A non-maximum count increments by one on the next clock.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (!reset_n)
        (count != 3'b111) |=> (count == ($past(count) + 3'b001))
    );

    // The maximum count wraps back to zero on the next clock.
    check_wrap_after_max: assert property (
        @(posedge clk) disable iff (!reset_n)
        (count == 3'b111) |=> (count == 3'b000)
    );

endmodule

