module rectangle_area(
    input [7:0] length,
    input [7:0] width,
    output reg [15:0] area
);

    always @(*) begin
        area = length * width;
    end

endmodule

sva:
module rectangle_area_sva (
    input logic        clk,
    input logic [7:0]  length,
    input logic [7:0]  width,
    input logic [15:0] area
);

    // Area must always equal the product of length and width.
    check_area_matches_product: assert property (
        @(posedge clk) area == (length * width)
    );

    // Zero length must produce zero area.
    check_zero_length_gives_zero_area: assert property (
        @(posedge clk) (length == 8'h00) |-> (area == 16'h0000)
    );

    // Zero width must produce zero area.
    check_zero_width_gives_zero_area: assert property (
        @(posedge clk) (width == 8'h00) |-> (area == 16'h0000)
    );

    // Unit length must pass width through to area.
    check_unit_length_passthrough: assert property (
        @(posedge clk) (length == 8'h01) |-> (area == {8'h00, width})
    );

    // Unit width must pass length through to area.
    check_unit_width_passthrough: assert property (
        @(posedge clk) (width == 8'h01) |-> (area == {8'h00, length})
    );

    // Stable inputs must keep area stable across sampled cycles.
    check_stable_inputs_keep_area_stable: assert property (
        @(posedge clk) ($stable(length) && $stable(width)) |-> $stable(area)
    );

endmodule

rtl:
module and_module (
    input [3:0] a,
    input [3:0] b,
    output [3:0] out
);
    assign out = a & b;
endmodule

module decoder_module (
    input [1:0] sel,
    output [3:0] out
);
    assign out = (sel == 2'b00) ? 4'b1110 :
                  (sel == 2'b01) ? 4'b1101 :
                  (sel == 2'b10) ? 4'b1011 :
                  (sel == 2'b11) ? 4'b0111 : 4'b0000;
endmodule

module mux_module (
    input [3:0] a,
    input [3:0] b,
    input A,
    input B,
    output out
);
    wire [3:0] and_out;
    wire [3:0] decoder_out;

    and_module and_inst (
        .a(a),
        .b(b),
        .out(and_out)
    );

    decoder_module decoder_inst (
        .sel({A, B}),
        .out(decoder_out)
    );

    assign out = (decoder_out == 4'b1110) ? and_out[0] :
                  (decoder_out == 4'b1101) ? and_out[1] :
                  (decoder_out == 4'b1011) ? and_out[2] :
                  (decoder_out == 4'b0111) ? and_out[3] : 1'b0;
endmodule

module top_module (
    input [3:0] a,
    input [3:0] b,
    input A,
    input B,
    output out
);
    wire mux_out;
    mux_module mux_inst (
        .a(a),
        .b(b),
        .A(A),
        .B(B),
        .out(mux_out)
    );

    assign out = ~mux_out;
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic A,
    input logic B,
    input logic out
);

    // When select is 00, out is the inverse of a[0] & b[0].
    check_select_00_routes_bit0: assert property (
        @(posedge clk)
        ((A == 1'b0) && (B == 1'b0)) |-> (out === ~(a[0] & b[0]))
    );

    // When select is 01, out is the inverse of a[1] & b[1].
    check_select_01_routes_bit1: assert property (
        @(posedge clk)
        ((A == 1'b0) && (B == 1'b1)) |-> (out === ~(a[1] & b[1]))
    );

    // When select is 10, out is the inverse of a[2] & b[2].
    check_select_10_routes_bit2: assert property (
        @(posedge clk)
        ((A == 1'b1) && (B == 1'b0)) |-> (out === ~(a[2] & b[2]))
    );

    // When select is 11, out is the inverse of a[3] & b[3].
    check_select_11_routes_bit3: assert property (
        @(posedge clk)
        ((A == 1'b1) && (B == 1'b1)) |-> (out === ~(a[3] & b[3]))
    );

    // With select 00 and selected inputs stable, out stays stable.
    check_select_00_stability: assert property (
        @(posedge clk)
        ($stable(A) && $stable(B) && (A == 1'b0) && (B == 1'b0) &&
         $stable(a[0]) && $stable(b[0])) |-> $stable(out)
    );

    // With select 01 and selected inputs stable, out stays stable.
    check_select_01_stability: assert property (
        @(posedge clk)
        ($stable(A) && $stable(B) && (A == 1'b0) && (B == 1'b1) &&
         $stable(a[1]) && $stable(b[1])) |-> $stable(out)
    );

    // With select 10 and selected inputs stable, out stays stable.
    check_select_10_stability: assert property (
        @(posedge clk)
        ($stable(A) && $stable(B) && (A == 1'b1) && (B == 1'b0) &&
         $stable(a[2]) && $stable(b[2])) |-> $stable(out)
    );

    // With select 11 and selected inputs stable, out stays stable.
    check_select_11_stability: assert property (
        @(posedge clk)
        ($stable(A) && $stable(B) && (A == 1'b1) && (B == 1'b1) &&
         $stable(a[3]) && $stable(b[3])) |-> $stable(out)
    );

endmodule

rtl:
module and_gate (
    input A,
    input B,
    output Y
);

    wire not_A;
    wire not_B;
    wire or_out;
    wire nand_out;

    not not_A_inst (not_A, A);
    not not_B_inst (not_B, B);
    or or_inst (or_out, not_A, not_B);
    nand nand_inst (nand_out, or_out, or_out);
    buf buf_inst (Y, nand_out);

endmodule

sva:
module and_gate_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Y
);

    // Y must always equal A AND B.
    check_output_matches_and: assert property (
        @(posedge clk) Y == (A & B)
    );

    // A LOW must force Y LOW.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) (A == 1'b0) |-> (Y == 1'b0)
    );

    // B LOW must force Y LOW.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b0)
    );

    // Both inputs HIGH must drive Y HIGH.
    check_both_high_drive_y_high: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1) |-> (Y == 1'b1)
    );

    // Y HIGH requires both inputs HIGH.
    check_y_high_requires_both_high: assert property (
        @(posedge clk) (Y == 1'b1) |-> (A == 1'b1 && B == 1'b1)
    );

endmodule

rtl:
module sky130_fd_sc_hdll__a211oi (
    Y ,
    A1,
    A2,
    B1,
    C1
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;
    input  C1;

    wire and0_out  ;
    wire nor0_out_Y;

    and and0 (and0_out  , A1, A2          );
    nor nor0 (nor0_out_Y, and0_out, B1, C1);
    buf buf0 (Y         , nor0_out_Y      );

endmodule

sva:
module sky130_fd_sc_hdll__a211oi_sva (
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1
);

    // Full combinational AOI211 function sampled on $global_clock.
    check_functional_equivalence: assert property (
        @($global_clock) Y === ~((A1 & A2) | B1 | C1)
    );

    // B1 high forces the output low.
    check_b1_forces_low: assert property (
        @($global_clock) B1 |-> !Y
    );

    // C1 high forces the output low.
    check_c1_forces_low: assert property (
        @($global_clock) C1 |-> !Y
    );

    // A1 and A2 high together force the output low.
    check_a1_a2_forces_low: assert property (
        @($global_clock) (A1 && A2) |-> !Y
    );

    // If no NOR input term is active, the output is high.
    check_no_active_term_gives_high: assert property (
        @($global_clock) (!B1 && !C1 && !(A1 && A2)) |-> Y
    );

    // With B1 and C1 low, Y reduces to the inversion of A1&A2.
    check_reduced_a_term_when_b1_c1_low: assert property (
        @($global_clock) (!B1 && !C1) |-> (Y === ~(A1 & A2))
    );

endmodule

rtl:
module up_counter(
    input clk,
    input reset,
    output reg [3:0] count
);

    always @(posedge clk or negedge reset) begin
        if (reset == 0) begin
            count <= 4'b0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module up_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

    // A sampled low reset clears count by the next clock sample.
    check_reset_clears_count: assert property (
        @(posedge clk) disable iff ($initstate)
        !reset |=> (count == 4'h0)
    );

    // On the sampled cycle reset is released, count is still zero.
    check_count_zero_on_reset_release: assert property (
        @(posedge clk) disable iff ($initstate)
        $rose(reset) |-> (count == 4'h0)
    );

    // An active clock leads to either an incremented count or a zero if async reset intervenes.
    check_active_cycle_transition: assert property (
        @(posedge clk) disable iff ($initstate)
        reset |=> ((count == 4'h0) || (count == ($past(count) + 4'd1)))
    );

    // From zero, the next sampled value is either one or zero if reset intervenes.
    check_zero_state_transition: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        (count == 4'h0) |=> ((count == 4'h0) || (count == 4'h1))
    );

    // From 4'hF, the next sampled value wraps to zero.
    check_max_state_wrap: assert property (
        @(posedge clk) disable iff (!reset || $initstate)
        (count == 4'hF) |=> (count == 4'h0)
    );

endmodule

rtl:
module sync2r_1 ( clk, preset, d, q );
    input clk;
    input preset;
    input d;
    output q;

    reg q1, q2; // two registers

    always @(posedge clk or posedge preset) begin
        if (preset) begin
            q1 <= 1'b0; // reset to known state
            q2 <= 1'b0;
        end else begin
            q1 <= d; // first register triggered by rising edge
            q2 <= q1; // second register triggered by falling edge
        end
    end

    assign q = q2; // output synchronized data signal
endmodule

sva:
module sync2r_1_sva (
    input logic clk,
    input logic preset,
    input logic d,
    input logic q,
    input logic q1,
    input logic q2
);

    // Output mirrors the second register.
    check_output_matches_q2: assert property (
        @(posedge clk) disable iff (preset) q == q2
    );

    // Sampled preset clears both registers and the output.
    check_preset_clears_state: assert property (
        @(posedge clk) preset |-> (!q1 && !q2 && !q)
    );

    // One clock after sampled preset, both stages and output are still low.
    check_post_preset_state_clear: assert property (
        @(posedge clk) preset |=> (!q1 && !q2 && !q)
    );

    // Sampled preset keeps the output low for the next two clocks.
    check_preset_blocks_output_two_clocks: assert property (
        @(posedge clk) preset |=> (!q ##1 !q)
    );

    // The first stage can only be high if d was high on the previous clock.
    check_q1_high_requires_prev_d_high: assert property (
        @(posedge clk) disable iff (preset)
        (!$initstate && !$past($initstate) && q1) |-> $past(d)
    );

    // The second stage can only be high if q1 was high on the previous clock.
    check_q2_high_requires_prev_q1_high: assert property (
        @(posedge clk) disable iff (preset)
        (!$initstate && !$past($initstate) && q2) |-> $past(q1)
    );

    // The output can only be high if d was high two clocks earlier.
    check_q_high_requires_d_high_two_clocks_earlier: assert property (
        @(posedge clk) disable iff (preset)
        (!$initstate && !$past($initstate) && q) |-> $past(d, 2)
    );

    // A low d drives the first stage low on the next clock.
    check_d_low_forces_q1_low_next_clock: assert property (
        @(posedge clk) disable iff (preset) !d |=> !q1
    );

    // A low q1 drives the second stage low on the next clock.
    check_q1_low_forces_q2_low_next_clock: assert property (
        @(posedge clk) disable iff (preset) !q1 |=> !q2
    );

    // A low d drives the output low two clocks later.
    check_d_low_forces_q_low_two_clcks_later: assert property (
        @(posedge clk) disable iff (preset) !d |=> ##1 !q
    );

endmodule

rtl:
module binary_counter (
    input clk,
    input reset,
    output reg [3:0] count
);

always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 4'b0;
    end else if (count == 4'b1001) begin
        count <= 4'b0;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] count
);

    // A sampled reset drives the counter to zero by the next clock.
    reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'd0)
    );

    // A count of 9 rolls over to 0 on the next clock.
    count_rolls_over_at_nine: assert property (
        @(posedge clk) disable iff (reset)
            (count == 4'd9) |=> (count == 4'd0)
    );

    // Any non-9 count advances by one, or is forced to 0 by async reset.
    count_advances_or_resets_otherwise: assert property (
        @(posedge clk) disable iff (reset)
            (count != 4'd9) |=> ((count == ($past(count) + 4'd1)) || (count == 4'd0))
    );

endmodule

rtl:
module gray_to_binary_decoder #(
  parameter width=32
)(
  input [width-1:0] gin,
  output [width-1:0] bout
);
  reg [width-1:0] breg;
  integer i;

  assign bout = breg;

  always @ (gin) begin
    breg[width-1] = gin[width-1];
    for (i = width-2; i >= 0; i = i - 1)
      breg[i] = gin[i] ^ breg[i+1];
  end
endmodule

sva:
module gray_to_binary_decoder_sva #(
    parameter integer width = 32
)(
    input logic [width-1:0] gin,
    input logic [width-1:0] bout
);

    // No RTL clock or reset; sample the combinational decoder on the formal global clock.
    // The DUT converts Gray-coded input gin into binary output bout.

    function automatic logic [width-1:0] gray_to_binary(input logic [width-1:0] g);
        integer j;
        begin
            gray_to_binary = '0;
            gray_to_binary[width-1] = g[width-1];
            for (j = width-2; j >= 0; j = j - 1)
                gray_to_binary[j] = g[j] ^ gray_to_binary[j+1];
        end
    endfunction

    // The MSB of the binary output matches the MSB of the Gray input.
    check_msb_passthrough: assert property (
        @($global_clock) bout[width-1] == gin[width-1]
    );

    genvar i;
    generate
        for (i = 0; i < width-1; i = i + 1) begin : gen_recursive_checks
            // Each lower binary bit is the Gray bit XOR the next higher binary bit.
            check_recursive_decode: assert property (
                @($global_clock) bout[i] == (gin[i] ^ bout[i+1])
            );
        end
    endgenerate

    // The full output vector matches the Gray-to-binary decode of the input.
    check_full_decode: assert property (
        @($global_clock) bout == gray_to_binary(gin)
    );

endmodule

rtl:
module top_module (
    input clk,
    input reset,
    input [7:0] in_1,
    input [7:0] in_2,
    input select,
    output [7:0] sum_output,
    output [7:0] or_output
);

    // 2-to-1 MUX
    wire [7:0] selected_input;
    mux_2to1 mux_inst (
        .in_0(in_1),
        .in_1(in_2),
        .select(select),
        .out(selected_input)
    );

    // 8-bit adder
    wire [8:0] sum;
    adder_8bit adder_inst (
        .a(selected_input),
        .b(in_2),
        .sum(sum)
    );

    // Bitwise OR
    assign or_output = selected_input | in_2;

    // Output assignments
    assign sum_output = sum[7:0];

endmodule

// 2-to-1 MUX module
module mux_2to1 (
    input [7:0] in_0,
    input [7:0] in_1,
    input select,
    output reg [7:0] out
);

    always @(*) begin
        if (select == 1'b0) begin
            out = in_0;
        end else begin
            out = in_1;
        end
    end

endmodule

// 8-bit adder module
module adder_8bit (
    input [7:0] a,
    input [7:0] b,
    output reg [8:0] sum
);

    always @(*) begin
        sum = {1'b0, a} + {1'b0, b};
    end

endmodule

sva:
module top_module_sva (
    input logic       clk,
    input logic       reset,
    input logic [7:0] in_1,
    input logic [7:0] in_2,
    input logic       select,
    input logic [7:0] sum_output,
    input logic [7:0] or_output
);

    // When select is low, sum_output is the truncated sum of in_1 and in_2.
    check_sum_select_low: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b0) |-> (sum_output == (in_1 + in_2))
    );

    // When select is high, sum_output is the truncated sum of in_2 and in_2.
    check_sum_select_high: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b1) |-> (sum_output == (in_2 + in_2))
    );

    // When select is low, or_output is the bitwise OR of in_1 and in_2.
    check_or_select_low: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b0) |-> (or_output == (in_1 | in_2))
    );

    // When select is high, or_output matches in_2 because in_2 is ORed with itself.
    check_or_select_high: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b1) |-> (or_output == in_2)
    );

    // With in_2 equal to zero, sum_output passes the selected input through.
    check_sum_zero_in2_identity: assert property (
        @(posedge clk) disable iff (reset)
        (in_2 == 8'h00) |-> (sum_output == (select ? 8'h00 : in_1))
    );

    // With in_2 equal to zero, or_output passes the selected input through.
    check_or_zero_in2_identity: assert property (
        @(posedge clk) disable iff (reset)
        (in_2 == 8'h00) |-> (or_output == (select ? 8'h00 : in_1))
    );

    // Doubling in_2 produces an even result, so the LSB of sum_output is zero.
    check_double_sum_lsb_zero: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b1) |-> (sum_output[0] == 1'b0)
    );

endmodule

