module  ogfx_sync_cell (

data_out,                      clk,                           data_in,                       rst                            );

output              data_out;      input               clk;          input               data_in;      input               rst;          reg  [1:0] data_sync;

always @(posedge clk or posedge rst)
  if (rst) data_sync <=  2'b00;
  else     data_sync <=  {data_sync[0], data_in};

assign     data_out   =   data_sync[1];


endmodule

sva:
module ogfx_sync_cell_sva (
    input logic clk,
    input logic rst,
    input logic data_in,
    input logic data_out
);

    // A sampled reset forces the output low by the next clock.
    check_reset_clears_output_by_next_clock: assert property (
        @(posedge clk) rst |=> (data_out == 1'b0)
    );

    // The first clock after reset release still has a low output.
    check_first_clock_after_reset_release_is_low: assert property (
        @(posedge clk) (rst ##1 !rst) |-> (data_out == 1'b0)
    );

    // The second clock after reset release still has a low output.
    check_second_clock_after_reset_release_is_low: assert property (
        @(posedge clk) (rst ##1 !rst ##1 !rst) |-> (data_out == 1'b0)
    );

    property p_two_cycle_input_to_output_delay;
        bit sampled_in;
        @(posedge clk) disable iff (rst)
            (1'b1, sampled_in = data_in) |=> ##1 (data_out == sampled_in);
    endproperty

    // Without reset interruption, data_out is data_in delayed by two clocks.
    check_two_cycle_input_to_output_delay: assert property (
        p_two_cycle_input_to_output_delay
    );

endmodule

rtl:
module ripple_carry_adder (
    COUT,
    SUM ,
    A   ,
    B   ,
    CIN 
);

    output COUT;
    output [3:0] SUM ;
    input  [3:0] A   ;
    input  [3:0] B   ;
    input  CIN ;

    wire [3:0] carry;

    full_adder fa0 (
        .COUT(carry[0]),
        .SUM(SUM[0]),
        .A(A[0]),
        .B(B[0]),
        .CIN(CIN)
    );

    full_adder fa1 (
        .COUT(carry[1]),
        .SUM(SUM[1]),
        .A(A[1]),
        .B(B[1]),
        .CIN(carry[0])
    );

    full_adder fa2 (
        .COUT(carry[2]),
        .SUM(SUM[2]),
        .A(A[2]),
        .B(B[2]),
        .CIN(carry[1])
    );

    full_adder fa3 (
        .COUT(COUT),
        .SUM(SUM[3]),
        .A(A[3]),
        .B(B[3]),
        .CIN(carry[2])
    );

endmodule

module full_adder (
    COUT,
    SUM ,
    A   ,
    B   ,
    CIN 
);

    output COUT;
    output SUM ;
    input  A   ;
    input  B   ;
    input  CIN ;

    assign SUM = A ^ B ^ CIN;
    assign COUT = (A & B) | (A & CIN) | (B & CIN);

endmodule

sva:
module ripple_carry_adder_sva (
    input logic clk,
    input logic COUT,
    input logic [3:0] SUM,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN
);

    // RTL is combinational with no reset; clk is a sampling clock for SVA.
    function automatic logic carry_maj (
        input logic a,
        input logic b,
        input logic cin
    );
        carry_maj = (a & b) | (a & cin) | (b & cin);
    endfunction

    // The 5-bit result must equal A + B + CIN.
    check_total_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        ({COUT, SUM} == ({1'b0, A} + {1'b0, B} + {4'b0000, CIN}))
    );

    // Bit 0 sum matches the first full adder.
    check_sum_bit0_function: assert property (
        @(posedge clk) disable iff (1'b0)
        (SUM[0] == (A[0] ^ B[0] ^ CIN))
    );

    // Bit 1 sum uses the carry from bit 0.
    check_sum_bit1_ripple: assert property (
        @(posedge clk) disable iff (1'b0)
        (SUM[1] == (A[1] ^ B[1] ^ carry_maj(A[0], B[0], CIN)))
    );

    // Bit 2 sum uses the carry from bit 1.
    check_sum_bit2_ripple: assert property (
        @(posedge clk) disable iff (1'b0)
        (SUM[2] == (A[2] ^ B[2] ^ carry_maj(A[1], B[1], carry_maj(A[0], B[0], CIN))))
    );

    // Bit 3 sum uses the carry from bit 2.
    check_sum_bit3_ripple: assert property (
        @(posedge clk) disable iff (1'b0)
        (SUM[3] == (A[3] ^ B[3] ^ carry_maj(A[2], B[2], carry_maj(A[1], B[1], carry_maj(A[0], B[0], CIN)))))
    );

    // Final carry-out matches the last full adder carry.
    check_cout_ripple: assert property (
        @(posedge clk) disable iff (1'b0)
        (COUT == carry_maj(A[3], B[3], carry_maj(A[2], B[2], carry_maj(A[1], B[1], carry_maj(A[0], B[0], CIN)))))
    );

    // Stable inputs must produce stable outputs.
    check_combinational_stability: assert property (
        @(posedge clk) disable iff (1'b0)
        $stable({A, B, CIN}) |-> $stable({COUT, SUM})
    );

    // Adding zero on B with no carry-in must pass A through.
    check_add_zero_right: assert property (
        @(posedge clk) disable iff (1'b0)
        ((B == 4'b0000) && (CIN == 1'b0)) |-> ({COUT, SUM} == {1'b0, A})
    );

    // Adding zero on A with no carry-in must pass B through.
    check_add_zero_left: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 4'b0000) && (CIN == 1'b0)) |-> ({COUT, SUM} == {1'b0, B})
    );

    // Zero operands must propagate CIN into the result.
    check_cin_only_case: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 4'b0000) && (B == 4'b0000)) |-> ({COUT, SUM} == {4'b0000, CIN})
    );

endmodule

rtl:
module my_and_gate (
    input A,
    input B,
    output Y
);

    wire not_A, not_B, or_AB;

    // Invert A and B
    not #(1) not_A_inst (not_A, A);
    not #(1) not_B_inst (not_B, B);

    // OR the inverted A and B
    or #(1) or_AB_inst (or_AB, not_A, not_B);

    // Invert the output of the OR gate to get the AND output
    not #(1) not_Y_inst (Y, or_AB);

endmodule

sva:
module my_and_gate_sva (
    input logic A,
    input logic B,
    input logic Y
);

    // Y must equal the AND of A and B.
    check_and_function: assert property (
        @($global_clock) Y === (A & B)
    );

    // Both inputs high must drive Y high.
    check_both_high_drive_y_high: assert property (
        @($global_clock) ((A === 1'b1) && (B === 1'b1)) |-> (Y === 1'b1)
    );

    // A low must force Y low.
    check_a_low_forces_y_low: assert property (
        @($global_clock) (A === 1'b0) |-> (Y === 1'b0)
    );

    // B low must force Y low.
    check_b_low_forces_y_low: assert property (
        @($global_clock) (B === 1'b0) |-> (Y === 1'b0)
    );

    // Y high implies both inputs are high.
    check_y_high_implies_both_high: assert property (
        @($global_clock) (Y === 1'b1) |-> ((A === 1'b1) && (B === 1'b1))
    );

endmodule

rtl:
module binary_counter(
    input clk,
    input rst,
    output reg [3:0] count
);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module binary_counter_assertions (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count
);

    // Reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) disable iff ($initstate) rst |-> (count == 4'b0000)
    );

    // The first clock after reset release still observes zero before incrementing.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk) disable iff (rst || $initstate) $past(rst) |-> (count == 4'b0000)
    );

    // In normal operation, the counter increments by one every clock.
    check_count_increments_each_cycle: assert property (
        @(posedge clk) disable iff (rst || $initstate) !$past(rst) |-> (count == ($past(count) + 4'd1))
    );

    // A count of 15 wraps back to 0 on the next active clock.
    check_count_wraps_from_f_to_zero: assert property (
        @(posedge clk) disable iff (rst || $initstate) (!$past(rst) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

endmodule

