module sky130_fd_sc_hdll__o22ai (
    Y ,
    A1,
    A2,
    B1,
    B2
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;
    input  B2;

    wire nor0_out ;
    wire nor1_out ;
    wire or0_out_Y;

    nor nor0 (nor0_out , B1, B2            );
    nor nor1 (nor1_out , A1, A2            );
    or  or0  (or0_out_Y, nor1_out, nor0_out);
    buf buf0 (Y        , or0_out_Y         );

endmodule

sva:
module sky130_fd_sc_hdll__o22ai_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2
);

    // Exact combinational function of the cell.
    check_output_equation: assert property (
        @(posedge clk) (Y == ((~(A1 | A2)) | (~(B1 | B2))))
    );

    // If both A inputs are low, Y must be high.
    check_output_high_when_a_pair_low: assert property (
        @(posedge clk) ((!A1 && !A2) |-> (Y == 1'b1))
    );

    // If both B inputs are low, Y must be high.
    check_output_high_when_b_pair_low: assert property (
        @(posedge clk) ((!B1 && !B2) |-> (Y == 1'b1))
    );

    // If both input groups have at least one high, Y must be low.
    check_output_low_when_both_groups_active: assert property (
        @(posedge clk) (((A1 || A2) && (B1 || B2)) |-> (Y == 1'b0))
    );

    // A high Y means at least one input pair is all low.
    check_high_output_implies_zero_pair: assert property (
        @(posedge clk) ((Y == 1'b1) |-> ((!A1 && !A2) || (!B1 && !B2)))
    );

    // A low Y means both input groups are active.
    check_low_output_implies_both_groups_active: assert property (
        @(posedge clk) ((Y == 1'b0) |-> ((A1 || A2) && (B1 || B2)))
    );

    // All-zero inputs drive Y high.
    check_all_inputs_low_drive_high: assert property (
        @(posedge clk) ((!A1 && !A2 && !B1 && !B2) |-> (Y == 1'b1))
    );

    // All-one inputs drive Y low.
    check_all_inputs_high_drive_low: assert property (
        @(posedge clk) ((A1 && A2 && B1 && B2) |-> (Y == 1'b0))
    );

endmodule

rtl:
module ripple_carry_adder (
    a,
    b,
    en,
    sum,
    carry
);

    input [3:0] a;
    input [3:0] b;
    input en;
    output [3:0] sum;
    output carry;

    wire [3:0] temp_sum;
    wire [3:0] temp_carry;

    assign temp_sum = a + b;
    assign temp_carry = {a[3], b[3], temp_sum[3]} & 3'b100;

    assign sum = en ? temp_sum : 4'b0000;
    assign carry = en ? temp_carry[2] : 1'b0;

endmodule

sva:
module ripple_carry_adder_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic en,
    input logic [3:0] sum,
    input logic carry
);

    // Outputs are forced low when enable is deasserted.
    check_outputs_zero_when_disabled: assert property (
        @(posedge clk) !en |-> (sum == 4'b0000 && carry == 1'b0)
    );

    // Sum matches the 4-bit addition when enable is asserted.
    check_sum_matches_addition_when_enabled: assert property (
        @(posedge clk) en |-> (sum == (a + b))
    );

    // Carry matches the implemented masked MSB behavior when enabled.
    check_carry_matches_a_msb_when_enabled: assert property (
        @(posedge clk) en |-> (carry == a[3])
    );

    // Sum always follows the enable-gated combinational equation.
    check_sum_function: assert property (
        @(posedge clk) sum == (en ? (a + b) : 4'b0000)
    );

    // Carry always follows the enable-gated combinational equation.
    check_carry_function: assert property (
        @(posedge clk) carry == (en ? a[3] : 1'b0)
    );

endmodule

