sva:
module sky130_fd_sc_ms__o21ai_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1
);

    // Y implements the inverted AND of B1 with (A1 OR A2).
    check_y_function: assert property (
        @(posedge clk) Y == ~((A1 | A2) & B1)
    );

    // A low B1 forces the NAND output high.
    check_b1_low_forces_y_high: assert property (
        @(posedge clk) (B1 == 1'b0) |-> (Y == 1'b1)
    );

    // When both OR inputs are low, Y must be high.
    check_a_inputs_low_force_y_high: assert property (
        @(posedge clk) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (Y == 1'b1)
    );

    // A1 high with B1 high drives Y low.
    check_a1_and_b1_drive_y_low: assert property (
        @(posedge clk) ((A1 == 1'b1) && (B1 == 1'b1)) |-> (Y == 1'b0)
    );

    // A2 high with B1 high drives Y low.
    check_a2_and_b1_drive_y_low: assert property (
        @(posedge clk) ((A2 == 1'b1) && (B1 == 1'b1)) |-> (Y == 1'b0)
    );

    // A low Y can only occur when B1 is high and at least one A input is high.
    check_y_low_has_valid_cause: assert property (
        @(posedge clk) (Y == 1'b0) |-> ((B1 == 1'b1) && ((A1 == 1'b1) || (A2 == 1'b1)))
    );

endmodule

rtl:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;
    wire carry0, carry1, carry2;

    // Full adder for the least significant bit
    full_adder FA0(
        .a(A[0]),
        .b(B[0]),
        .c(Cin),
        .sum(sum[0]),
        .carry(carry0)
    );

    // Full adder for bits 1-3
    full_adder FA1(
        .a(A[1]),
        .b(B[1]),
        .c(carry0),
        .sum(sum[1]),
        .carry(carry1)
    );

    full_adder FA2(
        .a(A[2]),
        .b(B[2]),
        .c(carry1),
        .sum(sum[2]),
        .carry(carry2)
    );

    full_adder FA3(
        .a(A[3]),
        .b(B[3]),
        .c(carry2),
        .sum(sum[3]),
        .carry(Cout)
    );

    assign S = sum;

endmodule
module full_adder(
    input a,
    input b,
    input c,
    output sum,
    output carry
);

    assign sum = a ^ b ^ c;
    assign carry = (a & b) | (a & c) | (b & c);

endmodule

sva:
module four_bit_adder_sva(
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] S,
    input logic       Cout
);

    // Full 5-bit result must match A + B + Cin.
    check_total_sum: assert property (
        @(posedge clk)
        {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Bit 0 sum must match the first full-adder XOR equation.
    check_sum_bit0: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum must use the ripple carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk)
        S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
    );

    // Bit 2 sum must use the ripple carry from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        S[2] == (
            A[2] ^ B[2] ^ (
                (A[1] & B[1]) |
                (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
            )
        )
    );

    // Bit 3 sum must use the ripple carry from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk)
        S[3] == (
            A[3] ^ B[3] ^ (
                (A[2] & B[2]) |
                (A[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                )) |
                (B[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                ))
            )
        )
    );

    // Carry out must match the final full-adder carry equation.
    check_cout_equation: assert property (
        @(posedge clk)
        Cout == (
            (A[3] & B[3]) |
            (A[3] & (
                (A[2] & B[2]) |
                (A[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                )) |
                (B[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                ))
            )) |
            (B[3] & (
                (A[2] & B[2]) |
                (A[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                )) |
                (B[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                ))
            ))
        )
    );

    // Zero inputs with zero carry-in must produce zero outputs.
    check_zero_addition: assert property (
        @(posedge clk)
        ((A == 4'b0000) && (B == 4'b0000) && (Cin == 1'b0)) |-> ((S == 4'b0000) && (Cout == 1'b0))
    );

    // With B and Cin at zero, the sum must pass A through.
    check_pass_a_when_b_zero: assert property (
        @(posedge clk)
        ((B == 4'b0000) && (Cin == 1'b0)) |-> ((S == A) && (Cout == 1'b0))
    );

    // With A and Cin at zero, the sum must pass B through.
    check_pass_b_when_a_zero: assert property (
        @(posedge clk)
        ((A == 4'b0000) && (Cin == 1'b0)) |-> ((S == B) && (Cout == 1'b0))
    );

    // Arithmetic overflow must set Cout.
    check_overflow_sets_cout: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B} + Cin) > 5'd15) |-> (Cout == 1'b1)
    );

    // No arithmetic overflow must clear Cout.
    check_no_overflow_clears_cout: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B} + Cin) <= 5'd15) |-> (Cout == 1'b0)
    );

endmodule

module calculator_sva(
    input logic signed [15:0] A,
    input logic signed [15:0] B,
    input logic [1:0] op,
    input logic signed [15:0] result
);

    // No RTL clock or reset; sample on the formal global clock.

    // Addition returns A plus B.
    check_addition_result: assert property (
        @($global_clock) (op == 2'b00) |-> (result == (A + B))
    );

    // Subtraction returns A minus B.
    check_subtraction_result: assert property (
        @($global_clock) (op == 2'b01) |-> (result == (A - B))
    );

    // Multiplication returns A times B.
    check_multiplication_result: assert property (
        @($global_clock) (op == 2'b10) |-> (result == (A * B))
    );

    // Division by zero returns 16'hFFFF.
    check_divide_by_zero_result: assert property (
        @($global_clock) ((op == 2'b11) && (B == 16'sd0)) |-> (result == 16'hFFFF)
    );

    // Division returns A divided by B when B is nonzero.
    check_division_result: assert property (
        @($global_clock) ((op == 2'b11) && (B != 16'sd0)) |-> (result == (A / B))
    );

endmodule

