module memory_interface (
                          // inputs:
                           address,
                           clk,
                           in_port,
                           reset_n,

                          // outputs:
                           readdata
                        )
;

  output  [ 31: 0] readdata;
  input   [  1: 0] address;
  input            clk;
  input   [ 10: 0] in_port;
  input            reset_n;


wire             clk_en;
wire    [ 10: 0] data_in;
wire    [ 10: 0] read_mux_out;
reg     [ 31: 0] readdata;
  assign clk_en = 1;
  //s1, which is an e_avalon_slave
  assign read_mux_out = {11 {(address == 0)}} & data_in;
  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          readdata <= 0;
      else if (clk_en)
          readdata <= {32'b0 | read_mux_out};
    end


  assign data_in = in_port;

endmodule

sva:
module memory_interface_sva (
    input logic [1:0]  address,
    input logic        clk,
    input logic [10:0] in_port,
    input logic        reset_n,
    input logic [31:0] readdata
);

    // A clock edge with reset asserted clears readdata by the next sampled cycle.
    check_reset_clears_readdata: assert property (
        @(posedge clk)
        (!reset_n) |=> (readdata == 32'b0)
    );

    // Address 0 captures in_port into readdata on the following cycle.
    check_address_zero_captures_input: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |=> (readdata == {21'b0, $past(in_port)})
    );

    // Any nonzero address produces zero readdata on the following cycle.
    check_nonzero_address_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |=> (readdata == 32'b0)
    );

    // Every non-reset update keeps the upper bits of readdata at zero.
    check_readdata_zero_extended: assert property (
        @(posedge clk) disable iff (!reset_n)
        1'b1 |=> (readdata[31:11] == 21'b0)
    );

endmodule

rtl:
module shift_register ( input clk, input d, input shift, output q );

  reg [2:0] register;

  always @(posedge clk) begin
    if (shift) begin
      register <= {register[1:0], d};
    end else begin
      register <= {register[2], d, register[1]};
    end
  end

  assign q = register[2];

endmodule

sva:
module shift_register_sva (
    input logic clk,
    input logic d,
    input logic shift,
    input logic q
);

    // q holds its value when shift is low.
    check_hold_when_shift_low: assert property (
        @(posedge clk) !shift |=> (q == $past(q))
    );

    // q can only change after a cycle with shift high.
    check_q_change_requires_shift: assert property (
        @(posedge clk) ((!$initstate) && (q != $past(q))) |-> $past(shift)
    );

    // A no-shift cycle followed by a shift moves that earlier d value to q.
    check_no_shift_then_shift_moves_d_to_q: assert property (
        @(posedge clk) (!shift ##1 shift) |=> (q == $past(d,2))
    );

    // Three consecutive shifts move d to q after three clocks.
    check_three_shifts_move_d_to_q: assert property (
        @(posedge clk) (shift ##1 shift ##1 shift) |=> (q == $past(d,3))
    );

endmodule

rtl:
module ClkDiv_5Hz(
		CLK,
		RST,
		CLKOUT
);

input            CLK;		input            RST;		output           CLKOUT;	reg CLKOUT;

   reg [23:0]       clkCount = 24'h000000;
   parameter [23:0] cntEndVal = 24'h989680;

always @(posedge CLK or posedge RST)

			if (RST == 1'b1) begin
					CLKOUT <= 1'b0;
					clkCount <= 24'h000000;
			end
			else begin
					if (clkCount == cntEndVal) begin
						CLKOUT <= (~CLKOUT);
						clkCount <= 24'h000000;
					end
					else begin
						clkCount <= clkCount + 1'b1;
					end
			end

endmodule

sva:
module ClkDiv_5Hz_sva #(
    parameter [23:0] cntEndVal = 24'h989680
) (
    input logic        CLK,
    input logic        RST,
    input logic        CLKOUT,
    input logic [23:0] clkCount
);

    // Reset clears the divided clock and the counter.
    check_reset_clears_state: assert property (
        @(posedge CLK)
        RST |-> (CLKOUT == 1'b0) && (clkCount == 24'h000000)
    );

    // The counter never exceeds its terminal count.
    check_count_within_range: assert property (
        @(posedge CLK) disable iff (RST)
        clkCount <= cntEndVal
    );

    // Before terminal count, the counter advances by one or is asynchronously reset.
    check_nonterminal_count_advances_or_resets: assert property (
        @(posedge CLK) disable iff (RST)
        (clkCount < cntEndVal) |=> ((clkCount == ($past(clkCount) + 24'h000001)) || (clkCount == 24'h000000))
    );

    // Before terminal count, the output holds its value or is asynchronously reset low.
    check_nonterminal_output_holds_or_resets_low: assert property (
        @(posedge CLK) disable iff (RST)
        (clkCount < cntEndVal) |=> ((CLKOUT == $past(CLKOUT)) || (CLKOUT == 1'b0))
    );

    // At terminal count, the counter wraps back to zero.
    check_terminal_count_wraps_to_zero: assert property (
        @(posedge CLK) disable iff (RST)
        (clkCount == cntEndVal) |=> (clkCount == 24'h000000)
    );

    // At terminal count, the output toggles or is asynchronously reset low.
    check_terminal_output_toggles_or_resets_low: assert property (
        @(posedge CLK) disable iff (RST)
        (clkCount == cntEndVal) |=> ((CLKOUT == ~$past(CLKOUT)) || (CLKOUT == 1'b0))
    );

    // On sampled reset deassertion, state is still the cleared reset state.
    check_reset_release_state_cleared: assert property (
        @(posedge CLK) disable iff (RST)
        $fell(RST) |-> (CLKOUT == 1'b0) && (clkCount == 24'h000000)
    );

    // One cycle after reset release, counting starts or reset has re-cleared state.
    check_first_cycle_after_reset_release: assert property (
        @(posedge CLK) disable iff (RST)
        $fell(RST) |=> (CLKOUT == 1'b0) && ((clkCount == 24'h000001) || (clkCount == 24'h000000))
    );

endmodule

bind ClkDiv_5Hz ClkDiv_5Hz_sva #(.cntEndVal(cntEndVal)) u_ClkDiv_5Hz_sva (
    .CLK(CLK),
    .RST(RST),
    .CLKOUT(CLKOUT),
    .clkCount(clkCount)
);

