module full_adder (
    COUT,
    SUM ,
    A   ,
    B   ,
    CI
);

    output COUT;
    output SUM ;
    input  A   ;
    input  B   ;
    input  CI  ;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign {COUT, SUM} = A + B + CI;

endmodule

sva:
module full_adder_sva (
    input logic clk,
    input logic COUT,
    input logic SUM,
    input logic A,
    input logic B,
    input logic CI
);

    // Outputs match the 2-bit sum of the three 1-bit inputs.
    check_output_matches_addition: assert property (
        @(posedge clk)
        {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI})
    );

    // SUM is the odd-parity function of A, B, and CI.
    check_sum_is_input_parity: assert property (
        @(posedge clk)
        SUM == (A ^ B ^ CI)
    );

    // COUT is high when at least two inputs are high.
    check_cout_is_majority: assert property (
        @(posedge clk)
        COUT == ((A & B) | (A & CI) | (B & CI))
    );

    // All-zero inputs produce zero outputs.
    check_zero_inputs: assert property (
        @(posedge clk)
        (!A && !B && !CI) |-> ({COUT, SUM} == 2'b00)
    );

    // All-one inputs produce both outputs high.
    check_all_one_inputs: assert property (
        @(posedge clk)
        (A && B && CI) |-> ({COUT, SUM} == 2'b11)
    );

    // Exactly one high input produces SUM only.
    check_one_high_input: assert property (
        @(posedge clk)
        (( A && !B && !CI) ||
         (!A &&  B && !CI) ||
         (!A && !B &&  CI)) |-> ({COUT, SUM} == 2'b01)
    );

    // Exactly two high inputs produce COUT only.
    check_two_high_inputs: assert property (
        @(posedge clk)
        (( A &&  B && !CI) ||
         ( A && !B &&  CI) ||
         (!A &&  B &&  CI)) |-> ({COUT, SUM} == 2'b10)
    );

endmodule

rtl:
module comparator (
    input [2:0] A,
    input [2:0] B,
    output reg out
);

always @(*) begin
    if (A > B)
        out = 1;
    else if (A < B)
        out = 0;
    else
        out = 0;
end

endmodule

sva:
module comparator_sva (
    input logic clk,
    input logic [2:0] A,
    input logic [2:0] B,
    input logic out
);

    // out must exactly reflect whether A is greater than B.
    check_out_matches_gt_compare: assert property (
        @(posedge clk) (out == (A > B))
    );

    // Greater-than case drives out high.
    check_out_high_when_a_gt_b: assert property (
        @(posedge clk) (A > B) |-> (out == 1'b1)
    );

    // Less-than case drives out low.
    check_out_low_when_a_lt_b: assert property (
        @(posedge clk) (A < B) |-> (out == 1'b0)
    );

    // Equal case drives out low.
    check_out_low_when_a_eq_b: assert property (
        @(posedge clk) (A == B) |-> (out == 1'b0)
    );

endmodule

rtl:
module shift_register (
  input clk,
  input [3:0] data_in,
  output [3:0] data_out
);

  reg [3:0] pipe_reg [0:3];

  always @(posedge clk) begin
    pipe_reg[0] <= data_in;
    pipe_reg[1] <= pipe_reg[0];
    pipe_reg[2] <= pipe_reg[1];
    pipe_reg[3] <= pipe_reg[2];
  end

  assign data_out = pipe_reg[3];

endmodule

module decoder_3to8 (
    input A, B, C, EN, // Inputs for the decoder
    output reg [7:0] Y // 8-bit output of the decoder
);

    always @ (A, B, C, EN)
    begin
        if (EN)
        begin
            case ({A, B, C})
                3'b000: Y = 8'b00000001;
                3'b001: Y = 8'b00000010;
                3'b010: Y = 8'b00000100;
                3'b011: Y = 8'b00001000;
                3'b100: Y = 8'b00010000;
                3'b101: Y = 8'b00100000;
                3'b110: Y = 8'b01000000;
                3'b111: Y = 8'b10000000;
            endcase
        end
        else
        begin
            Y = 8'b00000000;
        end
    end
endmodule

sva:
module decoder_3to8_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic EN,
    input logic [7:0] Y
);

    // Disabled decoder drives all outputs low.
    check_disable_drives_zero: assert property (
        @(posedge clk) (!EN) |-> (Y == 8'b00000000)
    );

    // Input 000 selects bit 0 when enabled.
    check_decode_000: assert property (
        @(posedge clk) (EN && !A && !B && !C) |-> (Y == 8'b00000001)
    );

    // Input 001 selects bit 1 when enabled.
    check_decode_001: assert property (
        @(posedge clk) (EN && !A && !B && C) |-> (Y == 8'b00000010)
    );

    // Input 010 selects bit 2 when enabled.
    check_decode_010: assert property (
        @(posedge clk) (EN && !A && B && !C) |-> (Y == 8'b00000100)
    );

    // Input 011 selects bit 3 when enabled.
    check_decode_011: assert property (
        @(posedge clk) (EN && !A && B && C) |-> (Y == 8'b00001000)
    );

    // Input 100 selects bit 4 when enabled.
    check_decode_100: assert property (
        @(posedge clk) (EN && A && !B && !C) |-> (Y == 8'b00010000)
    );

    // Input 101 selects bit 5 when enabled.
    check_decode_101: assert property (
        @(posedge clk) (EN && A && !B && C) |-> (Y == 8'b00100000)
    );

    // Input 110 selects bit 6 when enabled.
    check_decode_110: assert property (
        @(posedge clk) (EN && A && B && !C) |-> (Y == 8'b01000000)
    );

    // Input 111 selects bit 7 when enabled.
    check_decode_111: assert property (
        @(posedge clk) (EN && A && B && C) |-> (Y == 8'b10000000)
    );

    // Enabled decoder output must be one-hot encoded.
    check_enabled_output_onehot: assert property (
        @(posedge clk) EN |-> (
            (Y == 8'b00000001) ||
            (Y == 8'b00000010) ||
            (Y == 8'b00000100) ||
            (Y == 8'b00001000) ||
            (Y == 8'b00010000) ||
            (Y == 8'b00100000) ||
            (Y == 8'b01000000) ||
            (Y == 8'b10000000)
        )
    );

endmodule

module dff_reset_enable_sva (
    input logic D,
    input logic CLK,
    input logic RESET,
    input logic EN,
    input logic Q
);

    // Active-low reset forces Q low.
    check_reset_forces_q_low: assert property (
        @(posedge CLK)
        !RESET |-> (Q == 1'b0)
    );

    // A sampled reset leaves Q low through the next clock sample.
    check_reset_value_persists_to_next_clock: assert property (
        @(posedge CLK)
        !RESET |=> (Q == 1'b0)
    );

    // When enabled, Q captures D on the clock edge.
    check_load_when_enabled: assert property (
        @(posedge CLK) disable iff (!RESET)
        EN |=> (Q == $past(D))
    );

    // When disabled, Q holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (!RESET)
        !EN |=> (Q == $past(Q))
    );

endmodule

