module four_bit_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CLK,
    input logic RST,
    input logic [4:0] SUM
);

    // Synchronous reset forces SUM to zero.
    check_reset_clears_sum: assert property (
        @(posedge CLK) RST |=> (SUM == 5'b00000)
    );

    // Outside reset, SUM reflects the prior cycle addition of A and B.
    check_sum_matches_previous_addition: assert property (
        @(posedge CLK) disable iff (RST)
        !RST |=> (SUM == ({1'b0, $past(A)} + {1'b0, $past(B)}))
    );

    // Zero operands produce a zero sum on the next sampled cycle.
    check_zero_inputs_produce_zero_sum: assert property (
        @(posedge CLK) disable iff (RST)
        (!RST && (A == 4'b0000) && (B == 4'b0000)) |=> (SUM == 5'b00000)
    );

    // Maximum operands produce 30 on the next sampled cycle.
    check_max_inputs_produce_thirty: assert property (
        @(posedge CLK) disable iff (RST)
        (!RST && (A == 4'b1111) && (B == 4'b1111)) |=> (SUM == 5'd30)
    );

    // When A is zero, SUM equals the prior cycle value of B.
    check_a_zero_passes_b: assert property (
        @(posedge CLK) disable iff (RST)
        (!RST && (A == 4'b0000)) |=> (SUM == {1'b0, $past(B)})
    );

    // When B is zero, SUM equals the prior cycle value of A.
    check_b_zero_passes_a: assert property (
        @(posedge CLK) disable iff (RST)
        (!RST && (B == 4'b0000)) |=> (SUM == {1'b0, $past(A)})
    );

endmodule

module counter4_sva (
    input logic       clk,
    input logic       reset,
    input logic       enable,
    input logic [3:0] count
);

    property p_count_increments_when_enabled;
        logic [3:0] sampled_count;
        @(posedge clk iff !reset) disable iff (reset || $initstate)
            (enable, sampled_count = count) |=> @(posedge clk or posedge reset) (count == sampled_count + 4'd1);
    endproperty

    property p_count_holds_when_disabled;
        logic [3:0] sampled_count;
        @(posedge clk iff !reset) disable iff (reset || $initstate)
            (!enable, sampled_count = count) |=> @(posedge clk or posedge reset) (count == sampled_count);
    endproperty

    property p_clock_edge_with_reset_clears_count;
        @(posedge clk iff reset) disable iff ($initstate)
            1'b1 |=> @(posedge clk or posedge reset) (count == 4'd0);
    endproperty

    property p_async_reset_edge_clears_count;
        @(posedge reset) disable iff ($initstate)
            1'b1 |=> @(posedge clk or posedge reset) (count == 4'd0);
    endproperty

    // Count increments by one after a non-reset enabled clock edge.
    check_count_increments_when_enabled: assert property (p_count_increments_when_enabled);

    // Count holds its value after a non-reset disabled clock edge.
    check_count_holds_when_disabled: assert property (p_count_holds_when_disabled);

    // A clock edge taken while reset is high forces the count to zero.
    check_clock_edge_with_reset_clears_count: assert property (p_clock_edge_with_reset_clears_count);

    // An asynchronous reset edge forces the count to zero.
    check_async_reset_edge_clears_count: assert property (p_async_reset_edge_clears_count);

endmodule

rtl:
module mux4_to_1_async_reset (
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    input reset,
    output [3:0] out
);

    wire [3:0] mux1_out;
    wire [3:0] mux2_out;
    wire [3:0] mux3_out;
    wire [3:0] mux4_out;

    // First stage of the mux
    mux4to1 mux1 (
        .in0(in0),
        .in1(in1),
        .in2(in2),
        .in3(in3),
        .sel(sel[1]),
        .out(mux1_out)
    );

    // Second stage of the mux
    mux4to1 mux2 (
        .in0(in0),
        .in1(in1),
        .in2(in2),
        .in3(in3),
        .sel(sel[0]),
        .out(mux2_out)
    );

    // Third stage of the mux
    mux2to1 mux3 (
        .in0(mux1_out),
        .in1(mux2_out),
        .sel(sel[1]),
        .out(mux3_out)
    );

    // Fourth stage of the mux
    mux2to1 mux4 (
        .in0(mux3_out),
        .in1(4'b0),
        .sel(reset),
        .out(mux4_out)
    );

    assign out = mux4_out;

endmodule
module mux4to1 (
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input sel,
    output [3:0] out
);

    wire [3:0] mux1_out;
    wire [3:0] mux2_out;

    // First stage of the mux
    mux2to1 mux1 (
        .in0(in0),
        .in1(in1),
        .sel(sel),
        .out(mux1_out)
    );

    // Second stage of the mux
    mux2to1 mux2 (
        .in0(in2),
        .in1(in3),
        .sel(sel),
        .out(mux2_out)
    );

    // Third stage of the mux
    mux2to1 mux3 (
        .in0(mux1_out),
        .in1(mux2_out),
        .sel(sel),
        .out(out)
    );

endmodule
module mux2to1 (
    input [3:0] in0,
    input [3:0] in1,
    input sel,
    output [3:0] out
);

    assign out = sel ? in1 : in0;

endmodule

sva:
module mux4_to_1_async_reset_sva (
    input logic [3:0] in0,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] in3,
    input logic [1:0] sel,
    input logic reset,
    input logic [3:0] out
);

    // Reset forces the output to zero.
    check_reset_forces_zero: assert property (
        @($global_clock) reset |-> (out == 4'b0000)
    );

    // Select 00 routes in0 when reset is low.
    check_sel_00_routes_in0: assert property (
        @($global_clock) disable iff (reset)
        (sel == 2'b00) |-> (out == in0)
    );

    // Select 01 routes in0 when reset is low.
    check_sel_01_routes_in0: assert property (
        @($global_clock) disable iff (reset)
        (sel == 2'b01) |-> (out == in0)
    );

    // Select 10 routes in0 when reset is low.
    check_sel_10_routes_in0: assert property (
        @($global_clock) disable iff (reset)
        (sel == 2'b10) |-> (out == in0)
    );

    // Select 11 routes in3 when reset is low.
    check_sel_11_routes_in3: assert property (
        @($global_clock) disable iff (reset)
        (sel == 2'b11) |-> (out == in3)
    );

    // Changing only in1 does not affect the output.
    check_in1_change_has_no_effect: assert property (
        @($global_clock) disable iff (reset)
        ($stable(reset) && $stable(in0) && $changed(in1) && $stable(in2) && $stable(in3) && $stable(sel))
        |-> $stable(out)
    );

    // Changing only in2 does not affect the output.
    check_in2_change_has_no_effect: assert property (
        @($global_clock) disable iff (reset)
        ($stable(reset) && $stable(in0) && $stable(in1) && $changed(in2) && $stable(in3) && $stable(sel))
        |-> $stable(out)
    );

    // With sel[1] low, changing only sel[0] does not affect the output.
    check_sel0_change_has_no_effect_when_sel1_low: assert property (
        @($global_clock) disable iff (reset)
        ($stable(reset) && (sel[1] == 1'b0) && $stable(sel[1]) && $changed(sel[0]) &&
         $stable(in0) && $stable(in1) && $stable(in2) && $stable(in3))
        |-> $stable(out)
    );

    // With sel[0] low, changing only sel[1] does not affect the output.
    check_sel1_change_has_no_effect_when_sel0_low: assert property (
        @($global_clock) disable iff (reset)
        ($stable(reset) && (sel[0] == 1'b0) && $stable(sel[0]) && $changed(sel[1]) &&
         $stable(in0) && $stable(in1) && $stable(in2) && $stable(in3))
        |-> $stable(out)
    );

endmodule

