sva:
module sky130_fd_sc_ms__or2b_sva (
    input logic X,
    input logic A,
    input logic B_N
);

    // Output implements A OR inverted B_N.
    check_output_function: assert property (
        @($global_clock) X == (A | ~B_N)
    );

    // When B_N is high, the output reduces to A.
    check_b_n_high_passes_a: assert property (
        @($global_clock) B_N |-> (X == A)
    );

    // When B_N is low, inversion forces the output high.
    check_b_n_low_forces_high: assert property (
        @($global_clock) !B_N |-> (X == 1'b1)
    );

    // When A is low, the output matches the inversion of B_N.
    check_a_low_matches_inverted_b_n: assert property (
        @($global_clock) !A |-> (X == ~B_N)
    );

    // A low output occurs only for A low and B_N high.
    check_low_output_only_on_single_case: assert property (
        @($global_clock) !X |-> (!A && B_N)
    );

endmodule

rtl:
module mux_nand (
    input A,
    input B,
    input C,
    input sel1,
    input sel2,
    output Y
);

wire n_sel1, n_sel2, n_sel1_sel2, n_sel1_A, n_sel2_B, n_sel1_sel2_C;

assign n_sel1 = ~sel1;
assign n_sel2 = ~sel2;
assign n_sel1_sel2 = n_sel1 & n_sel2;
assign n_sel1_A = n_sel1 & A;
assign n_sel2_B = n_sel2 & B;
assign n_sel1_sel2_C = n_sel1_sel2 & C;

assign Y = ~(n_sel1_A | n_sel2_B | n_sel1_sel2_C);

endmodule

sva:
module mux_nand_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic sel1,
    input logic sel2,
    input logic Y
);

    // RTL is combinational with no reset; assertions are sampled on clk.

    // Y must match the implemented combinational equation.
    check_output_equation: assert property (
        @(posedge clk)
        Y == ~((~sel1 & A) | (~sel2 & B) | (~sel1 & ~sel2 & C))
    );

    // When both selects are high, all terms are disabled and Y is high.
    check_both_selects_high: assert property (
        @(posedge clk)
        (sel1 && sel2) |-> (Y == 1'b1)
    );

    // When only the A term is enabled, Y is the inverse of A.
    check_a_term_only_mode: assert property (
        @(posedge clk)
        (!sel1 && sel2) |-> (Y == ~A)
    );

    // When only the B term is enabled, Y is the inverse of B.
    check_b_term_only_mode: assert property (
        @(posedge clk)
        (sel1 && !sel2) |-> (Y == ~B)
    );

    // When all terms are enabled, Y is the NAND of A, B, and C.
    check_all_terms_enabled_mode: assert property (
        @(posedge clk)
        (!sel1 && !sel2) |-> (Y == ~(A | B | C))
    );

    // A high with sel1 low forces the output low.
    check_a_forces_low: assert property (
        @(posedge clk)
        (!sel1 && A) |-> (Y == 1'b0)
    );

    // B high with sel2 low forces the output low.
    check_b_forces_low: assert property (
        @(posedge clk)
        (!sel2 && B) |-> (Y == 1'b0)
    );

    // C high with both selects low forces the output low.
    check_c_forces_low: assert property (
        @(posedge clk)
        (!sel1 && !sel2 && C) |-> (Y == 1'b0)
    );

    // A low output must come from at least one active product term.
    check_low_output_has_active_term: assert property (
        @(posedge clk)
        (Y == 1'b0) |-> ((!sel1 && A) || (!sel2 && B) || (!sel1 && !sel2 && C))
    );

    // A high output means none of the implemented product terms is active.
    check_high_output_has_no_active_term: assert property (
        @(posedge clk)
        (Y == 1'b1) |-> ((sel1 || !A) && (sel2 || !B) && (sel1 || sel2 || !C))
    );

endmodule

rtl:
module comparator(
  input [2:0] A,
  input [2:0] B,
  output reg EQ,
  output reg GT,
  output reg LT
);

  always @(*) begin
    if (A == B) begin
      EQ = 1;
      GT = 0;
      LT = 0;
    end else if (A > B) begin
      EQ = 0;
      GT = 1;
      LT = 0;
    end else begin
      EQ = 0;
      GT = 0;
      LT = 1;
    end
  end

endmodule

sva:
module comparator_sva (
    input logic       clk,
    input logic [2:0] A,
    input logic [2:0] B,
    input logic       EQ,
    input logic       GT,
    input logic       LT
);

    // Equal inputs must assert only EQ.
    check_equal_case: assert property (
        @(posedge clk) (A == B) |-> (EQ && !GT && !LT)
    );

    // A greater than B must assert only GT.
    check_greater_case: assert property (
        @(posedge clk) (A > B) |-> (!EQ && GT && !LT)
    );

    // A less than B must assert only LT.
    check_less_case: assert property (
        @(posedge clk) (A < B) |-> (!EQ && !GT && LT)
    );

    // EQ can only be high when A equals B.
    check_eq_implies_equal: assert property (
        @(posedge clk) EQ |-> (A == B)
    );

    // GT can only be high when A is greater than B.
    check_gt_implies_greater: assert property (
        @(posedge clk) GT |-> (A > B)
    );

    // LT can only be high when A is less than B.
    check_lt_implies_less: assert property (
        @(posedge clk) LT |-> (A < B)
    );

    // Exactly one comparison result must be asserted.
    check_result_onehot: assert property (
        @(posedge clk) $onehot({EQ, GT, LT})
    );

endmodule

module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [3:0] count
);

    // Reset clears the counter to zero by the next sampled clock.
    check_reset_clears_count: assert property (
        @(posedge clk)
        reset |=> (count == 4'b0000)
    );

    // When enabled, the counter increments by one.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 4'b0001))
    );

    // When disabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

    // The 4-bit counter wraps from 15 back to 0 when enabled.
    check_wrap_from_f_to_0: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 4'hF) |=> (count == 4'h0)
    );

endmodule

rtl:
module mux4_2 (
    output reg X,
    input A0, A1, A2, A3, S0, S1, VPWR, VGND, VPB, VNB
);

    reg [3:0] A;
    reg [1:0] S;

    always @* begin
        A[0] = A0;
        A[1] = A1;
        A[2] = A2;
        A[3] = A3;

        S[0] = S0;
        S[1] = S1;

        case ({S[1], S[0]})
            2'b00: X = A[0];
            2'b01: X = A[1];
            2'b10: X = A[2];
            2'b11: X = A[3];
        endcase
    end

endmodule

sva:
module mux4_2_assertions (
    input logic clk,
    input logic X,
    input logic A0,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic S0,
    input logic S1,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

    // RTL is combinational; clk is an external sampling clock and there is no reset.
    // S1:S0 selects A0-A3 onto X.

    // S=00 routes A0 to X.
    check_select_00_routes_a0: assert property (
        @(posedge clk) ((S1 === 1'b0) && (S0 === 1'b0)) |-> (X === A0)
    );

    // S=01 routes A1 to X.
    check_select_01_routes_a1: assert property (
        @(posedge clk) ((S1 === 1'b0) && (S0 === 1'b1)) |-> (X === A1)
    );

    // S=10 routes A2 to X.
    check_select_10_routes_a2: assert property (
        @(posedge clk) ((S1 === 1'b1) && (S0 === 1'b0)) |-> (X === A2)
    );

    // S=11 routes A3 to X.
    check_select_11_routes_a3: assert property (
        @(posedge clk) ((S1 === 1'b1) && (S0 === 1'b1)) |-> (X === A3)
    );

    // With S=00 and A0 stable, X stays stable.
    check_select_00_stable_output: assert property (
        @(posedge clk) ((S1 === 1'b0) && (S0 === 1'b0) && $stable({S1, S0, A0})) |-> $stable(X)
    );

    // With S=01 and A1 stable, X stays stable.
    check_select_01_stable_output: assert property (
        @(posedge clk) ((S1 === 1'b0) && (S0 === 1'b1) && $stable({S1, S0, A1})) |-> $stable(X)
    );

    // With S=10 and A2 stable, X stays stable.
    check_select_10_stable_output: assert property (
        @(posedge clk) ((S1 === 1'b1) && (S0 === 1'b0) && $stable({S1, S0, A2})) |-> $stable(X)
    );

    // With S=11 and A3 stable, X stays stable.
    check_select_11_stable_output: assert property (
        @(posedge clk) ((S1 === 1'b1) && (S0 === 1'b1) && $stable({S1, S0, A3})) |-> $stable(X)
    );

    // If all functional inputs hold, X holds.
    check_all_functional_inputs_stable_hold_x: assert property (
        @(posedge clk) $stable({A0, A1, A2, A3, S0, S1}) |-> $stable(X)
    );

endmodule

rtl:
module nios_dut_nios2_gen2_0_cpu_nios2_oci_im (
  // inputs:
  clk,
  jrst_n,
  trc_ctrl,
  tw,

  // outputs:
  tracemem_on,
  tracemem_trcdata,
  tracemem_tw,
  trc_im_addr,
  trc_wrap,
  xbrk_wrap_traceoff
);

  output           tracemem_on;
  output  [ 35: 0] tracemem_trcdata;
  output           tracemem_tw;
  output  [  6: 0] trc_im_addr;
  output           trc_wrap;
  output           xbrk_wrap_traceoff;
  input            clk;
  input            jrst_n;
  input   [ 15: 0] trc_ctrl;
  input   [ 35: 0] tw;

  wire             tracemem_on;
  wire    [ 35: 0] tracemem_trcdata;
  wire             tracemem_tw;
  reg     [  6: 0] trc_im_addr ;
  wire    [ 35: 0] trc_im_data;
  wire             trc_on_chip;
  reg              trc_wrap ;
  wire             tw_valid;
  wire             xbrk_wrap_traceoff;

  assign tracemem_on = ~trc_ctrl[8];
  assign tracemem_trcdata = 0;
  assign tracemem_tw = (tw[35:32] != 4'b0000);
  assign trc_im_data = tw;
  assign tw_valid = |trc_im_data[35 : 32];
  assign xbrk_wrap_traceoff = (trc_ctrl[10] & trc_wrap);

  always @(posedge clk or negedge jrst_n) begin
    if (~jrst_n) begin
      trc_im_addr <= 0;
      trc_wrap <= 0;
    end else begin
      if (trc_wrap) begin
        trc_im_addr <= 0;
        trc_wrap <= 0;
      end else begin
        if (tw_valid) trc_im_addr <= trc_im_addr + 1;
        if (trc_im_addr == 7'h7F) trc_wrap <= 1;
      end
    end
  end

endmodule

sva:
module nios_dut_nios2_gen2_0_cpu_nios2_oci_im_sva (
    input logic        clk,
    input logic        jrst_n,
    input logic [15:0] trc_ctrl,
    input logic [35:0] tw,
    input logic        tracemem_on,
    input logic [35:0] tracemem_trcdata,
    input logic        tracemem_tw,
    input logic [6:0]  trc_im_addr,
    input logic        trc_wrap,
    input logic        xbrk_wrap_traceoff
);

    // Reset clears the address and wrap state.
    check_reset_clears_state: assert property (
        @(posedge clk) !jrst_n |-> (trc_im_addr == 7'd0) && (trc_wrap == 1'b0)
    );

    // tracemem_on is the inverse of trc_ctrl[8].
    check_tracemem_on_decode: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (tracemem_on == (~trc_ctrl[8]))
    );

    // tracemem_trcdata is always zero.
    check_tracemem_trcdata_zero: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (tracemem_trcdata == 36'd0)
    );

    // tracemem_tw reflects whether the trace word header is nonzero.
    check_tracemem_tw_decode: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (tracemem_tw == (tw[35:32] != 4'b0000))
    );

    // xbrk_wrap_traceoff is trc_ctrl[10] AND trc_wrap.
    check_xbrk_wrap_traceoff_decode: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (xbrk_wrap_traceoff == (trc_ctrl[10] & trc_wrap))
    );

    // A wrap condition clears the address and deasserts wrap on the next cycle.
    check_wrap_clears_next_cycle: assert property (
        @(posedge clk) disable iff (!jrst_n)
        trc_wrap |=> (!trc_wrap && (trc_im_addr == 7'd0))
    );

    // Without wrap, a valid trace word increments the address.
    check_addr_increments_on_valid: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!trc_wrap && (tw[35:32] != 4'b0000)) |=> (trc_im_addr == ($past(trc_im_addr) + 7'd1))
    );

    // Without wrap and without a valid trace word, the address holds.
    check_addr_holds_on_no_valid: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!trc_wrap && (tw[35:32] == 4'b0000)) |=> (trc_im_addr == $past(trc_im_addr))
    );

    // Reaching the terminal address asserts wrap on the next cycle.
    check_wrap_sets_at_terminal_addr: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!trc_wrap && (trc_im_addr == 7'h7F)) |=> trc_wrap
    );

    // Before the terminal address, wrap remains deasserted.
    check_wrap_stays_low_before_terminal_addr: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!trc_wrap && (trc_im_addr != 7'h7F)) |=> !trc_wrap
    );

endmodule

