    // With C_N and D_N high, X is determined only by A or B.
    check_or_term_when_nand_inactive: assert property (
        @(posedge clk) (C_N && D_N) |-> (X == (A | B))
    );

    // When all effective OR inputs are low, X is low.
    check_all_terms_low_drive_x_low: assert property (
        @(posedge clk) (!A && !B && C_N && D_N) |-> !X
    );

    // If X is low, all effective OR inputs must be low.
    check_x_low_requires_all_terms_low: assert property (
        @(posedge clk) !X |-> (!A && !B && C_N && D_N)
    );

endmodule

rtl:
module DFFSR (CLK, D, SET, RESET, Q, QN);
input CLK;
input D;
input SET;
input RESET;
output Q;
output QN;

reg Q;

always @(posedge CLK) begin
    if (SET) begin
        Q <= 1'b1;
    end else if (RESET) begin
        Q <= 1'b0;
    end else begin
        Q <= D;
    end
end

assign QN = ~Q;

endmodule

sva:
module DFFSR_sva (
    input logic CLK,
    input logic D,
    input logic SET,
    input logic RESET,
    input logic Q,
    input logic QN
);

    // QN is always the inverse of Q.
    check_qn_is_inverse_of_q: assert property (
        @(posedge CLK) disable iff (1'b0) (QN === ~Q)
    );

    // SET alone drives Q high on the next cycle.
    check_set_drives_q_high: assert property (
        @(posedge CLK) disable iff (1'b0) (SET && !RESET) |=> (Q === 1'b1)
    );

    // SET has priority over RESET on the next cycle.
    check_set_overrides_reset: assert property (
        @(posedge CLK) disable iff (1'b0) (SET && RESET) |=> (Q === 1'b1)
    );

    // RESET drives Q low when SET is low.
    check_reset_drives_q_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!SET && RESET) |=> (Q === 1'b0)
    );

    // D is captured when SET and RESET are low.
    check_data_capture: assert property (
        @(posedge CLK) disable iff (1'b0) (!SET && !RESET) |=> (Q === $past(D))
    );

endmodule

rtl:
module binary_to_gray (
    input [7:0] binary_in,
    input sel_b1,
    input sel_b2,
    output [7:0] gray_out);

    // Priority encoder to find position of first 1 in binary input
    wire [2:0] pos;
    wire [7:0] not_binary_in = ~binary_in;
    assign pos = not_binary_in > binary_in ? {3'b000, not_binary_in[7:3]} :
                                             not_binary_in > binary_in >> 1 ? {3'b001, not_binary_in[6:2]} :
                                                                             {3'b010, not_binary_in[5:1]};

    // 2-to-1 multiplexer to select between binary input and right shift by 1 bit
    wire [7:0] shift_right = {1'b0, binary_in[7:1]};
    assign gray_out = sel_b1 ? binary_in : (sel_b2 ? shift_right : binary_in);

endmodule

sva:
module binary_to_gray_sva (
    input logic        clk,
    input logic [7:0]  binary_in,
    input logic        sel_b1,
    input logic        sel_b2,
    input logic [7:0]  gray_out
);

    // No DUT clock or reset exists; sample this combinational logic on clk.
    // The internal pos calculation is unused at the output.

    // gray_out must match the implemented mux expression every cycle.
    check_output_function: assert property (
        @(posedge clk)
        gray_out == (sel_b1 ? binary_in : (sel_b2 ? {1'b0, binary_in[7:1]} : binary_in))
    );

    // sel_b1 selects the direct binary input.
    check_sel_b1_passthrough: assert property (
        @(posedge clk)
        sel_b1 |-> (gray_out == binary_in)
    );

    // With only sel_b2 asserted, gray_out is binary_in shifted right by 1.
    check_shift_right_selected: assert property (
        @(posedge clk)
        (!sel_b1 && sel_b2) |-> (gray_out == {1'b0, binary_in[7:1]})
    );

    // With both selects low, gray_out passes binary_in unchanged.
    check_default_passthrough: assert property (
        @(posedge clk)
        (!sel_b1 && !sel_b2) |-> (gray_out == binary_in)
    );

    // sel_b1 has priority over sel_b2 when both are high.
    check_sel_b1_priority: assert property (
        @(posedge clk)
        (sel_b1 && sel_b2) |-> (gray_out == binary_in)
    );

    // The shifted path forces the MSB of gray_out low.
    check_shifted_msb_zero: assert property (
        @(posedge clk)
        (!sel_b1 && sel_b2) |-> (gray_out[7] == 1'b0)
    );

    // Stable inputs must keep the combinational output stable at sampled edges.
    check_stable_inputs_stable_output: assert property (
        @(posedge clk)
        $stable({binary_in, sel_b1, sel_b2}) |-> $stable(gray_out)
    );

endmodule

rtl:
module counter_module (
    input clk,
    input rst,
    output reg [31:0] count,
    output reg max_reached
);

reg [31:0] max_count = 32'hFFFFFFFF; // maximum count value

always @(posedge clk) begin
    if (rst) begin
        count <= 0;
        max_reached <= 0;
    end
    else begin
        if (count == max_count) begin
            max_reached <= 1;
        end
        else begin
            count <= count + 1;
            max_reached <= 0;
        end
    end
end

endmodule

sva:
module counter_module_sva (
    input logic        clk,
    input logic        rst,
    input logic [31:0] count,
    input logic        max_reached
);

    // Synchronous reset clears the counter and flag on the next clock.
    check_reset_clears_state: assert property (
        @(posedge clk)
        rst |=> (count == 32'd0) && (max_reached == 1'b0)
    );

    // Below max, the counter increments by one and the flag stays low.
    check_increment_until_max: assert property (
        @(posedge clk) disable iff (rst)
        (count != 32'hFFFFFFFF) |=> (count == ($past(count) + 32'd1)) && (max_reached == 1'b0)
    );

    // At max, the counter saturates and the flag asserts.
    check_saturate_and_flag_at_max: assert property (
        @(posedge clk) disable iff (rst)
        (count == 32'hFFFFFFFF) |=> (count == $past(count)) && (max_reached == 1'b1)
    );

endmodule

