assign out = a & b;

endmodule

sva:
module dual_edge_ff_sva (
    input logic clk,
    input logic d,
    input logic q
);

    // A sampled 0-to-1 transition on d makes q high on the next clock.
    check_sampled_rise_sets_q_next: assert property (
        @(posedge clk)
        (!$isunknown($past(d,1)) && ($past(d,1) == 1'b0) && (d == 1'b1)) |=> (q == 1'b1)
    );

    // Any non-rising sampled d pattern keeps q low on the next clock.
    check_non_rise_clears_q_next: assert property (
        @(posedge clk)
        (!$isunknown($past(d,1)) && !(($past(d,1) == 1'b0) && (d == 1'b1))) |=> (q == 1'b0)
    );

    // q does not assert in the same cycle that d is sampled rising.
    check_rise_detect_is_delayed: assert property (
        @(posedge clk)
        (!$isunknown($past(d,1)) && ($past(d,1) == 1'b0) && (d == 1'b1)) |-> (q == 1'b0)
    );

    // q can only be high after the two previous d samples were 0 then 1.
    check_q_high_only_after_sampled_rise: assert property (
        @(posedge clk)
        (!$isunknown($past(d,2)) && (q == 1'b1)) |-> (($past(d,2) == 1'b0) && ($past(d,1) == 1'b1))
    );

    // q is a one-cycle pulse once enough input history exists.
    check_q_is_single_cycle_pulse: assert property (
        @(posedge clk)
        (!$isunknown($past(d,2)) && (q == 1'b1)) |=> (q == 1'b0)
    );

    // q matches the delayed rise-detect function of sampled d.
    check_q_matches_delayed_rise_detect: assert property (
        @(posedge clk)
        !$isunknown($past(d,2)) |-> (q == ($past(d,1) & (~$past(d,2))))
    );

endmodule

rtl:
module twos_complement (
    input [3:0] in,
    output [3:0] out
);

reg [7:0] sign_extended;
reg [7:0] twos_complement;
reg [3:0] out; // Change from wire to reg

always @(*) begin
    sign_extended = { {8{in[3]}}, in };
    twos_complement = ~sign_extended + 1;
    out = twos_complement[3:0];
end

endmodule

sva:
module twos_complement_sva (
    input logic       clk,
    input logic [3:0] in,
    input logic [3:0] out
);

    // RTL is combinational; assertions sample on an external clock.

    // Output is the 4-bit two's complement of the input.
    check_exact_twos_complement: assert property (
        @(posedge clk) out == (~in + 4'b0001)
    );

    // Input and output sum to zero modulo 16.
    check_additive_inverse: assert property (
        @(posedge clk) (in + out) == 4'h0
    );

    // Zero maps to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (in == 4'h0) |-> (out == 4'h0)
    );

    // 4'b1000 is its own two's complement.
    check_min_value_maps_to_self: assert property (
        @(posedge clk) (in == 4'h8) |-> (out == 4'h8)
    );

    // Positive nonzero inputs produce a negative 4-bit result.
    check_positive_nonzero_sign_flip: assert property (
        @(posedge clk) ((in[3] == 1'b0) && (in != 4'h0)) |-> (out[3] == 1'b1)
    );

    // Negative inputs other than 4'b1000 produce a positive 4-bit result.
    check_negative_nonmin_sign_flip: assert property (
        @(posedge clk) ((in[3] == 1'b1) && (in != 4'h8)) |-> (out[3] == 1'b0)
    );

endmodule

