module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C
);

    assign {C, S} = A + B;

endmodule
module shift_register (
    input clk,
    input [3:0] din,
    input load,
    input shift,
    output reg [3:0] dout
);

    always @(posedge clk) begin
        if (load) begin
            dout <= din;
        end else if (shift) begin
            dout <= {dout[2:0], 1'b0};
        end
    end

endmodule
module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input select, // Select input to choose between adder and shift_register
    input [3:0] A, // 4-bit input for the adder
    input [3:0] B, // 4-bit input for the adder
    input [3:0] din, // 4-bit input for the shift_register
    input load, // Load input for the shift_register
    input shift, // Shift input for the shift_register
    output [7:0] out // 8-bit output from the active module
);

    wire [3:0] S;
    wire C;
    wire [3:0] dout;

    ripple_carry_adder adder_inst (
        .A(A),
        .B(B),
        .S(S),
        .C(C)
    );

    shift_register shift_reg_inst (
        .clk(clk),
        .din(din),
        .load(load),
        .shift(shift),
        .dout(dout)
    );

    assign out = {S, dout};

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic select,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] din,
    input logic load,
    input logic shift,
    input logic [7:0] out
);

    // Upper nibble always reflects the 4-bit sum of A and B.
    check_adder_output: assert property (
        @(posedge clk) disable iff (reset)
        out[7:4] == (A + B)
    );

    // A load captures din into the lower nibble on the next cycle.
    check_shift_load: assert property (
        @(posedge clk) disable iff (reset)
        load |=> out[3:0] == $past(din)
    );

    // A shift without load moves the lower nibble left and inserts 0.
    check_shift_left: assert property (
        @(posedge clk) disable iff (reset)
        (!load && shift) |=> out[3:0] == { $past(out[2:0]), 1'b0 }
    );

    // With neither load nor shift, the lower nibble holds its value.
    check_shift_hold: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !shift) |=> out[3:0] == $past(out[3:0])
    );

    // Load takes priority over shift when both controls are asserted.
    check_load_priority: assert property (
        @(posedge clk) disable iff (reset)
        (load && shift) |=> out[3:0] == $past(din)
    );

endmodule

rtl:
module sky130_fd_sc_ls__o21ai (
    //# {{data|Data Signals}}
    input  A1  ,
    input  A2  ,
    input  B1  ,
    output Y   ,

    //# {{power|Power}}
    input  VPB ,
    input  VPWR,
    input  VGND,
    input  VNB
);

    assign Y = (A1 ^ A2) ? ~B1 : (A1 & A2) ? B1 : A1 & A2;

endmodule

sva:
module sky130_fd_sc_ls__o21ai_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic Y,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

    // Y matches the RTL equation each sampled cycle.
    check_y_matches_rtl_equation: assert property (
        @(posedge clk)
        Y == ((A1 ^ A2) ? ~B1 : ((A1 & A2) ? B1 : (A1 & A2)))
    );

    // When A1 and A2 differ, Y is the inverse of B1.
    check_y_inverts_b1_when_a_inputs_differ: assert property (
        @(posedge clk)
        (A1 ^ A2) |-> (Y == ~B1)
    );

    // When A1 and A2 are both high, Y follows B1.
    check_y_follows_b1_when_a_inputs_high: assert property (
        @(posedge clk)
        (A1 & A2) |-> (Y == B1)
    );

    // When A1 and A2 are both low, Y is low.
    check_y_low_when_a_inputs_low: assert property (
        @(posedge clk)
        (!A1 && !A2) |-> (Y == 1'b0)
    );

    // With B1 high, Y reduces to A1 and A2.
    check_y_equals_and_when_b1_high: assert property (
        @(posedge clk)
        B1 |-> (Y == (A1 & A2))
    );

    // With B1 low, Y reduces to A1 xor A2.
    check_y_equals_xor_when_b1_low: assert property (
        @(posedge clk)
        !B1 |-> (Y == (A1 ^ A2))
