sva:
module binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

    // Single-clock sequential counter with active-high synchronous reset.

    // A reset seen on the prior clock forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) disable iff ($initstate)
        $past(reset) |-> (count == 4'b0000)
    );

    // Outside reset, count follows the RTL next-state relation.
    check_count_next_state: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (count == ($past(reset) ? 4'b0000 : ($past(count) + 4'd1)))
    );

    // Outside reset, 4'hF wraps to 4'h0 on the next cycle.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (!$past(reset) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

endmodule

rtl:
module top_module (
    input [3:0] in,
    input S,
    input P,
    output reg Y
);

    wire [15:0] decoder_out;
    wire mux_out;

    decoder_4to16 decoder_inst (
        .in(in),
        .out(decoder_out)
    );

    priority_mux mux_inst (
        .A(decoder_out[S]),
        .B(decoder_out[S+1]),
        .C(in[2]),
        .S(S),
        .P(P),
        .Y(mux_out)
    );

    always @(*) begin
        if (P) begin
            Y = in[2];
        end else begin
            Y = mux_out;
        end
    end

endmodule

module decoder_4to16 (
    input [3:0] in,
    output reg [15:0] out
);

    always @(*) begin
        case (in)
            4'b0000: out = 16'b0000000000000001;
            4'b0001: out = 16'b0000000000000010;
            4'b0010: out = 16'b0000000000000100;
            4'b0011: out = 16'b0000000000001000;
            4'b0100: out = 16'b0000000000010000;
            4'b0101: out = 16'b0000000000100000;
            4'b0110: out = 16'b0000000001000000;
            4'b0111: out = 16'b0000000010000000;
            4'b1000: out = 16'b0000000100000000;
            4'b1001: out = 16'b0000001000000000;
            4'b1010: out = 16'b0000010000000000;
            4'b1011: out = 16'b0000100000000000;
            4'b1100: out = 16'b0001000000000000;
            4'b1101: out = 16'b0010000000000000;
            4'b1110: out = 16'b0100000000000000;
            4'b1111: out = 16'b1000000000000000;
        endcase
    end

endmodule

module priority_mux (
    input A,
    input B,
    input C,
    input S,
    input P,
    output reg Y
);

    always @(*) begin
        if (P) begin
            Y = C;
        end else begin
            if (S) begin
                Y = A;
            end else begin
                Y = B;
            end
        end
    end

endmodule

sva:
module top_module_sva (
    input logic [3:0] in,
    input logic S,
    input logic P,
    input logic Y
);

    // When P is high, Y bypasses the mux and follows in[2].
    check_priority_bypass: assert property (
        @($global_clock) disable iff (1'b0)
        P |-> (Y == in[2])
    );

    // When P is low and S is high, Y selects decoder bit 1.
    check_decode_path_s_high: assert property (
        @($global_clock) disable iff (1'b0)
        (!P && S) |-> (Y == (in == 4'b0001))
    );

    // When P is low and S is low, Y also selects decoder bit 1.
    check_decode_path_s_low: assert property (
        @($global_clock) disable iff (1'b0)
        (!P && !S) |-> (Y == (in == 4'b0001))
    );

    // When P is low, in==1 must drive Y high.
    check_decode_hit: assert property (
        @($global_clock) disable iff (1'b0)
        (!P && (in == 4'b0001)) |-> Y
    );

    // When P is low, any other input must drive Y low.
    check_decode_miss: assert property (
        @($global_clock) disable iff (1'b0)
        (!P && (in != 4'b0001)) |-> !Y
    );

    // Changing only S while P stays low cannot change Y.
    check_s_independent_when_p_low: assert property (
        @($global_clock) disable iff (1'b0)
        ($past(1'b1) && $past(!P) && !P && $stable(in) && $changed(S)) |-> $stable(Y)
    );

    // Changing only S while P stays high cannot change Y.
    check_s_independent_when_p_high: assert property (
        @($global_clock) disable iff (1'b0)
        ($past(1'b1) && $past(P) && P && $stable(in) && $changed(S)) |-> $stable(Y)
    );

    // If all inputs are stable, Y must remain stable.
    check_no_state_when_inputs_stable: assert property (
        @($global_clock) disable iff (1'b0)
        ($past(1'b1) && $stable({in, S, P})) |-> $stable(Y)
    );

    // The observable output matches the full combinational function.
    check_full_function: assert property (
        @($global_clock) disable iff (1'b0)
        Y == (P ? in[2] : (in == 4'b0001))
    );

endmodule

module BIN_DEC1_sva (
    input logic [15:0] B1,
    input logic [19:0] bcdout1
);

    function automatic int unsigned bcd_to_bin(input logic [19:0] bcd);
        int unsigned d4;
        int unsigned d3;
        int unsigned d2;
        int unsigned d1;
        int unsigned d0;
        begin
            d4 = bcd[19:16];
            d3 = bcd[15:12];
            d2 = bcd[11:8];
            d1 = bcd[7:4];
            d0 = bcd[3:0];
            bcd_to_bin = (d4 * 10000) + (d3 * 1000) + (d2 * 100) + (d1 * 10) + d0;
        end
    endfunction

    // Each output nibble must be a valid BCD digit.
    check_output_digits_are_valid_bcd: assert property (
        @($global_clock)
        (bcdout1[19:16] <= 4'd9) &&
        (bcdout1[15:12] <= 4'd9) &&
        (bcdout1[11:8]  <= 4'd9) &&
        (bcdout1[7:4]   <= 4'd9) &&
        (bcdout1[3:0]   <= 4'd9)
    );

    // The BCD output must reconstruct the original binary input.
    check_bcd_reconstructs_input: assert property (
        @($global_clock) bcd_to_bin(bcdout1) == B1
    );

    // Zero input must produce all-zero BCD digits.
    check_zero_maps_to_zero: assert property (
        @($global_clock) (B1 == 16'd0) |-> (bcdout1 == 20'd0)
    );

    // The maximum 16-bit input must encode as decimal 65535.
    check_max_maps_to_65535: assert property (
        @($global_clock) (B1 == 16'd65535) |-> (bcdout1 == 20'h65535)
    );

    // The ten-thousands digit cannot exceed 6 for a 16-bit input.
    check_ten_thousands_digit_range: assert property (
        @($global_clock) bcdout1[19:16] <= 4'd6
    );

    // Inputs below 10 must have zero in all upper BCD digits.
    check_single_digit_input_has_zero_upper_digits: assert property (
        @($global_clock) (B1 < 16'd10) |-> (bcdout1[19:4] == 16'd0)
    );

    // Inputs below 100 must have zero above the tens digit.
    check_two_digit_input_has_zero_upper_digits: assert property (
        @($global_clock) (B1 < 16'd100) |-> (bcdout1[19:8] == 12'd0)
    );

    // Inputs below 1000 must have zero above the hundreds digit.
    check_three_digit_input_has_zero_upper_digits: assert property (
        @($global_clock) (B1 < 16'd1000) |-> (bcdout1[19:12] == 8'd0)
    );

    // Inputs below 10000 must have a zero ten-thousands digit.
    check_four_digit_input_has_zero_top_digit: assert property (
        @($global_clock) (B1 < 16'd10000) |-> (bcdout1[19:16] == 4'd0)
    );

endmodule

