sva:
module sky130_fd_sc_lp__o21ai_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic Y,
    input logic VDD,
    input logic VSS
);

    // No RTL clock/reset; sample this combinational cell on clk.
    // Y matches the implemented combinational equation.
    check_function_equation: assert property (
