module d_ff_async_reset_sync_set (
  input D,
  input C,
  input R,
  input E,
  output Q
);

  reg Q_next;

  always @ (posedge C or negedge E) begin
    if (!E) begin
      Q_next <= Q_next;
    end else if (R) begin
      Q_next <= 1'b0;
    end else begin
      Q_next <= D;
    end
  end

  assign Q = Q_next;

endmodule

sva:
module d_ff_async_reset_sync_set_sva (
    input logic D,
    input logic C,
    input logic R,
    input logic E,
    input logic Q
);

    // Enabled clock edges update Q from the reset/data selection.
    check_enabled_update: assert property (
        @(posedge C) disable iff (1'b0)
        E |=> (Q == ($past(R) ? 1'b0 : $past(D)))
    );

    // Disabled clock edges hold the previous Q value.
    check_hold_when_disabled: assert property (
        @(posedge C) disable iff (1'b0)
        !E |=> (Q == $past(Q))
    );

    // Synchronous reset clears Q when E is high.
    check_sync_reset_clears_q: assert property (
        @(posedge C) disable iff (1'b0)
        (E && R) |=> (Q == 1'b0)
    );

    // With E high and no reset, D=1 is captured into Q.
    check_capture_one_when_enabled: assert property (
        @(posedge C) disable iff (1'b0)
        (E && !R && D) |=> (Q == 1'b1)
    );

    // With E high and no reset, D=0 is captured into Q.
    check_capture_zero_when_enabled: assert property (
        @(posedge C) disable iff (1'b0)
        (E && !R && !D) |=> (Q == 1'b0)
    );

    // E low prevents reset from changing Q on that clock edge.
    check_disabled_overrides_reset: assert property (
        @(posedge C) disable iff (1'b0)
        (!E && R) |=> (Q == $past(Q))
    );

endmodule

rtl:
 module lookahead(c_in, c_out, c, p, g, P, G);
   input [3:0] p, g;
   input c_in;

   output [2:0] c;
   output c_out;
   output P, G;

   assign  c[0] = g[0] | (p[0] & c_in); 
   assign  c[1] = g[1] | (g[0] & p[1]) | (p[1] & p[0] & c_in); 
   assign  c[2] = g[2] | (g[1] & p[2]) | (g[0] & p[1] & p[2]) | (p[2] & p[1] & p[0] & c_in); 
   assign  c_out = g[3] | (g[2] & p[3]) | (g[1] & p[2] & p[3]) | (g[0] & p[1] & p[2] & p[3]) | (p[3] & p[2] & p[1] & p[0] & c_in);  

   assign  G = g[3] | (g[2] & p[3]) | (g[1] & p[2] & p[3]) | (p[3] & p[2] & p[1] & g[0]);
   assign  P = p[3] & p[2] & p[1] & p[0];

endmodule

sva:
module lookahead_sva (
    input logic clk,
    input logic c_in,
    input logic [3:0] p,
    input logic [3:0] g,
    input logic [2:0] c,
    input logic c_out,
    input logic P,
    input logic G
);

    // Combinational DUT sampled on clk; no reset is present in the RTL.

    // c[0] matches the first lookahead carry equation.
    check_c0_equation: assert property (
        @(posedge clk) c[0] == (g[0] | (p[0] & c_in))
    );

    // c[1] matches the second lookahead carry equation.
    check_c1_equation: assert property (
        @(posedge clk) c[1] == (g[1] | (g[0] & p[1]) | (p[1] & p[0] & c_in))
    );

    // c[2] matches the third lookahead carry equation.
    check_c2_equation: assert property (
        @(posedge clk) c[2] == (g[2] | (g[1] & p[2]) | (g[0] & p[1] & p[2]) | (p[2] & p[1] & p[0] & c_in))
    );

    // c_out matches the full carry-out equation.
    check_cout_equation: assert property (
        @(posedge clk) c_out == (g[3] | (g[2] & p[3]) | (g[1] & p[2] & p[3]) | (g[0] & p[1] & p[2] & p[3]) | (p[3] & p[2] & p[1] & p[0] & c_in))
    );

    // G matches the group-generate equation.
    check_group_generate_equation: assert property (
        @(posedge clk) G == (g[3] | (g[2] & p[3]) | (g[1] & p[2] & p[3]) | (p[3] & p[2] & p[1] & g[0]))
    );

    // P matches the group-propagate equation.
    check_group_propagate_equation: assert property (
        @(posedge clk) P == (p[3] & p[2] & p[1] & p[0])
    );

    // c[1] also equals the recursive carry form using c[0].
    check_c1_recursive_form: assert property (
        @(posedge clk) c[1] == (g[1] | (p[1] & c[0]))
    );

    // c[2] also equals the recursive carry form using c[1].
    check_c2_recursive_form: assert property (
        @(posedge clk) c[2] == (g[2] | (p[2] & c[1]))
    );

    // c_out also equals the recursive carry form using c[2].
    check_cout_recursive_form: assert property (
        @(posedge clk) c_out == (g[3] | (p[3] & c[2]))
    );

    // c_out equals group generate OR propagated input carry.
    check_cout_group_relation: assert property (
        @(posedge clk) c_out == (G | (P & c_in))
    );

endmodule

rtl:
module karnaugh_map(
  input wire A, B, C, D,
  output reg F
);

  always @(*) begin
    case ({A,B,C,D})
      4'b0000, 4'b0010, 4'b0101, 4'b1001: F = 1;
      4'b0001, 4'b0100, 4'b1010, 4'b1111: F = 0;
      default: F = 1'b0;
    endcase
  end

endmodule

sva:
module karnaugh_map_sva(
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic F
);

    // F is 1 for the four minterms assigned high.
    check_f_high_minterms: assert property (
        @($global_clock) disable iff (1'b0)
        ((({A,B,C,D} === 4'b0000) ||
          ({A,B,C,D} === 4'b0010) ||
          ({A,B,C,D} === 4'b0101) ||
          ({A,B,C,D} === 4'b1001))) |-> (F === 1'b1)
    );

    // F is 0 for the four minterms explicitly assigned low.
    check_f_low_explicit_minterms: assert property (
        @($global_clock) disable iff (1'b0)
        ((({A,B,C,D} === 4'b0001) ||
          ({A,B,C,D} === 4'b0100) ||
          ({A,B,C,D} === 4'b1010) ||
          ({A,B,C,D} === 4'b1111))) |-> (F === 1'b0)
    );

    // F is 0 for every input combination handled by the default case.
    check_f_low_default_minterms: assert property (
        @($global_clock) disable iff (1'b0)
        ((({A,B,C,D} !== 4'b0000) &&
          ({A,B,C,D} !== 4'b0010) &&
          ({A,B,C,D} !== 4'b0101) &&
          ({A,B,C,D} !== 4'b1001) &&
          ({A,B,C,D} !== 4'b0001) &&
          ({A,B,C,D} !== 4'b0100) &&
          ({A,B,C,D} !== 4'b1010) &&
          ({A,B,C,D} !== 4'b1111))) |-> (F === 1'b0)
    );

endmodule

