sva:
module QPSK_Demodulator_Baseband_assertions (
    input logic clk,
    input logic signed [15:0] in0_re,
    input logic signed [15:0] in0_im,
    input logic [1:0] out0
);

    // No clock or reset exists in the RTL; sample combinational behavior on clk.

    // Positive in-phase and positive quadrature map to 00.
    check_pospos_symbol: assert property (
        @(posedge clk)
        (in0_re > 16'sd0 && in0_im > 16'sd0) |-> (out0 == 2'b00)
    );

    // Positive in-phase and zero quadrature map to 00.
    check_poszero_symbol: assert property (
        @(posedge clk)
        (in0_re > 16'sd0 && in0_im == 16'sd0) |-> (out0 == 2'b00)
    );

    // Positive in-phase and negative quadrature map to 10.
    check_posneg_symbol: assert property (
        @(posedge clk)
        (in0_re > 16'sd0 && in0_im < 16'sd0) |-> (out0 == 2'b10)
    );

    // Zero in-phase and positive quadrature map to 01.
    check_zeropos_symbol: assert property (
        @(posedge clk)
        (in0_re == 16'sd0 && in0_im > 16'sd0) |-> (out0 == 2'b01)
    );

    // Zero in-phase and zero quadrature map to 00.
    check_zerozero_symbol: assert property (
        @(posedge clk)
        (in0_re == 16'sd0 && in0_im == 16'sd0) |-> (out0 == 2'b00)
    );

    // Zero in-phase and negative quadrature map to 10.
    check_zeroneg_symbol: assert property (
        @(posedge clk)
        (in0_re == 16'sd0 && in0_im < 16'sd0) |-> (out0 == 2'b10)
    );

    // Negative in-phase and positive quadrature map to 01.
    check_negpos_symbol: assert property (
        @(posedge clk)
        (in0_re < 16'sd0 && in0_im > 16'sd0) |-> (out0 == 2'b01)
    );

    // Negative in-phase and zero quadrature map to 11.
    check_negzero_symbol: assert property (
        @(posedge clk)
        (in0_re < 16'sd0 && in0_im == 16'sd0) |-> (out0 == 2'b11)
    );

    // Negative in-phase and negative quadrature map to 11.
    check_negneg_symbol: assert property (
        @(posedge clk)
        (in0_re < 16'sd0 && in0_im < 16'sd0) |-> (out0 == 2'b11)
    );

endmodule

rtl:
module message_display_system (
    input clk,
    input reset,   // Synchronous active-high reset
    input [7:0] message,   // ASCII message string input
    output [15:0] display  // 16-character display output
);

    // 4:16 decoder
    wire [15:0] decoder_output;
    decoder_4to16 decoder(
        .in({message[3], message[2], message[1], message[0]}),
        .out(decoder_output)
    );

    // 16-bit shift register
    reg [15:0] shift_register;
    always @(posedge clk) begin
        if (reset) begin
            shift_register <= 16'b0;
        end else begin
            shift_register <= {shift_register[14:0], decoder_output[15]};
        end
    end

    // Output display
    assign display = shift_register;

endmodule

// 4:16 decoder module
module decoder_4to16 (
    input [3:0] in,
    output reg [15:0] out
);

    always @* begin
        case (in)
            4'b0000: out = 16'b0000000000000001;
            4'b0001: out = 16'b0000000000000010;
            4'b0010: out = 16'b0000000000000100;
            4'b0011: out = 16'b0000000000001000;
            4'b0100: out = 16'b0000000000010000;
            4'b0101: out = 16'b0000000000100000;
            4'b0110: out = 16'b0000000001000000;
            4'b0111: out = 16'b0000000010000000;
            4'b1000: out = 16'b0000000100000000;
            4'b1001: out = 16'b0000001000000000;
            4'b1010: out = 16'b0000010000000000;
            4'b1011: out = 16'b0000100000000000;
            4'b1100: out = 16'b0001000000000000;
            4'b1101: out = 16'b0010000000000000;
            4'b1110: out = 16'b0100000000000000;
            4'b1111: out = 16'b1000000000000000;
            default: out = 16'b0000000000000000;
        endcase
    end

endmodule

sva:
module message_display_system_sva (
    input logic        clk,
    input logic        reset,
    input logic [7:0]  message,
    input logic [15:0] display
);

    // Reset clears the display by the next sampled cycle.
    check_reset_clears_display: assert property (
        @(posedge clk) reset |=> (display == 16'b0)
    );

    // The upper 15 display bits shift from the prior lower 15 bits.
    check_display_upper_bits_shift: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        1'b1 |=> (display[15:1] == $past(display[14:0]))
    );

    // A lower nibble of 4'hF shifts a 1 into display bit 0.
    check_lsb_loads_one_on_f: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (message[3:0] === 4'hF) |=> (display[0] == 1'b1)
    );

    // Any lower nibble other than 4'hF shifts a 0 into display bit 0.
    check_lsb_loads_zero_otherwise: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        (message[3:0] !== 4'hF) |=> (display[0] == 1'b0)
    );

    // Sixteen consecutive zero inserts clear all prior display contents.
    check_sixteen_zero_inserts_clear_display: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        ((message[3:0] !== 4'hF)[*16]) |=> (display == 16'b0)
    );

    // Sixteen consecutive one inserts fill the display with ones.
    check_sixteen_one_inserts_fill_display: assert property (
        @(posedge clk) disable iff (reset || $initstate)
        ((message[3:0] === 4'hF)[*16]) |=> (display == 16'hFFFF)
    );

endmodule

rtl:
module combinational_logic (
    X   ,
    A1  ,
    A2  ,
    B1_N
);

    output X   ;
    input  A1  ;
    input  A2  ;
    input  B1_N;

    assign X = (~A1 & A2 & B1_N) | (A1 & ~A2 & B1_N) | (A1 & A2 & ~B1_N);

endmodule

sva:
module combinational_logic_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1_N
);

    // Sampling clock for this combinational DUT.

    // X matches the implemented sum-of-products equation.
    check_output_equation: assert property (
        @(posedge clk)
        X == ((~A1 & A2 & B1_N) | (A1 & ~A2 & B1_N) | (A1 & A2 & ~B1_N))
    );

    // With B1_N high, X reduces to A1 XOR A2.
    check_b1n_high_xor_behavior: assert property (
        @(posedge clk)
        B1_N |-> (X == (A1 ^ A2))
    );

    // With B1_N low, X reduces to A1 AND A2.
    check_b1n_low_and_behavior: assert property (
        @(posedge clk)
        ~B1_N |-> (X == (A1 & A2))
    );

    // If X is high, the inputs match one implemented minterm.
    check_x_high_only_on_implemented_minterms: assert property (
        @(posedge clk)
        X |-> ((~A1 & A2 & B1_N) | (A1 & ~A2 & B1_N) | (A1 & A2 & ~B1_N))
    );

    // Any implemented minterm drives X high.
    check_implemented_minterms_drive_high: assert property (
        @(posedge clk)
        ((~A1 & A2 & B1_N) | (A1 & ~A2 & B1_N) | (A1 & A2 & ~B1_N)) |-> X
    );

    // When A1 and A2 are both low, X is low.
    check_both_a_low_forces_x_low: assert property (
        @(posedge clk)
        (~A1 & ~A2) |-> ~X
    );

    // When A1 and A2 are both high, X is the inverse of B1_N.
    check_both_a_high_invert_b1n: assert property (
        @(posedge clk)
        (A1 & A2) |-> (X == ~B1_N)
    );

    // When exactly one of A1 or A2 is high, X follows B1_N.
    check_one_hot_a_inputs_follow_b1n: assert property (
        @(posedge clk)
        (A1 ^ A2) |-> (X == B1_N)
    );

endmodule

rtl:
module adder4(A, B, Cin, S, Cout);

input [3:0] A;
input [3:0] B;
input Cin;
output [3:0] S;
output Cout;

wire [3:0] carry;
wire [3:0] sum;


// First full adder (least significant bit)
full_adder fa0(A[0], B[0], Cin, sum[0], carry[0]);

// Second full adder
full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);

// Third full adder
full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);

// Fourth full adder (most significant bit)
full_adder fa3(A[3], B[3], carry[2], sum[3], Cout);

// Output the sum
assign S = sum;

endmodule

// Full adder module
module full_adder(a, b, cin, s, cout);

input a;
input b;
input cin;
output s;
output cout;

// Implement the full adder logic
assign s = a ^ b ^ cin;
assign cout = (a & b) | (cin & (a ^ b));

endmodule

sva:
module adder4_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] S,
    input logic       Cout
);

    function automatic logic fa_carry (
        input logic a,
        input logic b,
        input logic cin
    );
        fa_carry = (a & b) | (cin & (a ^ b));
    endfunction

    // The 5-bit result matches A + B + Cin.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Sum bit 0 matches the first full adder equation.
    check_sum_bit0: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Sum bit 1 uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ fa_carry(A[0], B[0], Cin))
    );

    // Sum bit 2 uses the carry generated by bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ fa_carry(A[1], B[1], fa_carry(A[0], B[0], Cin)))
    );

    // Sum bit 3 uses the carry generated by bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], Cin))))
    );

    // Cout matches the final ripple carry equation.
    check_cout: assert property (
        @(posedge clk) Cout == fa_carry(A[3], B[3], fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], Cin))))
    );

endmodule

rtl:
module oh_dsync  #(parameter PS    = 2,        parameter DELAY = 0         )
   (
    input  clk, input  nreset, input  din, output dout    );

`ifdef CFG_ASIC
   asic_dsync asic_dsync (.clk(clk),
			  .nreset(nreset),
			  .din(din),
			  .dout(dout));
`else
   reg [PS:0] sync_pipe; 
   always @ (posedge clk or negedge nreset)		 
     if(!nreset)
       sync_pipe[PS:0] <= 'b0;
     else
       sync_pipe[PS:0] <= {sync_pipe[PS-1:0],din};	      	      
   assign dout = (DELAY & sync_pipe[PS]) |  (~DELAY & sync_pipe[PS-1]); `endif endmodule

sva:
module oh_dsync_sva #(
    parameter int PS = 2,
    parameter int DELAY = 0
) (
    input logic clk,
    input logic nreset,
    input logic din,
    input logic dout
);

`ifndef CFG_ASIC
    localparam int TAP = DELAY[0] ? (PS + 1) : PS;

    // Reset drives the output low.
    check_reset_clears_output: assert property (
        @(posedge clk) !nreset |-> (dout == 1'b0)
    );

    // After reset release, the output stays low until the selected tap can fill.
    check_release_holds_output_low: assert property (
        @(posedge clk) disable iff (!nreset)
        $rose(nreset) |-> (dout == 1'b0)[*TAP]
    );

    // A sustained low input propagates to the output after the selected delay.
    check_low_level_propagates: assert property (
        @(posedge clk) disable iff (!nreset)
        ((din == 1'b0)[*TAP]) |=> (dout == 1'b0)
    );

    // A sustained high input propagates to the output after the selected delay.
    check_high_level_propagates: assert property (
        @(posedge clk) disable iff (!nreset)
        ((din == 1'b1)[*TAP]) |=> (dout == 1'b1)
    );

    generate
        if (TAP == 1) begin : gen_tap_eq_1
            // A rising input reaches a high output one clock later.
            check_rise_propagates_tap1: assert property (
                @(posedge clk) disable iff (!nreset)
                $rose(din) |=> (dout == 1'b1)
            );

            // A falling input reaches a low output one clock later.
            check_fall_propagates_tap1: assert property (
                @(posedge clk) disable iff (!nreset)
                $fell(din) |=> (dout == 1'b0)
            );
        end else begin : gen_tap_gt_1
            // A rising input held high long enough propagates to the output.
            check_rise_propagates_tapn: assert property (
                @(posedge clk) disable iff (!nreset)
                ($rose(din) ##1 (din == 1'b1)[*(TAP-1)]) |=> (dout == 1'b1)
            );

            // A falling input held low long enough propagates to the output.
            check_fall_propagates_tapn: assert property (
                @(posedge clk) disable iff (!nreset)
                ($fell(din) ##1 (din == 1'b0)[*(TAP-1)]) |=> (dout == 1'b0)
            );
        end
    endgenerate
`endif

endmodule

rtl:
module counter
(
input  wire clk,
input  wire rst,
output wire [3:0] count
);

reg [3:0] counter_reg;

always @(posedge clk or posedge rst)
    if (rst)
        counter_reg <= 4'b0000;
    else
        counter_reg <= counter_reg + 1;

assign count = counter_reg;

endmodule

sva:
module counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count
);

    // When reset is sampled high, count must be zero.
    reset_holds_count_zero: assert property (
        @(posedge clk)
        rst |-> (count == 4'b0000)
    );

    // A sampled reset keeps count at zero on the next sampled cycle.
    reset_keeps_next_count_zero: assert property (
        @(posedge clk)
        rst |=> (count == 4'b0000)
    );

    // Between sampled clocks, count can only increment or be cleared by async reset.
    count_next_is_zero_or_incremented: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> ((count == 4'b0000) || (count == ($past(count) + 4'd1)))
    );

    // A sampled max count must wrap to zero on the next sampled active cycle.
    count_wraps_after_max: assert property (
        @(posedge clk) disable iff (rst)
        (count == 4'hF) |=> (count == 4'h0)
    );

endmodule

rtl:
module comparator (
    A,
    B,
    EQ
);

    input [1:0] A;
    input [1:0] B;
    output reg EQ;

    always @(*) begin
        if (A == B) begin
            EQ = 1;
        end else begin
            EQ = 0;
        end
    end

endmodule

sva:
module comparator_sva (
    input logic       clk,
    input logic [1:0] A,
    input logic [1:0] B,
    input logic       EQ
);

    // EQ must be high when A and B are equal.
    check_eq_high_when_equal: assert property (
        @(posedge clk) (A == B) |-> (EQ == 1'b1)
    );

    // EQ must be low when A and B are different.
    check_eq_low_when_different: assert property (
        @(posedge clk) (A != B) |-> (EQ == 1'b0)
    );

    // A high EQ must only occur for equal inputs.
    check_eq_high_implies_equal: assert property (
        @(posedge clk) (EQ == 1'b1) |-> (A == B)
    );

    // A low EQ must only occur for different inputs.
    check_eq_low_implies_different: assert property (
        @(posedge clk) (EQ == 1'b0) |-> (A != B)
    );

