rtl:
module dna_sequencer #(
  parameter [95:0] SIM_DNA_VALUE = 96'h000000000000000000000000
)(
  output DOUT,

  input CLK,
  input DIN,
  input READ,
  input SHIFT
);

   localparam MAX_DNA_BITS = 96;
   localparam MSB_DNA_BITS = MAX_DNA_BITS - 1;

   reg [MSB_DNA_BITS:0] dna_val = SIM_DNA_VALUE;
   reg dout_out;

   always @(posedge CLK) begin
      if(READ == 1'b1) begin
         dna_val = SIM_DNA_VALUE;
	 dout_out = SIM_DNA_VALUE[0];
      end // READ == 1'b1
      else if(READ == 1'b0)
        if(SHIFT == 1'b1) begin
	   dna_val = {DIN, dna_val[MSB_DNA_BITS : 1]};
	   dout_out = dna_val[0];
        end  // SHIFT == 1'b1
   end // always @ (posedge CLK)

   assign DOUT = dout_out;

endmodule

sva:
module dna_sequencer_sva #(
    parameter [95:0] SIM_DNA_VALUE = 96'h000000000000000000000000
) (
    input logic DOUT,
    input logic CLK,
    input logic DIN,
    input logic READ,
    input logic SHIFT
);

    localparam integer MAX_DNA_BITS  = 96;
    localparam integer SHIFT_PIPELINE = MAX_DNA_BITS + 1;

    genvar i;

    // READ loads SIM_DNA_VALUE and drives its LSB on DOUT.
    check_read_loads_lsb: assert property (
        @(posedge CLK) READ |=> (DOUT == SIM_DNA_VALUE[0])
    );

    // READ takes priority over SHIFT when both are high.
    check_read_priority_over_shift: assert property (
        @(posedge CLK) (READ && SHIFT) |=> (DOUT == SIM_DNA_VALUE[0])
    );

    // With neither READ nor SHIFT, DOUT holds its value.
    check_idle_holds_dout: assert property (
        @(posedge CLK) (!READ && !SHIFT) |=> $stable(DOUT)
    );

    generate
        for (i = 0; i < MAX_DNA_BITS; i = i + 1) begin : gen_shifted_sim_bit_checks
            localparam integer SHIFT_COUNT = i + 1;
            // After READ and SHIFT_COUNT SHIFT cycles, DOUT presents SIM_DNA_VALUE[SHIFT_COUNT-1].
            check_shifted_sim_bit: assert property (
                @(posedge CLK) READ ##1 ((!READ && SHIFT)[*SHIFT_COUNT]) |=> (DOUT == SIM_DNA_VALUE[i])
            );
        end
    endgenerate

    // After 97 consecutive SHIFT cycles without READ, DOUT is DIN delayed through the shift path.
    check_shift_pipeline_delay: assert property (
        @(posedge CLK) ((!READ && SHIFT)[*SHIFT_PIPELINE]) |=> (DOUT == $past(DIN, SHIFT_PIPELINE))
    );

endmodule

rtl:
module bitwise_operations(
  input [7:0] a, b,
  input [2:0] op,
  output reg [7:0] result
);

  always @* begin
    case(op)
      3'b000: result = a & b;
      3'b001: result = a | b;
      3'b010: result = a ^ b;
      3'b011: result = a + b;
      3'b100: result = a - b;
      default: result = 8'b0;
    endcase
  end

endmodule

sva:
module bitwise_operations_sva(
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [2:0] op,
    input logic [7:0] result
);

    // External sampling clock; the RTL is combinational and has no reset.

    // op 000 selects bitwise AND.
    check_and_result: assert property (
        @(posedge clk) (op == 3'b000) |-> (result == (a & b))
    );

    // op 001 selects bitwise OR.
    check_or_result: assert property (
        @(posedge clk) (op == 3'b001) |-> (result == (a | b))
    );

    // op 010 selects bitwise XOR.
    check_xor_result: assert property (
        @(posedge clk) (op == 3'b010) |-> (result == (a ^ b))
    );

    // op 011 selects addition.
    check_add_result: assert property (
        @(posedge clk) (op == 3'b011) |-> (result == (a + b))
    );

    // op 100 selects subtraction.
    check_sub_result: assert property (
        @(posedge clk) (op == 3'b100) |-> (result == (a - b))
    );

    // Unsupported op values drive zero.
    check_default_result: assert property (
        @(posedge clk) ((op == 3'b101) || (op == 3'b110) || (op == 3'b111)) |-> (result == 8'b0)
    );

endmodule

rtl:
module CSADD(clk, rst, x, y, ld, sum);
    input clk, rst;
    input x, y;
    input ld;
    output reg sum;

    reg sc;

    // Half Adders logic
    wire hsum1, hco1;
    assign hsum1 = y ^ sc;
    assign hco1 = y & sc;

    wire hsum2, hco2;
    assign hsum2 = x ^ hsum1;
    assign hco2 = x & hsum1;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            //Reset logic goes here.
            sum <= 1'b0;
            sc <= 1'b0;
        end
        else if (ld) begin
             sum <= 1'b0;
             sc  <= 1'b0;
        end
        else begin
            //Sequential logic goes here.
            sum <= hsum2;
            sc <= hco1 ^ hco2;
        end
    end
endmodule

sva:
module CSADD_sva (
    input logic clk,
    input logic rst,
    input logic x,
    input logic y,
    input logic ld,
    input logic sum,
    input logic sc
);

    // Reset holds sum low.
    check_reset_clears_sum: assert property (
        @(posedge clk) rst |-> (sum == 1'b0)
    );

    // Reset holds the carry state low.
    check_reset_clears_sc: assert property (
        @(posedge clk) rst |-> (sc == 1'b0)
    );

    // ld clears both state registers.
    check_load_clears_state: assert property (
        @(posedge clk) disable iff (rst)
        ld |=> (sum == 1'b0 && sc == 1'b0)
    );

    // A reset or load cycle leaves the sampled state cleared.
    check_state_zero_after_prior_clear: assert property (
        @(posedge clk) disable iff (rst)
        ($past(rst) || $past(ld)) |-> (sum == 1'b0 && sc == 1'b0)
    );

    // On active cycles, sum captures x ^ y ^ sc.
    check_add_updates_sum: assert property (
        @(posedge clk) disable iff (rst)
        (!ld) |=> (sum == $past(x ^ y ^ sc))
    );

    // On active cycles, sc captures the RTL carry equation.
    check_add_updates_sc: assert property (
        @(posedge clk) disable iff (rst)
        (!ld) |=> (sc == $past((y & sc) ^ (x & (y ^ sc))))
    );

    // With carry-in 0, the next state is a half-adder result.
    check_zero_carry_reduces_to_half_add: assert property (
        @(posedge clk) disable iff (rst)
        (!ld && (sc == 1'b0)) |=> ({sc, sum} == {$past(x & y), $past(x ^ y)})
    );

    // With carry-in 1, the next state uses XNOR for sum and OR for carry.
    check_one_carry_reduces_to_xnor_or: assert property (
        @(posedge clk) disable iff (rst)
        (!ld && (sc == 1'b1)) |=> ({sc, sum} == {$past(x | y), $past(~(x ^ y))})
    );

endmodule

rtl:
module any_edge_detector (
    input clk,
    input [7:0] in,
    output reg [7:0] anyedge
);

reg [7:0] prev_in;

always @(posedge clk) begin
    // Shift in the current input values
    prev_in <= in;

    // Detect any edge and set corresponding anyedge bit to 1
    anyedge <= (in ^ prev_in) & in;
end

endmodule

sva:
module any_edge_detector_sva (
    input logic clk,
    input logic [7:0] in,
    input logic [7:0] anyedge
);

    // anyedge matches the RTL equation using the two previous input samples.
    check_anyedge_matches_rtl_equation: assert property (
        @(posedge clk)
        (!$initstate && !$past($initstate)) |-> (anyedge == (($past(in) ^ $past(in,2)) & $past(in)))
    );

    // anyedge can only assert bits that were high on the previous cycle.
    check_anyedge_subset_of_prev_input: assert property (
        @(posedge clk)
        (!$initstate && !$past($initstate)) |-> ((anyedge & ~$past(in)) == 8'h00)
    );

    // anyedge bits must have been low two cycles earlier.
    check_anyedge_excludes_older_high_bits: assert property (
        @(posedge clk)
        (!$initstate && !$past($initstate)) |-> ((anyedge & $past(in,2)) == 8'h00)
    );

    // If the input was unchanged across the prior cycle, anyedge must be zero.
    check_unchanged_input_clears_anyedge: assert property (
        @(posedge clk)
        (!$initstate && !$past($initstate) && ($past(in) == $past(in,2))) |-> (anyedge == 8'h00)
    );

    // Falling bits from the prior cycle are not reported in anyedge.
    check_falling_bits_not_reported: assert property (
        @(posedge clk)
        (!$initstate && !$past($initstate)) |-> ((anyedge & ($past(in,2) & ~$past(in))) == 8'h00)
    );

    // Rising bits from the prior cycle are reported in anyedge.
    check_rising_bits_reported: assert property (
        @(posedge clk)
        (!$initstate && !$past($initstate)) |-> ((anyedge & ($past(in) & ~$past(in,2))) == ($past(in) & ~$past(in,2)))
    );

endmodule

