sva:
module my_module_sva (
    input logic clk,
    input logic din,
    input logic reset_n,
    input logic stdsync,
    input logic dout
);

    // During active-low reset, the registered output is low.
    check_reset_clears_dout: assert property (
        @(posedge clk) !reset_n |-> (dout == 1'b0)
    );

    // On the first clock after reset release, the sampled output is still low.
    check_reset_release_cycle_dout_low: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!$initstate && !$past(reset_n)) |-> (dout == 1'b0)
    );

    // Outside reset, dout reflects din from the previous clock edge.
    check_dout_is_one_cycle_delayed_din: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!$initstate && $past(reset_n)) |-> (dout == $past(din))
    );

    // If din is stable across active cycles, dout matches the current din.
    check_stable_din_matches_dout: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!$initstate && $past(reset_n) && (din == $past(din))) |-> (dout == din)
    );

    // If din toggles across active cycles, dout still shows the prior value.
    check_input_toggle_shows_pipeline_delay: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!$initstate && $past(reset_n) && (din != $past(din))) |-> (dout != din)
    );

endmodule

rtl:
module pipestage
  #(parameter TAGWIDTH = 1)
   (input clk,
    input reset,
    input stb_in,
    input stb_out,
    output reg valid,
    input [TAGWIDTH-1:0] tag_in,
    output reg [TAGWIDTH-1:0] tag_out);

   always @(posedge clk)
     if(reset)
       begin
	  valid <= 0;
	  tag_out <= 0;
       end
     else if(stb_in)
       begin
	  valid <= 1;
	  tag_out <= tag_in;
       end
     else if(stb_out)
       begin
	  valid <= 0;
	  tag_out <= 0;
       end

endmodule

sva:
module pipestage_sva
  #(parameter TAGWIDTH = 1)
   (input logic clk,
    input logic reset,
    input logic stb_in,
    input logic stb_out,
    input logic valid,
    input logic [TAGWIDTH-1:0] tag_in,
    input logic [TAGWIDTH-1:0] tag_out);

    // Reset clears valid.
    check_reset_clears_valid: assert property (
        @(posedge clk) reset |=> (valid == 1'b0)
    );

    // Reset clears tag_out.
    check_reset_clears_tag: assert property (
        @(posedge clk) reset |=> (tag_out == '0)
    );

    // stb_in sets valid on the next cycle.
    check_load_sets_valid: assert property (
        @(posedge clk) disable iff (reset) stb_in |=> (valid == 1'b1)
    );

    // stb_in captures tag_in on the next cycle.
    check_load_captures_tag: assert property (
        @(posedge clk) disable iff (reset) stb_in |=> (tag_out == $past(tag_in))
    );

    // stb_out clears valid when no load is requested.
    check_clear_clears_valid: assert property (
        @(posedge clk) disable iff (reset) (!stb_in && stb_out) |=> (valid == 1'b0)
    );

    // stb_out clears tag_out when no load is requested.
    check_clear_clears_tag: assert property (
        @(posedge clk) disable iff (reset) (!stb_in && stb_out) |=> (tag_out == '0)
    );

    // With no strobes, valid holds its value.
    check_idle_holds_valid: assert property (
        @(posedge clk) disable iff (reset) (!stb_in && !stb_out) |=> $stable(valid)
    );

    // With no strobes, tag_out holds its value.
    check_idle_holds_tag: assert property (
        @(posedge clk) disable iff (reset) (!stb_in && !stb_out) |=> $stable(tag_out)
    );

    // stb_in has priority over stb_out for valid.
    check_stb_in_priority_valid: assert property (
        @(posedge clk) disable iff (reset) (stb_in && stb_out) |=> (valid == 1'b1)
    );

    // stb_in has priority over stb_out for tag capture.
    check_stb_in_priority_tag: assert property (
        @(posedge clk) disable iff (reset) (stb_in && stb_out) |=> (tag_out == $past(tag_in))
    );

endmodule

rtl:
module calculator (
    input signed [7:0] A,
    input signed [7:0] B,
    input [1:0] Op,
    output reg signed [7:0] C
);

always @(*) begin
    case (Op)
        2'b00: C = A + B;
        2'b01: C = A - B;
        2'b10: C = A * B;
        2'b11: C = A / B;
    endcase
end

endmodule

sva:
module calculator_sva (
    input logic signed [7:0] A,
    input logic signed [7:0] B,
    input logic [1:0] Op,
    input logic signed [7:0] C
);
    typedef logic signed [7:0] s8_t;

    // No RTL clock or reset; sample combinational behavior on the global formal clock.

    // Op 00 selects signed addition.
    check_add_operation: assert property (
        @($global_clock)
        (Op == 2'b00) |-> (C == s8_t'(A + B))
    );

    // Op 01 selects signed subtraction.
    check_sub_operation: assert property (
        @($global_clock)
        (Op == 2'b01) |-> (C == s8_t'(A - B))
    );

    // Op 10 selects signed multiplication with 8-bit truncation.
    check_mul_operation: assert property (
        @($global_clock)
        (Op == 2'b10) |-> (C == s8_t'(A * B))
    );

    // Op 11 selects signed division when the divisor is nonzero.
    check_div_operation_nonzero_divisor: assert property (
        @($global_clock)
        ((Op == 2'b11) && (B != 8'sd0)) |-> (C == s8_t'(A / B))
    );

endmodule

rtl:
module gray_converter(bin_in, gray_out);
input [3:0] bin_in;
output [3:0] gray_out;

assign gray_out[3] = bin_in[3];
assign gray_out[2] = bin_in[3] ^ bin_in[2];
assign gray_out[1] = bin_in[2] ^ bin_in[1];
assign gray_out[0] = bin_in[1] ^ bin_in[0];

endmodule

sva:
module gray_converter_sva (
    input logic        clk,
    input logic [3:0]  bin_in,
    input logic [3:0]  gray_out
);

    // Gray MSB matches binary MSB.
    check_gray_bit3_passthrough: assert property (
        @(posedge clk) gray_out[3] === bin_in[3]
    );

    // Gray bit 2 is bin_in[3] XOR bin_in[2].
    check_gray_bit2_xor: assert property (
        @(posedge clk) gray_out[2] === (bin_in[3] ^ bin_in[2])
    );

    // Gray bit 1 is bin_in[2] XOR bin_in[1].
    check_gray_bit1_xor: assert property (
        @(posedge clk) gray_out[1] === (bin_in[2] ^ bin_in[1])
    );

    // Gray bit 0 is bin_in[1] XOR bin_in[0].
    check_gray_bit0_xor: assert property (
        @(posedge clk) gray_out[0] === (bin_in[1] ^ bin_in[0])
    );

endmodule

