module alt_vipitc131_common_sync
    #(parameter
        CLOCKS_ARE_SAME = 0,
        WIDTH = 1)
    (
    input wire rst,
    input wire sync_clock,

    input wire [WIDTH-1:0] data_in,
    output wire [WIDTH-1:0] data_out);

 reg [WIDTH-1:0] data_out_sync0;
 reg [WIDTH-1:0] data_out_sync1;

generate
    if(CLOCKS_ARE_SAME) 
        assign data_out = data_in;
    else begin
        always @ (posedge rst or posedge sync_clock) begin
            if(rst) begin
                data_out_sync0 <= {WIDTH{1'b0}};
                data_out_sync1 <= {WIDTH{1'b0}};
            end else begin
                data_out_sync0 <= data_in;
                data_out_sync1 <= data_out_sync0;
            end
        end

        assign data_out = data_out_sync1;
    end
endgenerate

endmodule

sva:
module alt_vipitc131_common_sync_sva
#(
    parameter CLOCKS_ARE_SAME = 0,
    parameter WIDTH = 1
)
(
    input logic rst,
    input logic sync_clock,
    input logic [WIDTH-1:0] data_in,
    input logic [WIDTH-1:0] data_out
);

generate
    if (CLOCKS_ARE_SAME) begin : gen_same_clock

        // In passthrough mode, output matches input when reset is low.
        check_passthrough_data: assert property (
            @(posedge sync_clock) disable iff (rst)
                (data_out == data_in)
        );

        // In passthrough mode, output still matches input during reset.
        check_passthrough_data_in_reset: assert property (
            @(posedge sync_clock)
                rst |-> (data_out == data_in)
        );

    end else begin : gen_synchronizer

        // A sampled reset keeps the output at zero for the next two clocks.
        check_reset_flushes_pipeline: assert property (
            @(posedge sync_clock)
                rst |=> ((data_out == {WIDTH{1'b0}}) ##1 (data_out == {WIDTH{1'b0}}))
        );

        property p_two_cycle_sync_delay;
            logic [WIDTH-1:0] sampled_data;
            @(posedge sync_clock) disable iff (rst)
                (1'b1, sampled_data = data_in) |-> ##2 (data_out == sampled_data);
        endproperty

        // Without reset, output is the input delayed by two sync_clock edges.
        check_two_cycle_sync_delay: assert property (p_two_cycle_sync_delay);

    end
endgenerate

endmodule

rtl:
module mux4to1(
    input [3:0] A0,
    input [3:0] A1,
    input [3:0] A2,
    input [3:0] A3,
    input S0,
    input S1,
    input VPWR,
    input VGND,
    output reg Y
);

    always @ (S1 or S0 or A0 or A1 or A2 or A3) begin
        case ({S1, S0})
            2'b00: Y <= A0;
            2'b01: Y <= A1;
            2'b10: Y <= A2;
            2'b11: Y <= A3;
        endcase
    end

endmodule

sva:
module mux4to1_sva (
    input logic clk,
    input logic [3:0] A0,
    input logic [3:0] A1,
    input logic [3:0] A2,
    input logic [3:0] A3,
    input logic S0,
    input logic S1,
    input logic VPWR,
    input logic VGND,
    input logic Y
);

    // Y matches A0[0] when select is 00.
    check_select_00: assert property (
        @(posedge clk) ((S1 == 1'b0) && (S0 == 1'b0)) |-> (Y === A0[0])
    );

    // Y matches A1[0] when select is 01.
    check_select_01: assert property (
        @(posedge clk) ((S1 == 1'b0) && (S0 == 1'b1)) |-> (Y === A1[0])
    );

    // Y matches A2[0] when select is 10.
    check_select_10: assert property (
        @(posedge clk) ((S1 == 1'b1) && (S0 == 1'b0)) |-> (Y === A2[0])
    );

    // Y matches A3[0] when select is 11.
    check_select_11: assert property (
        @(posedge clk) ((S1 == 1'b1) && (S0 == 1'b1)) |-> (Y === A3[0])
    );

    // With select held at 00 and A0[0] stable, Y stays stable.
    check_stable_select_00: assert property (
        @(posedge clk)
        !$initstate &&
        (S1 == 1'b0) && (S0 == 1'b0) &&
        $stable({S1, S0, A0[0]})
        |-> $stable(Y)
    );

    // With select held at 01 and A1[0] stable, Y stays stable.
    check_stable_select_01: assert property (
        @(posedge clk)
        !$initstate &&
        (S1 == 1'b0) && (S0 == 1'b1) &&
        $stable({S1, S0, A1[0]})
        |-> $stable(Y)
    );

    // With select held at 10 and A2[0] stable, Y stays stable.
    check_stable_select_10: assert property (
        @(posedge clk)
        !$initstate &&
        (S1 == 1'b1) && (S0 == 1'b0) &&
        $stable({S1, S0, A2[0]})
        |-> $stable(Y)
    );

    // With select held at 11 and A3[0] stable, Y stays stable.
    check_stable_select_11: assert property (
        @(posedge clk)
        !$initstate &&
        (S1 == 1'b1) && (S0 == 1'b1) &&
        $stable({S1, S0, A3[0]})
        |-> $stable(Y)
    );

endmodule

rtl:
module calculator(
    input clk,
    input rst,
    input clear,
    input [1:0] op,
    input [7:0] num1,
    input [7:0] num2,
    output [7:0] result
);

reg [7:0] temp_result;

always @ (posedge clk) begin
    if (rst) begin
        temp_result <= 0;
    end else if (clear) begin
        temp_result <= 0;
    end else begin
        case (op)
            2'b00: temp_result <= num1 + num2;
            2'b01: temp_result <= num1 - num2;
            2'b10: temp_result <= num1 * num2;
            2'b11: temp_result <= num1 / num2;
        endcase
    end
end

assign result = temp_result;

endmodule

