module EX_stage(
    clk, rst, EX_stall, EX_flush, M_stall, EX_regwrite, 
    EX_memtoreg, EX_memread, EX_memwrite, EX_memaddr, 
    EX_load_op, EX_store_op, EX_alu_out, EX_alu_out_t, 
    EX_rt_rd, 

    M_regwrite, M_memtoreg, M_memread,
    M_memwrite, M_memaddr, M_load_op,
    M_store_op, M_alu_out, M_rt_rd);
    input   clk;
    input   rst;
    input   EX_stall;
    input   EX_flush;
    input   M_stall;
    input   EX_regwrite;
    input   EX_memtoreg;
    input   EX_memread;
    input   EX_memwrite;
    input   [31:0]  EX_memaddr;
    input   [8:0]   EX_load_op;
    input   [5:0]   EX_store_op;
    input   [31:0]  EX_alu_out;
    input   [31:0]  EX_alu_out_t;
    input   [4:0]   EX_rt_rd;

    output  reg M_regwrite;
    output  reg M_memtoreg;
    output  reg M_memread;
    output  reg M_memwrite;
    output  reg [31:0]  M_memaddr;
    output  reg [8:0]   M_load_op;
    output  reg [5:0]   M_store_op;
    output  reg [31:0]  M_alu_out;
    output  reg [4:0]   M_rt_rd;

    always @(posedge clk) begin
        M_regwrite  <= rst ? 0     : (M_stall ? M_regwrite : ((EX_stall | EX_flush) ? 0 : EX_regwrite));
        M_memtoreg  <= rst ? 0     : (M_stall ? M_memtoreg : EX_memtoreg);
        M_memwrite  <= rst ? 0     : (M_stall ? M_memwrite : ((EX_stall | EX_flush) ? 0 : EX_memwrite));
        M_memread   <= rst ? 0     : (M_stall ? M_memread  : ((EX_stall | EX_flush) ? 0 : EX_memread));
        M_memaddr   <= rst ? 0     : (M_stall ? M_memaddr  : ((EX_stall | EX_flush) ? 0 : EX_memaddr));
        M_load_op   <= rst ? 9'b0  : (M_stall ? M_load_op  : EX_load_op);
        M_store_op  <= rst ? 6'b0  : (M_stall ? M_store_op : EX_store_op);
        M_alu_out   <= rst ? 32'b0 : (M_stall ? M_alu_out  : EX_alu_out);
        M_rt_rd     <= rst ? 5'b0  : (M_stall ? M_rt_rd    : EX_rt_rd);
    end

endmodule

module fifo_read_counter(
    out,
    O1,
    sel,
    rd_clk,
    Q
);

    output [11:0] out;
    output [11:0] O1;
    input sel;
    input rd_clk;
    input Q;

    reg [11:0] out;
    reg [11:0] O1;

    always @(posedge rd_clk) begin
        if(Q) begin
            out <= 12'h0;
            O1 <= 12'h0;
        end else if(sel) begin
            out <= out + 1;
            O1 <= out;
        end
    end

endmodule

sva:
module fifo_read_counter_sva (
    input logic [11:0] out,
    input logic [11:0] O1,
    input logic sel,
    input logic rd_clk,
    input logic Q
);

    // Q clears both registers on the next sampled cycle.
    check_sync_clear: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        Q |=> (out == 12'h000 && O1 == 12'h000)
    );

    // Q has priority over sel when both are high.
    check_clear_priority_over_sel: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (Q && sel) |=> (out == 12'h000 && O1 == 12'h000)
    );

    // sel increments out when Q is low.
    check_out_increments_on_sel: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (!Q && sel) |=> (out == ($past(out) + 12'd1))
    );

    // sel loads O1 with the previous out value when Q is low.
    check_o1_captures_previous_out: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (!Q && sel) |=> (O1 == $past(out))
    );

    // With Q low and sel low, both registers hold their values.
    check_hold_when_idle: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (!Q && !sel) |=> (out == $past(out) && O1 == $past(O1))
    );

    // After a sel update, out is exactly one count ahead of O1.
    check_sel_creates_expected_offset: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (!Q && sel) |=> (out == (O1 + 12'd1))
    );

endmodule

rtl:
module shift_register (
  input clk, load, shift,
  input [3:0] data_in,
  output [3:0] data_out
);

reg [3:0] shift_reg;

always @(posedge clk) begin
  if (load) begin
    shift_reg <= data_in;
  end else if (shift) begin
    shift_reg <= {shift_reg[2:0], 1'b0};
  end
end

assign data_out = shift_reg;

endmodule

sva:
module shift_register_sva (
    input logic       clk,
    input logic       load,
    input logic       shift,
    input logic [3:0] data_in,
    input logic [3:0] data_out
);

    // Load captures data_in when shift is low.
    check_load_without_shift: assert property (
        @(posedge clk) disable iff ($initstate)
        (load && !shift) |=> (data_out == $past(data_in))
    );

    // Shift lefts the register and inserts 0 when load is low.
    check_shift_updates_output: assert property (
        @(posedge clk) disable iff ($initstate)
        (!load && shift) |=> (data_out == {$past(data_out[2:0]), 1'b0})
    );

    // Idle cycles hold the previous register value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff ($initstate)
        (!load && !shift) |=> (data_out == $past(data_out))
    );

    // Load has priority over shift when both are asserted.
    check_load_priority_over_shift: assert property (
        @(posedge clk) disable iff ($initstate)
        (load && shift) |=> (data_out == $past(data_in))
    );

    // A shift operation always clears the LSB.
    check_shift_clears_lsb: assert property (
        @(posedge clk) disable iff ($initstate)
        (!load && shift) |=> (data_out[0] == 1'b0)
    );

    // A shift operation moves the lower bits into the upper positions.
    check_shift_moves_upper_bits: assert property (
        @(posedge clk) disable iff ($initstate)
        (!load && shift) |=> (data_out[3:1] == $past(data_out[2:0]))
    );

endmodule

rtl:
module inv_lsb(
    input [1:0] data,
    output reg q
);

    always @(*) begin
        q = ~data[0];
    end

endmodule

sva:
module inv_lsb_sva (
    input logic [1:0] data,
    input logic q
);

    // q always equals the inverted least significant input bit.
    check_q_matches_inverted_lsb: assert property (
        @($global_clock) q === ~data[0]
    );

    // q is high when the least significant input bit is low.
    check_q_high_when_lsb_low: assert property (
        @($global_clock) (data[0] === 1'b0) |-> (q === 1'b1)
    );

    // q is low when the least significant input bit is high.
    check_q_low_when_lsb_high: assert property (
        @($global_clock) (data[0] === 1'b1) |-> (q === 1'b0)
    );

    // A rising least significant input bit makes q fall.
    check_q_falls_when_lsb_rises: assert property (
        @($global_clock) $rose(data[0]) |-> $fell(q)
    );

    // A falling least significant input bit makes q rise.
    check_q_rises_when_lsb_falls: assert property (
        @($global_clock) $fell(data[0]) |-> $rose(q)
    );

    // q only changes when the least significant input bit changes.
    check_q_changes_only_with_lsb: assert property (
        @($global_clock) $changed(q) |-> $changed(data[0])
    );

    // Changing only the most significant input bit does not affect q.
    check_msb_has_no_effect_on_q: assert property (
        @($global_clock) ($changed(data[1]) && $stable(data[0])) |-> $stable(q)
    );

endmodule

rtl:
module Problem1(
    input A,
    input B,
    input C,
    input D,
    output reg X,
    output reg Y
    );
    always @ (A or B or C or D)
        begin
            if (!((A & C) ^ (B & D)) == 1) X = 1;
            else if ((~C) & (B | D) & C ^ !( B & D) == 1)
                X = 1;
            else
                X = 0;

            if ( !(A & ~C) == 1 )  Y = 1;
            else if ((D & (A ^ B) & C)  == 1)
                Y = 1;
            else if ((D & (~B | A)) == 1)
                Y = 1;
            else
                Y = 0;
        end
endmodule

sva:
module Problem1_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic X,
    input logic Y
);

    // X must be high whenever A and C are both high.
    check_x_ac_high: assert property (
        @($global_clock)
        ((A & C) == 1'b1) |-> (X == 1'b1)
    );

    // X must be high whenever B and D are not both high.
    check_x_bd_not_both_high: assert property (
        @($global_clock)
        ((B & D) == 1'b0) |-> (X == 1'b1)
    );

    // X is low only when B and D are high and A and C are not both high.
    check_x_only_low_case: assert property (
        @($global_clock)
        (((A & C) == 1'b0) && ((B & D) == 1'b1)) |-> (X == 1'b0)
    );

    // Y must be high whenever A and ~C are not both high.
    check_y_primary_case: assert property (
        @($global_clock)
        ((A & (~C)) == 1'b0) |-> (Y == 1'b1)
    );

    // Y must be high in the remaining case when D is high.
    check_y_remaining_case_d_high: assert property (
        @($global_clock)
        (((A & (~C)) == 1'b1) && (D == 1'b1)) |-> (Y == 1'b1)
    );

    // Y is low only when A is high, C is low, and D is low.
    check_y_only_low_case: assert property (
        @($global_clock)
        (((A & (~C)) == 1'b1) && (D == 1'b0)) |-> (Y == 1'b0)
    );

endmodule

rtl:
module adder_subtractor (
    input [7:0] A,
    input [7:0] B,
    input CIN,
    input SUB,
    output reg [7:0] SUM,
    output reg OVF
);

    reg [8:0] temp_sum;
    reg [7:0] temp_a;
    reg [7:0] temp_b;

    always @(*) begin
        if (SUB == 1'b1) begin
            temp_a = A;
            temp_b = ~B + 1;
        end
        else begin
            temp_a = A;
            temp_b = B;
        end

        if (CIN == 1'b1) begin
            temp_sum = {1'b1, temp_a} + {1'b1, temp_b};
        end
        else begin
            temp_sum = temp_a + temp_b;
        end

        if (temp_sum[8] == 1'b1) begin
            OVF = 1'b1;
        end
        else begin
            OVF = 1'b0;
        end

        SUM = temp_sum[7:0];
    end

endmodule

sva:
module adder_subtractor_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic CIN,
    input logic SUB,
    input logic [7:0] SUM,
    input logic OVF
);

    // In add mode, SUM is the low 8 bits of A plus B.
    check_add_mode_sum: assert property (
        @(posedge clk)
        (!SUB) |-> (SUM == (A + B))
    );

    // In subtract mode, SUM is the low 8 bits of A plus two's-complement B.
    check_sub_mode_sum: assert property (
        @(posedge clk)
        (SUB) |-> (SUM == (A + (~B + 8'h01)))
    );

    // OVF is never asserted when CIN is low.
    check_no_ovf_without_cin: assert property (
        @(posedge clk)
        (!CIN) |-> (OVF == 1'b0)
    );

    // With CIN high in add mode, outputs match the 9-bit sum of A and B.
    check_add_with_cin: assert property (
        @(posedge clk)
        (!SUB && CIN) |-> ({OVF, SUM} == ({1'b0, A} + {1'b0, B}))
    );

    // With CIN high in subtract mode, outputs match the 9-bit sum of A and two's-complement B.
    check_sub_with_cin: assert property (
        @(posedge clk)
        (SUB && CIN) |-> ({OVF, SUM} == ({1'b0, A} + {1'b0, (~B + 8'h01)}))
    );

endmodule

rtl:
module ctr_fsm(clk, ar, start, stop, ctr_en, ctr_ar);

  parameter [1:0] IDLE=2'b00, PRERUN=2'b01, RUN=2'b10, STOPPED=2'b11;

  parameter start_assert = 1'b1; parameter stop_assert = 1'b0; 
  input clk, ar, start, stop;
  output ctr_en, ctr_ar;


  reg [1:0] state;


  assign ctr_en = (state==RUN); assign ctr_ar = ~(state==PRERUN|state==IDLE); 
  always @ (posedge clk or negedge ar)
  begin
    if(~ar)
    begin
      state <= IDLE; end else
    begin
      case(state)
        IDLE:begin
          if(start==start_assert) begin
            state<=PRERUN;
          end else
          begin
            state<=IDLE;
          end
        end
        PRERUN:begin
          if(stop==stop_assert)
          begin
            state<=STOPPED; end else
          begin
            state<=RUN; end
        end
        RUN:begin if(stop==stop_assert) begin
            state<=STOPPED;
          end
			 else begin
            state<=RUN;
          end
        end
		  default:begin if(start==~start_assert) begin
            state<=IDLE;
          end else
          begin
            state<=STOPPED; end
        end
      endcase
    end
  end

  endmodule

sva:
module ctr_fsm_sva (
    input logic       clk,
    input logic       ar,
    input logic       start,
    input logic       stop,
    input logic       ctr_en,
    input logic       ctr_ar,
    input logic [1:0] state
);

    localparam [1:0] IDLE    = 2'b00;
    localparam [1:0] PRERUN  = 2'b01;
    localparam [1:0] RUN     = 2'b10;
    localparam [1:0] STOPPED = 2'b11;

    localparam start_assert = 1'b1;
    localparam stop_assert  = 1'b0;

    // Active-low reset forces IDLE and idle outputs.
    check_reset_to_idle: assert property (
        @(posedge clk) !ar |-> (state == IDLE) && (ctr_en == 1'b0) && (ctr_ar == 1'b0)
    );

    // ctr_en is high only in RUN.
    check_ctr_en_decode: assert property (
        @(posedge clk) disable iff (!ar) ctr_en == (state == RUN)
    );

    // ctr_ar is low only in IDLE and PRERUN.
    check_ctr_ar_decode: assert property (
        @(posedge clk) disable iff (!ar) ctr_ar == ~((state == PRERUN) || (state == IDLE))
    );

    // IDLE moves to PRERUN when start is asserted.
    check_idle_to_prerun_on_start: assert property (
        @(posedge clk) disable iff (!ar) (state == IDLE && start == start_assert) |=> (state == PRERUN)
    );

    // IDLE stays in IDLE when start is not asserted.
    check_idle_stays_idle_without_start: assert property (
        @(posedge clk) disable iff (!ar) (state == IDLE && start != start_assert) |=> (state == IDLE)
    );

    // PRERUN moves to STOPPED when stop is asserted.
    check_prerun_to_stopped_on_stop: assert property (
        @(posedge clk) disable iff (!ar) (state == PRERUN && stop == stop_assert) |=> (state == STOPPED)
    );

    // PRERUN moves to RUN when stop is not asserted.
    check_prerun_to_run_without_stop: assert property (
        @(posedge clk) disable iff (!ar) (state == PRERUN && stop != stop_assert) |=> (state == RUN)
    );

    // RUN moves to STOPPED when stop is asserted.
    check_run_to_stopped_on_stop: assert property (
        @(posedge clk) disable iff (!ar) (state == RUN && stop == stop_assert) |=> (state == STOPPED)
    );

    // RUN stays in RUN when stop is not asserted.
    check_run_stays_run_without_stop: assert property (
        @(posedge clk) disable iff (!ar) (state == RUN && stop != stop_assert) |=> (state == RUN)
    );

    // STOPPED returns to IDLE when start is deasserted.
    check_stopped_to_idle_on_start_deassert: assert property (
        @(posedge clk) disable iff (!ar) (state == STOPPED && start != start_assert) |=> (state == IDLE)
    );

    // STOPPED stays in STOPPED while start is asserted.
    check_stopped_stays_stopped_on_start_assert: assert property (
        @(posedge clk) disable iff (!ar) (state == STOPPED && start == start_assert) |=> (state == STOPPED)
    );

endmodule

rtl:
module bitwise_or (
    input [2:0] a,
    input [2:0] b,
    output [2:0] result
);
    assign result = a | b;
endmodule

module logical_or (
    input [2:0] a,
    input [2:0] b,
    output result
);
    assign result = (a != 0) || (b != 0);
endmodule

module accumulator (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid,
    output reg [7:0] data_out
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 8'b0;
        end else if (valid) begin
            data_out <= data_out + data_in;
        end
    end
endmodule

module combiner (
    input [7:0] acc_data,
    input [2:0] bitwise_data,
    input logical_data,
    output [9:0] data_out
);
    assign data_out = {acc_data, bitwise_data, logical_data};
endmodule

module top_module (
    input clk,
    input rst_n,
    input [2:0] a,
    input [2:0] b,
    input [7:0] data_in,
    input valid_a,
    input ready_b,

    output ready_a,
    output reg valid_b,
    output reg [9:0] data_out
);
    wire [2:0] bitwise_result;
    wire logical_result;
    reg [7:0] acc_data;

    bitwise_or or1 (
        .a(a),
        .b(b),
        .result(bitwise_result)
    );

    logical_or or2 (
        .a(a),
        .b(b),
        .result(logical_result)
    );

    accumulator acc (
        .clk(clk),
        .rst_n(rst_n),
        .data_in(data_in),
        .valid(valid_a),
        .data_out(acc_data)
    );

    combiner comb (
        .acc_data(acc_data),
        .bitwise_data(bitwise_result),
        .logical_data(logical_result),
        .data_out(data_out)
    );

    assign ready_a = ready_b;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_b <= 1'b0;
        end else begin
            valid_b <= valid_a;
        end
    end
endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic rst_n,
    input logic [2:0] a,
    input logic [2:0] b,
    input logic [7:0] data_in,
    input logic valid_a,
    input logic ready_b,
    input logic ready_a,
    input logic valid_b,
    input logic [9:0] data_out
);

    // ready_a is a direct pass-through of ready_b.
    check_ready_passthrough: assert property (
        @(posedge clk) disable iff (!rst_n)
        (ready_a == ready_b)
    );

    // valid_b is driven low while reset is asserted.
    check_valid_b_reset_low: assert property (
        @(posedge clk)
        (!rst_n) |-> (valid_b == 1'b0)
    );

    // valid_b goes high one cycle after valid_a is high.
    check_valid_b_sets_after_valid_a: assert property (
        @(posedge clk) disable iff (!rst_n)
        valid_a |=> (valid_b == 1'b1)
    );

    // valid_b goes low one cycle after valid_a is low.
    check_valid_b_clears_after_invalid_a: assert property (
        @(posedge clk) disable iff (!rst_n)
        (!valid_a) |=> (valid_b == 1'b0)
    );

    // data_out[3:1] reflects the bitwise OR of a and b.
    check_data_out_bitwise_or_bits: assert property (
        @(posedge clk) disable iff (!rst_n)
        (data_out[3:1] == (a | b))
    );

    // data_out[0] reflects the logical OR of nonzero a and b.
    check_data_out_logical_or_bit: assert property (
        @(posedge clk) disable iff (!rst_n)
        (data_out[0] == ((a != 3'b000) || (b != 3'b000)))
    );

    // The logical OR bit matches whether the bitwise OR bits are nonzero.
    check_logical_bit_matches_bitwise_nonzero: assert property (
        @(posedge clk) disable iff (!rst_n)
        (data_out[0] == (data_out[3:1] != 3'b000))
    );

    // data_out[9:4] resets to zero with the accumulator.
    check_accumulator_low_bits_reset_zero: assert property (
        @(posedge clk)
        (!rst_n) |-> (data_out[9:4] == 6'b0)
    );

    // data_out[9:4] holds when valid_a is low.
    check_accumulator_low_bits_hold_when_invalid: assert property (
        @(posedge clk) disable iff (!rst_n)
        (!valid_a) |=> (data_out[9:4] == $past(data_out[9:4]))
    );

    // data_out[9:4] adds data_in[5:0] when valid_a is high.
    check_accumulator_low_bits_add_when_valid: assert property (
        @(posedge clk) disable iff (!rst_n)
        valid_a |=> (data_out[9:4] == ($past(data_out[9:4]) + $past(data_in[5:0])))
    );

endmodule

rtl:
module bitwise_xor(busA, busB, busXOR);

input [7:0] busA;
input [7:0] busB;
output [7:0] busXOR;

wire [7:0] temp1, temp2, temp3, temp4;

// XOR operation
assign temp1 = busA ^ busB;

// Invert the inputs
assign temp2 = ~busA;
assign temp3 = ~busB;

// AND operation
assign temp4 = temp2 & temp3;

// Final XOR operation
assign busXOR = temp1 ^ temp4;

endmodule

sva:
module bitwise_xor_sva (
    input logic        clk,
    input logic [7:0]  busA,
    input logic [7:0]  busB,
    input logic [7:0]  busXOR,
    input logic [7:0]  temp1,
    input logic [7:0]  temp2,
    input logic [7:0]  temp3,
    input logic [7:0]  temp4
);

    // temp1 is the bitwise XOR of the two input buses.
    check_temp1_xor: assert property (
        @(posedge clk) temp1 == (busA ^ busB)
    );

    // temp2 is the bitwise inversion of busA.
    check_temp2_invert_busA: assert property (
        @(posedge clk) temp2 == (~busA)
    );

    // temp3 is the bitwise inversion of busB.
    check_temp3_invert_busB: assert property (
        @(posedge clk) temp3 == (~busB)
    );

    // temp4 is the AND of the two inverted buses.
    check_temp4_and_stage: assert property (
        @(posedge clk) temp4 == (temp2 & temp3)
    );

    // temp4 also matches DeMorgan reduction of the inputs.
    check_temp4_demorgan: assert property (
        @(posedge clk) temp4 == (~(busA | busB))
    );

    // busXOR is the XOR of temp1 and temp4.
    check_output_final_xor: assert property (
        @(posedge clk) busXOR == (temp1 ^ temp4)
    );

    // busXOR simplifies to the bitwise NAND of the inputs.
    check_output_nand_function: assert property (
        @(posedge clk) busXOR == (~(busA & busB))
    );

    // Stable inputs keep the combinational output stable.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(busA) && $stable(busB)) |-> $stable(busXOR)
    );

endmodule

