sva:
module top_module_sva (
    input logic clk,
    input logic [2:0] in,
    input logic select,
    input logic and_result,
    input logic or_result,
    input logic xor_result
);

    // and_result is masked low when select is high, else it is the 3-input AND.
    check_and_output_function: assert property (
        @(posedge clk)
        and_result == (select ? 1'b0 : (in[0] & in[1] & in[2]))
    );

    // or_result passes the 3-input OR when select is high, else it is low.
    check_or_output_function: assert property (
        @(posedge clk)
        or_result == (select ? (in[0] | in[1] | in[2]) : 1'b0)
    );

    // xor_result is always the XOR of the raw AND and raw OR results.
    check_xor_output_function: assert property (
        @(posedge clk)
        xor_result == ((in[0] & in[1] & in[2]) ^ (in[0] | in[1] | in[2]))
    );

    // When select is high, AND is blocked and OR is selected.
    check_select_high_routing: assert property (
        @(posedge clk)
        select |-> ((and_result == 1'b0) && (or_result == (in[0] | in[1] | in[2])))
    );

    // When select is low, OR is blocked and AND is selected.
    check_select_low_routing: assert property (
        @(posedge clk)
        !select |-> ((and_result == (in[0] & in[1] & in[2])) && (or_result == 1'b0))
    );

    // All outputs are low when all inputs are low.
    check_all_zero_input_case: assert property (
        @(posedge clk)
        (in == 3'b000) |-> ((and_result == 1'b0) && (or_result == 1'b0) && (xor_result == 1'b0))
    );

    // xor_result is high for any nonzero input pattern that is not all ones.
    check_partial_one_input_xor_high: assert property (
        @(posedge clk)
        ((in != 3'b000) && (in != 3'b111)) |-> (xor_result == 1'b1)
    );

    // xor_result is low when all inputs are high.
    check_all_one_input_xor_low: assert property (
        @(posedge clk)
        (in == 3'b111) |-> (xor_result == 1'b0)
    );

endmodule

rtl:
module traffic_light_controller(
  input reset,
  input clk,
  output reg green,
  output reg yellow,
  output reg red
);

  // Define the state machine states
  parameter green_state = 2'b00;
  parameter yellow_state = 2'b01;
  parameter red_state = 2'b10;

  // Define the state machine signals
  reg [1:0] state;
  reg [5:0] counter;

  // Initialize the state machine
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      state <= green_state;
      counter <= 0;
    end else begin
      case (state)
        green_state: begin
          counter <= counter + 1;
          if (counter == 30) begin
            state <= yellow_state;
            counter <= 0;
          end
        end
        yellow_state: begin
          counter <= counter + 1;
          if (counter == 5) begin
            state <= red_state;
            counter <= 0;
          end
        end
        red_state: begin
          counter <= counter + 1;
          if (counter == 25) begin
            state <= green_state;
            counter <= 0;
          end
        end
      endcase
    end
  end

  // Set the output signals based on the current state
  always @ (state) begin
    case (state)
      green_state: begin
        green <= 1;
        yellow <= 0;
        red <= 0;
      end
      yellow_state: begin
        green <= 0;
        yellow <= 1;
        red <= 0;
      end
      red_state: begin
        green <= 0;
        yellow <= 0;
        red <= 1;
      end
    endcase
  end

endmodule

sva:
module traffic_light_controller_sva (
    input logic reset,
    input logic clk,
    input logic green,
    input logic yellow,
    input logic red,
    input logic [1:0] state,
    input logic [5:0] counter
);

    localparam logic [1:0] GREEN_STATE  = 2'b00;
    localparam logic [1:0] YELLOW_STATE = 2'b01;
    localparam logic [1:0] RED_STATE    = 2'b10;

    // Reset returns the FSM to green with a zero counter.
    check_reset_state: assert property (
        @(posedge clk) reset |=> (state == GREEN_STATE) && (counter == 6'd0)
    );

    // Reset leads to the green output pattern.
    check_reset_outputs: assert property (
        @(posedge clk) reset |=> (green == 1'b1) && (yellow == 1'b0) && (red == 1'b0)
    );

    // Green state increments the counter before the transition point.
    check_green_count_increment: assert property (
        @(posedge clk) disable iff (reset)
        (state == GREEN_STATE && counter < 6'd30) |=> (state == GREEN_STATE) && (counter == ($past(counter) + 6'd1))
    );

    // Green state transitions to yellow when the counter reaches 30.
    check_green_to_yellow_transition: assert property (
        @(posedge clk) disable iff (reset)
        (state == GREEN_STATE && counter == 6'd30) |=> (state == YELLOW_STATE) && (counter == 6'd0)
    );

    // Yellow state increments the counter before the transition point.
    check_yellow_count_increment: assert property (
        @(posedge clk) disable iff (reset)
        (state == YELLOW_STATE && counter < 6'd5) |=> (state == YELLOW_STATE) && (counter == ($past(counter) + 6'd1))
    );

    // Yellow state transitions to red when the counter reaches 5.
    check_yellow_to_red_transition: assert property (
        @(posedge clk) disable iff (reset)
        (state == YELLOW_STATE && counter == 6'd5) |=> (state == RED_STATE) && (counter == 6'd0)
    );

    // Red state increments the counter before the transition point.
    check_red_count_increment: assert property (
        @(posedge clk) disable iff (reset)
        (state == RED_STATE && counter < 6'd25) |=> (state == RED_STATE) && (counter == ($past(counter) + 6'd1))
    );

    // Red state transitions to green when the counter reaches 25.
    check_red_to_green_transition: assert property (
        @(posedge clk) disable iff (reset)
        (state == RED_STATE && counter == 6'd25) |=> (state == GREEN_STATE) && (counter == 6'd0)
    );

    // Green state drives only green high.
    check_green_outputs: assert property (
        @(posedge clk) disable iff (reset)
        (state == GREEN_STATE) |-> (green == 1'b1) && (yellow == 1'b0) && (red == 1'b0)
    );

    // Yellow state drives only yellow high.
    check_yellow_outputs: assert property (
        @(posedge clk) disable iff (reset)
        (state == YELLOW_STATE) |-> (green == 1'b0) && (yellow == 1'b1) && (red == 1'b0)
    );

    // Red state drives only red high.
    check_red_outputs: assert property (
        @(posedge clk) disable iff (reset)
        (state == RED_STATE) |-> (green == 1'b0) && (yellow == 1'b0) && (red == 1'b1)
    );

endmodule

module four_nor_inv_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);

    // Y must equal the 4-input NOR of A, B, C, and D.
    check_y_matches_nor_function: assert property (
        @(posedge clk) Y == ~(A | B | C | D)
    );

    // When all inputs are low, Y must be high.
    check_all_low_drives_y_high: assert property (
        @(posedge clk) (!A && !B && !C && !D) |-> Y
    );

    // When any input is high, Y must be low.
    check_any_high_drives_y_low: assert property (
        @(posedge clk) (A || B || C || D) |-> !Y
    );

    // A high Y implies all inputs are low.
    check_y_high_implies_all_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && !D)
    );

    // A low Y implies at least one input is high.
    check_y_low_implies_some_high: assert property (
        @(posedge clk) !Y |-> (A || B || C || D)
    );

endmodule

