module carry_lookahead_adder_sva (
    input logic        clk,
    input logic [15:0] a,
    input logic [15:0] b,
    input logic [31:0] sum
);

    // Sum matches the RTL carry equations and concatenation add.
    check_sum_matches_rtl: assert property (
        @(posedge clk)
        sum == (
            {28'b0,
             ((a[3] & b[3]) |
              ((a[3] ^ b[3]) & (a[2] & b[2])) |
              ((a[3] ^ b[3]) & (a[2] ^ b[2]) & (a[1] & b[1])) |
              ((a[3] ^ b[3]) & (a[2] ^ b[2]) & (a[1] ^ b[1]) & (a[0] & b[0]))),
             ((a[2] & b[2]) |
              ((a[2] ^ b[2]) & (a[1] & b[1])) |
              ((a[2] ^ b[2]) & (a[1] ^ b[1]) & (a[0] & b[0]))),
             ((a[1] & b[1]) |
              ((a[1] ^ b[1]) & (a[0] & b[0]))),
             (a[0] & b[0])}
            + {a, b}
        )
    );

    // Low 16 bits are b plus the four carry bits.
    check_low_half_matches_rtl: assert property (
        @(posedge clk)
        sum[15:0] == (
            b + {12'b0,
                 ((a[3] & b[3]) |
                  ((a[3] ^ b[3]) & (a[2] & b[2])) |
                  ((a[3] ^ b[3]) & (a[2] ^ b[2]) & (a[1] & b[1])) |
                  ((a[3] ^ b[3]) & (a[2] ^ b[2]) & (a[1] ^ b[1]) & (a[0] & b[0]))),
                 ((a[2] & b[2]) |
                  ((a[2] ^ b[2]) & (a[1] & b[1])) |
                  ((a[2] ^ b[2]) & (a[1] ^ b[1]) & (a[0] & b[0]))),
                 ((a[1] & b[1]) |
                  ((a[1] ^ b[1]) & (a[0] & b[0]))),
                 (a[0] & b[0])}
        )
    );

    // Sum bit 0 follows b[0] plus c[0].
    check_sum_bit0_behavior: assert property (
        @(posedge clk)
        sum[0] == (b[0] & ~a[0])
    );

    // No low-nibble generate means the output is just {a,b}.
    check_no_generate_passthrough: assert property (
        @(posedge clk)
        ((a[3:0] & b[3:0]) == 4'b0000) |-> (sum == {a, b})
    );

    // All low-nibble generates force the adder to add 15.
    check_all_generate_adds_fifteen: assert property (
        @(posedge clk)
        ((a[3:0] & b[3:0]) == 4'b1111) |-> (sum == ({a, b} + 32'd15))
    );

    // With bits [3:1] clear, only c[0] can contribute.
    check_only_bit0_region_can_add: assert property (
        @(posedge clk)
        ((a[3:1] == 3'b000) && (b[3:1] == 3'b000)) |-> (sum == ({a, b} + {31'b0, (a[0] & b[0])}))
    );

    // With bits [3:2] clear and no bit0 generate, only c[1] can contribute.
    check_only_bit1_region_can_add: assert property (
        @(posedge clk)
        ((a[3:2] == 2'b00) && (b[3:2] == 2'b00) && ((a[0] & b[0]) == 1'b0)) |-> (sum == ({a, b} + {30'b0, (a[1] & b[1]), 1'b0}))
    );

endmodule

module sky130_fd_sc_hs__mux2i_sva (
    input logic clk,
    input logic A0,
    input logic A1,
    input logic S,
    input logic VPWR,
    input logic VGND,
    input logic Y
);

    // When select is low, Y follows A0.
    check_select_low_routes_a0: assert property (
        @(posedge clk) disable iff (1'b0)
        (S === 1'b0) |-> (Y === A0)
    );

    // When select is high, Y follows A1.
    check_select_high_routes_a1: assert property (
        @(posedge clk) disable iff (1'b0)
        (S === 1'b1) |-> (Y === A1)
    );

    // With stable A0, A1, and S, Y stays stable.
    check_stable_inputs_hold_output: assert property (
        @(posedge clk) disable iff (1'b0)
        $stable({A0, A1, S}) |-> $stable(Y)
    );

    // While A0 remains selected and unchanged, A1 cannot affect Y.
    check_unselected_a1_is_ignored: assert property (
        @(posedge clk) disable iff (1'b0)
        (S === 1'b0 && $past(S) === 1'b0 && A0 === $past(A0)) |-> (Y === $past(Y))
    );

    // While A1 remains selected and unchanged, A0 cannot affect Y.
    check_unselected_a0_is_ignored: assert property (
        @(posedge clk) disable iff (1'b0)
        (S === 1'b1 && $past(S) === 1'b1 && A1 === $past(A1)) |-> (Y === $past(Y))
    );

endmodule

rtl:
module boolean_ops (
   // Outputs
   logic_out, 
   // Inputs
   rs1_data, rs2_data, isand, isor, isxor, pass_rs2_data, inv_logic, 
   ifu_exu_sethi_inst_e
   );

   input [63:0] rs1_data;             // 1st input operand
   input [63:0] rs2_data;             // 2nd input operand
   input isand;
   input isor;
   input isxor;
   input pass_rs2_data;
   input inv_logic;
   input ifu_exu_sethi_inst_e;       // zero out top half of rs2 on mov

   output [63:0] logic_out;      // output of logic block

   wire [63:0] rs1_data_bf1;                 // buffered rs1_data
   wire [63:0] rs2_data_bf1;                 // buffered rs2_data
   wire [63:0] mov_data;
   wire [63:0] result_and;              // rs1_data & rs2_data
   wire [63:0] result_or;               // rs1_data | rs2_data
   wire [63:0] result_xor;              // rs1_data ^ rs2_data
   wire [63:0] rs2_xor_invert;           // output of mux between various results

   // buffer inputs
   assign rs1_data_bf1 = rs1_data;
   assign rs2_data_bf1 = rs2_data;

   // zero out top of rs2 for sethi_inst
   assign mov_data[63:32] = rs2_data_bf1[63:32] & {32{~ifu_exu_sethi_inst_e}};
   assign mov_data[31:0] = rs2_data_bf1[31:0];

   // invert input2 for andn, orn, xnor
   assign rs2_xor_invert = rs2_data_bf1 ^ {64{inv_logic}};

   // do boolean ops
   assign result_and = rs1_data_bf1 & rs2_xor_invert;
   assign result_or = rs1_data_bf1 | rs2_xor_invert;
   assign result_xor = rs1_data_bf1 ^ rs2_xor_invert;

   // mux between various results
   assign logic_out = (isand) ? result_and: 
                        (isor) ? result_or:
                        (isxor) ? result_xor:
                        mov_data;

endmodule

sva:
module boolean_ops_sva (
    input logic        clk,
    input logic [63:0] rs1_data,
    input logic [63:0] rs2_data,
    input logic        isand,
    input logic        isor,
    input logic        isxor,
    input logic        pass_rs2_data,
    input logic        inv_logic,
    input logic        ifu_exu_sethi_inst_e,
    input logic [63:0] logic_out
);

    // logic_out must match the implemented priority mux and datapath.
    check_logic_out_mux_function: assert property (
        @(posedge clk)
        logic_out == (
            isand ? (rs1_data & (rs2_data ^ {64{inv_logic}})) :
            isor  ? (rs1_data | (rs2_data ^ {64{inv_logic}})) :
            isxor ? (rs1_data ^ (rs2_data ^ {64{inv_logic}})) :
                    {(rs2_data[63:32] & {32{~ifu_exu_sethi_inst_e}}), rs2_data[31:0]}
        )
    );

    // isand selects the AND path regardless of other select inputs.
    check_and_selected: assert property (
        @(posedge clk)
        isand |-> (logic_out == (rs1_data & (rs2_data ^ {64{inv_logic}})))
    );

    // isor selects the OR path when isand is not asserted.
    check_or_selected: assert property (
        @(posedge clk)
        (!isand && isor) |-> (logic_out == (rs1_data | (rs2_data ^ {64{inv_logic}})))
    );

    // isxor selects the XOR path when higher-priority selects are not asserted.
    check_xor_selected: assert property (
        @(posedge clk)
        (!isand && !isor && isxor) |-> (logic_out == (rs1_data ^ (rs2_data ^ {64{inv_logic}})))
    );

    // With no boolean select asserted, logic_out must follow mov_data.
    check_mov_selected: assert property (
        @(posedge clk)
        (!isand && !isor && !isxor) |-> (
            logic_out == {(rs2_data[63:32] & {32{~ifu_exu_sethi_inst_e}}), rs2_data[31:0]}
        )
    );

    // In mov mode, the upper half is masked off only by ifu_exu_sethi_inst_e.
    check_mov_upper_half_masked: assert property (
        @(posedge clk)
        (!isand && !isor && !isxor) |-> (
            logic_out[63:32] == (rs2_data[63:32] & {32{~ifu_exu_sethi_inst_e}})
        )
    );

    // In mov mode, the lower half always passes rs2_data unchanged.
    check_mov_lower_half_passes_rs2: assert property (
        @(posedge clk)
        (!isand && !isor && !isxor) |-> (logic_out[31:0] == rs2_data[31:0])
    );

endmodule

