module top_module (
    input clk,
    input reset,
    input [31:0] in,
    input select,
    output q
);

    wire [31:0] out_module1;
    wire q_module2;
    wire [31:0] out_functional;

    module1 module1_inst (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(out_module1)
    );

    module2 module2_inst (
        .clk(clk),
        .d(out_module1[0]),
        .q(q_module2)
    );

    functional_module functional_module_inst (
        .out_module1(out_module1),
        .q_module2(q_module2),
        .select(select),
        .out(out_functional)
    );

    assign q = out_functional[0];

endmodule
module module1 (
    input clk,
    input reset,
    input [31:0] in,
    output [31:0] out
);

    reg [31:0] out_reg;

    always @(posedge clk) begin
        if (reset) begin
            out_reg <= 0;
        end else begin
            out_reg <= {out_reg[30:0], in[31]};
        end
    end

    assign out = out_reg;

endmodule
module module2 (
    input clk,
    input d,
    output q
);

    reg q_reg;

    always @(posedge clk) begin
        q_reg <= d;
    end

    assign q = q_reg;

endmodule
module functional_module (
    input [31:0] out_module1,
    input q_module2,
    input select,
    output [31:0] out
);

    assign out = select ? out_module1 : {31'b0, q_module2};

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic        reset,
    input logic [31:0] in,
    input logic        select,
    input logic        q,
    input logic [31:0] out_module1,
    input logic        q_module2,
    input logic [31:0] out_functional
);

    // module1 output clears on the cycle after reset is asserted.
    check_module1_reset_clears: assert property (
        @(posedge clk) reset |=> (out_module1 == 32'b0)
    );

    // module1 shifts prior bits [30:0] into bits [31:1].
    check_module1_shift_upper_bits: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (out_module1[31:1] == $past(out_module1[30:0]))
    );

    // module1 loads the previous in[31] into bit 0.
    check_module1_loads_input_into_lsb: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (out_module1[0] == $past(in[31]))
    );

    // module2 registers the previous out_module1[0].
    check_module2_captures_module1_lsb: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (q_module2 == $past(out_module1[0]))
    );

    // functional_module passes out_module1 when select is high.
    check_functional_select_high: assert property (
        @(posedge clk) disable iff (reset)
        select |-> (out_functional == out_module1)
    );

    // functional_module zero-extends q_module2 when select is low.
    check_functional_select_low: assert property (
        @(posedge clk) disable iff (reset)
        !select |-> (out_functional == {31'b0, q_module2})
    );

    // top-level q is the low bit of out_functional.
    check_top_q_matches_out_functional_lsb: assert property (
        @(posedge clk) disable iff (reset)
        q == out_functional[0]
    );

    // q matches out_module1[0] when select is high.
    check_top_q_select_high: assert property (
        @(posedge clk) disable iff (reset)
        select |-> (q == out_module1[0])
    );

    // q matches q_module2 when select is low.
    check_top_q_select_low: assert property (
        @(posedge clk) disable iff (reset)
        !select |-> (q == q_module2)
    );

endmodule

bind top_module top_module_sva top_module_sva_inst (
    .clk(clk),
    .reset(reset),
    .in(in),
    .select(select),
    .q(q),
    .out_module1(out_module1),
    .q_module2(q_module2),
    .out_functional(out_functional)
);

rtl:
module comparator (
    input [3:0] a,
    input [3:0] b,
    output reg eq,
    output reg gt_a,
    output reg gt_b
);

    always @(*) begin
        eq = (a == b);
        gt_a = (a > b);
        gt_b = (b > a);
    end

endmodule

sva:
module comparator_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic eq,
    input logic gt_a,
    input logic gt_b
);

    // eq reflects whether a and b are equal.
    check_eq_matches_equality: assert property (
        @($global_clock) eq == (a == b)
    );

    // gt_a reflects whether a is greater than b.
    check_gt_a_matches_a_greater: assert property (
        @($global_clock) gt_a == (a > b)
    );

    // gt_b reflects whether b is greater than a.
    check_gt_b_matches_b_greater: assert property (
        @($global_clock) gt_b == (b > a)
    );

    // Equal inputs drive only eq high.
    check_equal_inputs_drive_eq_only: assert property (
        @($global_clock) (a == b) |-> (eq && !gt_a && !gt_b)
    );

    // a greater than b drives only gt_a high.
    check_a_greater_drives_gt_a_only: assert property (
        @($global_clock) (a > b) |-> (!eq && gt_a && !gt_b)
    );

    // b greater than a drives only gt_b high.
    check_b_greater_drives_gt_b_only: assert property (
        @($global_clock) (b > a) |-> (!eq && !gt_a && gt_b)
    );

    // No two outputs are high at the same time.
    check_outputs_are_mutually_exclusive: assert property (
        @($global_clock) (!(eq && gt_a) && !(eq && gt_b) && !(gt_a && gt_b))
    );

    // One comparison result is always indicated.
    check_one_output_is_always_high: assert property (
        @($global_clock) (eq || gt_a || gt_b)
    );

endmodule

rtl:
module adder4bit(
  input [3:0] A, B,
  input Cin,
  output [3:0] S,
  output Cout
  );

  wire [3:0] sum;
  wire C1, C2, C3;

  // Full adder for bit 0
  full_adder fa0(A[0], B[0], Cin, sum[0], C1);

  // Full adder for bit 1
  full_adder fa1(A[1], B[1], C1, sum[1], C2);

  // Full adder for bit 2
  full_adder fa2(A[2], B[2], C2, sum[2], C3);

  // Full adder for bit 3
  full_adder fa3(A[3], B[3], C3, sum[3], Cout);

  assign S = sum;

endmodule

module full_adder(
  input A, B, Cin,
  output S, Cout
  );

  assign S = A ^ B ^ Cin;
  assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

sva:
module adder4bit_sva(
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] S,
    input logic       Cout
);

    // Combined carry and sum must match 4-bit addition with carry-in.
    check_full_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + {4'b0000, Cin})
    );

    // Bit 0 sum must implement the full-adder XOR equation.
    check_bit0_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Lower two sum bits must match the 2-bit addition result.
    check_low2_sum: assert property (
        @(posedge clk) S[1:0] == (A[1:0] + B[1:0] + Cin)
    );

    // Lower three sum bits must match the 3-bit addition result.
    check_low3_sum: assert property (
        @(posedge clk) S[2:0] == (A[2:0] + B[2:0] + Cin)
    );

    // Zero B and zero carry-in must pass A through with no carry-out.
    check_b_zero_passthrough: assert property (
        @(posedge clk) ((B == 4'b0000) && (Cin == 1'b0)) |-> ((S == A) && (Cout == 1'b0))
    );

    // Zero A and zero carry-in must pass B through with no carry-out.
    check_a_zero_passthrough: assert property (
        @(posedge clk) ((A == 4'b0000) && (Cin == 1'b0)) |-> ((S == B) && (Cout == 1'b0))
    );

    // Zero A and zero B must pass Cin into the least-significant sum bit only.
    check_cin_only_behavior: assert property (
        @(posedge clk) ((A == 4'b0000) && (B == 4'b0000)) |-> ((S == {3'b000, Cin}) && (Cout == 1'b0))
    );

    // Carry-out must be asserted exactly when the 5-bit sum exceeds 15.
    check_cout_threshold: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + {4'b0000, Cin}) > 5'd15)
    );

endmodule

rtl:
module sel_logic (
    input [1:0] sel,
    input A,
    input B,
    output Y
);

    wire xor_out;
    wire and_out;
    wire or_out;
    wire nand_out;

    assign xor_out = A ^ B;
    assign and_out = A & B;
    assign or_out = A | B;
    assign nand_out = ~(A & B);

    assign Y = (sel == 0) ? xor_out :
               (sel == 1) ? and_out :
               (sel == 2) ? or_out :
                            nand_out;

endmodule

sva:
module sel_logic_sva (
    input logic clk,
    input logic [1:0] sel,
    input logic A,
    input logic B,
    input logic Y
);

    // RTL is combinational with no reset; clk is the SVA sampling clock.

    // Y must match the selected boolean function.
    check_y_functional_equivalence: assert property (
        @(posedge clk)
        Y == ((sel == 2'b00) ? (A ^ B) :
              (sel == 2'b01) ? (A & B) :
              (sel == 2'b10) ? (A | B) :
                               ~(A & B))
    );

    // sel=00 selects XOR of A and B.
    check_sel_xor: assert property (
        @(posedge clk)
        (sel == 2'b00) |-> (Y == (A ^ B))
    );

    // sel=01 selects AND of A and B.
    check_sel_and: assert property (
        @(posedge clk)
        (sel == 2'b01) |-> (Y == (A & B))
    );

    // sel=10 selects OR of A and B.
    check_sel_or: assert property (
        @(posedge clk)
        (sel == 2'b10) |-> (Y == (A | B))
    );

    // sel=11 selects NAND of A and B.
    check_sel_nand: assert property (
        @(posedge clk)
        (sel == 2'b11) |-> (Y == ~(A & B))
    );

endmodule

module binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

    // Reset clears count on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

    // Count wraps from 9 back to 0 when not in reset.
    check_wrap_at_nine: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'b1001) |=> (count == 4'b0000)
    );

    // Count increments by one on all other non-reset cycles.
    check_increment_otherwise: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'b1001) |=> (count == ($past(count) + 4'b0001))
    );

endmodule

module counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       enable,
    input logic [3:0] count
);

    // While reset is asserted, count must be zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 4'b0000)
    );

    // A reset in the previous cycle clears count to zero.
    check_prev_reset_clears_count: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && $past(reset)) |-> (count == 4'b0000)
    );

    // When enabled, count increments by one on the next cycle.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset) && $past(enable)) |-> (count == ($past(count) + 4'd1))
    );

    // When not enabled, count holds its value on the next cycle.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!$initstate && !$past(reset) && !$past(enable)) |-> (count == $past(count))
    );

endmodule
